// ===== カーソス問題の完全修正 =====
(function() {
  console.log('🔧 カーソス修正システムを初期化...')
  
  // CSSでカーソスを強制的に修正
  const cursorFixStyle = document.createElement('style')
  cursorFixStyle.id = 'cursor-fix-ultimate'
  cursorFixStyle.textContent = `
    /* 究極のカーソス修正 */
    *, *::before, *::after {
      cursor: auto !important;
    }
    
    /* ボタンやリンクは pointer に */
    button, a, [role="button"], [onclick] {
      cursor: pointer !important;
    }
    
    /* テキスト入力は text に */
    input[type="text"], input[type="email"], input[type="search"], textarea {
      cursor: text !important;
    }
    
    /* ドラッグ可能な要素 */
    [draggable="true"] {
      cursor: move !important;
    }
    
    /* 待機カーソスを完全に無効化 */
    html, body {
      cursor: auto !important;
    }
    
    /* オーバーレイ中も黒いカーソスを維持 */
    #ocr-loading-overlay,
    #test-overlay,
    #ocr-loading-overlay *,
    #test-overlay * {
      cursor: auto !important;
    }
    
    /* アニメーション定義 */
    @keyframes fade-in {
      from {
        opacity: 0;
        transform: translateY(-10px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }
    
    .animate-fade-in {
      animation: fade-in 0.3s ease-out;
    }
    
    /* ★ ボタン押下フィードバック（全ボタンに適用） */
    button, [role="button"], [onclick] {
      transition: transform 0.1s ease, box-shadow 0.1s ease, filter 0.1s ease !important;
    }
    button:active, [role="button"]:active, [onclick]:active {
      transform: scale(0.95) !important;
      filter: brightness(0.92) !important;
    }
    /* グラデーションボタンの押下フィードバック強化 */
    .bg-gradient-to-r:active, .bg-gradient-to-br:active {
      transform: scale(0.93) !important;
      box-shadow: inset 0 2px 4px rgba(0,0,0,0.2) !important;
    }
    
    /* ★ 正解アニメーション */
    @keyframes bounceIn {
      0% { transform: scale(0.5); opacity: 0; }
      50% { transform: scale(1.15); }
      100% { transform: scale(1); opacity: 1; }
    }
    
    /* ★ ボタンリップルエフェクト */
    @keyframes ripple {
      0% { transform: scale(0); opacity: 0.5; }
      100% { transform: scale(3); opacity: 0; }
    }
    
    /* ============================================
     * Phase 5-2: レスポンシブデザイン
     * スマホ/タブレット対応
     * ============================================ */
    
    /* ベース: モバイルファースト */
    @media (max-width: 768px) {
      /* ナビゲーション */
      #app-header {
        padding: 0.5rem 1rem !important;
      }
      
      /* コンテンツエリア */
      #main-content {
        padding: 0.5rem !important;
      }
      
      /* カードグリッド */
      .card-grid, .curriculum-grid {
        grid-template-columns: 1fr !important;
        gap: 0.5rem !important;
      }
      
      /* ボタン */
      button {
        padding: 0.75rem 1rem !important;
        font-size: 0.875rem !important;
      }
      
      /* モーダル */
      .modal-content {
        width: 95vw !important;
        max-height: 90vh !important;
        padding: 1rem !important;
      }
      
      /* テーブル */
      table {
        font-size: 0.75rem !important;
      }
      
      th, td {
        padding: 0.5rem !important;
      }
    }
    
    /* タブレット */
    @media (min-width: 769px) and (max-width: 1024px) {
      .card-grid, .curriculum-grid {
        grid-template-columns: repeat(2, 1fr) !important;
      }
      
      .modal-content {
        width: 85vw !important;
      }
    }
    
    /* デスクトップ */
    @media (min-width: 1025px) {
      .card-grid, .curriculum-grid {
        grid-template-columns: repeat(3, 1fr) !important;
      }
      
      .modal-content {
        max-width: 900px !important;
      }
    }
    
    /* Phase 5-2: スムーズなアニメーション */
    * {
      transition: all 0.2s ease-in-out !important;
    }
    
    /* ローディングアニメーション */
    @keyframes spin {
      0% { transform: rotate(0deg); }
      100% { transform: rotate(360deg); }
    }
    
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }
    
    .loading-spinner {
      animation: spin 1s linear infinite !important;
    }
    
    .fade-in {
      animation: fadeIn 0.3s ease-out !important;
    }
    
    /* ========== 動的ウィジェット アニメーション ========== */
    @keyframes widgetSlideIn {
      from { opacity: 0; transform: translateY(20px) scale(0.95); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }
    @keyframes widgetBounce {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }
    @keyframes widgetPulse {
      0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.4); }
      50% { transform: scale(1.05); box-shadow: 0 0 20px 5px rgba(99, 102, 241, 0.2); }
    }
    @keyframes widgetShake {
      0%, 100% { transform: rotate(0deg); }
      25% { transform: rotate(-3deg); }
      75% { transform: rotate(3deg); }
    }
    @keyframes widgetGlow {
      0%, 100% { box-shadow: 0 0 5px rgba(236, 72, 153, 0.3); }
      50% { box-shadow: 0 0 20px rgba(236, 72, 153, 0.6), 0 0 40px rgba(236, 72, 153, 0.2); }
    }
    @keyframes confettiFall {
      0% { transform: translateY(-10px) rotate(0deg); opacity: 1; }
      100% { transform: translateY(100px) rotate(720deg); opacity: 0; }
    }
    @keyframes starPop {
      0% { transform: scale(0) rotate(0deg); opacity: 0; }
      50% { transform: scale(1.3) rotate(180deg); opacity: 1; }
      100% { transform: scale(1) rotate(360deg); opacity: 1; }
    }
    @keyframes ripple {
      0% { transform: scale(0.8); opacity: 1; }
      100% { transform: scale(2.5); opacity: 0; }
    }
    .widget-animate-in { animation: widgetSlideIn 0.5s ease-out forwards !important; }
    .widget-bounce { animation: widgetBounce 0.6s ease !important; }
    .widget-pulse { animation: widgetPulse 2s ease-in-out infinite !important; }
    .widget-shake { animation: widgetShake 0.4s ease !important; }
    .widget-glow { animation: widgetGlow 2s ease-in-out infinite !important; }
    
    /* タッチ対応ドラッグ要素 */
    .draggable-item {
      cursor: grab !important;
      user-select: none !important;
      -webkit-user-select: none !important;
      touch-action: none !important;
      transition: transform 0.15s ease, box-shadow 0.15s ease !important;
    }
    .draggable-item:active {
      cursor: grabbing !important;
      transform: scale(1.1) !important;
      box-shadow: 0 8px 25px rgba(0,0,0,0.2) !important;
      z-index: 100 !important;
    }
    .drop-zone {
      transition: background-color 0.2s ease, border-color 0.2s ease !important;
    }
    .drop-zone.drag-over {
      background-color: rgba(99, 102, 241, 0.1) !important;
      border-color: #6366f1 !important;
      box-shadow: inset 0 0 10px rgba(99, 102, 241, 0.2) !important;
    }
    
    /* インタラクティブ分数バー */
    .fraction-bar-segment {
      cursor: pointer !important;
      transition: all 0.2s ease !important;
    }
    .fraction-bar-segment:hover {
      filter: brightness(1.2) !important;
      transform: scaleY(1.15) !important;
    }
    .fraction-bar-segment.selected {
      filter: brightness(1.3) !important;
      outline: 3px solid #fff !important;
      outline-offset: -2px !important;
    }
    
    /* リップルエフェクト（タッチフィードバック）*/
    .touch-ripple {
      position: absolute !important;
      border-radius: 50% !important;
      background: rgba(255,255,255,0.5) !important;
      animation: ripple 0.6s ease-out !important;
      pointer-events: none !important;
    }
  `
  document.head.appendChild(cursorFixStyle)
  
  // JavaScript側でも強制リセット
  document.body.style.cursor = ''
  document.documentElement.style.cursor = ''
  
  // MutationObserverでカーソス変更を監視して自動修正
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      if (mutation.type === 'attributes' && mutation.attributeName === 'style') {
        const target = mutation.target
        if (target.style.cursor === 'wait' || target.style.cursor === 'progress') {
          console.log('🔧 待機カーソスを自動リセット:', target.tagName)
          target.style.cursor = ''
        }
      }
    })
  })
  
  // body と html を監視
  observer.observe(document.body, { attributes: true, attributeFilter: ['style'] })
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['style'] })
  
  console.log('✅ カーソス修正システム初期化完了')
})();

