// デバイスタイプ判定
function getDeviceType() {
  const width = window.innerWidth
  if (width < 768) return 'mobile'
  if (width < 1024) return 'tablet'
  return 'desktop'
}

// 学習タイマー管理
const learningTimer = {
  startTime: null,
  
  start() {
    this.startTime = Date.now()
  },
  
  getElapsedSeconds() {
    if (!this.startTime) return 0
    return Math.floor((Date.now() - this.startTime) / 1000)
  },
  
  reset() {
    this.startTime = null
  }
}

