// グローバルローディング管理
const loadingManager = {
  _timer: null,
  show: (message = '読み込み中...') => {
    const existing = document.getElementById('global-loading')
    if (existing) return
    
    const loadingDiv = document.createElement('div')
    loadingDiv.id = 'global-loading'
    loadingDiv.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50'
    loadingDiv.innerHTML = `
      <div class="bg-white rounded-lg p-8 shadow-2xl max-w-sm mx-4 text-center">
        <div class="animate-spin rounded-full h-16 w-16 border-b-4 border-indigo-600 mx-auto mb-4"></div>
        <p class="text-xl font-bold text-gray-800 mb-2">${message}</p>
        <p class="text-sm text-gray-500">しばらくお待ちください</p>
      </div>
    `
    document.body.appendChild(loadingDiv)
    
    // 安全網：30秒後にローディングを自動解除（ぐるぐる永久防止）
    if (loadingManager._timer) clearTimeout(loadingManager._timer)
    loadingManager._timer = setTimeout(() => {
      const el = document.getElementById('global-loading')
      if (el) {
        console.warn('⚠️ ローディング30秒タイムアウト、自動解除')
        el.remove()
      }
    }, 30000)
  },
  
  hide: () => {
    if (loadingManager._timer) { clearTimeout(loadingManager._timer); loadingManager._timer = null }
    const loading = document.getElementById('global-loading')
    if (loading) {
      loading.remove()
    }
  }
}

// ボタン押下フィードバック: 押した直後にローディング状態にし、処理完了後に復元
function btnLoading(btn, loadingText = '読み込み中...') {
  if (!btn || btn.dataset.loading === 'true') return null
  const original = { html: btn.innerHTML, disabled: btn.disabled, classes: btn.className }
  btn.dataset.loading = 'true'
  btn.disabled = true
  btn.classList.add('btn-loading-state')
  btn.innerHTML = `
    <span class="inline-flex items-center gap-2">
      <svg class="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
        <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
        <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
      </svg>
      <span>${loadingText}</span>
    </span>`
  // トースト通知を表示
  showToast(loadingText, 'info')
  return {
    restore: () => {
      btn.innerHTML = original.html
      btn.disabled = original.disabled
      btn.classList.remove('btn-loading-state')
      delete btn.dataset.loading
    }
  }
}

// トースト通知
function showToast(message, type = 'info', duration = 2500) {
  // 既存のトーストを削除
  document.querySelectorAll('.toast-notification').forEach(t => t.remove())
  const colors = {
    info: 'background: linear-gradient(135deg, #6366f1, #8b5cf6); color: white;',
    success: 'background: linear-gradient(135deg, #10b981, #34d399); color: white;',
    error: 'background: linear-gradient(135deg, #ef4444, #f87171); color: white;',
    warning: 'background: linear-gradient(135deg, #f59e0b, #fbbf24); color: #1f2937;'
  }
  const icons = { info: 'fas fa-spinner fa-spin', success: 'fas fa-check-circle', error: 'fas fa-exclamation-circle', warning: 'fas fa-exclamation-triangle' }
  const toast = document.createElement('div')
  toast.className = 'toast-notification'
  toast.style.cssText = colors[type] || colors.info
  toast.innerHTML = `<i class="${icons[type] || icons.info} mr-2"></i>${message}`
  document.body.appendChild(toast)
  setTimeout(() => {
    toast.classList.add('fade-out')
    setTimeout(() => toast.remove(), 300)
  }, duration)
  return toast
}

// 初期化関数（DOMContentLoaded or 外部から呼び出し可能）
function initializeApp() {
  if (window._appBootstrapped) return // 二重実行防止
  window._appBootstrapped = true
  console.log('🚀 app.js 初期化開始')
  
  // bfcache対策: ページが戻る/進むボタンで復元された場合にリロード
  window.addEventListener('pageshow', (event) => {
    if (event.persisted) {
      console.log('🔄 bfcacheから復元 - リロードします')
      location.reload()
      return
    }
  })
  
  // 音声合成の初期化（ボイスリストを読み込む）
  if ('speechSynthesis' in window) {
    // ボイスリストの読み込みを待つ
    let voicesLoaded = false
    const loadVoices = () => {
      const voices = window.speechSynthesis.getVoices()
      if (voices.length > 0 && !voicesLoaded) {
        voicesLoaded = true
        console.log('音声合成が利用可能:', voices.length, '種類の音声')
        
        // 日本語音声の確認
        const japaneseVoices = voices.filter(v => v.lang.startsWith('ja'))
        console.log('日本語音声:', japaneseVoices.length, '種類')
      }
    }
    
    // Chrome/Edge用
    if (window.speechSynthesis.onvoiceschanged !== undefined) {
      window.speechSynthesis.onvoiceschanged = loadVoices
    }
    
    // Safari用（すぐに読み込まれる場合）
    loadVoices()
  }
  
  // 音声自動読み上げ設定を復元
  const savedAutoPlayVoice = localStorage.getItem('autoPlayAIVoice')
  // デフォルトはON（初回アクセス時）
  window.autoPlayAIVoice = savedAutoPlayVoice === null ? true : savedAutoPlayVoice === 'true'
  console.log('🔊 音声自動読み上げ:', window.autoPlayAIVoice ? 'ON' : 'OFF')
  
  // ローカルストレージから認証情報を復元
  const savedSession = localStorage.getItem('session_token')
  const savedUser = localStorage.getItem('user')
  
  // axios グローバル設定: AI生成は数分かかるため十分な余裕を設定（個別設定で上書き可能）
  axios.defaults.timeout = 300000 // 5分
  
  // axios リクエストインターセプター: 認証トークンを自動付与
  axios.interceptors.request.use(function(config) {
    const token = state.auth.sessionToken || localStorage.getItem('session_token')
    if (token) {
      config.headers = config.headers || {}
      config.headers['Authorization'] = 'Bearer ' + token
    }
    return config
  })
  
  if (savedSession && savedUser) {
    // セッション検証
    verifySession().then(isValid => {
      if (isValid) {
        state.auth.sessionToken = savedSession
        state.auth.refreshToken = localStorage.getItem('refresh_token')
        state.auth.user = JSON.parse(savedUser)
        state.auth.isAuthenticated = true
        
        // ユーザー情報をstateに反映
        if (state.auth.user.role === 'student') {
          state.currentStudent = {
            id: state.auth.user.user_id,
            name: state.auth.user.full_name
          }
        }
        
        // トップページを表示
        renderTopPage()
      } else {
        // セッションが無効な場合はログイン画面
        renderLoginPage()
      }
    })
  } else {
    // セッションがない場合はログイン画面
    renderLoginPage()
  }
}
// グローバルに公開
window.initializeApp = initializeApp

// 通常のページ読み込み時はDOMContentLoadedで初期化
// 動的スクリプトロード時（/landing）はDOMContentLoadedが既に発火済みなので
// document.readyStateをチェック
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeApp)
} else {
  // DOMContentLoadedは既に発火済み - 即座に初期化
  initializeApp()
}

