async function loadTopPageData() {
  try {
    // 選択肢データの取得
    const response = await axios.get('/api/curriculum/options')
    const { grades, subjects, textbooks } = response.data

    // 学年選択肢を設定（全学年を静的に表示）
    const gradeSelect = document.getElementById('gradeSelect')
    if (!gradeSelect) return
    const allGrades = [
      '小学1年', '小学2年', '小学3年', '小学4年', '小学5年', '小学6年',
      '中学1年', '中学2年', '中学3年'
    ]
    const dbGrades = new Set(grades.map(g => g.grade))
    allGrades.forEach(g => {
      const option = document.createElement('option')
      option.value = g
      option.textContent = dbGrades.has(g) ? g : g + '（AI新規生成）'
      gradeSelect.appendChild(option)
    })
    // DBにあってallGradesにない学年も追加
    grades.forEach(item => {
      if (!allGrades.includes(item.grade)) {
        const option = document.createElement('option')
        option.value = item.grade
        option.textContent = item.grade
        gradeSelect.appendChild(option)
      }
    })

    // 教科選択肢を設定（全教科を静的に表示 + DB既存をマーク）
    const subjectSelect = document.getElementById('subjectSelect')
    const allSubjects = [
      { value: '算数', label: '算数' },
      { value: '数学', label: '数学' },
      { value: '国語', label: '国語' },
      { value: '理科', label: '理科' },
      { value: '社会', label: '社会' },
      { value: '英語', label: '英語' },
      { value: '外国語活動', label: '外国語活動' },
      { value: '生活', label: '生活' },
      { value: '音楽', label: '音楽' },
      { value: '図工', label: '図工・美術' },
      { value: '体育', label: '体育' },
      { value: '保健体育', label: '保健体育' },
      { value: '家庭科', label: '家庭科' },
      { value: '技術', label: '技術' },
      { value: '総合', label: '総合的な学習' },
      { value: '道徳', label: '道徳' },
      { value: '特別活動', label: '特別活動' },
      { value: 'プログラミング', label: 'プログラミング' },
    ]
    const dbSubjects = new Set(subjects.map(s => s.subject))
    allSubjects.forEach(s => {
      const option = document.createElement('option')
      option.value = s.value
      option.textContent = dbSubjects.has(s.value) ? s.label : s.label + '（AI新規生成）'
      subjectSelect.appendChild(option)
    })
    // DBにあってallSubjectsにない教科も追加
    subjects.forEach(item => {
      if (!allSubjects.some(s => s.value === item.subject)) {
        const option = document.createElement('option')
        option.value = item.subject
        option.textContent = item.subject
        subjectSelect.appendChild(option)
      }
    })

    // 教科書会社選択肢を設定（全出版社を静的表示 + DB既存をマーク）
    const textbookSelect = document.getElementById('textbookSelect')
    const allTextbooks = [
      '東京書籍', '啓林館', '大日本図書', '学校図書', '教育出版',
      '光村図書', '日本文教出版', '三省堂', '帝国書院', '開隆堂',
      '信教出版', '数研出版', '実教出版', '第一学習社',
      'その他（指定なし）'
    ]
    const dbTextbooks = new Set(textbooks.map(t => t.textbook_company))
    allTextbooks.forEach(t => {
      const option = document.createElement('option')
      option.value = t
      option.textContent = dbTextbooks.has(t) ? t : t
      textbookSelect.appendChild(option)
    })
    // DBにあってallTextbooksにない出版社も追加
    textbooks.forEach(item => {
      if (!allTextbooks.includes(item.textbook_company)) {
        const option = document.createElement('option')
        option.value = item.textbook_company
        option.textContent = item.textbook_company
        textbookSelect.appendChild(option)
      }
    })

    // ステップインジケーター更新
    function updateStepIndicators() {
      const g = gradeSelect.value
      const s = subjectSelect.value
      const t = textbookSelect.value
      const activeClass = 'bg-white bg-opacity-30'
      const inactiveClass = 'bg-white bg-opacity-20'
      const activeDot = 'bg-white text-purple-600'
      const inactiveDot = 'bg-white bg-opacity-50 text-purple-600'

      const s1 = document.getElementById('step1Indicator')
      const s2 = document.getElementById('step2Indicator')
      const s3 = document.getElementById('step3Indicator')
      const s4 = document.getElementById('step4Indicator')
      if (!s1) return

      // Step 1 always active since page loaded
      s1.className = s1.className.replace(inactiveClass, activeClass)
      s2.className = g ? s2.className.replace(inactiveClass, activeClass) : s2.className.replace(activeClass, inactiveClass)
      s3.className = g && s ? s3.className.replace(inactiveClass, activeClass) : s3.className.replace(activeClass, inactiveClass)
      const noTxtSubjects = ['体育','保健体育','音楽','図工','家庭科','技術','道徳','総合','特別活動','プログラミング','外国語活動']
      const skipTextbook = s && noTxtSubjects.includes(s)
      s4.className = (g && s && (t || skipTextbook)) ? s4.className.replace(inactiveClass, activeClass) : s4.className.replace(activeClass, inactiveClass)
    }

    // ★ 学年に応じて教科リストをフィルタリング（小学→算数、中学→数学）
    function updateSubjectListForGrade() {
      const grade = gradeSelect.value
      const isElementary = grade.startsWith('小学')
      const isMiddle = grade.startsWith('中学')
      const currentSubject = subjectSelect.value
      
      Array.from(subjectSelect.options).forEach(opt => {
        if (opt.value === '') return // 「選択してください」は常に表示
        if (opt.value === '算数') {
          opt.style.display = isMiddle ? 'none' : ''
          opt.disabled = isMiddle
        } else if (opt.value === '数学') {
          opt.style.display = isElementary ? 'none' : ''
          opt.disabled = isElementary
        } else if (opt.value === '生活') {
          // 生活は小1・小2のみ
          const isLow = ['小学1年','小学2年'].includes(grade)
          opt.style.display = (!grade || isLow) ? '' : 'none'
          opt.disabled = grade && !isLow
        }
      })
      
      // 現在選択中の教科が非表示になった場合、自動切替
      if (isElementary && currentSubject === '数学') {
        subjectSelect.value = '算数'
      } else if (isMiddle && currentSubject === '算数') {
        subjectSelect.value = '数学'
      }
    }
    
    // 選択が変更されたら単元リストを更新（★ スクロール位置を保持）
    gradeSelect.addEventListener('change', () => { const sy = window.scrollY; updateSubjectListForGrade(); updateStepIndicators(); updateUnitList().then(() => window.scrollTo(0, sy)) })
    subjectSelect.addEventListener('change', () => { const sy = window.scrollY; updateStepIndicators(); updateUnitList().then(() => window.scrollTo(0, sy)) })
    textbookSelect.addEventListener('change', () => { const sy = window.scrollY; updateStepIndicators(); updateUnitList().then(() => window.scrollTo(0, sy)) })

  } catch (error) {
    console.error('データ読み込みエラー:', error)
  }
}

// 単元カード要素を作成するヘルパー
function createUnitCard(item, idx) {
  const card = document.createElement('div')
  card.className = 'bg-white border-2 border-gray-200 rounded-lg p-4 hover:border-purple-400 hover:shadow-md transition-all duration-200 cursor-pointer flex items-center justify-between group'
  card.setAttribute('data-curriculum-id', item.id)
  card.innerHTML = `
    <div class="flex-1 pointer-events-none">
      <p class="font-bold text-gray-800 group-hover:text-purple-700 transition"><i class="fas fa-book-open mr-2 text-purple-400"></i>${idx + 1}. ${item.unit_name}</p>
      <p class="text-sm text-gray-500 ml-7">${item.grade} ${item.subject} - ${item.textbook_company}</p>
    </div>
    <div class="flex gap-2">
      <button 
        onclick="event.stopPropagation(); duplicateCurriculum(${item.id})" 
        class="bg-green-100 text-green-700 hover:bg-green-200 px-3 py-1 rounded transition opacity-0 group-hover:opacity-100 pointer-events-auto"
        title="複製">
        <i class="fas fa-copy"></i>
      </button>
      <button 
        onclick="event.stopPropagation(); deleteCurriculum(${item.id}, '${item.unit_name.replace(/'/g, "\\'")}')" 
        class="bg-red-100 text-red-700 hover:bg-red-200 px-3 py-1 rounded transition opacity-0 group-hover:opacity-100 pointer-events-auto"
        title="削除">
        <i class="fas fa-trash"></i>
      </button>
    </div>
  `
  // ★ カード全体にクリックハンドラ（ボタンのstopPropagationで複製/削除は上書きされない）
  card.addEventListener('click', function(e) {
    // ボタン内のクリックは除外（stopPropagationで処理済み）
    console.log('📌 単元カードクリック:', item.id, item.unit_name)
    selectUnit(item.id)
  })
  return card
}

async function updateUnitList() {
  const grade = document.getElementById('gradeSelect').value
  const subject = document.getElementById('subjectSelect').value
  const textbook = document.getElementById('textbookSelect').value
  const unitSelect = document.getElementById('unitSelect')
  const startButton = document.getElementById('startButton')
  const unitArea = document.getElementById('unitSelectArea')

  startButton.disabled = true
  startButton.classList.add('hidden')

  // 教科書が不要な教科（体育、音楽、家庭科、図工、道徳、総合、特別活動、保健体育、外国語活動、プログラミング）
  const noTextbookSubjects = ['体育','保健体育','音楽','図工','図工・美術','家庭科','技術','道徳','総合','総合的な学習','特別活動','プログラミング','外国語活動']
  const needsTextbook = !noTextbookSubjects.includes(subject)
  // 教科書不要の教科は学年と教科だけで進める
  const canProceed = grade && subject && (textbook || !needsTextbook)
  // 教科書選択の表示/非表示
  const textbookContainer = textbookSelect?.closest('div')?.parentElement ? textbookSelect.closest('div') : null
  if (textbookContainer) {
    if (!needsTextbook && subject) {
      textbookContainer.style.opacity = '0.4'
      textbookContainer.style.pointerEvents = 'none'
      textbookContainer.title = 'この教科は教科書会社の選択は不要です'
    } else {
      textbookContainer.style.opacity = '1'
      textbookContainer.style.pointerEvents = ''
      textbookContainer.title = ''
    }
  }
  if (canProceed) {
    // ラベル表示 + スピナー（現在のスクロール位置を保持）
    const scrollY = window.scrollY
    document.getElementById('unitSelectLabel').style.display = ''
    unitSelect.className = 'space-y-2 max-h-[600px] overflow-y-auto border-2 border-gray-200 rounded-xl p-4 bg-gray-50'
    unitSelect.innerHTML = '<p class="text-gray-400 text-center py-8"><i class="fas fa-spinner fa-spin mr-2"></i>読み込み中...</p>'
    window.scrollTo(0, scrollY)
    try {
      const response = await axios.get('/api/curriculum')
      const curricula = response.data.filter(c => {
        const gradeMatch = c.grade == grade
        const subjectMatch = c.subject === subject
        // 教科書不要の教科はtextbookフィルタなし
        const textbookMatch = !needsTextbook || c.textbook_company === textbook
        return gradeMatch && subjectMatch && textbookMatch
      })

      if (curricula.length > 0) {
        // カード形式で表示（スクロール位置を保持）
        const sy = window.scrollY
        unitSelect.innerHTML = ''
        
        // 6年社会の場合、歴史と公民の分野ヘッダーを追加
        // 歴史時代名キーワード（これを含む場合は歴史として優先判定）
        const historyEraKeywords = ['縄文','弥生','古墳','大和','飛鳥','奈良時代','平安','鎌倉','室町','戦国','安土桃山','江戸','明治維新','明治時代','大正','昭和','日清','日露','近代国家']
        const civicsKeywords = ['憲法','選挙','国会','内閣','裁判','三権','人権','国民主権','天皇の地位','平和主義','税金','地方自治','国際協力','持続可能','グローバル','まちづくり','子育て支援','震災復興','願いを実現']
        const isSocialStudies = subject === '社会'
        let civicsSectionAdded = false
        
        // 社会の場合、歴史と公民に分類
        if (isSocialStudies && curricula.length > 10) {
          const historyUnits = []
          const civicsUnits = []
          curricula.forEach(item => {
            // 歴史時代名を含む場合は歴史として優先判定（「奈良時代の政治と文化」等の誤分類防止）
            const isHistory = historyEraKeywords.some(kw => item.unit_name.includes(kw))
            const isCivics = !isHistory && civicsKeywords.some(kw => item.unit_name.includes(kw))
            if (isCivics) civicsUnits.push(item)
            else historyUnits.push(item)
          })
          
          if (historyUnits.length > 0 && civicsUnits.length > 0) {
            // 歴史分野ヘッダー
            const histHeader = document.createElement('div')
            histHeader.className = 'bg-amber-50 border-2 border-amber-300 rounded-lg px-4 py-2 mb-1'
            histHeader.innerHTML = '<p class="text-sm font-bold text-amber-800"><i class="fas fa-landmark mr-2"></i>📜 歴史分野（' + historyUnits.length + '単元）</p>'
            unitSelect.appendChild(histHeader)
            
            historyUnits.forEach((item, idx) => {
              unitSelect.appendChild(createUnitCard(item, idx))
            })
            
            // 公民分野ヘッダー
            const civicsHeader = document.createElement('div')
            civicsHeader.className = 'bg-blue-50 border-2 border-blue-300 rounded-lg px-4 py-2 mb-1 mt-3'
            civicsHeader.innerHTML = '<p class="text-sm font-bold text-blue-800"><i class="fas fa-balance-scale mr-2"></i>🏛️ 政治・公民分野（' + civicsUnits.length + '単元）</p>'
            unitSelect.appendChild(civicsHeader)
            
            civicsUnits.forEach((item, idx) => {
              unitSelect.appendChild(createUnitCard(item, historyUnits.length + idx))
            })
            civicsSectionAdded = true
          }
        }
        
        // 通常の表示（社会以外、または分類不要の場合）
        if (!civicsSectionAdded) {
          curricula.forEach((item, idx) => {
            unitSelect.appendChild(createUnitCard(item, idx))
          })
        }
        
        startButton.disabled = false
        window.scrollTo(0, sy)
      } else {
        unitSelect.innerHTML = `
          <div class="text-center py-6">
            <i class="fas fa-info-circle text-purple-400 text-3xl mb-3 block"></i>
            <p class="text-gray-600 font-bold mb-2">「${subject}」の単元はまだ登録されていません</p>
            <p class="text-sm text-gray-400 mb-4">AIで新しい単元を自動生成できます（約2〜4分）</p>
            <button onclick="showUnitGeneratorModal()" class="bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white font-bold py-3 px-8 rounded-xl transition shadow-lg">
              <i class="fas fa-wand-magic-sparkles mr-2"></i>AIで「${subject}」の単元を作成する
            </button>
          </div>`
        startButton.disabled = true
      }
    } catch (error) {
      console.error('単元リスト読み込みエラー:', error)
      const errMsg = error?.response?.status === 401 ? 'ログインが必要です。ページを再読み込みしてください。' : '読み込みエラー。再度お試しください。'
      unitSelect.innerHTML = `<p class="text-red-400 text-center py-8"><i class="fas fa-exclamation-triangle mr-2"></i>${errMsg}</p>
        <div class="text-center mt-2">
          <button onclick="updateUnitList()" class="text-sm bg-purple-500 hover:bg-purple-600 text-white px-4 py-2 rounded-lg font-bold transition">
            <i class="fas fa-sync-alt mr-1"></i>再読み込み
          </button>
        </div>`
    }
  } else {
    // 単元リストを非表示（スクロール位置を保持）
    const scrollY2 = window.scrollY
    document.getElementById('unitSelectLabel').style.display = 'none'
    unitSelect.className = 'space-y-2 max-h-[600px] overflow-y-auto rounded-xl p-4'
    unitSelect.innerHTML = ''
    window.scrollTo(0, scrollY2)
    // 教科書不要教科の表示状態をリセット
    const textbookContainer2 = textbookSelect?.closest('div')
    if (textbookContainer2) {
      textbookContainer2.style.opacity = '1'
      textbookContainer2.style.pointerEvents = ''
      textbookContainer2.title = ''
    }
  }
}

// 単元を選択
async function selectUnit(curriculumId) {
  state.selectedCurriculumId = curriculumId
  
  // ★ スクロール位置を保持
  const savedScrollY = window.scrollY
  
  // ★ 即座に選択した感を出す（ローディング表示）
  const allCards = document.querySelectorAll('#unitSelect > div[data-curriculum-id]')
  allCards.forEach(card => {
    const cardId = card.getAttribute('data-curriculum-id')
    if (String(cardId) === String(curriculumId)) {
      card.classList.add('border-purple-500', 'bg-purple-50', 'shadow-lg')
      card.style.transform = 'scale(0.98)'
      card.style.transition = 'all 0.2s ease'
      const nameEl = card.querySelector('p.font-bold')
      if (nameEl) nameEl.innerHTML = '<i class="fas fa-spinner fa-spin mr-2 text-purple-500"></i>' + nameEl.textContent
    } else {
      card.style.opacity = '0.4'
      card.style.pointerEvents = 'none'
      card.style.transition = 'all 0.2s ease'
    }
  })
  
  // スクロール位置を復元
  window.scrollTo(0, savedScrollY)
  
  // まずカリキュラムのカード数を確認
  try {
    const response = await axios.get(`/api/curriculum/${curriculumId}`)
    const { curriculum, courses } = response.data
    const totalCards = (courses || []).reduce((sum, c) => sum + (c.cards?.length || 0), 0)
    
    if (totalCards === 0) {
      // カードが0枚：即座にメーター画面で自動生成を開始
      console.log('📦 カード0枚のため自動生成を開始:', curriculumId, curriculum.unit_name)
      state.selectedCurriculum = curriculum
      state.courses = courses || []
      
      // autoGenerateCardsForCurriculumを直接呼び出し（メーター画面が表示される）
      autoGenerateCardsForCurriculum(curriculumId)
      return
    }
  } catch (e) {
    console.warn('カード数確認エラー、てびきページに遷移:', e.message)
  }
  
  // カードがある場合は通常通りてびきページへ
  loadGuidePage(curriculumId)
}
window.selectUnit = selectUnit

// 単元を削除
// 単元を複製
async function duplicateCurriculum(curriculumId) {
  try {
    // カリキュラムデータを取得
    const response = await axios.get(`/api/curriculum/${curriculumId}`)
    const { curriculum } = response.data
    
    // 複製モーダルを表示
    const modal = document.createElement('div')
    modal.id = 'duplicateModal'
    modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4'
    modal.innerHTML = `
      <div class="bg-white rounded-lg shadow-2xl max-w-2xl w-full p-8">
        <h2 class="text-2xl font-bold text-gray-800 mb-6">
          <i class="fas fa-copy mr-2 text-green-600"></i>
          単元を複製
        </h2>
        
        <p class="text-gray-600 mb-6">
          「${curriculum.unit_name}」を複製します。<br>
          必要に応じて基本情報を変更してください。
        </p>
        
        <div class="space-y-4">
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">学年</label>
            <input type="text" id="dupGrade" value="${curriculum.grade}" 
                   class="w-full p-3 border-2 border-gray-300 rounded-lg focus:border-green-500 focus:outline-none">
          </div>
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">教科</label>
            <input type="text" id="dupSubject" value="${curriculum.subject}" 
                   class="w-full p-3 border-2 border-gray-300 rounded-lg focus:border-green-500 focus:outline-none">
          </div>
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">教科書会社</label>
            <input type="text" id="dupTextbook" value="${curriculum.textbook_company}" 
                   class="w-full p-3 border-2 border-gray-300 rounded-lg focus:border-green-500 focus:outline-none">
          </div>
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">単元名</label>
            <input type="text" id="dupUnitName" value="${curriculum.unit_name}（コピー）" 
                   class="w-full p-3 border-2 border-gray-300 rounded-lg focus:border-green-500 focus:outline-none">
          </div>
        </div>
        
        <div class="flex gap-4 mt-8">
          <button onclick="executeDuplicate(${curriculumId})" 
                  class="flex-1 bg-gradient-to-r from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700 text-white py-3 px-6 rounded-lg font-bold transition shadow-lg">
            <i class="fas fa-check mr-2"></i>
            複製する
          </button>
          <button onclick="closeDuplicateModal()" 
                  class="bg-gray-300 hover:bg-gray-400 text-gray-800 py-3 px-6 rounded-lg font-bold transition">
            <i class="fas fa-times mr-2"></i>
            キャンセル
          </button>
        </div>
      </div>
    `
    
    document.body.appendChild(modal)
  } catch (error) {
    console.error('複製モーダル表示エラー:', error)
    alert(`❌ エラーが発生しました: ${error.message}`)
  }
}

function closeDuplicateModal() {
  const modal = document.getElementById('duplicateModal')
  if (modal) {
    modal.remove()
  }
}

async function executeDuplicate(curriculumId) {
  try {
    const newGrade = document.getElementById('dupGrade').value
    const newSubject = document.getElementById('dupSubject').value
    const newTextbook = document.getElementById('dupTextbook').value
    const newUnitName = document.getElementById('dupUnitName').value
    
    if (!newGrade || !newSubject || !newTextbook || !newUnitName) {
      alert('すべての項目を入力してください')
      return
    }
    
    loadingManager.show('単元を複製中...')
    
    const response = await axios.post(`/api/curriculum/${curriculumId}/duplicate`, {
      newGrade,
      newSubject,
      newTextbook,
      newUnitName
    })
    
    loadingManager.hide()
    closeDuplicateModal()
    
    if (response.data.success) {
      alert(`✅ 単元「${newUnitName}」を複製しました！`)
      // 単元リストを更新
      updateUnitList()
    } else {
      throw new Error(response.data.error || '複製に失敗しました')
    }
  } catch (error) {
    loadingManager.hide()
    console.error('単元複製エラー:', error)
    alert(`❌ 単元の複製に失敗しました: ${error.message}`)
  }
}

async function deleteCurriculum(curriculumId, unitName) {
  const confirmed = confirm(`本当に「${unitName}」を削除しますか？\n\nこの操作は取り消せません。\n- 単元の基本情報\n- すべてのコース\n- すべてのカード\n- すべての問題\nが削除されます。`)
  
  if (!confirmed) {
    return
  }
  
  try {
    const response = await axios.delete(`/api/curriculum/${curriculumId}`)
    
    if (response.data.success) {
      alert(`✅ 「${unitName}」を削除しました`)
      // 単元リストを再読み込み
      updateUnitList()
    } else {
      throw new Error(response.data.error || '削除に失敗しました')
    }
  } catch (error) {
    console.error('削除エラー:', error)
    alert(`❌ 削除に失敗しました: ${error.response?.data?.error || error.message}`)
  }
}
window.deleteCurriculum = deleteCurriculum

// 単元を編集
async function editCurriculum(curriculumId) {
  try {
    // カリキュラムデータを取得
    const response = await axios.get(`/api/curriculum/${curriculumId}`)
    const { curriculum, courses } = response.data
    
    // 編集モーダルを表示
    showEditCurriculumModal(curriculum, courses)
    
  } catch (error) {
    console.error('編集データ取得エラー:', error)
    alert(`❌ データの取得に失敗しました: ${error.message}`)
  }
}

