async function selectCourse(courseId) {
  try {
    const response = await axios.get(`/api/courses/${courseId}/cards`)
    const cards = response.data
    
    state.selectedCourse = courseId
    
    // カード一覧をグローバルに保存（ページネーション用）
    window._courseCardsList = cards.map(c => c.card_id || c.id).filter(Boolean)
    window._courseCardsData = cards
    console.log('📚 コースカード一覧保存:', window._courseCardsList.length, '枚')
    
    // 学習セッションを開始（初回のみ）
    if (!learningSession.sessionId) {
      await startLearningSession(state.selectedCurriculum?.id)
    }

    // ★ 1ページ目のカードを直接表示（カード一覧をスキップして1枚ずつ進行）
    if (cards.length > 0) {
      const firstCardId = cards[0].card_id || cards[0].id
      loadCardPage(firstCardId)
      return
    }

    const app = document.getElementById('app')
    app.innerHTML = `
      <div class="container mx-auto px-4 py-8">
        <!-- ヘッダー -->
        <div class="bg-white rounded-lg shadow-lg p-6 mb-6">
          <button onclick="goBackToGuide()" class="text-indigo-600 hover:text-indigo-800 mb-4">
            <i class="fas fa-arrow-left mr-2"></i>学習のてびきに戻る
          </button>
          <h1 class="text-3xl font-bold text-indigo-600 mb-2">
            学習カード
          </h1>
          <p class="text-xl text-gray-800">
            ${state.selectedCurriculum.unit_name}
          </p>
          <p class="text-sm text-gray-500 mt-1"><i class="fas fa-book mr-1"></i>${state.selectedCurriculum.textbook_company || ''} ${state.selectedCurriculum.grade || ''} ${state.selectedCurriculum.subject || ''}</p>
        </div>

        <!-- 学習カード一覧 -->
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          ${cards.map((card, index) => `
            <div class="bg-white rounded-lg shadow-lg p-6 hover:shadow-xl transition cursor-pointer"
                 onclick="loadCardPage(${card.card_id || card.id})">
              <div class="flex items-center justify-between mb-4">
                <h3 class="text-xl font-bold text-gray-800">カード ${card.card_number}</h3>
                <div class="w-12 h-12 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold">
                  ${card.card_number}
                </div>
              </div>
              <h4 class="text-lg font-bold text-gray-700 mb-3">${card.card_title}</h4>
              <div class="flex items-center text-sm text-gray-500 mb-3">
                <i class="fas fa-signal mr-2"></i>
                <span>${getDifficultyLabel(card.difficulty_level)}</span>
              </div>
              ${card.real_world_connection ? `
                <p class="text-xs text-gray-600 bg-gray-50 rounded p-2">
                  <i class="fas fa-lightbulb mr-1"></i>${card.real_world_connection}
                </p>
              ` : ''}
              <button class="w-full mt-4 bg-indigo-600 text-white py-2 px-4 rounded-lg font-bold hover:bg-indigo-700 transition">
                学習する
              </button>
            </div>
          `).join('')}
        </div>
        
        <!-- カード枚数が少ない場合のメッセージ＋再生成ボタン -->
        ${cards.length <= 3 ? `
        <div class="mt-6 bg-yellow-50 border-2 border-yellow-300 rounded-xl p-6 text-center">
          <i class="fas fa-info-circle text-yellow-500 text-2xl mb-3"></i>
          <p class="text-gray-700 font-bold mb-2">
            現在 ${cards.length} 枚のカードがあります
          </p>
          <p class="text-sm text-gray-600 mb-4">
            カードの枚数を増やしたい場合は「カード再生成」ボタンを押してください。<br>
            AIが単元に合わせた学習カードを追加生成します。
          </p>
          <button onclick="regenerateCards(${state.selectedCourse}, ${state.selectedCurriculum?.id})" 
                  class="bg-gradient-to-r from-yellow-500 to-orange-500 hover:from-yellow-600 hover:to-orange-600 text-white py-3 px-8 rounded-lg font-bold transition shadow-lg">
            <i class="fas fa-sync-alt mr-2"></i>
            カード再生成（8〜10枚）
          </button>
        </div>
        ` : ''}
        
        <!-- クラス進捗確認ボタン（児童用）-->
        <div class="mt-6 text-center">
          <button onclick="showClassProgress()" class="bg-blue-500 hover:bg-blue-600 text-white py-3 px-8 rounded-lg font-bold transition">
            <i class="fas fa-users mr-2"></i>
            クラスのみんなの進捗を見る
          </button>
          <p class="text-sm text-gray-600 mt-2">
            できている友達に助けを求めることができます
          </p>
        </div>
      </div>
    `
  } catch (error) {
    console.error('コース読み込みエラー:', error)
    alert('データの読み込みに失敗しました')
  }
}

// カード再生成
async function regenerateCards(courseId, curriculumId) {
  if (!confirm('学習カードを再生成します。\nAIが8〜10枚の新しいカードを作成します。\nよろしいですか？')) return
  
  try {
    loadingManager.show('AIが学習カードを生成中...（約2分〜4分）')
    
    const response = await axios.post(`/api/courses/${courseId}/regenerate-cards`, {
      curriculum_id: curriculumId,
      target_count: 10
    }, { timeout: 180000 })
    
    loadingManager.hide()
    
    if (response.data.success) {
      alert(`✅ ${response.data.cards_count || 10}枚のカードを生成しました！`)
      selectCourse(courseId)
    } else {
      alert('カード生成に失敗しました: ' + (response.data.error || '不明なエラー'))
    }
  } catch (error) {
    loadingManager.hide()
    console.error('カード再生成エラー:', error)
    alert('カード再生成に失敗しました。もう一度お試しください。\n' + (error.response?.data?.error || error.message))
  }
}
window.regenerateCards = regenerateCards

// 教師用モードへ遷移
async function loadTeacherOverview(curriculumId) {
  try {
    // カリキュラムとコースデータを取得
    const response = await axios.get(`/api/curriculum/${curriculumId}`)
    const { curriculum, courses } = response.data
    
    // コース選択問題と共通チェックテストをメタデータから取得
    let courseSelectionProblems = []
    let commonCheckTest = null
    try {
      const metaResponse = await axios.get(`/api/curriculum/${curriculumId}/metadata`)
      courseSelectionProblems = metaResponse.data.course_selection_problems || []
      commonCheckTest = metaResponse.data.common_check_test || null
      console.log('✅ メタデータ取得 (教師用):', {
        courseSelectionCount: courseSelectionProblems.length,
        hasCheckTest: !!commonCheckTest
      })
    } catch (metaError) {
      console.warn('⚠️ メタデータ取得エラー:', metaError)
    }
    
    // 選択問題を取得
    const optionalProblemsResponse = await axios.get(`/api/curriculum/${curriculumId}/optional-problems`)
    const optionalProblems = (optionalProblemsResponse.data.optional_problems || []).map(p => {
      if (p.content && typeof p.content === 'string') {
        try { return { ...p, ...JSON.parse(p.content) } } catch (e) { /* */ }
      }
      return p
    })
    
    // 教師用全体確認画面を表示
    showTeacherOverview({ 
      curriculum, 
      courses, 
      optional_problems: optionalProblems,
      course_selection_problems: courseSelectionProblems,
      common_check_test: commonCheckTest
    })
  } catch (error) {
    console.error('教師用モード読み込みエラー:', error)
    alert('教師用モードの読み込みに失敗しました。')
  }
}

// コース学習開始関数
async function startCourseStudy(curriculumId, courseId) {
  try {
    loadingManager.show('学習カードを準備中...')
    
    // キャッシュ判定: stateに同じcurriculumのデータがあればAPIスキップ
    let curriculum, courses
    if (state.selectedCurriculum?.id == curriculumId && state.courses && state.courses.length > 0) {
      console.log('📦 startCourseStudy: キャッシュデータを使用')
      curriculum = state.selectedCurriculum
      courses = state.courses
    } else {
      const response = await axios.get(`/api/curriculum/${curriculumId}`, { timeout: 30000 })
      curriculum = response.data.curriculum
      courses = response.data.courses
    }
    
    // 指定されたコースを探す
    const selectedCourse = courses.find(c => (c.course_id || c.id) === courseId)
    
    if (!selectedCourse) {
      throw new Error('コースが見つかりません')
    }
    
    if (!selectedCourse.cards || selectedCourse.cards.length === 0) {
      throw new Error('このコースにはまだ学習カードがありません')
    }
    
    // state を更新
    state.selectedCurriculum = curriculum
    state.courses = courses
    state.selectedCourse = courseId
    
    // 通常コース学習なので個別最適フラグをクリア
    window._isPersonalizedCourse = false
    window._personalizedCourseId = null
    window._personalizedCurriculumId = null
    
    // カード一覧をグローバルに保存（ページネーション用）
    window._courseCardsList = selectedCourse.cards.map(c => c.card_id || c.id).filter(Boolean)
    window._courseCardsData = selectedCourse.cards
    console.log('📚 コースカード一覧保存:', window._courseCardsList.length, '枚')
    
    // 最初のカードを表示
    const firstCard = selectedCourse.cards[0]
    const cardId = firstCard.card_id || firstCard.id
    
    if (!cardId) {
      throw new Error('カードIDが取得できませんでした')
    }
    
    console.log('🎴 カード表示開始:', { cardId, card_title: firstCard.card_title })
    
    loadingManager.hide()
    
    // loadCardPage を使用してカードを表示
    loadCardPage(cardId)
    
  } catch (error) {
    console.error('コース学習開始エラー:', error)
    loadingManager.hide()
    alert('学習カードの読み込みに失敗しました: ' + error.message)
  }
}

