// ============================================
// 学習カードページ
// ============================================
async function loadCardPage(cardId) {
  state.currentView = 'card'
  state.selectedCard = cardId
  
  try {
    const response = await axios.get(`/api/cards/${cardId}`)
    const { card, hints, answer } = response.data
    
    // カードデータにヒントと解答を含める
    // 空のヒント（hint_text/hint_contentが空）をフィルタリング
    const validHints = (hints || []).filter(h => (h.hint_content || h.hint_text || '').trim().length > 0)
    card.hints = validHints
    card.answer = answer?.answer_text || card.correct_answer || card.answer || card.example_solution || ''
    card.answer_explanation = answer?.explanation || card.answer_explanation || card.explanation || ''
    
    // カードデータをグローバルに保存（ヘルプ要請時に使用）
    window.currentCardData = card
    
    // 学年別のフォントサイズを取得
    const grade = state.selectedCurriculum?.grade || '小学3年'
    const defaultFontSize = getGradeFontSize(grade)
    
    // AI先生用に学年情報を保存（会話時に使用）
    if (!window.aiDetectedGrade && grade) {
      window.aiDetectedGrade = grade
      console.log('学年情報を設定:', window.aiDetectedGrade)
    }
    
    // problem_contentがJSON形式の場合パースしてカードデータを補完
    parseProblemContentJSON(card)
    
    // ローカルストレージから保存されたフォントサイズを取得
    const savedFontSize = localStorage.getItem('customFontSize')
    const fontSize = savedFontSize ? JSON.parse(savedFontSize) : defaultFontSize
    
    const app = document.getElementById('app')
    app.innerHTML = `
      <style>
        .card-content {
          font-size: ${fontSize.base}px;
          line-height: 1.8;
        }
        .card-title {
          font-size: ${fontSize.title}px;
        }
        .card-heading {
          font-size: ${fontSize.heading}px;
        }
        /* テキスト入力カーソルを黒に設定 */
        input[type="text"],
        input[type="number"],
        input[type="email"],
        input[type="password"],
        textarea {
          caret-color: #000000 !important;
        }
      </style>
      <div class="container mx-auto px-4 py-8">
        <!-- ページネーションナビ（上部） -->
        ${(() => {
          const cardsList = window._courseCardsList || []
          const currentIdx = cardsList.indexOf(card.card_id || card.id)
          const total = cardsList.length || Math.max(card.card_number || 1, 1)
          const num = currentIdx >= 0 ? currentIdx + 1 : (card.card_number || 1)
          const prevId = currentIdx > 0 ? cardsList[currentIdx - 1] : null
          const nextId = currentIdx >= 0 && currentIdx < cardsList.length - 1 ? cardsList[currentIdx + 1] : null
          return `
          <div class="bg-gradient-to-r from-indigo-500 to-blue-600 rounded-xl shadow-lg p-4 mb-4 text-white">
            <div class="flex items-center justify-between">
              ${prevId ? `
              <button onclick="loadCardPage(${prevId})" 
                      class="flex items-center gap-2 bg-white bg-opacity-20 hover:bg-opacity-30 px-4 py-2 rounded-lg transition font-bold text-sm">
                <i class="fas fa-chevron-left"></i>
                前のカード
              </button>
              ` : (window._isPersonalizedCourse ? `
              <div class="flex flex-col gap-1">
                <button onclick="goBackToPersonalizedGuide()" 
                        class="flex items-center gap-2 bg-white bg-opacity-20 hover:bg-opacity-30 px-3 py-1.5 rounded-lg transition font-bold text-xs">
                  <i class="fas fa-chevron-left"></i>
                  <i class="fas fa-user-graduate mr-1"></i>個別のてびき
                </button>
                <button onclick="goBackToMainGuide()" 
                        class="flex items-center gap-2 bg-white bg-opacity-10 hover:bg-opacity-20 px-3 py-1.5 rounded-lg transition font-bold text-xs">
                  <i class="fas fa-chevron-left"></i>
                  <i class="fas fa-book mr-1"></i>全体のてびき
                </button>
              </div>
              ` : `
              <button onclick="goBackToGuide()" 
                      class="flex items-center gap-2 bg-white bg-opacity-20 hover:bg-opacity-30 px-4 py-2 rounded-lg transition font-bold text-sm">
                <i class="fas fa-chevron-left"></i>
                てびきに戻る
              </button>
              `)}
              <div class="text-center">
                <div class="flex items-center gap-2 justify-center">
                  ${cardsList.map((_, i) => '<div class="w-3 h-3 rounded-full ' + (i === currentIdx ? 'bg-white shadow-lg scale-125' : 'bg-white bg-opacity-40') + ' transition-all"></div>').join('')}
                </div>
                <p class="text-xs mt-1 opacity-90">${num} / ${total} まいめ</p>
              </div>
              <button onclick="${nextId ? 'loadCardPage(' + nextId + ')' : ''}" 
                      class="flex items-center gap-2 ${nextId ? 'bg-white bg-opacity-20 hover:bg-opacity-30' : 'bg-white bg-opacity-10 cursor-not-allowed'} px-4 py-2 rounded-lg transition font-bold text-sm"
                      ${nextId ? '' : 'disabled'}>
                ${nextId ? '次のカード' : '最後のカード'}
                <i class="fas fa-chevron-right"></i>
              </button>
            </div>
          </div>`
        })()}

        <!-- ヘッダー -->
        <div class="bg-white rounded-lg shadow-lg p-6 mb-6">
          <div class="flex items-center justify-between">
            <div>
              <h1 class="text-3xl font-bold text-indigo-600 mb-2">
                <i class="fas fa-bookmark mr-2"></i>カード ${card.card_number}
              </h1>
              <h2 class="card-title text-gray-800">${formatText(card.card_title)}</h2>
              <p class="text-sm text-gray-500 mt-1"><i class="fas fa-book mr-1"></i>${state.selectedCurriculum?.textbook_company || ''} ${state.selectedCurriculum?.grade || ''} ${state.selectedCurriculum?.subject || ''} ― ${state.selectedCurriculum?.unit_name || ''}</p>
            </div>
            <div class="flex items-center gap-3">
              ${state.auth.user?.role === 'teacher' ? `
                <!-- 教師用フォントサイズ設定 -->
                <button onclick="toggleFontSizePanel()" 
                        class="bg-gray-500 hover:bg-gray-600 text-white px-4 py-3 rounded-lg font-bold transition shadow-lg flex flex-col items-center justify-center min-w-[100px]"
                        title="フォントサイズ設定">
                  <i class="fas fa-text-height text-xl mb-1"></i>
                  <span class="text-xs">文字サイズ</span>
                </button>
              ` : ''}
              <!-- ヘルプボタン4つ -->
              <button onclick="showAITeacher()" 
                      class="bg-blue-500 hover:bg-blue-600 text-white px-4 py-3 rounded-lg font-bold transition shadow-lg flex flex-col items-center justify-center min-w-[100px]"
                      title="AI先生に質問">
                <i class="fas fa-robot text-xl mb-1"></i>
                <span class="text-xs">AI先生</span>
              </button>
              <button onclick="callTeacher()" 
                      class="bg-green-500 hover:bg-green-600 text-white px-4 py-3 rounded-lg font-bold transition shadow-lg flex flex-col items-center justify-center min-w-[100px]"
                      title="先生にヘルプを要求">
                <i class="fas fa-chalkboard-teacher text-xl mb-1"></i>
                <span class="text-xs">先生にヘルプ</span>
              </button>
              <button onclick="askFriend()" 
                      class="bg-purple-500 hover:bg-purple-600 text-white px-4 py-3 rounded-lg font-bold transition shadow-lg flex flex-col items-center justify-center min-w-[100px]"
                      title="できている友達を確認">
                <i class="fas fa-user-friends text-xl mb-1"></i>
                <span class="text-xs">友達に聞く</span>
              </button>
              <button onclick="toggleHintPanel()" 
                      class="bg-yellow-500 hover:bg-yellow-600 text-white px-4 py-3 rounded-lg font-bold transition shadow-lg flex flex-col items-center justify-center min-w-[100px]"
                      title="ヒントを見る">
                <i class="fas fa-lightbulb text-xl mb-1"></i>
                <span class="text-xs">ヒント</span>
              </button>
            </div>
          </div>
        </div>

        <!-- 旧ヘルプメニューを削除し、ヒントは別途表示 -->

        <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <!-- メインコンテンツ（左側・中央） -->
          <div class="lg:col-span-2 space-y-6">
            <!-- 新出語句・キーワード -->
            ${card.new_terms ? `
              <div class="bg-blue-50 border-l-4 border-blue-500 rounded-lg p-6">
                <h3 class="card-heading font-bold text-blue-800 mb-3">
                  <i class="fas fa-book mr-2"></i>新しく学ぶこと
                </h3>
                <pre class="card-content text-gray-800 whitespace-pre-wrap font-sans">${card.new_terms}</pre>
              </div>
            ` : ''}

            <!-- AI先生からのメッセージ -->
              <div class="bg-gradient-to-r from-blue-50 to-indigo-50 border-2 border-blue-200 rounded-xl p-4">
                <div class="flex items-start gap-3">
                  <div class="bg-blue-500 text-white rounded-full w-10 h-10 flex items-center justify-center flex-shrink-0">
                    <i class="fas fa-robot"></i>
                  </div>
                  <div>
                    <p class="text-sm font-bold text-blue-800 mb-1"><i class="fas fa-comment-dots mr-1"></i>AI先生より</p>
                    <p class="text-sm text-gray-700 mb-1">${card.ai_teacher_message || 'この問題にチャレンジしてみよう！わからないときは「AI先生」ボタンを押してね。'}</p>
                    ${card.ai_teacher_advice ? `<p class="text-xs text-blue-600"><i class="fas fa-lightbulb mr-1"></i>${card.ai_teacher_advice}</p>` : '<p class="text-xs text-blue-600"><i class="fas fa-lightbulb mr-1"></i>まずは問題をよく読んで、自分の言葉で考えてみよう</p>'}
                    ${card.teacher_help_keywords ? `<p class="text-xs text-gray-500 mt-1"><i class="fas fa-question-circle mr-1"></i>わからないとき先生に聞くキーワード: <strong>${card.teacher_help_keywords}</strong></p>` : ''}
                  </div>
                </div>
              </div>

            <!-- 例題 -->
            ${card.example_problem ? `
              <div class="bg-white rounded-lg shadow-lg p-6">
                <h3 class="card-heading font-bold text-gray-800 mb-4">
                  <i class="fas fa-lightbulb mr-2 text-yellow-500"></i>例題
                </h3>
                <div class="bg-yellow-50 rounded-lg p-4 mb-4">
                  <pre class="card-content text-gray-800 whitespace-pre-wrap font-sans font-bold">${formatText(card.example_problem)}</pre>
                  <div id="example-diagram-card-${card.card_id || card.id || 0}" class="mt-2">
                    ${card.example_image_url ? `<div class="text-center mt-2"><img src="${card.example_image_url}" alt="例題の図" class="max-h-48 rounded border mx-auto"></div>` : `
                    <div class="flex items-center gap-2 mt-2 p-2 bg-yellow-100 rounded-lg">
                      <i class="fas fa-image text-yellow-600"></i>
                      <span class="text-xs text-yellow-800 font-bold">この例題は図があるとわかりやすい</span>
                      <button onclick="generateExampleDiagramApp('${(card.card_id || card.id || 0)}', '${(card.card_title||'').replace(/'/g,'')}', '${(card.example_problem||'').replace(/'/g,'').substring(0,100)}', '${(card.example_solution||'').replace(/'/g,'').substring(0,100)}')" class="ml-auto bg-gradient-to-r from-yellow-500 to-orange-500 text-white px-3 py-1 rounded-lg text-xs font-bold shadow hover:shadow-md transition">
                        <i class="fas fa-wand-magic-sparkles mr-1"></i>AIに図をかいてもらう
                      </button>
                    </div>`}
                  </div>
                </div>
                ${card.example_solution ? `
                  <div class="bg-green-50 rounded-lg p-4">
                    <h4 class="card-heading font-bold text-green-800 mb-2">
                      <i class="fas fa-check-circle mr-2"></i>解き方
                    </h4>
                    <pre class="card-content text-gray-800 whitespace-pre-wrap font-sans">${formatText(card.example_solution)}</pre>
                  </div>
                ` : ''}
              </div>
            ` : ''}

            <!-- 問題 -->
            <div class="bg-white rounded-xl shadow-xl p-6 border-2 border-indigo-200 relative overflow-hidden">
              <!-- 問題マーク大型バッジ -->
              <div class="absolute -top-1 -left-1 bg-gradient-to-br from-red-500 to-pink-600 text-white px-6 py-2 rounded-br-2xl shadow-lg z-10">
                <span class="text-lg font-black tracking-wider"><i class="fas fa-pencil-alt mr-2"></i>もんだい</span>
              </div>
              <div class="h-8"></div>
              
              ${card.real_world_context ? `
                <div class="bg-indigo-50 rounded-xl p-4 mb-4 flex items-start border border-indigo-200">
                  <i class="fas fa-globe mr-2 text-indigo-600 mt-1 text-lg"></i>
                  <p class="text-base text-indigo-800">${card.real_world_context}</p>
                </div>
              ` : ''}
              
              <!-- もんだい：大きく目立つ問題文 -->
              <div class="bg-gradient-to-br from-yellow-50 via-orange-50 to-pink-50 border-4 border-orange-400 rounded-2xl p-6 mb-4 shadow-inner relative">
                <div class="absolute top-2 right-2 flex gap-1">
                  <button onclick="readCardAloud()" class="bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-bold px-2 py-1 rounded-full cursor-pointer transition shadow-sm" title="問題を読み上げる"><i class="fas fa-volume-up mr-1" id="tts-icon-main"></i>🔊 読み上げ</button>
                  <span class="bg-orange-400 text-white text-xs font-bold px-2 py-1 rounded-full"><i class="fas fa-question-circle mr-1"></i>よく読もう</span>
                </div>
                <pre class="card-content text-gray-900 whitespace-pre-wrap font-sans leading-loose font-bold" style="font-size: 1.4em;">${formatText(card.problem_text || card.problem_content || card.problem_description || '')}</pre>
              </div>
              
              <!-- 問題の説明（problem_descriptionがproblem_textと異なる場合） -->
              ${(card.problem_description && card.problem_description !== card.problem_text && card.problem_description !== card.problem_content) ? `
                <div class="bg-gray-50 rounded-lg p-4 mb-4">
                  <pre class="card-content text-gray-700 whitespace-pre-wrap font-sans leading-relaxed">${formatText(card.problem_description)}</pre>
                </div>
              ` : ''}
              
              <!-- 動画ボタン（NHK for School / YouTube） -->
              ${(() => {
                const vUrl = card.solution_video_url || ''
                const ytTitle = card._youtube_title || ''
                if (vUrl.includes('youtube.com/results') || vUrl.includes('nhk.or.jp')) {
                  const displayTitle = ytTitle || (card.card_title || '').replace(/[！!？?「」『』（）()【】]/g, '').substring(0, 30)
                  return '<div class="mb-4"><a href="' + vUrl + '" target="_blank" rel="noopener" class="inline-flex items-center gap-2 bg-red-500 hover:bg-red-600 text-white px-5 py-3 rounded-xl font-bold transition shadow-sm text-sm"><i class="fas fa-play-circle"></i>▶ ' + displayTitle + ' を見る</a></div>'
                }
                return ''
              })()}
              
              <!-- きいてみよう（音声読み上げ） - 全カードで常に表示 -->
              <div class="bg-green-50 border-l-3 border-green-400 p-3 rounded mb-4 flex items-center gap-3 cursor-pointer hover:bg-green-100 transition"
                   onclick="readCardAloud()">
                <i class="fas fa-volume-up text-green-600 text-lg" id="tts-icon-listen"></i>
                <div>
                  <span class="font-bold text-green-800 text-sm">🔊 きいてみよう：</span>
                  <span class="text-green-700 text-sm">${card._audio_instruction || '問題文をタップして読み上げます'}</span>
                </div>
                <span class="ml-auto bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-full flex-shrink-0">▶ タップ</span>
              </div>
              
              <!-- 図の説明 -->
              ${card._image_description ? `
                <div class="bg-blue-50 border-l-3 border-blue-400 p-3 rounded mb-4 flex items-center gap-3">
                  <i class="fas fa-image text-blue-500"></i>
                  <span class="text-blue-800 text-sm"><strong>🖼 図：</strong>${card._image_description}</span>
                </div>
              ` : ''}
              
              <!-- 問題画像/動画/音声 -->
              ${card.problem_image_url ? 
                renderMediaEmbed(card.problem_image_url, card.card_id || card.id || 0, card._image_description || '問題の図')
              : (() => {
                // イラスト説明があるが画像がない場合のプレースホルダー + AI生成ボタン
                const rawImgDesc = card._image_description || ''
                // プレースホルダー的なテキストを除外（実際の図の説明のみ表示）
                const isPlaceholderText = /用意されていません|まだありません|画像を追加|図が必要です|必要ですが/.test(rawImgDesc)
                const imgDesc = isPlaceholderText ? '' : rawImgDesc
                const problemText = card.problem_content || card.problem_text || ''
                const cardTitle = card.card_title || ''
                const cardIdVal = card.card_id || card.id || 0
                const subject = card.subject || ''
                const unitName = card.unit_name || ''
                
                // --- スマートAI生成プロンプトを問題内容から自動構築 ---
                const smartPromptParts = []
                if (imgDesc) {
                  smartPromptParts.push(imgDesc)
                } else {
                  // 問題文のキーワードから最適な図の種類を推定
                  const pt = (problemText + ' ' + cardTitle + ' ' + unitName).toLowerCase()
                  if (/折れ線グラフ|折れ線/.test(pt)) smartPromptParts.push('折れ線グラフ')
                  else if (/棒グラフ/.test(pt)) smartPromptParts.push('棒グラフ')
                  else if (/円グラフ/.test(pt)) smartPromptParts.push('円グラフ')
                  else if (/表を見|表を読/.test(pt)) smartPromptParts.push('データ表')
                  else if (/数直線/.test(pt)) smartPromptParts.push('数直線')
                  else if (/地図|都道府県|地形/.test(pt)) smartPromptParts.push('地図・地理図')
                  else if (/図形|三角|四角|平行|台形|ひし形|円/.test(pt)) smartPromptParts.push('図形の説明図')
                  else if (/面積|体積|展開図/.test(pt)) smartPromptParts.push('面積・体積の図解')
                  else if (/角度|分度器/.test(pt)) smartPromptParts.push('角度の図')
                  else if (/時計|時刻|時間/.test(pt)) smartPromptParts.push('時計の図')
                  else if (/温度|気温|天気/.test(pt)) smartPromptParts.push('気温・天気の図')
                  else if (/比例|反比例/.test(pt)) smartPromptParts.push('比例のグラフ')
                  else if (/分数/.test(pt)) smartPromptParts.push('分数の図解')
                  else if (/小数/.test(pt)) smartPromptParts.push('小数の図解')
                  else if (/植物|花|葉|茎|根/.test(pt)) smartPromptParts.push('植物の観察図')
                  else if (/昆虫|虫|動物/.test(pt)) smartPromptParts.push('生物の図鑑イラスト')
                  else if (/天体|月|星|太陽/.test(pt)) smartPromptParts.push('天体の図')
                  else if (/電気|回路|磁石/.test(pt)) smartPromptParts.push('回路・実験の図')
                  else if (/漢字/.test(pt)) smartPromptParts.push('漢字の書き順イラスト')
                  else smartPromptParts.push(cardTitle || unitName || '学習内容の図解')
                  
                  // 文脈を追加
                  if (cardTitle && !smartPromptParts[0].includes(cardTitle.substring(0, 10))) {
                    smartPromptParts.push(cardTitle.substring(0, 30))
                  }
                }
                const aiDesc = smartPromptParts.join(' - ').replace(/'/g, '').replace(/\n/g, ' ').substring(0, 120)
                
                // 図の種類を推定してアイコンを選択
                const ptLower = (problemText + cardTitle).toLowerCase()
                let placeholderIcon = 'fa-image'
                let placeholderColor = 'yellow'
                if (/グラフ|表/.test(ptLower)) { placeholderIcon = 'fa-chart-line'; placeholderColor = 'blue' }
                else if (/図形|面積|体積/.test(ptLower)) { placeholderIcon = 'fa-shapes'; placeholderColor = 'green' }
                else if (/地図|都道府県/.test(ptLower)) { placeholderIcon = 'fa-map-marked-alt'; placeholderColor = 'indigo' }
                else if (/植物|動物|昆虫/.test(ptLower)) { placeholderIcon = 'fa-leaf'; placeholderColor = 'emerald' }
                else if (/天体|月|星/.test(ptLower)) { placeholderIcon = 'fa-moon'; placeholderColor = 'purple' }
                else if (/電気|回路/.test(ptLower)) { placeholderIcon = 'fa-bolt'; placeholderColor = 'amber' }
                
                const bgGradient = placeholderColor === 'blue' ? 'from-blue-50 to-indigo-50' :
                                   placeholderColor === 'green' ? 'from-green-50 to-emerald-50' :
                                   placeholderColor === 'indigo' ? 'from-indigo-50 to-purple-50' :
                                   placeholderColor === 'purple' ? 'from-purple-50 to-pink-50' :
                                   placeholderColor === 'amber' ? 'from-amber-50 to-yellow-50' :
                                   'from-yellow-50 to-orange-50'
                const borderColor = placeholderColor === 'blue' ? 'border-blue-300' :
                                    placeholderColor === 'green' ? 'border-green-300' :
                                    placeholderColor === 'indigo' ? 'border-indigo-300' :
                                    placeholderColor === 'purple' ? 'border-purple-300' :
                                    placeholderColor === 'amber' ? 'border-amber-300' :
                                    'border-yellow-300'
                const iconBg = placeholderColor === 'blue' ? 'bg-blue-100 text-blue-500' :
                               placeholderColor === 'green' ? 'bg-green-100 text-green-500' :
                               placeholderColor === 'indigo' ? 'bg-indigo-100 text-indigo-500' :
                               placeholderColor === 'purple' ? 'bg-purple-100 text-purple-500' :
                               placeholderColor === 'amber' ? 'bg-amber-100 text-amber-500' :
                               'bg-yellow-100 text-yellow-500'
                
                return `<div class="mt-4 bg-gradient-to-br ${bgGradient} border-2 ${borderColor} rounded-2xl p-6 text-center shadow-md relative overflow-hidden" id="image-placeholder-${cardIdVal}">
                  <!-- 背景装飾 -->
                  <div class="absolute top-0 right-0 w-32 h-32 opacity-5">
                    <i class="fas ${placeholderIcon}" style="font-size: 8rem;"></i>
                  </div>
                  
                  <div class="relative z-10">
                    <!-- アイコンとメッセージ -->
                    <div class="mb-4">
                      <div class="inline-flex items-center justify-center w-20 h-20 ${iconBg} rounded-full mb-3 shadow-inner">
                        <i class="fas ${placeholderIcon} text-4xl"></i>
                      </div>
                      ${imgDesc ? '<p class="text-base text-gray-800 font-bold mb-2"><i class="fas fa-info-circle text-blue-500 mr-1"></i>' + imgDesc + '</p>' : ''}
                      <p class="text-base font-bold text-gray-700 mb-1">${imgDesc ? 'この図をすぐに追加できます！' : 'この問題に合った図を追加しましょう！'}</p>
                      <p class="text-sm text-gray-500">AI自動生成 or 先生が画像を挿入</p>
                    </div>
                    
                    <!-- メインアクションボタン -->
                    <div class="flex flex-col gap-3 max-w-sm mx-auto mb-4">
                      <button onclick="openPromptImageGenerate(${cardIdVal}, 'replace')"
                              class="group relative flex items-center justify-center gap-3 bg-gradient-to-r from-purple-500 via-pink-500 to-rose-500 hover:from-purple-600 hover:via-pink-600 hover:to-rose-600 text-white px-8 py-4 rounded-2xl font-bold text-lg transition-all duration-300 shadow-lg hover:shadow-xl transform hover:scale-105 hover:-translate-y-0.5"
                              style="animation: pulse 2s infinite;">
                        <i class="fas fa-wand-magic-sparkles text-xl group-hover:animate-spin"></i>
                        <span>AIで図を自動生成</span>
                        <i class="fas fa-arrow-right text-sm opacity-70 group-hover:translate-x-1 transition-transform"></i>
                      </button>
                      
                      <!-- ファイル直接追加ボタン行 -->
                      <div class="flex gap-2">
                        <button onclick="openFilePickerForCard(${cardIdVal})"
                                class="flex-1 flex items-center justify-center gap-2 bg-white hover:bg-orange-50 text-orange-600 border-2 border-orange-300 hover:border-orange-400 px-4 py-3 rounded-xl font-bold text-sm transition-all shadow-sm hover:shadow-md">
                          <i class="fas fa-file-image"></i>
                          <span>JPG / PDF を選択</span>
                        </button>
                        <button onclick="quickPasteImageUrl(${cardIdVal})"
                                class="flex-1 flex items-center justify-center gap-2 bg-white hover:bg-green-50 text-green-600 border-2 border-green-300 hover:border-green-400 px-4 py-3 rounded-xl font-bold text-sm transition-all shadow-sm hover:shadow-md">
                          <i class="fas fa-paste"></i>
                          <span>URL貼り付け</span>
                        </button>
                      </div>
                      
                      <!-- ドラッグ&ドロップ案内 -->
                      <div class="border-2 border-dashed border-gray-300 rounded-xl py-3 px-4 text-center bg-white bg-opacity-50 hover:border-purple-400 hover:bg-purple-50 transition-all cursor-pointer"
                           onclick="openFilePickerForCard(${cardIdVal})">
                        <p class="text-xs text-gray-500">
                          <i class="fas fa-cloud-upload-alt text-gray-400 mr-1"></i>
                          ここに<strong>ファイルをドラッグ&ドロップ</strong>、<strong>Ctrl+V</strong>、または<strong>右クリック→貼り付け</strong>で画像を追加
                        </p>
                        <p class="text-xs text-gray-400 mt-0.5">JPG・PNG・PDF 対応（10MBまで）・右クリックで貼り付け可</p>
                      </div>
                    </div>
                    
                    <!-- 説明 -->
                    <div class="bg-white bg-opacity-70 rounded-xl p-3 text-left max-w-sm mx-auto">
                      <p class="text-xs text-gray-600 flex items-start gap-2">
                        <i class="fas fa-robot text-purple-500 mt-0.5 flex-shrink-0"></i>
                        <span><strong>AI自動生成：</strong>ボタンを押すと「<em class="text-purple-700">${aiDesc.substring(0, 40)}</em>」の図をAIが自動で描きます</span>
                      </p>
                      <p class="text-xs text-gray-600 flex items-start gap-2 mt-1">
                        <i class="fas fa-file-image text-orange-500 mt-0.5 flex-shrink-0"></i>
                        <span><strong>ファイル追加：</strong>手持ちのJPG・PNG・PDFをドラッグ&ドロップまたは選択で即挿入</span>
                      </p>
                    </div>
                  </div>
                </div>`
              })()}
              
              <!-- 複数メディアギャラリー（画像・動画・音声） -->
              <div id="media-gallery-${card.card_id || card.id || 0}" class="mt-3"></div>
              <script>
                (function(){
                  const cid = ${card.card_id || card.id || 0};
                  if (cid && typeof loadMediaGallery === 'function') {
                    setTimeout(() => loadMediaGallery(cid), 200);
                  }
                })();
              </script>
              
              <!-- インタラクティブ触覚ウィジェット -->
              ${(() => {
                const tactile = card._tactile_activity || ''
                if (!tactile) return ''
                const cardIdVal = card.card_id || card.id || 0
                const widgetContainerId = 'tactile-widget-' + cardIdVal
                return '<div class="mt-4 bg-gradient-to-br from-orange-50 to-yellow-50 border-2 border-orange-300 rounded-xl p-4 shadow-sm relative" id="' + widgetContainerId + '-wrapper">' +
                  '<div class="flex items-center gap-2 mb-3">' +
                    '<span class="bg-orange-500 text-white text-sm font-bold px-3 py-1 rounded-full"><i class="fas fa-hand-sparkles mr-1"></i>やってみよう</span>' +
                    '<span class="text-sm font-bold text-gray-700">' + tactile + '</span>' +
                    '<button onclick="this.closest(\'[id$=-wrapper]\').style.display=\'none\'" class="ml-auto text-gray-400 hover:text-red-500 text-xs px-2 py-1 rounded hover:bg-red-50 transition" title="このウィジェットを非表示"><i class="fas fa-times"></i> 非表示</button>' +
                  '</div>' +
                  '<div id="tactile-ai-illust-card-' + cardIdVal + '" class="flex items-center justify-center mb-2 min-h-[80px]"><span class="text-4xl" id="tactile-illust-' + cardIdVal + '"></span></div>' +
                  '<button onclick="generateTactileIllustration(\'tactile-ai-illust-card-' + cardIdVal + '\', \'' + (tactile||'').replace(/'/g, "\\'").substring(0,120) + '\', \'' + (card.subject||'').replace(/'/g, "\\'") + '\', \'' + (card.grade||'').replace(/'/g, "\\'") + '\')" class="inline-flex items-center gap-1 bg-gradient-to-r from-orange-500 to-yellow-500 text-white px-3 py-1.5 rounded-lg text-xs font-bold shadow hover:shadow-md transition mb-2"><i class="fas fa-image"></i>AIにイラストを描いてもらう</button>' +
                  '<div id="' + widgetContainerId + '" class="bg-white rounded-lg border border-gray-200 overflow-hidden min-h-[200px] relative"></div>' +
                  '<p class="text-xs text-gray-500 mt-2 text-center"><i class="fas fa-hand-pointer mr-1"></i>画面をタッチ・ドラッグして操作してみよう</p>' +
                  '<script>try{var _ti=document.getElementById("tactile-illust-' + cardIdVal + '");if(_ti&&typeof getTactileIllustration==="function"){_ti.textContent=getTactileIllustration("' + (tactile||'').replace(/"/g,'\\"').replace(/\n/g,' ').substring(0,100) + '",window.currentCardData?.card).icons}}catch(e){}</script>' +
                '</div>'
              })()}
              
              <!-- 動画コンテンツ / 外部リンク（YouTube / NHK / Gemini等） -->
              ${(() => {
                const vUrl = card.solution_video_url || ''
                const ytRegex = new RegExp('(?:v=|youtu\\.be/)([^&?]+)')
                const ytMatch = vUrl.match(ytRegex)
                const ytId = ytMatch ? ytMatch[1] : ''
                if (ytId) {
                  return '<div class="mt-4 rounded-xl overflow-hidden border-2 border-gray-200 shadow-sm"><div style="position:relative;padding-bottom:56.25%;height:0;overflow:hidden;"><iframe style="position:absolute;top:0;left:0;width:100%;height:100%;" src="https://www.youtube.com/embed/' + ytId + '?rel=0" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div><div class="p-2 bg-gray-50 flex items-center justify-between"><p class="text-xs text-gray-500"><i class="fas fa-video mr-1"></i>学習動画：一時停止しながら考えてみよう</p><button onclick="deleteCardMedia(' + (card.card_id||card.id||0) + ')" class="text-xs text-red-500 hover:text-red-700"><i class="fas fa-trash mr-1"></i>削除</button></div></div>'
                } else if (vUrl.includes('nhk.or.jp') || vUrl.includes('youtube.com/results')) {
                  const cardTitle = (card.card_title || card.unit_name || '').replace(/[！!？?「」『』（）()【】]/g, '').substring(0, 20)
                  const nhkSearchUrl = 'https://edu.web.nhk/school/?q=' + encodeURIComponent(cardTitle)
                  const ytSearchUrl = 'https://www.youtube.com/results?search_query=' + encodeURIComponent('NHK for School ' + cardTitle)
                  return '<div class="mt-4 bg-gradient-to-r from-blue-50 to-indigo-50 border-2 border-blue-300 rounded-xl p-5 shadow-sm"><div class="flex items-center gap-3 mb-4"><span class="bg-blue-600 text-white text-sm font-bold px-4 py-1.5 rounded-full"><i class="fas fa-tv mr-1"></i>NHK for School</span><span class="text-base font-bold text-gray-800">関連する学習動画</span></div><div class="bg-white rounded-xl p-6 text-center border-2 border-blue-200"><i class="fas fa-play-circle text-5xl text-blue-500 mb-4 block"></i><p class="text-sm text-gray-700 mb-4">関連する学習動画を見て学習を深めましょう！</p><div class="flex flex-col sm:flex-row gap-3 justify-center"><a href="' + ytSearchUrl + '" target="_blank" rel="noopener" class="inline-flex items-center gap-2 bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-xl font-bold transition shadow-lg"><i class="fab fa-youtube"></i>YouTubeで動画を探す</a><a href="' + nhkSearchUrl + '" target="_blank" rel="noopener" class="inline-flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold transition shadow-lg"><i class="fas fa-external-link-alt"></i>NHK for School で探す</a></div></div></div>'
                } else if (vUrl.includes('gemini.google.com')) {
                  // Gemini共有リンク
                  return '<div class="mt-4 bg-gradient-to-br from-purple-50 to-indigo-50 border-2 border-purple-300 rounded-xl p-5 shadow-sm text-center"><div class="mb-3"><i class="fas fa-sparkles text-purple-500 text-4xl"></i></div><p class="text-sm font-bold text-purple-800 mb-3">Gemini共有リンク（問題を確認しよう）</p><a href="' + vUrl + '" target="_blank" rel="noopener" class="inline-flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-8 py-4 rounded-xl font-bold transition shadow-lg text-base"><i class="fas fa-external-link-alt"></i>Geminiを開いて問題を見る</a><div class="mt-3 flex items-center justify-center gap-2"><button onclick="deleteCardMedia(' + (card.card_id||card.id||0) + ')" class="text-xs text-red-500 hover:text-red-700"><i class="fas fa-trash mr-1"></i>削除</button></div></div>'
                } else if (vUrl) {
                  // その他のURL（一般的な外部リンク）
                  return '<div class="mt-4 bg-gradient-to-br from-gray-50 to-blue-50 border-2 border-gray-300 rounded-xl p-4 shadow-sm text-center"><a href="' + vUrl + '" target="_blank" rel="noopener" class="inline-flex items-center gap-2 bg-blue-500 hover:bg-blue-600 text-white px-5 py-3 rounded-lg font-bold transition shadow-sm"><i class="fas fa-external-link-alt text-lg"></i>参考資料を開く</a><div class="mt-2"><button onclick="deleteCardMedia(' + (card.card_id||card.id||0) + ')" class="text-xs text-red-500 hover:text-red-700"><i class="fas fa-trash mr-1"></i>削除</button></div></div>'
                }
                return ''
              })()}
              
              <!-- 回答欄 -->
              <div class="mt-6 bg-gradient-to-br from-blue-50 to-indigo-50 border-2 border-blue-300 rounded-2xl p-5">
                <label class="block text-lg font-black text-blue-800 mb-3"><i class="fas fa-pen-fancy mr-2"></i>こたえを書こう！</label>
                
                <!-- タブ切り替え -->
                <div class="flex gap-2 mb-2">
                  <button onclick="switchAnswerMode('text')" 
                          id="textModeBtn"
                          class="flex-1 bg-blue-500 text-white px-4 py-2 rounded-lg font-bold hover:bg-blue-600 transition">
                    <i class="fas fa-keyboard mr-2"></i>文字入力
                  </button>
                  <button onclick="switchAnswerMode('handwriting')" 
                          id="handwritingModeBtn"
                          class="flex-1 bg-gray-300 text-gray-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-400 transition">
                    <i class="fas fa-pen mr-2"></i>手書き入力
                  </button>
                </div>
                
                <!-- 文字入力エリア -->
                <div id="textAnswerArea">
                  <textarea id="answerInput" 
                            rows="6" 
                            class="w-full p-4 border-2 border-gray-300 rounded-lg focus:border-indigo-500 focus:outline-none focus:ring-2 focus:ring-indigo-200 text-lg"
                            style="font-size: 20px; line-height: 2.0; resize: vertical; min-height: 180px; caret-color: #000000; cursor: text; color: #1a1a1a; background-color: #ffffff; -webkit-user-select: text; user-select: text; -webkit-appearance: none; position: relative; z-index: 10; pointer-events: auto; touch-action: auto; -webkit-text-fill-color: #1a1a1a; opacity: 1;"
                            placeholder="ここをタップ（クリック）して答えを書いてください"
                            autocomplete="off"
                            autocorrect="off"
                            spellcheck="false"
                            inputmode="text"
                            ></textarea>
                  <p class="text-xs text-gray-400 mt-1"><i class="fas fa-keyboard mr-1"></i>キーボードで入力できます。タップ（クリック）してから入力してください。</p>
                </div>
                
                <!-- 手書き入力エリア -->
                <div id="handwritingAnswerArea" class="hidden">
                  <div class="bg-white border-2 border-blue-300 rounded-lg p-4">
                    <div class="flex justify-between items-center mb-2">
                      <h4 class="font-bold text-gray-800">
                        <i class="fas fa-pen mr-2"></i>指やタッチペンで書こう
                      </h4>
                      <div class="flex gap-2">
                        <button onclick="undoAnswerHandwriting()" 
                                class="bg-orange-500 hover:bg-orange-600 text-white px-3 py-1 rounded text-sm">
                          <i class="fas fa-undo mr-1"></i>1画戻す
                        </button>
                        <button onclick="recognizeAnswerHandwriting()" 
                                class="bg-purple-500 hover:bg-purple-600 text-white px-3 py-1 rounded text-sm">
                          <i class="fas fa-magic mr-1"></i>認識
                        </button>
                        <button onclick="clearAnswerHandwriting()" 
                                class="bg-gray-500 hover:bg-gray-600 text-white px-3 py-1 rounded text-sm">
                          <i class="fas fa-eraser mr-1"></i>全消去
                        </button>
                      </div>
                    </div>
                    <canvas id="answerCanvas" 
                            width="800" 
                            height="400" 
                            class="border-2 border-gray-300 rounded bg-white w-full touch-none"
                            style="touch-action: none; cursor: crosshair;">
                    </canvas>
                    <p class="text-xs text-gray-600 mt-2">
                      <i class="fas fa-info-circle mr-1"></i>
                      手書きで答えを書いて、「認識」ボタンで文字に変換できます
                    </p>
                  </div>
                </div>
              </div>

              <!-- 分かった度 -->
              <div class="mt-6">
                <label class="block text-sm font-bold text-gray-700 mb-3">今の分かった度</label>
                <div class="flex justify-around">
                  <button onclick="setUnderstanding(1)" 
                          class="understanding-btn flex flex-col items-center p-3 rounded-lg hover:bg-gray-100 transition"
                          data-level="1">
                    <span class="text-4xl">😢</span>
                    <span class="text-xs mt-2">わからない</span>
                  </button>
                  <button onclick="setUnderstanding(2)" 
                          class="understanding-btn flex flex-col items-center p-3 rounded-lg hover:bg-gray-100 transition"
                          data-level="2">
                    <span class="text-4xl">😕</span>
                    <span class="text-xs mt-2">少し難しい</span>
                  </button>
                  <button onclick="setUnderstanding(3)" 
                          class="understanding-btn flex flex-col items-center p-3 rounded-lg hover:bg-gray-100 transition"
                          data-level="3">
                    <span class="text-4xl">😊</span>
                    <span class="text-xs mt-2">だいたいOK</span>
                  </button>
                  <button onclick="setUnderstanding(4)" 
                          class="understanding-btn flex flex-col items-center p-3 rounded-lg hover:bg-gray-100 transition"
                          data-level="4">
                    <span class="text-4xl">😄</span>
                    <span class="text-xs mt-2">よくわかる</span>
                  </button>
                  <button onclick="setUnderstanding(5)" 
                          class="understanding-btn flex flex-col items-center p-3 rounded-lg hover:bg-gray-100 transition"
                          data-level="5">
                    <span class="text-4xl">🤩</span>
                    <span class="text-xs mt-2">完璧！</span>
                  </button>
                </div>
              </div>

              <!-- アクションボタン -->
              <div class="mt-6 space-y-3">
                <!-- 採点ボタン（目立つ） -->
                <button onclick="gradeAnswer('${(card.correct_answer || card.answer || '').replace(/'/g, "\\'").replace(/\n/g, '\\n')}')" 
                        id="gradeBtn"
                        class="w-full bg-gradient-to-r from-green-500 to-emerald-600 text-white py-5 px-6 rounded-2xl font-black text-xl hover:from-green-600 hover:to-emerald-700 transition shadow-xl border-2 border-green-400">
                  <i class="fas fa-check-double mr-2 text-2xl"></i>
                  答え合わせをする
                </button>
                <!-- 採点結果表示エリア -->
                <div id="gradeResult" class="hidden"></div>
                
                <div class="flex gap-3">
                  ${(() => {
                    const cardsList = window._courseCardsList || []
                    const currentIdx = cardsList.indexOf(card.card_id || card.id)
                    const nextId = currentIdx >= 0 && currentIdx < cardsList.length - 1 ? cardsList[currentIdx + 1] : null
                    return `
                  <button onclick="saveProgressAndNext(${nextId || 0})" 
                          class="flex-1 bg-gradient-to-r from-indigo-600 to-blue-600 text-white py-4 px-4 rounded-xl font-black hover:from-indigo-700 hover:to-blue-700 transition text-base shadow-lg">
                    <i class="fas fa-arrow-right mr-2"></i>
                    ${nextId ? '保存して次のカードへ' : '保存して終了'}
                  </button>`
                  })()}
                  <button onclick="showAnswer()" 
                          class="flex-1 bg-gray-500 text-white py-4 px-4 rounded-xl font-bold hover:bg-gray-600 transition text-base">
                    <i class="fas fa-eye mr-2"></i>
                    解答を見る
                  </button>
                </div>
              </div>
            </div>

            <!-- 解答表示エリア（非表示） -->
            ${(answer || card.answer || card.example_solution) ? `
              <div id="answerSection" class="hidden bg-green-50 border-l-4 border-green-500 rounded-lg p-6">
                <h3 class="text-lg font-bold text-green-800 mb-4">
                  <i class="fas fa-check-circle mr-2"></i>解答
                </h3>
                <div class="bg-white rounded-lg p-4 mb-4">
                  <div class="text-gray-800 whitespace-pre-wrap font-sans" style="line-height: 1.8;">${(() => {
                    const mainAnswer = answer?.answer_content || card.answer || card.example_solution || '解答は準備中です'
                    let keywords = card.answer_keywords || []
                    if (typeof keywords === 'string') { try { keywords = JSON.parse(keywords) } catch(e) { keywords = [] } }
                    // answer_keywordsに含まれるがmainAnswerに含まれないキーワードを補足表示
                    const missingKw = keywords.filter(kw => kw && !mainAnswer.includes(kw))
                    const extra = missingKw.length > 0 ? '<div class="mt-2 text-sm text-green-700 bg-green-100 rounded px-3 py-2"><i class="fas fa-plus-circle mr-1"></i>キーワード: ' + missingKw.join('、') + '</div>' : ''
                    return mainAnswer.replace(/\n/g, '<br>') + extra
                  })()}</div>
                </div>
                <div class="bg-blue-50 rounded-lg p-4">
                  <h4 class="font-bold text-blue-800 mb-2">
                    <i class="fas fa-info-circle mr-2"></i>解説
                  </h4>
                  <div class="text-gray-700 whitespace-pre-wrap font-sans" style="line-height: 1.8;">${(answer?.explanation || answer?.answer_explanation || card.answer_explanation || card.explanation || card.example_solution || card.real_world_connection || 'この問題の解説は、先生が編集できます。').replace(/\n/g, '<br>')}</div>
                  ${card.real_world_connection ? `<div class="mt-2 bg-orange-50 rounded-lg p-3"><strong class="text-orange-700">🌍 せいかつとのつながり：</strong><span class="text-gray-700">${card.real_world_connection}</span></div>` : ''}
                </div>
              </div>
            ` : `
              <div id="answerSection" class="hidden bg-gray-50 border-l-4 border-gray-300 rounded-lg p-6">
                <h3 class="text-lg font-bold text-gray-600 mb-4">
                  <i class="fas fa-exclamation-circle mr-2"></i>解答
                </h3>
                <p class="text-gray-600">解答は準備中です</p>
              </div>
            `}
          </div>

          <!-- サイドバー（右側） -->
          <div class="lg:col-span-1 space-y-6">
            <!-- ヒントカードエリア -->
            <div id="hintsArea" class="bg-yellow-50 border-l-4 border-yellow-500 rounded-lg p-6">
              <h3 class="text-lg font-bold text-yellow-800 mb-4">
                <i class="fas fa-lightbulb mr-2"></i>3だんかいヒント
              </h3>
              <p class="text-xs text-gray-500 mb-3"><i class="fas fa-info-circle mr-1"></i>こまったときは、ヒントを使ってみよう！ヒント1から順番に見てね。</p>
              <div class="space-y-3">
                ${hints.length > 0 ? hints.map((hint, index) => `
                  <div class="bg-white rounded-lg p-4 border ${index === 0 ? 'border-green-200' : index === 1 ? 'border-yellow-200' : 'border-orange-200'}">
                    <button onclick="toggleHint(${index})" 
                            class="w-full text-left font-bold text-gray-800 hover:text-indigo-600 transition flex items-center justify-between">
                      <span>${index === 0 ? '🟢 ヒント1（考える方向）' : index === 1 ? '🟡 ヒント2（具体的手がかり）' : '🟠 ヒント3（答えに近づく）'}</span>
                      <i class="fas fa-chevron-down"></i>
                    </button>
                    <div id="hint-${index}" class="hidden mt-3 pt-3 border-t">
                      <pre class="text-gray-700 whitespace-pre-wrap font-sans text-sm">${hint.hint_content || hint.hint_text || ''}</pre>
                      ${hint.thinking_tool_suggestion ? `
                        <div class="mt-3 bg-blue-50 rounded p-3">
                          <p class="text-xs font-bold text-blue-800 mb-1">
                            <i class="fas fa-tools mr-1"></i>思考ツール
                          </p>
                          <p class="text-xs text-blue-700">${hint.thinking_tool_suggestion}</p>
                        </div>
                      ` : ''}
                    </div>
                  </div>
                `).join('') : `
                  <div class="bg-white rounded-lg p-4 border border-green-200">
                    <button onclick="toggleHint(0)" class="w-full text-left font-bold text-gray-800 hover:text-indigo-600 transition flex items-center justify-between">
                      <span>🟢 ヒント1（考える方向）</span>
                      <i class="fas fa-chevron-down"></i>
                    </button>
                    <div id="hint-0" class="hidden mt-3 pt-3 border-t">
                      <pre class="text-gray-700 whitespace-pre-wrap font-sans text-sm">まず、問題で何を求められているか確認しましょう。\nキーワードに線を引いてみよう。</pre>
                    </div>
                  </div>
                  <div class="bg-white rounded-lg p-4 border border-yellow-200">
                    <button onclick="toggleHint(1)" class="w-full text-left font-bold text-gray-800 hover:text-indigo-600 transition flex items-center justify-between">
                      <span>🟡 ヒント2（具体的手がかり）</span>
                      <i class="fas fa-chevron-down"></i>
                    </button>
                    <div id="hint-1" class="hidden mt-3 pt-3 border-t">
                      <pre class="text-gray-700 whitespace-pre-wrap font-sans text-sm">図や表に書いて整理してみましょう。\n似ている問題を思い出してみよう。</pre>
                    </div>
                  </div>
                  <div class="bg-white rounded-lg p-4 border border-orange-200">
                    <button onclick="toggleHint(2)" class="w-full text-left font-bold text-gray-800 hover:text-indigo-600 transition flex items-center justify-between">
                      <span>🟠 ヒント3（答えに近づく）</span>
                      <i class="fas fa-chevron-down"></i>
                    </button>
                    <div id="hint-2" class="hidden mt-3 pt-3 border-t">
                      <pre class="text-gray-700 whitespace-pre-wrap font-sans text-sm">もう一度ゆっくり問題を読んでみよう。\nわからないときはAI先生に聞いてみてね！</pre>
                    </div>
                  </div>
                `}
              </div>
            </div>

            <!-- 先生ヘルプエリア -->
            ${card.teacher_help_keywords ? `
              <div class="bg-green-50 border-l-4 border-green-500 rounded-lg p-6">
                <h3 class="text-lg font-bold text-green-800 mb-3">
                  <i class="fas fa-chalkboard-teacher mr-2"></i>先生にきくときのキーワード
                </h3>
                <p class="text-sm text-gray-700">${card.teacher_help_keywords}</p>
                <p class="text-xs text-gray-500 mt-2"><i class="fas fa-hand-point-right mr-1"></i>先生に質問するとき、このキーワードを使うと伝わりやすいよ！</p>
              </div>
            ` : `
              <div class="bg-green-50 border-l-4 border-green-500 rounded-lg p-6">
                <h3 class="text-lg font-bold text-green-800 mb-3">
                  <i class="fas fa-chalkboard-teacher mr-2"></i>先生にきくときのポイント
                </h3>
                <p class="text-sm text-gray-700">「どこが分からないのか」を先生に伝えてみよう！</p>
                <ul class="text-xs text-gray-600 mt-2 space-y-1">
                  <li>💬「この問題の意味がわかりません」</li>
                  <li>💬「ここまで考えたけど、次がわかりません」</li>
                  <li>💬「答えは出たけど、合っているか不安です」</li>
                </ul>
              </div>
            `}

            <!-- AI先生エリア（デフォルト表示） -->
            <div id="aiTeacherArea" class="bg-gradient-to-b from-blue-50 to-indigo-50 border-2 border-blue-300 rounded-xl p-6 shadow-md" style="display:flex;flex-direction:column;max-height:80vh;overflow:hidden;">
              <div class="flex items-center justify-between mb-4">
                <h3 class="text-lg font-black text-blue-800">
                  <i class="fas fa-robot mr-2 text-2xl"></i>AI先生にきいてみよう！
                </h3>
                <button onclick="toggleAutoVoice()" 
                        id="autoVoiceToggle"
                        class="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-2 rounded-lg text-sm font-bold transition"
                        title="音声読み上げON/OFF">
                  <i class="fas fa-volume-mute mr-1"></i>
                  <span id="autoVoiceStatus">読み上げOFF</span>
                </button>
              </div>
              <div id="aiChat" class="space-y-3 mb-4 overflow-y-auto" style="flex:1;min-height:0;">
                <!-- チャットメッセージがここに表示されます -->
              </div>
              
              <!-- 手書き入力エリア -->
              <div id="handwritingArea" class="hidden mb-4 bg-white border-2 border-blue-300 rounded-lg p-4">
                <div class="flex justify-between items-center mb-2">
                  <h4 class="font-bold text-gray-800">
                    <i class="fas fa-pen mr-2"></i>手書きで考えを書こう
                  </h4>
                  <div class="flex gap-2">
                    <button onclick="undoHandwriting()" 
                            class="bg-orange-500 hover:bg-orange-600 text-white px-3 py-1 rounded text-sm">
                      <i class="fas fa-undo mr-1"></i>1画戻す
                    </button>
                    <button onclick="clearHandwriting()" 
                            class="bg-gray-500 hover:bg-gray-600 text-white px-3 py-1 rounded text-sm">
                      <i class="fas fa-eraser mr-1"></i>全消去
                    </button>
                    <button onclick="sendHandwriting()" 
                            class="bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded text-sm">
                      <i class="fas fa-check mr-1"></i>送信
                    </button>
                    <button onclick="closeHandwriting()" 
                            class="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-sm">
                      <i class="fas fa-times mr-1"></i>閉じる
                    </button>
                  </div>
                </div>
                <canvas id="handwritingCanvas" 
                        width="600" 
                        height="300" 
                        class="border-2 border-gray-300 rounded bg-white w-full touch-none"
                        style="touch-action: none; cursor: crosshair;">
                </canvas>
                <p class="text-xs text-gray-600 mt-2">
                  <i class="fas fa-info-circle mr-1"></i>
                  指やタッチペンで自由に書き込めます
                </p>
              </div>
              
              <div class="flex gap-2 items-center" style="align-items:center;">
                <button onclick="startVoiceInput()" 
                        id="voiceButton"
                        class="bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-bold transition flex-shrink-0 flex items-center justify-center"
                        style="width:42px;height:42px;min-width:42px;"
                        title="音声で質問">
                  <i class="fas fa-microphone"></i>
                </button>
                <button onclick="toggleHandwriting()" 
                        id="handwritingButton"
                        class="bg-orange-600 hover:bg-orange-700 text-white rounded-lg font-bold transition flex-shrink-0 flex items-center justify-center"
                        style="width:42px;height:42px;min-width:42px;"
                        title="手書きで入力">
                  <i class="fas fa-pen"></i>
                </button>
                <input type="text" 
                       id="aiQuestionInput" 
                       placeholder="質問を入力..." 
                       class="flex-1 min-w-0 border-2 border-gray-300 rounded-lg focus:border-blue-500 focus:outline-none text-sm"
                       style="padding:8px 12px;height:42px;"
                       onkeypress="if(event.key==='Enter') { event.preventDefault(); askAI(); }">
                <button onclick="askAI()" 
                        id="aiSendBtn"
                        class="bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition flex-shrink-0 flex items-center justify-center"
                        style="width:42px;height:42px;min-width:42px;">
                  <i class="fas fa-paper-plane"></i>
                </button>
              </div>
              
              <!-- 音声認識状態表示 -->
              <div id="voiceStatus" class="hidden mt-2 p-2 bg-purple-100 rounded text-sm text-purple-800">
                <i class="fas fa-microphone animate-pulse mr-2"></i>
                <span id="voiceStatusText">音声を認識中...</span>
              </div>
            </div>

            <!-- 学習のポイント -->
            <div class="bg-indigo-50 rounded-lg p-6">
              <h3 class="text-lg font-bold text-indigo-800 mb-3">
                <i class="fas fa-star mr-2"></i>学習のポイント
              </h3>
              <ul class="text-sm text-gray-700 space-y-2">
                <li class="flex items-start">
                  <i class="fas fa-check-circle text-green-500 mr-2 mt-1"></i>
                  <span>まずは自分で考えてみよう</span>
                </li>
                <li class="flex items-start">
                  <i class="fas fa-check-circle text-green-500 mr-2 mt-1"></i>
                  <span>わからないときは助けを求めよう</span>
                </li>
                <li class="flex items-start">
                  <i class="fas fa-check-circle text-green-500 mr-2 mt-1"></i>
                  <span>間違いは学びのチャンス！</span>
                </li>
              </ul>
            </div>

            <!-- もう1問練習する -->
            <div class="bg-purple-50 rounded-lg p-6">
              <h3 class="text-lg font-bold text-purple-800 mb-3">
                <i class="fas fa-redo mr-2"></i>もっと練習する
              </h3>
              <button onclick="generateAndShowSimilarProblem()" 
                      id="generateSimilarBtn"
                      class="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-bold py-3 px-4 rounded-lg transition shadow-lg">
                <i class="fas fa-magic mr-2"></i>
                もう1問練習する
              </button>
              <p class="text-xs text-gray-600 mt-2">
                AIが似たような問題を作ります
              </p>
            </div>

            <!-- 進捗情報 -->
            <div class="bg-white rounded-lg shadow p-6">
              <h3 class="text-lg font-bold text-gray-800 mb-3">
                <i class="fas fa-chart-line mr-2"></i>あなたの進捗
              </h3>
              <div class="text-sm text-gray-600">
                ${(() => {
                  const cardsList = window._courseCardsList || []
                  const currentIdx = cardsList.indexOf(card.card_id || card.id)
                  const total = cardsList.length || 6
                  const num = currentIdx >= 0 ? currentIdx + 1 : (card.card_number || 1)
                  return `<p class="font-bold">カード ${num} / ${total}</p>
                <div class="w-full bg-gray-200 rounded-full h-3 mt-2">
                  <div class="bg-indigo-600 h-3 rounded-full transition-all" style="width: ${(num / total) * 100}%"></div>
                </div>`
                })()}
              </div>
            </div>
          </div>
        </div>
        
        <!-- 下部ページネーション（固定バー） -->
        ${(() => {
          const cardsList2 = window._courseCardsList || []
          const currentIdx2 = cardsList2.indexOf(card.card_id || card.id)
          const prevId2 = currentIdx2 > 0 ? cardsList2[currentIdx2 - 1] : null
          const nextId2 = currentIdx2 >= 0 && currentIdx2 < cardsList2.length - 1 ? cardsList2[currentIdx2 + 1] : null
          return `
        <div class="mt-6 bg-white rounded-xl shadow-xl p-4 border-2 border-indigo-200 sticky bottom-4 z-40">
          <div class="flex items-center justify-between">
            ${prevId2 ? `
            <button onclick="loadCardPage(${prevId2}); window.scrollTo(0,0);" 
                    class="flex items-center gap-2 bg-indigo-500 hover:bg-indigo-600 text-white px-5 py-3 rounded-xl transition font-bold text-sm">
              <i class="fas fa-chevron-left"></i>
              前
            </button>
            ` : (window._isPersonalizedCourse ? `
            <div class="flex flex-col gap-1">
              <button onclick="goBackToPersonalizedGuide()" 
                      class="flex items-center gap-1 bg-pink-500 hover:bg-pink-600 text-white px-3 py-1.5 rounded-lg transition font-bold text-xs">
                <i class="fas fa-chevron-left"></i><i class="fas fa-user-graduate"></i>個別
              </button>
              <button onclick="goBackToMainGuide()" 
                      class="flex items-center gap-1 bg-gray-200 text-gray-600 hover:bg-gray-300 px-3 py-1.5 rounded-lg transition font-bold text-xs">
                <i class="fas fa-chevron-left"></i><i class="fas fa-book"></i>全体
              </button>
            </div>
            ` : `
            <button onclick="goBackToGuide()" 
                    class="flex items-center gap-2 bg-gray-200 text-gray-600 hover:bg-gray-300 px-5 py-3 rounded-xl transition font-bold text-sm">
              <i class="fas fa-chevron-left"></i>
              戻る
            </button>
            `)}
            <div class="flex items-center gap-1">
              ${cardsList2.map((id, i) => '<button onclick="loadCardPage(' + id + '); window.scrollTo(0,0);" class="w-8 h-8 rounded-full text-xs font-bold ' + (i === currentIdx2 ? 'bg-indigo-600 text-white shadow-lg scale-110' : 'bg-gray-100 text-gray-600 hover:bg-indigo-100') + ' transition-all">' + (i + 1) + '</button>').join('')}
            </div>
            <button onclick="${nextId2 ? 'loadCardPage(' + nextId2 + '); window.scrollTo(0,0);' : ''}" 
                    class="flex items-center gap-2 ${nextId2 ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg' : 'bg-gray-200 text-gray-500 cursor-not-allowed'} px-5 py-3 rounded-xl transition font-bold text-sm"
                    ${nextId2 ? '' : 'disabled'}>
              ${nextId2 ? '次' : '終了'}
              <i class="fas fa-chevron-right"></i>
            </button>
          </div>
        </div>`
        })()}

      </div>
    `

    // 分かった度の状態管理用変数を初期化
    window.currentUnderstandingLevel = 3 // デフォルトは「だいたいOK」
    window.currentHelpType = null
    window.helpCount = 0
    window.currentCardData = { card, hints, answer }

    // 一問一答モードを初期化（複数の小問がある場合）
    const problemText = card.problem_text || card.problem_content || card.problem_description || ''
    const correctAnswerText = card.correct_answer || card.answer || answer?.answer_content || ''
    const cardIdForQA = card.card_id || card.id || 0
    if (typeof initQAStepMode === 'function') {
      setTimeout(() => initQAStepMode(problemText, correctAnswerText, cardIdForQA), 100)
    }

    // 触覚ウィジェットを初期化
    if (typeof initTactileWidgets === 'function') {
      initTactileWidgets()
    }

    // ドロップゾーン初期化（D&D・クリップボード対応）
    if (typeof initAllDropZones === 'function') {
      setTimeout(() => initAllDropZones(), 300)
    }

  } catch (error) {
    console.error('学習カード読み込みエラー:', error)
    alert('データの読み込みに失敗しました')
  }
}

// loadCardPage をグローバルスコープに登録
window.loadCardPage = loadCardPage

// ヘルプメニュー表示
function showHelpMenu() {
  document.getElementById('helpMenu').classList.remove('hidden')
}

// ヘルプメニュー非表示
function closeHelpMenu() {
  document.getElementById('helpMenu').classList.add('hidden')
}

// ヒントカード表示
function showHints() {
  const hintsArea = document.getElementById('hintsArea')
  hintsArea.classList.remove('hidden')
  hintsArea.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  window.currentHelpType = 'hint'
  window.helpCount++
}

// ヒント開閉トグル
function toggleHint(index) {
  const hintContent = document.getElementById(`hint-${index}`)
  const isHidden = hintContent.classList.contains('hidden')
  hintContent.classList.toggle('hidden')
  
  // アイコンの向きを変更
  const button = hintContent.previousElementSibling
  const icon = button.querySelector('i')
  if (isHidden) {
    icon.classList.remove('fa-chevron-down')
    icon.classList.add('fa-chevron-up')
  } else {
    icon.classList.remove('fa-chevron-up')
    icon.classList.add('fa-chevron-down')
  }
}

// AI先生表示
function showAITeacher() {
  const aiArea = document.getElementById('aiTeacherArea')
  if (aiArea) {
    aiArea.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
    // AI入力欄にフォーカス
    const input = document.getElementById('aiQuestionInput')
    if (input) setTimeout(() => input.focus(), 300)
  }
  window.currentHelpType = 'ai'
  window.helpCount++
  
  // 会話履歴を初期化
  if (!window.aiConversationHistory) {
    window.aiConversationHistory = []
  }
  if (!window.aiDetectedGrade) {
    window.aiDetectedGrade = null
  }
  
  // 初回メッセージ
  const aiChat = document.getElementById('aiChat')
  if (aiChat.children.length === 0) {
    const cardData = window.currentCardData
    const card = cardData?.card || cardData // 構造に対応
    const cardTitle = card?.card_title || '学習カード'
    const problemDesc = card?.problem_description || ''
    
    let welcomeMsg = `こんにちは！AI先生です。😊\n\n`
    
    if (problemDesc) {
      // 問題文を要約して表示（長すぎる場合は最初の100文字）
      const shortDesc = problemDesc.length > 100 ? problemDesc.substring(0, 100) + '...' : problemDesc
      welcomeMsg += `📝 **${cardTitle}**\n\n${shortDesc}\n\n`
    } else {
      welcomeMsg += `📝 **${cardTitle}**\n\n`
    }
    
    welcomeMsg += `わからないことがあったら、なんでも聞いてください！\n\n例えば：\n• 「どこから解けばいいの？」\n• 「この問題は何を聞いているの？」\n• 「〇〇って何？」\n• 「ヒントをください」\n\n一緒に考えましょう！`
    
    addAIMessage(welcomeMsg, 'ai')
  }
  
  // 対話履歴を読み込む
  if (window.aiSessionId) {
    loadConversationHistory()
  }
  
  // 音声読み上げトグルボタンの初期状態を復元
  setTimeout(() => {
    const toggle = document.getElementById('autoVoiceToggle')
    if (toggle) {
      if (window.autoPlayAIVoice) {
        toggle.classList.remove('bg-gray-200', 'hover:bg-gray-300', 'text-gray-700')
        toggle.classList.add('bg-green-500', 'hover:bg-green-600', 'text-white')
        toggle.innerHTML = '<i class="fas fa-volume-up mr-1"></i><span id="autoVoiceStatus">読み上げON</span>'
        console.log('✅ 音声読み上げボタン: ON に設定')
      } else {
        toggle.classList.remove('bg-green-500', 'hover:bg-green-600', 'text-white')
        toggle.classList.add('bg-gray-200', 'hover:bg-gray-300', 'text-gray-700')
        toggle.innerHTML = '<i class="fas fa-volume-mute mr-1"></i><span id="autoVoiceStatus">読み上げOFF</span>'
        console.log('✅ 音声読み上げボタン: OFF に設定')
      }
    }
  }, 100)
}

// 対話履歴を読み込む
async function loadConversationHistory() {
  if (!window.aiSessionId) return
  
  try {
    const response = await axios.get(`/api/ai/conversations/${window.aiSessionId}`)
    const conversations = response.data.conversations || []
    
    // 既存のチャットをクリア（ウェルカムメッセージは保持）
    const aiChat = document.getElementById('aiChat')
    const messages = aiChat.querySelectorAll('.message:not(.welcome)')
    messages.forEach(msg => msg.remove())
    
    // 履歴を表示
    conversations.forEach(conv => {
      const type = conv.message_type === 'question' ? 'user' : 'ai'
      addAIMessage(conv.message_text, type)
    })
    
    console.log('対話履歴を読み込みました:', conversations.length, '件')
  } catch (error) {
    console.error('対話履歴の読み込みエラー:', error)
  }
}

// AI先生に質問
async function askAI() {
  // 送信中フラグをチェック（重複送信を防止）
  if (window.aiSending) {
    console.log('⚠️ 送信中です。重複送信を防止しました。')
    return
  }
  
  const input = document.getElementById('aiQuestionInput')
  const question = input.value.trim()
  
  if (!question) return
  
  // 学習内容以外の質問をフィルタリング（クライアント側での事前チェック）
  const offTopicKeywords = [
    '恋愛', '好き', '告白', '彼氏', '彼女', 'デート', '付き合',
    'いじめ', '友達', '喧嘩', 'ケンカ', '仲直り',
    '悩み', '相談', '困って', '助けて'
  ]
  
  const isOffTopic = offTopicKeywords.some(keyword => question.includes(keyword))
  
  if (isOffTopic) {
    // 学習内容以外の質問には警告メッセージを表示
    // 学年に応じて教科名を調整（中学は「数学」、小学は「算数」）
    const grade = window.aiDetectedGrade || state?.student?.grade || ''
    const isMiddleSchool = grade.includes('中学')
    const mathSubject = isMiddleSchool ? '数学' : '算数'
    const warningMsg = `ごめんね、ぼくは勉強を教える先生だから、学習の質問にだけ答えることができるよ。😊\n\n${mathSubject}や国語、理科や社会の勉強で困っていることはある？`
    addAIMessage(warningMsg, 'ai')
    return
  }
  
  // 送信中フラグを設定
  window.aiSending = true
  
  // ユーザーメッセージを追加
  addAIMessage(question, 'user')
  input.value = ''
  
  // 会話履歴に質問を追加
  if (!window.aiConversationHistory) {
    window.aiConversationHistory = []
  }
  window.aiConversationHistory.push({
    role: 'user',
    message: question
  })
  
  // 学年を検出（質問内容から）
  if (!window.aiDetectedGrade) {
    const gradeMatch = question.match(/([1-6])年生/)
    if (gradeMatch) {
      window.aiDetectedGrade = `小学${gradeMatch[1]}年生`
      console.log('学年を検出しました:', window.aiDetectedGrade)
    }
  }
  
  // ローディング表示
  const aiChat = document.getElementById('aiChat')
  const loadingId = 'loading-' + Date.now()
  addAIMessage('考えているよ... 💭', 'ai', loadingId)
  
  try {
    // セッションIDを生成または取得
    if (!window.aiSessionId) {
      window.aiSessionId = `session-${state.student.id}-${state.selectedCard}-${Date.now()}`
    }
    
    // カード情報を取得
    const cardData = window.currentCardData
    const card = cardData?.card || cardData // 構造に対応
    const cardContext = card ? {
      card_title: card.card_title || '',
      problem_description: card.problem_description || card.problem_text || card.problem_content || '',
      new_terms: card.new_terms || '',
      answer: card.correct_answer || card.answer || card.example_solution || '',
      hints: Array.isArray(card.hints) ? card.hints.map(h => typeof h === 'string' ? h : h.hint_text || '').join('、') : ''
    } : null
    
    // 会話履歴をAPIに送信する形式に変換
    const conversationHistory = window.aiConversationHistory.map(conv => ({
      role: conv.role,
      text: conv.message  // 'content' ではなく 'text' を使用
    }))
    
    // AI先生APIを呼び出す（会話履歴と学年を含める）
    const response = await axios.post('/api/ai-chat', {
      message: question,
      cardContext: cardContext,
      conversationHistory: conversationHistory,
      studentGrade: window.aiDetectedGrade || null
    })
    
    // ローディングメッセージを削除
    const loadingMsg = document.getElementById(loadingId)
    if (loadingMsg) loadingMsg.remove()
    
    // AIの回答を追加
    if (response.data.error) {
      // エラーレスポンスの場合、詳細をログに出力
      console.error('❌ AI先生のエラー:', response.data.error)
      console.error('❌ エラー詳細:', response.data.details)
      
      // APIキーが未設定の場合は特別なメッセージ
      if (response.data.error.includes('APIキー') || response.data.error.includes('API key')) {
        const errorAnswer = `【重要】AI先生がまだ準備できていません 🔧

${response.data.error}

【先生へ】
${response.data.details || 'Cloudflare Pagesの環境変数でGEMINI_API_KEYを設定してください。'}

【生徒の皆さんへ】
今はまだAI先生が使えないから、分からないことがあったら先生に聞いてね！`
        
        addAIMessage(errorAnswer, 'ai')
        
        // 会話履歴に回答を追加
        window.aiConversationHistory.push({
          role: 'assistant',
          message: errorAnswer
        })
      } else {
        const errorAnswer = `ごめんね、今その質問にうまく答えられなかったよ。
もう一度、別の言葉で質問してみてくれるかな？
先生に聞いてみるのもいいよ！

【デバッグ情報】
エラー: ${response.data.error}
詳細: ${response.data.details || 'なし'}`
        
        addAIMessage(errorAnswer, 'ai')
        
        // 会話履歴に回答を追加
        window.aiConversationHistory.push({
          role: 'assistant',
          message: errorAnswer
        })
      }
    } else {
      const answer = response.data.response || 'ごめんね、うまく答えられなかったよ。先生に聞いてみてね。'
      addAIMessage(answer, 'ai')
      
      // 会話履歴に回答を追加
      window.aiConversationHistory.push({
        role: 'assistant',
        message: answer
      })
      
      // 学年を再検出（AIの回答から）
      if (!window.aiDetectedGrade && answer.includes('何年生')) {
        console.log('AIが学年を尋ねています')
      }
      
      // セッションIDを更新
      if (response.data.sessionId) {
        window.aiSessionId = response.data.sessionId
      }
      
      // トークン使用量を表示（デバッグ用）
      if (response.data.tokensUsed) {
        console.log('AI Tokens used:', response.data.tokensUsed)
      }
    }
    
  } catch (error) {
    console.error('AI質問エラー:', error)
    console.error('エラー詳細:', error.response?.data || error.message)
    const loadingMsg = document.getElementById(loadingId)
    if (loadingMsg) loadingMsg.remove()
    
    // エラーメッセージ
    const errorMsg = error.response?.data?.error || 'エラーが発生しました'
    addAIMessage(`ごめんね、うまく答えられなかったよ。\n\n【先生に聞いてみてね】\n${errorMsg}`, 'ai')
  } finally {
    // 送信中フラグをリセット（必ず実行）
    window.aiSending = false
  }
}

// AIチャットメッセージ追加
function addAIMessage(message, sender, loadingId = null) {
  const aiChat = document.getElementById('aiChat')
  const messageDiv = document.createElement('div')
  const messageId = loadingId || `msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
  messageDiv.id = messageId
  messageDiv.className = `flex ${sender === 'user' ? 'justify-end' : 'justify-start'} mb-3`
  
  // LaTeX記号をプレーンテキストに変換
  let cleanMessage = message
  if (sender === 'ai') {
    // $...$ 形式のLaTeX記号を変換
    cleanMessage = cleanMessage.replace(/\$([^$]+)\$/g, (match, content) => {
      // 基本的な数式記号を変換
      return content
        .replace(/\\times/g, '×')
        .replace(/\\div/g, '÷')
        .replace(/\\pm/g, '±')
        .replace(/\\leq/g, '≤')
        .replace(/\\geq/g, '≥')
        .replace(/\\neq/g, '≠')
        .replace(/\\cdot/g, '·')
        .replace(/\^(\d+)/g, (m, exp) => '^' + exp)  // 上付き文字
        .replace(/_(\d+)/g, (m, sub) => '_' + sub)   // 下付き文字
    })
  }
  
  messageDiv.innerHTML = `
    <div class="${sender === 'user' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-800 border-2 border-gray-200'} rounded-lg p-4 ${sender === 'user' ? 'max-w-[80%]' : 'max-w-[95%]'} shadow">
      ${sender === 'ai' ? '<div class="flex items-center mb-2"><i class="fas fa-robot text-blue-500 mr-2"></i><span class="font-bold text-sm">AI先生</span><button onclick="speakText(this.closest(\'[data-ai-msg]\').getAttribute(\'data-ai-msg\'))" style="margin-left:auto;background:none;border:1px solid #C7D2FE;border-radius:8px;padding:2px 8px;cursor:pointer;font-size:0.7rem;color:#6366F1;" title="この回答を読み上げ"><i class="fas fa-volume-up"></i></button></div>' : ''}
      <p class="text-sm whitespace-pre-wrap leading-relaxed">${cleanMessage}</p>
    </div>
  `
  if (sender === 'ai') messageDiv.setAttribute('data-ai-msg', cleanMessage.replace(/<[^>]*>/g, '').substring(0, 3000))
  
  aiChat.appendChild(messageDiv)
  aiChat.scrollTop = aiChat.scrollHeight
  
  // AI先生の回答を音声で読み上げ（オプション）
  if (sender === 'ai' && window.autoPlayAIVoice) {
    speakText(message)
  }
  
  return messageId
}

// Update existing AI message
function updateAIMessage(messageId, newMessage) {
  const messageDiv = document.getElementById(messageId)
  if (!messageDiv) {
    console.warn('⚠️ メッセージが見つかりません:', messageId)
    return
  }
  
  const messageContent = messageDiv.querySelector('p')
  if (messageContent) {
    messageContent.textContent = newMessage
  }
  
  const aiChat = document.getElementById('aiChat')
  if (aiChat) {
    aiChat.scrollTop = aiChat.scrollHeight
  }
}

// 問題文をゆっくり読み上げる
// === Gemini TTS 音声再生エンジン（PCM 24kHz 16bit mono 対応） ===
// readCardAloudも共通のglobal TTS を使用

function readCardAloud() {
  console.log('🔊 readCardAloud 呼び出し')
  
  // 再生中ならストップ
  if (_globalTtsPlaying) {
    stopGlobalTts()
    stopTtsCard()
    return
  }
  
  // UIを読み上げ中に
  const mainIcon = document.getElementById('tts-icon-main')
  if (mainIcon) { mainIcon.className = 'fas fa-spinner fa-spin'; mainIcon.closest('button')?.classList.add('animate-pulse') }
  document.querySelectorAll('[onclick="readCardAloud()"] i.fa-volume-up').forEach(i => i.className = 'fas fa-spinner fa-spin')
  
  // カードデータ取得
  let text = ''
  const cardData = window.currentCardData
  const card = cardData?.card || cardData
  
  if (card && typeof card === 'object') {
    text = card._audio_instruction || card.problem_text || card.problem_content || card.problem_description || card.card_title || ''
  }
  
  if (!text) {
    const problemEl = document.querySelector('.card-content')
    if (problemEl) text = problemEl.textContent.trim()
  }
  if (!text) {
    const audioEl = document.querySelector('[onclick="readCardAloud()"] .text-green-700')
    if (audioEl) text = audioEl.textContent.trim()
  }
  
  if (!text) {
    console.warn('readCardAloud: 読み上げるテキストがありません')
    stopTtsCard()
    return
  }
  
  // Gemini TTS APIで読み上げ（speakTextと同じエンジン）
  _globalTtsPlaying = true
  updateFloatingTtsButton(true)
  
  fetch('/api/ai/tts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text: text.substring(0, 2000), voiceType: 'female-friendly', mood: window._currentMood || '' })
  })
  .then(r => r.json())
  .then(data => {
    if (data.success && data.audioContent && data.audioFormat === 'pcm') {
      const mi = document.getElementById('tts-icon-main')
      if (mi) mi.className = 'fas fa-stop'
      playPcmGlobal(data.audioContent, data.sampleRate || 24000, () => {
        stopTtsCard()
        stopGlobalTts()
        try { TactileSounds.play('correct') } catch(e) {}
      })
    } else if (data.success && data.audioContent) {
      const audio = new Audio('data:audio/mp3;base64,' + data.audioContent)
      audio.onended = () => { stopTtsCard(); stopGlobalTts() }
      audio.onerror = () => fallbackWebSpeechCard(text)
      audio.play().catch(() => fallbackWebSpeechCard(text))
    } else {
      fallbackWebSpeechCard(text)
    }
  })
  .catch(err => {
    console.warn('Gemini TTS エラー:', err.message)
    fallbackWebSpeechCard(text)
  })
}
window.readCardAloud = readCardAloud

function fallbackWebSpeechCard(text) {
  if (!('speechSynthesis' in window)) {
    console.warn('⚠️ Web Speech API 非対応')
    stopTtsCard()
    return
  }
  window.speechSynthesis.cancel()
  const utterance = new SpeechSynthesisUtterance(text)
  utterance.lang = 'ja-JP'
  utterance.rate = 0.85
  utterance.pitch = 1.2
  utterance.volume = 1.0
  
  const voices = window.speechSynthesis.getVoices()
  let voice = voices.find(v => v.lang === 'ja-JP' && v.name.includes('Google'))
    || voices.find(v => v.lang === 'ja-JP' && v.name.includes('Kyoko'))
    || voices.find(v => v.lang === 'ja-JP')
    || voices.find(v => v.lang.startsWith('ja'))
  if (voice) utterance.voice = voice
  
  const mi = document.getElementById('tts-icon-main')
  if (mi) mi.className = 'fas fa-stop'
  
  utterance.onend = () => { stopTtsCard(); try { TactileSounds.play('correct') } catch(e) {} }
  utterance.onerror = () => stopTtsCard()
  
  if (voices.length === 0) {
    window.speechSynthesis.onvoiceschanged = () => {
      const v2 = window.speechSynthesis.getVoices()
      const jaV = v2.find(v => v.lang === 'ja-JP') || v2.find(v => v.lang.startsWith('ja'))
      if (jaV) utterance.voice = jaV
      window.speechSynthesis.speak(utterance)
    }
    setTimeout(() => { if (!window.speechSynthesis.speaking) window.speechSynthesis.speak(utterance) }, 500)
    return
  }
  window.speechSynthesis.speak(utterance)
}

// 直接Web Speech APIで読み上げ（互換性維持）
function speakTextDirect(text, speed = 0.85) {
  if (!('speechSynthesis' in window)) {
    console.warn('⚠️ Web Speech API 非対応')
    alert('このブラウザは音声読み上げに対応していません')
    return
  }
  window.speechSynthesis.cancel()
  const utterance = new SpeechSynthesisUtterance(text)
  utterance.lang = 'ja-JP'
  utterance.rate = speed
  utterance.pitch = 1.2
  utterance.volume = 1.0
  
  const voices = window.speechSynthesis.getVoices()
  let voice = voices.find(v => v.lang === 'ja-JP' && v.name.includes('Google'))
    || voices.find(v => v.lang === 'ja-JP' && v.name.includes('Kyoko'))
    || voices.find(v => v.lang === 'ja-JP')
    || voices.find(v => v.lang.startsWith('ja'))
  if (voice) {
    utterance.voice = voice
    console.log('🎙️ 音声選択:', voice.name)
  }
  
  if (voices.length === 0) {
    window.speechSynthesis.onvoiceschanged = () => {
      const v2 = window.speechSynthesis.getVoices()
      const jaVoice = v2.find(v => v.lang === 'ja-JP') || v2.find(v => v.lang.startsWith('ja'))
      if (jaVoice) utterance.voice = jaVoice
      window.speechSynthesis.speak(utterance)
    }
    setTimeout(() => { if (!window.speechSynthesis.speaking) window.speechSynthesis.speak(utterance) }, 500)
    return
  }
  
  utterance.onstart = () => console.log('🔊 読み上げ開始')
  utterance.onend = () => {
    console.log('✅ 読み上げ完了')
    document.querySelectorAll('[onclick="readCardAloud()"] i').forEach(icon => icon.classList.remove('animate-pulse'))
    TactileSounds.play('correct')
  }
  utterance.onerror = (e) => console.error('❌ 読み上げエラー:', e.error)
  window.speechSynthesis.speak(utterance)
}
window.speakTextDirect = speakTextDirect

// 画像生成を強制する関数（HTML図解ではなくAI画像）
async function generateImageForCardAsImage(cardId, description) {
  if (!cardId) return
  const placeholder = document.getElementById('image-placeholder-' + cardId) || 
                       document.getElementById('card-image-container-' + cardId) ||
                       document.getElementById('guide-img-' + cardId)
  if (placeholder) {
    placeholder.innerHTML = `
      <div class="bg-gradient-to-br from-blue-50 to-indigo-50 border-2 border-blue-300 rounded-2xl p-6 text-center">
        <div class="inline-flex items-center justify-center w-16 h-16 bg-blue-100 rounded-full mb-3">
          <i class="fas fa-image text-2xl text-blue-500 animate-pulse"></i>
        </div>
        <p class="text-sm text-blue-800 font-bold">AIで画像を生成中...</p>
        <p class="text-xs text-gray-500 mt-1">10〜30秒ほどお待ちください</p>
      </div>`
  }
  try {
    const rawCd = window.currentCardData || {}
    const cd = rawCd.card || rawCd
    const answerObj = rawCd.answer || {}
    const answerText = cd.answer || cd.correct_answer || answerObj.answer_text || answerObj.answer_content || ''
    const answerExplanation = cd.answer_explanation || cd.explanation || answerObj.explanation || ''
    const res = await axios.post('/api/ai/generate-image', {
      prompt: description || cd.card_title || cd.title || '教育用図解',
      card_id: cardId,
      problem_text: cd.problem_content || cd.problem_text || cd.content || '',
      card_title: cd.card_title || cd.title || '',
      unit_name: cd.unit_name || '',
      subject: cd.subject || '',
      grade: cd.grade_level || cd.grade || '',
      answer_text: answerText,
      answer_explanation: answerExplanation,
      prefer_image: true
    }, { timeout: 90000 })
    if (res.data.success && res.data.image_url) {
      try { await axios.put('/api/card/' + cardId, { problem_image_url: res.data.image_url }) } catch(e) {}
      if (placeholder) {
        const safeDesc = (description||'').replace(/'/g,'').replace(/"/g,'').replace(/\n/g,' ').substring(0,60)
        placeholder.innerHTML = `
          <div class="text-center" id="card-image-container-${cardId}">
            <img src="${res.data.image_url}" alt="${description || '問題の図'}" 
                 class="max-w-full h-auto rounded-lg shadow-md mx-auto border-2 border-gray-200" style="max-height: 400px;">
            <div class="mt-2 flex items-center justify-center gap-2 flex-wrap">
              <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold">
                <i class="fas fa-check-circle mr-1"></i>${res.data.model || 'AI'}（${((res.data.generation_time_ms||0)/1000).toFixed(1)}秒）
              </span>
              <button onclick="openPromptImageGenerate(${cardId}, 'nb_pro')" class="text-xs text-pink-500 hover:text-pink-700 underline"><i class="fas fa-star mr-1"></i>高精度画像</button>
              <button onclick="generateImageForCard(${cardId}, '${safeDesc}')" class="text-xs text-purple-500 hover:text-purple-700 underline"><i class="fas fa-chart-line mr-1"></i>グラフで再生成</button>
              <button onclick="openImageEditor(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline"><i class="fas fa-edit mr-1"></i>編集</button>
              <button onclick="deleteCardImage(${cardId})" class="text-xs text-red-400 hover:text-red-600 underline"><i class="fas fa-trash mr-1"></i>削除</button>
            </div>
            ${res.data.ai_description ? '<p class="text-xs text-gray-500 mt-1">' + res.data.ai_description.substring(0, 100) + '</p>' : ''}
          </div>`
      }
    } else {
      throw new Error(res.data.error || '画像生成に失敗')
    }
  } catch (err) {
    if (placeholder) {
      placeholder.innerHTML = `<div class="p-4 text-center text-red-600"><i class="fas fa-exclamation-triangle mr-1"></i>画像生成に失敗: ${err.message || 'エラー'}<br><button onclick="generateImageForCard(${cardId})" class="mt-2 text-sm text-blue-500 underline">HTML図解で再試行</button></div>`
    }
  }
}
window.generateImageForCardAsImage = generateImageForCardAsImage

