// ========== 面積ビジュアル ==========
function renderAreaVisual(container, card) {
  const problem = card.problem_text || ''
  const nums = (problem.match(/\d+/g) || []).map(Number).filter(n => n > 0 && n <= 100)
  const w = nums[0] || 5
  const h = nums[1] || 3

  container.innerHTML = `
    <div class="p-4 bg-gradient-to-br from-lime-50 to-green-50 rounded-xl border-2 border-lime-200">
      <div class="flex items-center gap-2 mb-3">
        <span class="bg-lime-600 text-white text-sm font-bold px-3 py-1 rounded-full"><i class="fas fa-vector-square mr-1"></i>みてわかる！面積</span>
      </div>
      <div class="flex items-center gap-4 justify-center">
        <svg viewBox="0 0 ${Math.max(w*20+40, 120)} ${Math.max(h*20+60, 100)}" width="${Math.min(250, Math.max(w*20+40, 120))}" height="${Math.min(200, Math.max(h*20+60, 100))}">
          <rect x="20" y="20" width="${w * 20}" height="${h * 20}" fill="#bbf7d0" stroke="#16a34a" stroke-width="2"/>
          ${Array.from({length: w * h}, (_, i) => {
            const col = i % w
            const row = Math.floor(i / w)
            return `<rect x="${20 + col * 20}" y="${20 + row * 20}" width="20" height="20" fill="none" stroke="#86efac" stroke-width="0.5"/>`
          }).join('')}
          <text x="${20 + w * 10}" y="${h * 20 + 45}" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">${w}cm</text>
          <text x="${w * 20 + 35}" y="${20 + h * 10}" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a" transform="rotate(90, ${w * 20 + 35}, ${20 + h * 10})">${h}cm</text>
        </svg>
        <div class="text-center">
          <p class="text-sm text-gray-600">たて × よこ</p>
          <p class="text-2xl font-bold text-lime-700">${h} × ${w} = ${w * h}</p>
          <p class="text-sm text-gray-500">${w * h} cm²</p>
          <p class="text-xs text-gray-400 mt-1">マス目 ${w * h} 個分</p>
        </div>
      </div>
    </div>`
}

// ========== 視覚ウィジェット自動挿入 ==========
function initVisualWidgets() {
  const cardData = window.currentCardData
  const card = cardData?.card || cardData
  if (!card) return
  
  const cardId = card.card_id || card.id || 0
  const containerId = 'visual-widget-' + cardId
  
  // 既にコンテナがあれば再利用
  let container = document.getElementById(containerId)
  if (!container) {
    // 挿入位置を決定（優先順位付き）
    const insertBefore = 
      // 1. 問題画像コンテナの前
      document.getElementById('card-image-container-' + cardId)
      // 2. 画像プレースホルダーの前
      || document.getElementById('image-placeholder-' + cardId)
      // 3. きいてみようの前
      || document.querySelector('[onclick="readCardAloud()"]')?.closest('.bg-green-50')
      // 4. 触覚ウィジェットの前
      || document.getElementById('tactile-widget-' + cardId + '-wrapper')
      // 5. 動画セクションの前
      || document.querySelector('.rounded-xl.overflow-hidden.border-2')
      // 6. 回答欄の前（ほぼ全カードに存在）
      || document.querySelector('[id="textModeBtn"]')?.closest('.mt-6')
      // 7. 問題文ブロックの直後（最終フォールバック）
      || null
    
    if (insertBefore && insertBefore.parentElement) {
      container = document.createElement('div')
      container.id = containerId
      container.className = 'mt-4 mb-4'
      insertBefore.parentElement.insertBefore(container, insertBefore)
    } else {
      // 最終手段：問題文ブロック(.bg-pink-50)の次に追加
      const problemBlock = document.querySelector('.bg-pink-50.border-l-4')
      if (problemBlock && problemBlock.parentElement) {
        container = document.createElement('div')
        container.id = containerId
        container.className = 'mt-4 mb-4'
        problemBlock.parentElement.insertBefore(container, problemBlock.nextSibling)
      }
    }
  }
  
  if (!container) return
  
  // ★ Nano Banana 2 で問題連動型の図解を動的生成
  // 固定テンプレートではなく、NB2が問題内容を理解して最適な図解を設計
  container.innerHTML = `
    <div id="nb2-visual-${cardId}" style="background:linear-gradient(135deg,#F5F3FF,#FDF2F8);border:2px dashed #DDD6FE;border-radius:16px;padding:20px;text-align:center;">
      <div style="display:inline-block;width:40px;height:40px;border:3px solid #7C3AED;border-top-color:transparent;border-radius:50%;animation:spin 1s linear infinite;margin-bottom:10px;"></div>
      <p style="font-size:1rem;font-weight:bold;color:#7C3AED;">🧠 Nano Banana 2 が図解を設計中...</p>
      <p style="font-size:0.8rem;color:#9CA3AF;margin-top:4px;">問題に合った視覚教材を生成しています（10〜20秒）</p>
    </div>
    <div id="nb2-visual-toolbar-${cardId}" style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:10px;"></div>
  `
  
  const problemText = card.problem_text || card.problem_content || ''
  const cardTitle = card.card_title || ''
  
  fetch('/api/ai/generate-tactile-widget', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      card_id: cardId,
      card_title: cardTitle,
      problem_text: problemText.substring(0, 800),
      tactile_activity: '問題内容を理解しやすくする正確な図解・ダイアグラムを生成してください。問題の数値・図形・関係性を正確に反映した視覚教材が必要です。',
      subject: card.subject || '',
      grade: card.grade_level || '',
      unit_name: card.unit_name || ''
    })
  })
  .then(r => r.json())
  .then(data => {
    const area = document.getElementById('nb2-visual-' + cardId)
    const toolbar = document.getElementById('nb2-visual-toolbar-' + cardId)
    if (!area) return
    
    if (data.success && data.widget_html) {
      area.innerHTML = `
        <div style="background:white;border-radius:16px;border:2px solid #E5E7EB;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.06);">
          <div style="background:linear-gradient(135deg,#7C3AED,#EC4899);padding:8px 16px;display:flex;align-items:center;justify-content:space-between;">
            <span style="color:white;font-size:0.8rem;font-weight:bold;"><i class="fas fa-robot" style="margin-right:5px;"></i>Nano Banana 2 図解</span>
            <span style="color:rgba(255,255,255,0.8);font-size:0.7rem;">${((data.generation_time_ms||0)/1000).toFixed(1)}秒</span>
          </div>
          <div style="padding:14px;" id="nb2-visual-content-${cardId}">${data.widget_html}</div>
        </div>
      `
      // ★ innerHTML で挿入された <script> を実行
      try {
        const bodyEl = document.getElementById('nb2-visual-content-' + cardId)
        if (bodyEl) {
          const scripts = bodyEl.querySelectorAll('script')
          scripts.forEach(oldScript => {
            const newScript = document.createElement('script')
            if (oldScript.src) newScript.src = oldScript.src
            else newScript.textContent = oldScript.textContent
            oldScript.parentNode.replaceChild(newScript, oldScript)
          })
        }
      } catch (e) { console.warn('NB2 script実行:', e) }
      if (data.illustration_url) {
        area.innerHTML += `<div style="margin-top:10px;text-align:center;">
          <img src="${data.illustration_url}" alt="NB2図解" style="max-width:100%;max-height:300px;border-radius:14px;border:2px solid #DDD6FE;box-shadow:0 4px 16px rgba(124,58,237,0.15);" />
        </div>`
      }
    } else if (data.success && data.illustration_url) {
      area.innerHTML = `<div style="text-align:center;padding:14px;">
        <img src="${data.illustration_url}" alt="NB2図解" style="max-width:100%;max-height:300px;border-radius:14px;border:2px solid #DDD6FE;" />
        <p style="font-size:0.7rem;color:#9CA3AF;margin-top:6px;">Nano Banana 2（${((data.generation_time_ms||0)/1000).toFixed(1)}秒）</p>
      </div>`
    } else {
      area.innerHTML = `<div style="padding:14px;text-align:center;background:#FEF3C7;border-radius:14px;border:1px solid #FDE68A;">
        <p style="font-size:0.85rem;color:#92400E;">⚠️ 図解生成に失敗しました</p>
      </div>`
    }
    
    // ツールバー: 再生成・修正・画像生成
    if (toolbar) {
      toolbar.innerHTML = `
        <button onclick="regenerateVisualWidget('${cardId}')" style="background:linear-gradient(135deg,#7C3AED,#EC4899);color:white;border:none;padding:7px 14px;border-radius:10px;font-weight:bold;cursor:pointer;font-size:0.78rem;box-shadow:0 2px 6px rgba(124,58,237,0.3);"><i class="fas fa-sync-alt" style="margin-right:4px;"></i>🧠 NB2で再生成</button>
        <button onclick="editVisualWidget('${cardId}')" style="background:#F59E0B;color:white;border:none;padding:7px 14px;border-radius:10px;font-weight:bold;cursor:pointer;font-size:0.78rem;box-shadow:0 2px 6px rgba(245,158,11,0.3);"><i class="fas fa-edit" style="margin-right:4px;"></i>✏️ 修正指示</button>
        <button onclick="window.generateImageForCard && generateImageForCard(${cardId})" style="background:linear-gradient(135deg,#EC4899,#F97316);color:white;border:none;padding:7px 14px;border-radius:10px;font-weight:bold;cursor:pointer;font-size:0.78rem;box-shadow:0 2px 6px rgba(236,72,153,0.3);"><i class="fas fa-image" style="margin-right:4px;"></i>🎨 別の画像</button>
      `
    }
  })
  .catch(err => {
    const area = document.getElementById('nb2-visual-' + cardId)
    if (area) {
      area.innerHTML = `<div style="padding:14px;text-align:center;background:#FEF2F2;border-radius:14px;border:1px solid #FECACA;">
        <p style="font-size:0.85rem;color:#DC2626;">通信エラー: ${err.message || ''}</p>
        <button onclick="regenerateVisualWidget('${cardId}')" style="margin-top:8px;background:#7C3AED;color:white;border:none;padding:8px 16px;border-radius:10px;font-weight:bold;font-size:0.8rem;cursor:pointer;">🔄 再試行</button>
      </div>`
    }
  })
  
  // ★ 作図問題なら回答ウィジェットも差し替え
  window._constructionStates = {}
  if (typeof initConstructionAnswerWidget === 'function') {
    try { initConstructionAnswerWidget(card) } catch (e) { console.warn('作図ウィジェット初期化エラー:', e) }
  }
}

// 視覚支援が一切ないカードへのフォールバックビジュアル
function renderFallbackVisual(container, card) {
  const title = card.card_title || ''
  const unit = card.unit_name || ''
  const subject = card.subject || ''
  const problem = card.problem_text || card.problem_content || ''
  const grade = card.grade_level || ''
  
  // 問題文からキーポイントを抽出してビジュアル化
  const nums = (problem.match(/-?\d+(\.\d+)?/g) || []).map(Number).filter(n => !isNaN(n))
  const searchQuery = (title + ' ' + unit).replace(/[！!？?「」『』（）()【】]/g, '').substring(0, 25)
  
  // 教科に応じた学習リソースリンク
  const nhkUrl = 'https://edu.web.nhk/school/?q=' + encodeURIComponent(searchQuery)
  const ytUrl = 'https://www.youtube.com/results?search_query=' + encodeURIComponent(searchQuery + ' わかりやすい 解説')
  const imgUrl = 'https://www.google.com/search?tbm=isch&q=' + encodeURIComponent(searchQuery + ' 図解 わかりやすい')
  
  // 問題に数値がある場合は数直線を表示
  let numlineHtml = ''
  if (nums.length >= 1 && (subject.includes('数学') || subject.includes('算数'))) {
    const minN = Math.min(-10, ...nums) - 2
    const maxN = Math.max(10, ...nums) + 2
    const range = maxN - minN
    numlineHtml = `
      <div class="bg-white rounded-lg p-3 border mb-3">
        <p class="text-xs font-bold text-indigo-700 mb-1"><i class="fas fa-ruler-horizontal mr-1"></i>数直線で見てみよう</p>
        <svg viewBox="0 0 400 50" class="w-full" style="max-height:50px">
          <line x1="10" y1="25" x2="390" y2="25" stroke="#374151" stroke-width="2"/>
          <polygon points="385,20 395,25 385,30" fill="#374151"/>
          ${Array.from({length: range + 1}, (_, i) => {
            const val = minN + i
            const x = 10 + (i / range) * 380
            const isMajor = val % 5 === 0 || val === 0
            const isTarget = nums.includes(val)
            return `<line x1="${x}" y1="${isMajor ? 15 : 19}" x2="${x}" y2="${isMajor ? 35 : 31}" stroke="${isTarget ? '#ef4444' : val === 0 ? '#dc2626' : '#6b7280'}" stroke-width="${isTarget ? 3 : isMajor ? 1.5 : 0.8}"/>
              ${isMajor || isTarget ? `<text x="${x}" y="${45}" text-anchor="middle" font-size="${isTarget ? 11 : 9}" fill="${isTarget ? '#ef4444' : val === 0 ? '#dc2626' : val < 0 ? '#2563eb' : '#16a34a'}" font-weight="${isTarget || val === 0 ? 'bold' : 'normal'}">${val}</text>` : ''}
              ${isTarget ? `<circle cx="${x}" cy="10" r="4" fill="#ef4444"/><text x="${x}" y="8" text-anchor="middle" font-size="6" fill="white" font-weight="bold">★</text>` : ''}`
          }).join('')}
        </svg>
        ${nums.length >= 2 ? `<p class="text-xs text-gray-500 text-center">★印の数 ${nums.slice(0,4).join(', ')} を数直線で確認しよう</p>` : ''}
      </div>`
  }
  
  // 問題文のキーワードをハイライト表示
  const keywords = problem.match(/[「」]|正[のな]|負[のな]|＋|ー|加法|減法|乗法|除法|絶対値|累乗|符号|基準|逆数|平均|計算|比べ|大き|小さ|高い|低い/g) || []
  const uniqueKeywords = [...new Set(keywords)].slice(0, 6)
  
  container.innerHTML = `
    <div class="p-4 bg-gradient-to-br from-indigo-50 to-blue-50 rounded-xl border-2 border-indigo-200">
      <div class="flex items-center gap-2 mb-3">
        <span class="bg-indigo-500 text-white text-sm font-bold px-3 py-1 rounded-full"><i class="fas fa-lightbulb mr-1"></i>学習サポート</span>
        <span class="text-xs text-gray-500">${subject} ${unit}</span>
      </div>
      ${numlineHtml}
      ${uniqueKeywords.length > 0 ? `
        <div class="bg-white rounded-lg p-3 border mb-3">
          <p class="text-xs font-bold text-amber-700 mb-1"><i class="fas fa-key mr-1"></i>この問題のキーワード</p>
          <div class="flex flex-wrap gap-1">
            ${uniqueKeywords.map(kw => `<span class="inline-block bg-amber-100 text-amber-800 text-xs px-2 py-0.5 rounded-full font-bold">${kw}</span>`).join('')}
          </div>
        </div>
      ` : ''}
      <div class="flex flex-wrap gap-2 justify-center">
        <a href="${ytUrl}" target="_blank" rel="noopener"
           class="inline-flex items-center gap-1 bg-red-500 hover:bg-red-600 text-white text-xs px-3 py-1.5 rounded-lg font-bold transition shadow">
          <i class="fab fa-youtube"></i>動画で学ぶ
        </a>
        <a href="${nhkUrl}" target="_blank" rel="noopener"
           class="inline-flex items-center gap-1 bg-blue-600 hover:bg-blue-700 text-white text-xs px-3 py-1.5 rounded-lg font-bold transition shadow">
          <i class="fas fa-tv"></i>NHK for School
        </a>
        <a href="${imgUrl}" target="_blank" rel="noopener"
           class="inline-flex items-center gap-1 bg-purple-500 hover:bg-purple-600 text-white text-xs px-3 py-1.5 rounded-lg font-bold transition shadow">
          <i class="fas fa-images"></i>図解を見る
        </a>
      </div>
    </div>`
}

window.initVisualWidgets = initVisualWidgets
window.renderVisualWidget = renderVisualWidget

// === NB2 図解ウィジェット: 再生成 ===
window.regenerateVisualWidget = function(cardId) {
  const cardData = window.currentCardData
  const card = cardData?.card || cardData
  if (!card) return
  initVisualWidgets() // 再度呼び出して再生成
}

// === NB2 図解ウィジェット: 修正指示 ===
window.editVisualWidget = function(cardId) {
  const cardData = window.currentCardData
  const card = cardData?.card || cardData
  if (!card) return
  const instruction = prompt('図解の修正指示を入力してください\n例:「平行移動の図を描いて」「三角形を追加して」「矢印で移動方向を示して」')
  if (!instruction) return
  
  const area = document.getElementById('nb2-visual-' + cardId)
  if (area) {
    area.innerHTML = `<div style="padding:16px;text-align:center;background:linear-gradient(135deg,#FFFBEB,#FDF2F8);border-radius:14px;border:2px dashed #F59E0B;">
      <div style="display:inline-block;width:36px;height:36px;border:3px solid #F59E0B;border-top-color:transparent;border-radius:50%;animation:spin 1s linear infinite;margin-bottom:8px;"></div>
      <p style="font-size:0.9rem;font-weight:bold;color:#D97706;">✏️ NB2で修正中: ${instruction.substring(0,30)}...</p>
    </div>`
  }
  
  fetch('/api/ai/generate-tactile-widget', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      card_id: cardId,
      card_title: card.card_title || '',
      problem_text: (card.problem_text || card.problem_content || '').substring(0, 800),
      tactile_activity: '問題内容を理解しやすくする正確な図解・ダイアグラムを生成してください。',
      subject: card.subject || '',
      grade: card.grade_level || '',
      unit_name: card.unit_name || '',
      edit_instruction: instruction
    })
  })
  .then(r => r.json())
  .then(data => {
    if (!area) return
    if (data.success && data.widget_html) {
      area.innerHTML = `<div style="background:white;border-radius:14px;border:2px solid #F59E0B;overflow:hidden;box-shadow:0 2px 8px rgba(245,158,11,0.15);">
        <div style="background:linear-gradient(135deg,#F59E0B,#D97706);padding:6px 14px;display:flex;align-items:center;justify-content:space-between;">
          <span style="color:white;font-size:0.75rem;font-weight:bold;"><i class="fas fa-edit" style="margin-right:4px;"></i>修正版 by Nano Banana 2</span>
          <span style="color:rgba(255,255,255,0.8);font-size:0.65rem;">${((data.generation_time_ms||0)/1000).toFixed(1)}秒</span>
        </div>
        <div style="padding:14px;">${data.widget_html}</div>
      </div>`
      if (data.illustration_url) {
        area.innerHTML += `<div style="margin-top:8px;text-align:center;"><img src="${data.illustration_url}" style="max-width:100%;max-height:250px;border-radius:12px;" /></div>`
      }
    } else {
      area.innerHTML = `<div style="padding:12px;text-align:center;color:#DC2626;font-size:0.85rem;">修正失敗: ${data.error || ''}</div>`
    }
  })
  .catch(err => {
    if (area) area.innerHTML = `<div style="padding:12px;text-align:center;color:#DC2626;">通信エラー: ${err.message}</div>`
  })
}

// ========== 動的ウィジェット: 詩の音読ハイライト ==========
function highlightPoetryLine(el) {
  // 前の選択を解除
  el.parentElement.querySelectorAll('.poetry-line').forEach(l => {
    l.classList.remove('bg-rose-200', 'font-bold', 'text-rose-700')
  })
  el.classList.add('bg-rose-200', 'font-bold', 'text-rose-700')
  el.classList.add('widget-bounce')
  setTimeout(() => el.classList.remove('widget-bounce'), 600)
  try { TactileSounds.play('tap') } catch(e) {}
}
window.highlightPoetryLine = highlightPoetryLine

function readPoetryAloud(containerId) {
  if (!('speechSynthesis' in window)) { alert('お使いのブラウザでは音声読み上げができません'); return }
  const container = document.getElementById(containerId) || document.querySelector('[id$="' + containerId + '"]')?.closest('[id^="visual-widget"]')
  if (!container) return
  const lines = container.querySelectorAll('.poetry-line')
  if (lines.length === 0) return
  
  let idx = 0
  function speakNext() {
    if (idx >= lines.length) {
      lines.forEach(l => l.classList.remove('bg-rose-200', 'font-bold', 'text-rose-700'))
      return
    }
    lines.forEach(l => l.classList.remove('bg-rose-200', 'font-bold', 'text-rose-700'))
    lines[idx].classList.add('bg-rose-200', 'font-bold', 'text-rose-700')
    lines[idx].scrollIntoView({ behavior: 'smooth', block: 'center' })
    
    const utter = new SpeechSynthesisUtterance(lines[idx].textContent)
    utter.lang = 'ja-JP'
    utter.rate = 0.85
    utter.onend = () => { idx++; setTimeout(speakNext, 300) }
    window.speechSynthesis.speak(utter)
  }
  window.speechSynthesis.cancel()
  speakNext()
}
window.readPoetryAloud = readPoetryAloud

function shufflePoetryWords(containerId) {
  const poetryDiv = document.getElementById('poetry-lines-' + containerId)
  if (!poetryDiv) return
  const lines = Array.from(poetryDiv.querySelectorAll('.poetry-line'))
  if (lines.length < 2) return
  // シャッフル
  for (let i = lines.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [lines[i], lines[j]] = [lines[j], lines[i]]
  }
  poetryDiv.innerHTML = ''
  lines.forEach((l, i) => {
    l.style.animation = 'widgetSlideIn 0.3s ease ' + (i * 0.1) + 's both'
    l.classList.add('bg-amber-100', 'border', 'border-amber-300', 'mb-1')
    poetryDiv.appendChild(l)
    poetryDiv.appendChild(document.createElement('br'))
  })
  try { TactileSounds.play('shuffle') } catch(e) {}
}
window.shufflePoetryWords = shufflePoetryWords

// ====================================================================
// /自動視覚支援ウィジェットエンジン END
// ====================================================================

// ====================================================================
// 統一音声読み上げエンジン - Gemini 2.5 Flash Preview TTS (Achird=Friendly)
// すべての画面で同じ高品質音声を使用
// ====================================================================
let _globalTtsPlaying = false
let _globalTtsSource = null
let _globalTtsAudioCtx = null
let _globalTtsAudio = null  // Audio要素（MP3フォールバック用）

// === カード読み上げ用の停止関数（readCardAloudから呼ばれる） ===
function stopTtsCard() {
  _globalTtsPlaying = false
  if (_globalTtsSource) { try { _globalTtsSource.stop() } catch(e){} }
  _globalTtsSource = null
  if (_globalTtsAudio) { try { _globalTtsAudio.pause(); _globalTtsAudio = null } catch(e){} }
  if (window.speechSynthesis && window.speechSynthesis.speaking) window.speechSynthesis.cancel()
  // UIアイコンを復元
  const mi = document.getElementById('tts-icon-main')
  if (mi) { mi.className = 'fas fa-volume-up'; const btn = mi.closest('button'); if (btn) btn.classList.remove('animate-pulse') }
  document.querySelectorAll('[onclick="readCardAloud()"] i.fa-spinner, [onclick="readCardAloud()"] i.fa-stop').forEach(i => i.className = 'fas fa-volume-up')
  updateFloatingTtsButton(false)
}
window.stopTtsCard = stopTtsCard

// === 全TTS停止（マスター停止） ===
function stopGlobalTts() {
  if (_globalTtsSource) { try { _globalTtsSource.stop() } catch(e){} }
  if (_globalTtsAudio) { try { _globalTtsAudio.pause(); _globalTtsAudio = null } catch(e){} }
  if (window.speechSynthesis && window.speechSynthesis.speaking) window.speechSynthesis.cancel()
  _globalTtsPlaying = false
  _globalTtsSource = null
  // index.tsx側のTTSも停止（グローバル変数連携）
  if (window._ttsCurrentSource) { try { window._ttsCurrentSource.stop() } catch(e){} window._ttsCurrentSource = null }
  // フローティングボタンを復元
  updateFloatingTtsButton(false)
}

// === フローティング読み上げボタンの更新 ===
function updateFloatingTtsButton(isPlaying) {
  const btn = document.getElementById('floating-tts-btn')
  if (!btn) return
  if (isPlaying) {
    btn.innerHTML = '<i class="fas fa-stop"></i>'
    btn.title = '読み上げ停止'
    btn.classList.remove('bg-emerald-500', 'hover:bg-emerald-600')
    btn.classList.add('bg-red-500', 'hover:bg-red-600', 'animate-pulse')
  } else {
    btn.innerHTML = '<i class="fas fa-headphones"></i>'
    btn.title = '選択テキストを読み上げ'
    btn.classList.remove('bg-red-500', 'hover:bg-red-600', 'animate-pulse')
    btn.classList.add('bg-emerald-500', 'hover:bg-emerald-600')
  }
}

// === フローティング読み上げボタンの作成 ===
function createFloatingTtsButton() {
  if (document.getElementById('floating-tts-btn')) return
  
  const btn = document.createElement('button')
  btn.id = 'floating-tts-btn'
  btn.innerHTML = '<i class="fas fa-headphones"></i>'
  btn.title = '選択テキストを読み上げ'
  btn.style.cssText = 'position:fixed;bottom:24px;right:24px;width:56px;height:56px;border-radius:50%;border:none;color:white;font-size:1.4rem;cursor:pointer;z-index:9999;box-shadow:0 4px 15px rgba(0,0,0,0.25);display:flex;align-items:center;justify-content:center;transition:all 0.3s ease;'
  btn.className = 'bg-emerald-500 hover:bg-emerald-600'
  
  btn.onclick = function() {
    // 再生中なら停止
    if (_globalTtsPlaying) {
      stopGlobalTts()
      stopTtsCard()
      return
    }
    
    // テキスト選択があればそれを読み上げ
    const selectedText = window.getSelection().toString().trim()
    if (selectedText && selectedText.length > 0) {
      speakText(selectedText, 'female-friendly', 0.85)
      return
    }
    
    // 選択なしの場合は現在の問題文を読み上げ
    readCardAloud()
  }
  
  document.body.appendChild(btn)
  
  // 選択テキストがあるときに視覚的にフィードバック
  document.addEventListener('selectionchange', function() {
    const btn = document.getElementById('floating-tts-btn')
    if (!btn || _globalTtsPlaying) return
    const sel = window.getSelection().toString().trim()
    if (sel && sel.length > 1) {
      btn.innerHTML = '<i class="fas fa-play"></i>'
      btn.title = '「' + sel.substring(0, 20) + (sel.length > 20 ? '...' : '') + '」を読み上げ'
      btn.style.transform = 'scale(1.1)'
    } else {
      btn.innerHTML = '<i class="fas fa-headphones"></i>'
      btn.title = '選択テキストを読み上げ'
      btn.style.transform = 'scale(1)'
    }
  })
}

// ページ読み込み時にフローティングボタンを作成
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', createFloatingTtsButton)
} else {
  setTimeout(createFloatingTtsButton, 500)
}

function playPcmGlobal(base64Data, sampleRate, onEnd) {
  try {
    if (!_globalTtsAudioCtx) _globalTtsAudioCtx = new (window.AudioContext || window.webkitAudioContext)()
    const raw = atob(base64Data)
    const bytes = new Uint8Array(raw.length)
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i)
    const samples = bytes.length / 2
    const float32 = new Float32Array(samples)
    const dv = new DataView(bytes.buffer)
    for (let j = 0; j < samples; j++) {
      float32[j] = dv.getInt16(j * 2, true) / 32768.0
    }
    const buffer = _globalTtsAudioCtx.createBuffer(1, float32.length, sampleRate)
    buffer.getChannelData(0).set(float32)
    const source = _globalTtsAudioCtx.createBufferSource()
    source.buffer = buffer
    source.connect(_globalTtsAudioCtx.destination)
    source.onended = onEnd
    _globalTtsSource = source
    source.start(0)
  } catch (e) {
    console.warn('PCM再生エラー:', e)
    if (onEnd) onEnd()
  }
}

async function speakText(text, voiceType = 'female-friendly', speed = 0.85) {
  if (!text || text.trim().length < 1) return
  
  // 再生中なら停止
  if (_globalTtsPlaying) {
    stopGlobalTts()
    return
  }
  
  _globalTtsPlaying = true
  updateFloatingTtsButton(true)
  
  console.log('🎤 speakText(Gemini TTS):', text.substring(0, 50) + '...')
  
  try {
    const response = await axios.post('/api/ai/tts', {
      text: text.substring(0, 3000),
      voiceType,
      speed,
      mood: window._currentMood || ''
    })
    
    if (response.data.success && response.data.audioContent) {
      if (response.data.audioFormat === 'pcm') {
        // PCM再生（Gemini TTS標準出力）
        playPcmGlobal(response.data.audioContent, response.data.sampleRate || 24000, () => {
          _globalTtsPlaying = false
          updateFloatingTtsButton(false)
          try { TactileSounds.play('correct') } catch(e) {}
        })
      } else {
        // MP3フォールバック
        const audio = new Audio('data:audio/mp3;base64,' + response.data.audioContent)
        audio.onended = () => { _globalTtsPlaying = false; updateFloatingTtsButton(false) }
        audio.onerror = () => speakTextWebSpeechFallback(text, speed)
        await audio.play()
      }
      return
    }
  } catch (error) {
    console.warn('Gemini TTS エラー:', error.message)
  }
  
  // フォールバック: Web Speech API
  speakTextWebSpeechFallback(text, speed)
}

function speakTextWebSpeechFallback(text, speed = 0.85) {
  if (!('speechSynthesis' in window)) {
    _globalTtsPlaying = false
    updateFloatingTtsButton(false)
    return
  }
  window.speechSynthesis.cancel()
  const u = new SpeechSynthesisUtterance(text)
  u.lang = 'ja-JP'
  u.rate = speed
  u.pitch = 1.1
  const voices = window.speechSynthesis.getVoices()
  const jaVoice = voices.find(v => v.lang === 'ja-JP' && v.name.includes('Google'))
    || voices.find(v => v.lang === 'ja-JP')
    || voices.find(v => v.lang.startsWith('ja'))
  if (jaVoice) u.voice = jaVoice
  u.onend = () => { _globalTtsPlaying = false; updateFloatingTtsButton(false) }
  u.onerror = () => { _globalTtsPlaying = false; updateFloatingTtsButton(false) }
  window.speechSynthesis.speak(u)
}

// Web Speech API を使用した音声読み上げ（最適化版）
function speakTextWithWebSpeech(text, speed = 0.95, voiceType = 'female-friendly') {
  console.log('🎙️ Web Speech API 開始:', { voiceType, speed })
  
  // 音声合成がサポートされているか確認
  if (!('speechSynthesis' in window)) {
    console.warn('音声合成はこのブラウザではサポートされていません')
    return
  }
  
  // 既存の読み上げを停止
  window.speechSynthesis.cancel()
  
  const utterance = new SpeechSynthesisUtterance(text)
  utterance.lang = 'ja-JP'
  utterance.rate = speed  // 速度（0.1 ~ 10.0）
  utterance.pitch = 1.0   // ピッチ（0.0 ~ 2.0）
  utterance.volume = 1.0  // 音量（0.0 ~ 1.0）
  
  // 音声タイプに応じてピッチと速度を調整
  switch(voiceType) {
    case 'female-friendly':
      utterance.pitch = 1.3  // より高め（明るい女性の声）
      utterance.rate = 0.95  // ややゆっくり
      console.log('🎀 女性の優しい声を設定: pitch 1.3')
      break
    case 'male-friendly':
      utterance.pitch = 0.85 // やや低め
      utterance.rate = 0.9   // ゆっくり
      break
    case 'female-energetic':
      utterance.pitch = 1.4  // 高め（元気な女性の声）
      utterance.rate = 1.05  // やや速め
      break
    case 'male-energetic':
      utterance.pitch = 0.8  // 低め
      utterance.rate = 1.0   // 標準
      break
    default:
      utterance.pitch = 1.0
      utterance.rate = speed
  }
  
  // 日本語音声を選択（詳細な優先順位付き）
  const voices = window.speechSynthesis.getVoices()
  
  // 音声タイプに応じた選択
  let targetVoice = null
  
  if (voiceType === 'female-friendly' || voiceType === 'female-energetic') {
    // 女性音声の優先順位
    targetVoice = voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Google') && v.name.includes('Female')
    ) || voices.find(v => 
      v.lang === 'ja-JP' && (v.name.includes('Kyoko') || v.name.includes('O-ren'))
    ) || voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Microsoft') && v.name.includes('Ayumi')
    ) || voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Google')
    )
  } else {
    // 男性音声の優先順位
    targetVoice = voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Google') && v.name.includes('Male')
    ) || voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Otoya')
    ) || voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Microsoft') && v.name.includes('Ichiro')
    ) || voices.find(v => 
      v.lang === 'ja-JP' && v.name.includes('Google')
    )
  }
  
  // フォールバック: 任意の日本語音声
  if (!targetVoice) {
    targetVoice = voices.find(v => v.lang === 'ja-JP') || voices.find(v => v.lang.startsWith('ja'))
  }
  
  if (targetVoice) {
    utterance.voice = targetVoice
    console.log('✅ 選択された音声:', targetVoice.name)
    console.log('📊 音声タイプ:', voiceType)
    console.log('⚡ 速度:', utterance.rate, '/ ピッチ:', utterance.pitch)
  } else {
    console.warn('⚠️ 日本語音声が見つかりませんでした')
  }
  
  // 音声アイコンを表示
  const voiceButton = document.getElementById('voiceButton')
  if (voiceButton) {
    voiceButton.innerHTML = '<i class="fas fa-volume-up"></i>'
  }
  
  utterance.onstart = () => {
    console.log('🔊 音声再生開始')
  }
  
  utterance.onend = () => {
    console.log('✅ 音声再生完了')
    if (voiceButton) {
      voiceButton.innerHTML = '<i class="fas fa-microphone"></i>'
    }
  }
  
  utterance.onerror = (event) => {
    console.error('❌ 音声再生エラー:', event.error)
    if (voiceButton) {
      voiceButton.innerHTML = '<i class="fas fa-microphone"></i>'
    }
  }
  
  // テキストが長い場合は分割して読み上げ（より自然な発音）
  if (text.length > 200) {
    console.log('📝 長いテキストを分割して読み上げます（', text.length, '文字）')
    
    // 句読点で分割
    const sentences = text.split(/([。！？、])/g).filter(s => s.trim())
    let currentText = ''
    
    sentences.forEach((sentence, index) => {
      currentText += sentence
      
      // 区切り文字に達したら、または最後の文なら読み上げ
      if (sentence.match(/[。！？]/) || index === sentences.length - 1) {
        const sentenceUtterance = new SpeechSynthesisUtterance(currentText.trim())
        sentenceUtterance.lang = 'ja-JP'
        sentenceUtterance.rate = utterance.rate
        sentenceUtterance.pitch = utterance.pitch
        sentenceUtterance.volume = utterance.volume
        sentenceUtterance.voice = targetVoice
        
        window.speechSynthesis.speak(sentenceUtterance)
        currentText = ''
      }
    })
  } else {
    // 通常の読み上げ
    window.speechSynthesis.speak(utterance)
  }
}

// 音声認識の初期化
let recognition = null
if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition
  recognition = new SpeechRecognition()
  recognition.lang = 'ja-JP'
  recognition.continuous = false
  recognition.interimResults = false
  
  recognition.onresult = (event) => {
    const transcript = event.results[0][0].transcript
    console.log('音声認識結果:', transcript)
    
    // 認識結果を入力欄に設定
    const input = document.getElementById('aiQuestionInput')
    if (input) {
      input.value = transcript
    }
    
    // ステータスを非表示
    const status = document.getElementById('voiceStatus')
    const statusText = document.getElementById('voiceStatusText')
    if (status) {
      status.classList.add('hidden')
    }
    
    // ボタンを元に戻す
    const voiceButton = document.getElementById('voiceButton')
    if (voiceButton) {
      voiceButton.innerHTML = '<i class="fas fa-microphone"></i>'
      voiceButton.classList.remove('bg-red-600', 'hover:bg-red-700')
      voiceButton.classList.add('bg-purple-600', 'hover:bg-purple-700')
    }
    
    // 自動送信
    setTimeout(() => {
      askAI()
    }, 500)
  }
  
  recognition.onerror = (event) => {
    console.error('音声認識エラー:', event.error)
    
    const status = document.getElementById('voiceStatus')
    const statusText = document.getElementById('voiceStatusText')
    
    let errorMessage = '音声認識エラーが発生しました'
    if (event.error === 'no-speech') {
      errorMessage = '音声が検出されませんでした。もう一度お試しください。'
    } else if (event.error === 'audio-capture') {
      errorMessage = 'マイクが見つかりません。マイクの接続を確認してください。'
    } else if (event.error === 'not-allowed') {
      errorMessage = 'マイクの使用が許可されていません。ブラウザの設定を確認してください。'
    }
    
    if (status && statusText) {
      statusText.textContent = errorMessage
      status.classList.remove('bg-purple-100', 'text-purple-800')
      status.classList.add('bg-red-100', 'text-red-800')
      
      setTimeout(() => {
        status.classList.add('hidden')
      }, 3000)
    }
    
    // ボタンを元に戻す
    const voiceButton = document.getElementById('voiceButton')
    if (voiceButton) {
      voiceButton.innerHTML = '<i class="fas fa-microphone"></i>'
      voiceButton.classList.remove('bg-red-600', 'hover:bg-red-700')
      voiceButton.classList.add('bg-purple-600', 'hover:bg-purple-700')
    }
  }
  
  recognition.onend = () => {
    console.log('音声認識終了')
  }
}

// 音声入力開始
function startVoiceInput() {
  if (!recognition) {
    alert('音声認識はこのブラウザではサポートされていません。\n\nChrome、Edge、またはSafariをお試しください。')
    return
  }
  
  // マイクの権限をリクエスト
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then(() => {
      // 音声認識を開始
      recognition.start()
      console.log('音声認識開始')
      
      // ステータス表示
      const status = document.getElementById('voiceStatus')
      const statusText = document.getElementById('voiceStatusText')
      if (status) {
        statusText.textContent = '音声を認識中... 質問を話してください'
        status.classList.remove('hidden', 'bg-red-100', 'text-red-800')
        status.classList.add('bg-purple-100', 'text-purple-800')
      }
      
      // ボタンの状態を変更
      const voiceButton = document.getElementById('voiceButton')
      if (voiceButton) {
        voiceButton.innerHTML = '<i class="fas fa-stop"></i>'
        voiceButton.classList.remove('bg-purple-600', 'hover:bg-purple-700')
        voiceButton.classList.add('bg-red-600', 'hover:bg-red-700')
      }
    })
    .catch((error) => {
      console.error('マイクアクセスエラー:', error)
      alert('マイクへのアクセスが拒否されました。\n\nブラウザの設定でマイクの使用を許可してください。')
    })
}

// 手書きエリアの表示/非表示
function toggleHandwriting() {
  const handwritingArea = document.getElementById('handwritingArea')
  if (!handwritingArea) return
  
  if (handwritingArea.classList.contains('hidden')) {
    handwritingArea.classList.remove('hidden')
    initHandwritingCanvas()
  } else {
    handwritingArea.classList.add('hidden')
  }
}

// 手書きエリアを閉じる
function closeHandwriting() {
  const handwritingArea = document.getElementById('handwritingArea')
  if (handwritingArea) {
    handwritingArea.classList.add('hidden')
  }
}

// 手書きCanvasの初期化
let isDrawing = false
let lastX = 0
let lastY = 0
let handwritingStrokes = [] // ストローク履歴（思考過程記録用）

function initHandwritingCanvas() {
  const canvas = document.getElementById('handwritingCanvas')
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // 白い背景を描画
  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, 0, canvas.width, canvas.height)
  
  // Canvas設定
  ctx.strokeStyle = '#000000'
  ctx.lineWidth = 2
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  
  // カーソルスタイルを固定（黒十字）
  canvas.style.cursor = 'crosshair'
  
  // タッチデバイス対応
  canvas.addEventListener('pointerdown', startDrawing)
  canvas.addEventListener('pointermove', draw)
  canvas.addEventListener('pointerup', stopDrawing)
  canvas.addEventListener('pointerout', stopDrawing)
  
  // マウス対応も追加（PC環境用）
  canvas.addEventListener('mousedown', startDrawing)
  canvas.addEventListener('mousemove', draw)
  canvas.addEventListener('mouseup', stopDrawing)
  canvas.addEventListener('mouseout', stopDrawing)
  
  function startDrawing(e) {
    isDrawing = true
    const rect = canvas.getBoundingClientRect()
    
    // スケール補正を計算
    const scaleX = canvas.width / rect.width
    const scaleY = canvas.height / rect.height
    
    // clientX/Yを使用（pageX/Yではなく）
    const clientX = e.clientX || (e.touches && e.touches[0].clientX)
    const clientY = e.clientY || (e.touches && e.touches[0].clientY)
    
    lastX = (clientX - rect.left) * scaleX
    lastY = (clientY - rect.top) * scaleY
    
    // カーソルをcrosshairに強制設定
    canvas.style.cursor = 'crosshair'
    
    // 新しいストロークを開始
    handwritingStrokes.push({
      points: [{x: lastX, y: lastY, time: Date.now()}],
      color: '#000000',
      width: 2
    })
  }
  
  function draw(e) {
    if (!isDrawing) return
    
    e.preventDefault()
    
    const rect = canvas.getBoundingClientRect()
    
    // スケール補正を計算
    const scaleX = canvas.width / rect.width
    const scaleY = canvas.height / rect.height
    
    // clientX/Yを使用（pageX/Yではなく）
    const clientX = e.clientX || (e.touches && e.touches[0].clientX)
    const clientY = e.clientY || (e.touches && e.touches[0].clientY)
    
    const x = (clientX - rect.left) * scaleX
    const y = (clientY - rect.top) * scaleY
    
    // カーソルをcrosshairに強制設定（重要: 毎回実行）
    canvas.style.cursor = 'crosshair'
    
    // 線の描画設定を毎回設定（他の処理でリセットされる可能性があるため）
    ctx.strokeStyle = '#000000'
    ctx.lineWidth = 2
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'
    
    ctx.beginPath()
    ctx.moveTo(lastX, lastY)
    ctx.lineTo(x, y)
    ctx.stroke()
    
    // ストローク履歴に追加
    const currentStroke = handwritingStrokes[handwritingStrokes.length - 1]
    if (currentStroke) {
      currentStroke.points.push({x, y, time: Date.now()})
    }
    
    lastX = x
    lastY = y
  }
  
  function stopDrawing() {
    isDrawing = false
    // カーソルをcrosshairに強制設定
    canvas.style.cursor = 'crosshair'
  }
}

// 手書きをクリア
function clearHandwriting() {
  const canvas = document.getElementById('handwritingCanvas')
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // 白い背景を再描画
  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, 0, canvas.width, canvas.height)
  
  // ストローク履歴もクリア
  handwritingStrokes = []
  
  // カーソルをcrosshairに強制設定
  canvas.style.cursor = 'crosshair'
  console.log('✅ AI先生手書きをクリアしました（カーソル: crosshair）')
}

// 1画戻す（Undo）
function undoHandwriting() {
  if (handwritingStrokes.length === 0) return
  
  // 最後のストロークを削除
  handwritingStrokes.pop()
  
  // Canvasを再描画
  redrawHandwriting('handwritingCanvas', handwritingStrokes)
  
  // カーソルをcrosshairに強制設定
  const canvas = document.getElementById('handwritingCanvas')
  if (canvas) {
    canvas.style.cursor = 'crosshair'
  }
}

// 回答用の1画戻す
function undoAnswerHandwriting() {
  if (answerStrokes.length === 0) return
  
  answerStrokes.pop()
  redrawHandwriting('answerCanvas', answerStrokes)
  
  // カーソルをcrosshairに強制設定
  const canvas = document.getElementById('answerCanvas')
  if (canvas) {
    canvas.style.cursor = 'crosshair'
  }
}

// Canvasを再描画
function redrawHandwriting(canvasId, strokes) {
  const canvas = document.getElementById(canvasId)
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // 白い背景を描画
  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, 0, canvas.width, canvas.height)
  
  // すべてのストロークを再描画
  strokes.forEach(stroke => {
    ctx.strokeStyle = stroke.color || '#000000'
    ctx.lineWidth = stroke.width || 2
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'
    
    ctx.beginPath()
    stroke.points.forEach((point, index) => {
      if (index === 0) {
        ctx.moveTo(point.x, point.y)
      } else {
        ctx.lineTo(point.x, point.y)
      }
    })
    ctx.stroke()
  })
}

function clearAnswerHandwriting() {
  const canvas = document.getElementById('answerCanvas')
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // 白い背景を再描画
  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, 0, canvas.width, canvas.height)
  
  answerStrokes = []
  
  // カーソルをcrosshairに強制設定
  canvas.style.cursor = 'crosshair'
  console.log('✅ 回答用手書きをクリアしました（カーソル: crosshair）')
}

// 手書きを送信
async function sendHandwriting() {
  const canvas = document.getElementById('handwritingCanvas')
  if (!canvas) {
    alert('手書きキャンバスが見つかりません')
    return
  }
  
  // 手書きストロークがない場合
  if (!handwritingStrokes || handwritingStrokes.length === 0) {
    alert('まだ何も書かれていません')
    return
  }
  
  // Canvasを画像として取得
  const imageData = canvas.toDataURL('image/png')
  
  // 思考過程の分析（簡易版）
  const strokeCount = handwritingStrokes.length
  const totalPoints = handwritingStrokes.reduce((sum, stroke) => sum + stroke.points.length, 0)
  
  let thinkingNote = ''
  if (strokeCount > 10) {
    thinkingNote = '（たくさん書いて考えたね！）'
  } else if (strokeCount > 5) {
    thinkingNote = '（しっかり書いて考えたね）'
  } else if (strokeCount > 0) {
    thinkingNote = '（手書きで考えたね）'
  }
  
  // 画像を表示
  addAIMessage(`[手書きメモ${thinkingNote}を認識中...]\n\n📝 ${strokeCount}回のストローク、${totalPoints}個の点`, 'user')
  
  // 既存のオーバーレイを削除
  const existingOverlay = document.getElementById('ocr-loading-overlay')
  if (existingOverlay) existingOverlay.remove()
  
  // ローディングオーバーレイを作成
  const loadingOverlay = document.createElement('div')
  loadingOverlay.id = 'ocr-loading-overlay'
  
  // インラインスタイルで完全制御
  Object.assign(loadingOverlay.style, {
    position: 'fixed',
    top: '0',
    left: '0',
    width: '100vw',
    height: '100vh',
    background: 'rgba(0, 0, 0, 0.92)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: '2147483647',
    backdropFilter: 'blur(12px)',
    WebkitBackdropFilter: 'blur(12px)',
    fontFamily: 'system-ui, -apple-system, sans-serif'
  })
  
  loadingOverlay.innerHTML = `
    <div id="ocr-overlay-content" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 3.5rem; border-radius: 2rem; box-shadow: 0 35px 100px rgba(0,0,0,0.7); text-align: center; max-width: 520px; width: 92%; border: 5px solid rgba(255,255,255,0.5); transform: scale(0.7); opacity: 0; transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);">
      <div style="font-size: 6rem; animation: spin 1s linear infinite; display: inline-block; filter: drop-shadow(0 6px 20px rgba(0,0,0,0.5));">🔄</div>
      <div style="font-size: 2.25rem; font-weight: 900; margin-top: 1.75rem; color: white; text-shadow: 0 4px 8px rgba(0,0,0,0.5); letter-spacing: 1px;">文字認識中...</div>
      <div id="ocr-progress-text" style="font-size: 1.3rem; color: rgba(255,255,255,0.98); margin-top: 1.2rem; min-height: 32px; font-weight: 600;">準備中...</div>
      <div style="width: 100%; height: 16px; background: rgba(255,255,255,0.3); border-radius: 8px; margin-top: 2rem; overflow: hidden; box-shadow: inset 0 3px 6px rgba(0,0,0,0.4);">
        <div id="ocr-progress-bar" style="width: 0%; height: 100%; background: linear-gradient(90deg, #ff6b6b, #feca57, #48dbfb, #ff9ff3, #ee5a6f); transition: width 0.7s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: 0 0 20px rgba(255,255,255,0.8); border-radius: 8px;"></div>
      </div>
      <div id="ocr-progress-percent" style="font-size: 2rem; font-weight: 900; color: white; margin-top: 1.5rem; text-shadow: 0 4px 8px rgba(0,0,0,0.5); letter-spacing: 3px;">0%</div>
    </div>
  `
  
  document.body.appendChild(loadingOverlay)
  
  // アニメーション用CSS（spin）を追加
  if (!document.getElementById('ocr-spin-style')) {
    const style = document.createElement('style')
    style.id = 'ocr-spin-style'
    style.textContent = `
      @keyframes spin {
        from { transform: rotate(0deg); }
        to { transform: rotate(360deg); }
      }
    `
    document.head.appendChild(style)
  }
  
  // オーバーレイをアニメーション表示
  setTimeout(() => {
    const content = document.getElementById('ocr-overlay-content')
    if (content) {
      content.style.transform = 'scale(1)'
      content.style.opacity = '1'
    }
  }, 50)
  
  // 進捗更新関数
  const updateProgress = (text, percent) => {
    const progressText = document.getElementById('ocr-progress-text')
    const progressBar = document.getElementById('ocr-progress-bar')
    const progressPercent = document.getElementById('ocr-progress-percent')
    if (progressText) progressText.textContent = text
    if (progressBar) progressBar.style.width = `${percent}%`
    if (progressPercent) progressPercent.textContent = `${Math.round(percent)}%`
  }
  
  // 非同期処理を200ms後に開始（UIの更新を確実に）
  setTimeout(async () => {
    let progressMessageId = null
    
    try {
      // OCR認識を実行（2段階フォールバック: Vision API → Gemini Vision）
      console.log('🔍 手書きOCR認識開始（2段階フォールバック）...')
      console.log('📊 画像データサイズ:', imageData.length, 'bytes')
      
      // Progress message
      progressMessageId = addAIMessage('🌐 第1段階: Google Cloud Vision API で認識中...', 'system')
      updateProgress('🌐 第1段階: Google Cloud Vision API で認識中...', 45)
      
      // Call OCR API directly (no external function needed)
      const response = await axios.post('/api/ai/ocr', {
        imageData: imageData,
        language: 'ja'
      })
      
      console.log('📦 サーバーレスポンス:', response.data)
      
      updateProgress('✅ 認識完了！', 100)
      
      // 成功表示を少し長めに
      await new Promise(resolve => setTimeout(resolve, 1000))
      
      // フェードアウトアニメーション
      const content = document.getElementById('ocr-overlay-content')
      if (content) {
        content.style.transform = 'scale(0.85)'
        content.style.opacity = '0'
      }
      loadingOverlay.style.opacity = '0'
      
      // ローディングオーバーレイを削除
      setTimeout(() => {
        loadingOverlay.remove()
      }, 400)
      
      const result = response.data
      
      console.log('✅ OCR認識完了:', result)
      
      if (result.success && result.text) {
        const recognizedText = result.text.trim()
        
        console.log('✅ 認識されたテキスト:', recognizedText)
        console.log('📊 認識方法:', result.method)
        console.log('📊 認識段階:', result.stageInfo)
        
        // Update progress message (認識成功のシステムメッセージを削除)
        if (progressMessageId) {
          const progressMsg = document.getElementById(progressMessageId)
          if (progressMsg) progressMsg.remove()
        }
        
        // AI先生に送信する質問を設定
        const input = document.getElementById('aiQuestionInput')
        if (input) {
          input.value = recognizedText  // 認識したテキストだけを質問とする
        }
        
        // 認識したテキストをユーザーメッセージとして表示
        addAIMessage(`${recognizedText}`, 'user')
        
        // 会話履歴に追加（askAI内で重複追加されないように）
        if (!window.aiConversationHistory) {
          window.aiConversationHistory = []
        }
        window.aiConversationHistory.push({
          role: 'user',
          message: recognizedText
        })
        
        // 入力欄をクリア（askAI内で addAIMessage(question, 'user') が実行されないようにする）
        input.value = ''
        
        // AI先生に質問を送信（askAI内での addAIMessage をスキップ）
        // askAI関数内で question が空なので return されるため、別の方法を使う
        
        // ローディング表示
        const aiChat = document.getElementById('aiChat')
        const loadingId = 'loading-' + Date.now()
        addAIMessage('考えているよ... 💭', 'ai', loadingId)
        
        // セッションIDを生成または取得
        if (!window.aiSessionId) {
          window.aiSessionId = `session-${state.student.id}-${state.selectedCard}-${Date.now()}`
        }
        
        // カード情報を取得
        const card = window.currentCardData
        const cardContext = card ? {
          card_title: card.card_title,
          problem_description: card.problem_description,
          new_terms: card.new_terms
        } : null
        
        // 会話履歴をAPIに送信する形式に変換
        const conversationHistory = window.aiConversationHistory.map(conv => ({
          role: conv.role,
          text: conv.message
        }))
        
        // AI先生APIを呼び出す
        try {
          const aiResponse = await axios.post('/api/ai-chat', {
            message: recognizedText,
            cardContext: cardContext,
            conversationHistory: conversationHistory,
            studentGrade: window.aiDetectedGrade || null
          })
          
          // ローディングメッセージを削除
          const loadingMsg = document.getElementById(loadingId)
          if (loadingMsg) loadingMsg.remove()
          
          // AIの回答を追加
          if (aiResponse.data.error) {
            console.error('❌ AI先生のエラー:', aiResponse.data.error)
            addAIMessage(`ごめんね、エラーが発生しました: ${aiResponse.data.error}`, 'ai')
          } else {
            const answer = aiResponse.data.answer || aiResponse.data.response || 'ごめんね、答えられませんでした。'
            addAIMessage(answer, 'ai')
            
            // 会話履歴に回答を追加
            window.aiConversationHistory.push({
              role: 'assistant',
              message: answer
            })
            
            // 自動音声再生
            if (window.autoPlayAIVoice) {
              speakText(answer, 'female-friendly', 0.95, 0)
            }
          }
        } catch (aiError) {
          console.error('❌ AI APIエラー:', aiError)
          const loadingMsg = document.getElementById(loadingId)
          if (loadingMsg) loadingMsg.remove()
          addAIMessage('ごめんね、AI先生に接続できませんでした。もう一度試してみてね！', 'ai')
        }
      } else {
        console.warn('⚠️ OCR認識失敗:', result)
        
        if (progressMessageId) {
          updateAIMessage(progressMessageId, '⚠️ 文字認識に失敗しました')
        }
        
        // フォールバック: 手書きの説明だけで送信
        const input = document.getElementById('aiQuestionInput')
        if (input) {
          const originalText = input.value.trim()
          input.value = `[手書きメモ${thinkingNote}を送信（文字認識できませんでした）]\n${originalText || 'この手書きの内容について教えてください'}`
        }
        
        addAIMessage('⚠️ 文字認識に失敗しました。もう一度はっきり書いてみてください。', 'system')
        
        // それでも質問を送信
        askAI()
      }
    } catch (error) {
      console.error('❌ OCR認識エラー:', error)
      
      // ローディングオーバーレイを削除
      if (loadingOverlay && loadingOverlay.parentNode) {
        loadingOverlay.remove()
      }
      
      if (progressMessageId) {
        updateAIMessage(progressMessageId, '❌ 認識エラーが発生しました')
      }
      
      // エラー時のフォールバック
      const input = document.getElementById('aiQuestionInput')
      if (input) {
        const originalText = input.value.trim()
        input.value = `[手書きメモ${thinkingNote}を送信（文字認識エラー）]\n${originalText || 'この手書きの内容について教えてください'}`
      }
      
      addAIMessage('❌ 文字認識でエラーが発生しました。もう一度試してみてください。', 'system')
      
      // それでも質問を送信
      askAI()
    }
  }, 100)  // 100ms後に実行（UIブロック防止）
  
  // 手書きエリアを閉じる
  closeHandwriting()
  
  // Canvasをクリア
  clearHandwriting()
}

window.speakText = speakText
window.startVoiceInput = startVoiceInput
window.toggleHandwriting = toggleHandwriting
window.closeHandwriting = closeHandwriting
window.clearHandwriting = clearHandwriting
window.sendHandwriting = sendHandwriting
window.stopGlobalTts = stopGlobalTts
window.stopTtsCard = stopTtsCard
window.updateFloatingTtsButton = updateFloatingTtsButton

// 音声自動読み上げON/OFF切り替え
function toggleAutoVoice() {
  window.autoPlayAIVoice = !window.autoPlayAIVoice
  
  // LocalStorageに保存
  localStorage.setItem('autoPlayAIVoice', window.autoPlayAIVoice)
  
  const toggle = document.getElementById('autoVoiceToggle')
  const status = document.getElementById('autoVoiceStatus')
  
  if (window.autoPlayAIVoice) {
    toggle.classList.remove('bg-gray-200', 'hover:bg-gray-300', 'text-gray-700')
    toggle.classList.add('bg-green-500', 'hover:bg-green-600', 'text-white')
    toggle.innerHTML = '<i class="fas fa-volume-up mr-1"></i><span id="autoVoiceStatus">読み上げON</span>'
    
    // テスト音声
    speakText('音声読み上げをオンにしました')
  } else {
    toggle.classList.remove('bg-green-500', 'hover:bg-green-600', 'text-white')
    toggle.classList.add('bg-gray-200', 'hover:bg-gray-300', 'text-gray-700')
    toggle.innerHTML = '<i class="fas fa-volume-mute mr-1"></i><span id="autoVoiceStatus">読み上げOFF</span>'
    
    // すべての読み上げを停止
    stopGlobalTts()
    stopTtsCard()
    if ('speechSynthesis' in window) window.speechSynthesis.cancel()
  }
}

// 回答欄のモード切り替え
function switchAnswerMode(mode) {
  const textArea = document.getElementById('textAnswerArea')
  const handwritingArea = document.getElementById('handwritingAnswerArea')
  const textBtn = document.getElementById('textModeBtn')
  const handwritingBtn = document.getElementById('handwritingModeBtn')
  
  if (mode === 'text') {
    textArea.classList.remove('hidden')
    handwritingArea.classList.add('hidden')
    
    textBtn.classList.remove('bg-gray-300', 'text-gray-700')
    textBtn.classList.add('bg-blue-500', 'text-white')
    
    handwritingBtn.classList.remove('bg-blue-500', 'text-white')
    handwritingBtn.classList.add('bg-gray-300', 'text-gray-700')
  } else {
    textArea.classList.add('hidden')
    handwritingArea.classList.remove('hidden')
    
    textBtn.classList.remove('bg-blue-500', 'text-white')
    textBtn.classList.add('bg-gray-300', 'text-gray-700')
    
    handwritingBtn.classList.remove('bg-gray-300', 'text-gray-700')
    handwritingBtn.classList.add('bg-blue-500', 'text-white')
    
    // Canvasを初期化
    initAnswerCanvas()
  }
}

// 回答用Canvasの初期化
let answerDrawing = false
let answerLastX = 0
let answerLastY = 0
let answerStrokes = []

function initAnswerCanvas() {
  const canvas = document.getElementById('answerCanvas')
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // 白い背景を描画
  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, 0, canvas.width, canvas.height)
  
  // Canvas設定
  ctx.strokeStyle = '#000000'
  ctx.lineWidth = 3
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  
  // カーソルスタイルを固定（黒十字）
  canvas.style.cursor = 'crosshair'
  
  // イベントリスナーを削除してから再追加（重複防止）
  canvas.removeEventListener('pointerdown', answerStartDrawing)
  canvas.removeEventListener('pointermove', answerDraw)
  canvas.removeEventListener('pointerup', answerStopDrawing)
  canvas.removeEventListener('pointerout', answerStopDrawing)
  
  canvas.addEventListener('pointerdown', answerStartDrawing)
  canvas.addEventListener('pointermove', answerDraw)
  canvas.addEventListener('pointerup', answerStopDrawing)
  canvas.addEventListener('pointerout', answerStopDrawing)
  
  // マウス対応も追加（PC環境用）
  canvas.removeEventListener('mousedown', answerStartDrawing)
  canvas.removeEventListener('mousemove', answerDraw)
  canvas.removeEventListener('mouseup', answerStopDrawing)
  canvas.removeEventListener('mouseout', answerStopDrawing)
  
  canvas.addEventListener('mousedown', answerStartDrawing)
  canvas.addEventListener('mousemove', answerDraw)
  canvas.addEventListener('mouseup', answerStopDrawing)
  canvas.addEventListener('mouseout', answerStopDrawing)
}

function answerStartDrawing(e) {
  answerDrawing = true
  const canvas = document.getElementById('answerCanvas')
  const rect = canvas.getBoundingClientRect()
  
  // スケール補正を計算
  const scaleX = canvas.width / rect.width
  const scaleY = canvas.height / rect.height
  
  // clientX/Yを使用（pageX/Yではなく）
  const clientX = e.clientX || (e.touches && e.touches[0].clientX)
  const clientY = e.clientY || (e.touches && e.touches[0].clientY)
  
  answerLastX = (clientX - rect.left) * scaleX
  answerLastY = (clientY - rect.top) * scaleY
  
  // カーソルをcrosshairに強制設定
  canvas.style.cursor = 'crosshair'
  
  answerStrokes.push({
    points: [{x: answerLastX, y: answerLastY, time: Date.now()}],
    color: '#000000',
    width: 3
  })
  
  console.log('Start drawing:', { clientX, clientY, rect, scaleX, scaleY, x: answerLastX, y: answerLastY })
}

function answerDraw(e) {
  if (!answerDrawing) return
  
  e.preventDefault()
  
  const canvas = document.getElementById('answerCanvas')
  const rect = canvas.getBoundingClientRect()
  
  // スケール補正を計算
  const scaleX = canvas.width / rect.width
  const scaleY = canvas.height / rect.height
  
  // clientX/Yを使用（pageX/Yではなく）
  const clientX = e.clientX || (e.touches && e.touches[0].clientX)
  const clientY = e.clientY || (e.touches && e.touches[0].clientY)
  
  const x = (clientX - rect.left) * scaleX
  const y = (clientY - rect.top) * scaleY
  
  // カーソルをcrosshairに強制設定（重要: 毎回実行）
  canvas.style.cursor = 'crosshair'
  
  const ctx = canvas.getContext('2d')
  
  // 線の描画設定を毎回設定（他の処理でリセットされる可能性があるため）
  ctx.strokeStyle = '#000000'
  ctx.lineWidth = 3
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  
  ctx.beginPath()
  ctx.moveTo(answerLastX, answerLastY)
  ctx.lineTo(x, y)
  ctx.stroke()
  
  const currentStroke = answerStrokes[answerStrokes.length - 1]
  if (currentStroke) {
    currentStroke.points.push({x, y, time: Date.now()})
  }
  
  answerLastX = x
  answerLastY = y
}

function answerStopDrawing() {
  answerDrawing = false
  // カーソルをcrosshairに強制設定
  const canvas = document.getElementById('answerCanvas')
  if (canvas) {
    canvas.style.cursor = 'crosshair'
  }
}

// 手書き認識（統合版）
async function recognizeAnswerHandwriting() {
  if (answerStrokes.length === 0) {
    alert('まだ何も書かれていません')
    return
  }
  
  // 認識中表示
  const canvas = document.getElementById('answerCanvas')
  // カーソルは常にcrosshairを維持（認識後も変更しない）
  canvas.style.cursor = 'wait'
  
  try {
    console.log('=== 手書き認識開始 ===')
    
    // 画像データを取得
    const imageData = canvas.toDataURL('image/png')
    console.log('画像データサイズ:', imageData.length)
    
    // 1. Google Cloud Vision API で OCR 認識（優先）
    try {
      console.log('✅ Google Cloud Vision OCR 開始...')
      console.log('🔍 OCR認識中です... Google Cloud Vision APIを使用しています。')
      
      const response = await axios.post('/api/ai/ocr', {
        imageData: imageData,
        language: 'ja'
      })
      
      if (response.data.success && response.data.text) {
        const text = response.data.text.trim()
        console.log('✅ Google Cloud Vision OCR認識成功:', text)
        document.getElementById('answerInput').value = text
        alert(`✅ 認識結果: ${text}\n\n認識方法: Google Cloud Vision API`)
        switchAnswerMode('text')
        canvas.style.cursor = 'crosshair'
        return
      } else {
        console.log('⚠️ Google Cloud Vision OCRで結果が得られませんでした')
      }
    } catch (cloudVisionError) {
      console.error('❌ Google Cloud Vision OCRエラー:', cloudVisionError)
      console.log('⚠️ Google Cloud Vision APIが利用できません。Tesseract.jsにフォールバックします。')
      // フォールバック: Tesseract.jsを試す
    }
    
    // 2. Tesseract.js で OCR 認識（フォールバック）
    console.log('Tesseract利用可能:', typeof Tesseract !== 'undefined')
    
    // Tesseract.jsの読み込み待機（最大10秒）
    let tesseractLoaded = typeof Tesseract !== 'undefined'
    if (!tesseractLoaded) {
      console.log('⏳ Tesseract.jsの読み込みを待機中...')
      for (let i = 0; i < 20; i++) {
        await new Promise(resolve => setTimeout(resolve, 500))
        tesseractLoaded = typeof Tesseract !== 'undefined'
        if (tesseractLoaded) {
          console.log('✅ Tesseract.js読み込み完了')
          break
        }
      }
    }
    
    if (tesseractLoaded) {
      console.log('✅ Tesseract OCR 開始（フォールバック）...')
      console.log('🔍 OCR認識中です... 日本語テキストを認識しています。完了まで数秒かかります。')
      
      try {
        // Tesseract.jsの明示的な初期化とWorker設定
        const { createWorker } = Tesseract
        console.log('🔧 Tesseract Worker初期化中...')
        
        const worker = await createWorker('jpn+eng', 1, {
          logger: m => {
            console.log('OCR進捗:', m)
            if (m.status === 'recognizing text') {
              console.log('認識進捗:', Math.round(m.progress * 100) + '%')
            }
          },
          workerPath: 'https://cdn.jsdelivr.net/npm/tesseract.js@5.0.4/dist/worker.min.js',
          langPath: 'https://cdn.jsdelivr.net/npm/tesseract.js-data@1.0.0',
          corePath: 'https://cdn.jsdelivr.net/npm/tesseract.js-core@5.0.0',
        })
        
        console.log('✅ Tesseract Worker準備完了')
        
        const result = await worker.recognize(imageData)
        
        console.log('✅ OCR完了:', result)
        
        await worker.terminate()
        console.log('✅ Tesseract Worker終了')
        
        if (result && result.data && result.data.text && result.data.text.trim()) {
          const text = result.data.text.trim()
          console.log('✅ Tesseract OCR認識成功:', text)
          console.log('認識信頼度:', result.data.confidence)
          document.getElementById('answerInput').value = text
          alert(`✅ 認識結果: ${text}\n\n信頼度: ${Math.round(result.data.confidence)}%\n認識方法: Tesseract.js (フォールバック)`)
          switchAnswerMode('text')
          canvas.style.cursor = 'crosshair'
          return
        } else {
          console.log('⚠️ Tesseract OCR結果が空でした')
        }
      } catch (ocrError) {
        console.error('❌ Tesseract OCRエラー:', ocrError)
        console.error('エラー詳細:', ocrError.message, ocrError.stack)
        // OCRエラーでも次の方法にフォールバック
      }
    } else {
      console.log('⚠️ Tesseract.js が読み込まれていません（10秒待機後もロードされず）')
    }
    
    // 3. ブラウザのHandwriting Recognition APIを試す
    if ('queryHandwritingRecognizer' in navigator) {
      const recognizer = await navigator.queryHandwritingRecognizer({
        languages: ['ja', 'en']
      })
      
      if (recognizer) {
        const drawing = {
          strokes: answerStrokes.map(stroke => ({
            points: stroke.points.map(p => ({x: p.x, y: p.y}))
          }))
        }
        
        const predictions = await recognizer.recognize(drawing)
        
        if (predictions && predictions.length > 0) {
          const text = predictions[0].text
          document.getElementById('answerInput').value = text
          alert(`✅ 認識結果: ${text}\n\n認識方法: ブラウザAPI`)
          switchAnswerMode('text')
          return
        }
      }
    }
    
    // 4. 簡易的な形状認識（数式・図形）
    const recognized = simpleShapeRecognition(answerStrokes)
    if (recognized) {
      document.getElementById('answerInput').value += recognized
      alert(`✅ 認識結果: ${recognized}\n\n認識方法: 形状認識`)
      switchAnswerMode('text')
      return
    }
    
    // 5. 画像として保存して通知
    alert('⚠️ 手書き文字認識に失敗しました。\n\n手書き内容は画像として保存されました。\n文字モードに切り替えて、内容を入力してください。')
    
    // 文字モードに切り替え
    switchAnswerMode('text')
    
  } catch (error) {
    console.error('手書き認識エラー:', error)
    alert('⚠️ 手書き認識に失敗しました。\n\n文字モードに切り替えて入力してください。')
    switchAnswerMode('text')
  } finally {
    canvas.style.cursor = 'crosshair'
  }
}

// 簡易的な形状認識（数式・図形）
function simpleShapeRecognition(strokes) {
  if (strokes.length === 0) return null
  
  // ストローク数と点数の分析
  const strokeCount = strokes.length
  const totalPoints = strokes.reduce((sum, stroke) => sum + stroke.points.length, 0)
  const avgPointsPerStroke = totalPoints / strokeCount
  
  // 1. 円形の検出（単一ストローク、点が多い）
  if (strokeCount === 1 && avgPointsPerStroke > 50) {
    const stroke = strokes[0]
    if (isCircular(stroke.points)) {
      return '○ (円)'
    }
  }
  
  // 2. 直線の検出（点が少ない）
  if (strokeCount === 1 && avgPointsPerStroke < 15) {
    return '━ (直線)'
  }
  
  // 3. 四角形の検出（4-5ストローク）
  if (strokeCount >= 4 && strokeCount <= 5) {
    return '□ (四角形)'
  }
  
  // 4. 三角形の検出（3ストローク）
  if (strokeCount === 3) {
    return '△ (三角形)'
  }
  
  // 5. 数式記号の簡易検出
  if (strokeCount === 2) {
    // +(プラス)の可能性
    if (arePerpendicular(strokes[0].points, strokes[1].points)) {
      return '+'
    }
    
    // =(イコール)の可能性
    if (areParallel(strokes[0].points, strokes[1].points)) {
      return '='
    }
    
    // ×(かける)の可能性
    if (isDiagonalCross(strokes[0].points, strokes[1].points)) {
      return '×'
    }
  }
  
  if (strokeCount === 1 && avgPointsPerStroke < 20) {
    // -(マイナス)の可能性
    if (isHorizontal(strokes[0].points)) {
      return '-'
    }
    
    // /(スラッシュ・割り算)の可能性
    if (isDiagonal(strokes[0].points)) {
      return '÷'
    }
  }
  
  // 6. 分数記号の検出（横線1本）
  if (strokeCount === 1 && isHorizontal(strokes[0].points)) {
    return '―（分数の線）'
  }
  
  // 7. 複雑な数式パターン
  if (strokeCount > 5) {
    return '[複雑な数式]'
  }
  
  return null
}

// 円形判定
function isCircular(points) {
  if (points.length < 50) return false
  
  const firstPoint = points[0]
  const lastPoint = points[points.length - 1]
  const distance = Math.sqrt(
    Math.pow(lastPoint.x - firstPoint.x, 2) + 
    Math.pow(lastPoint.y - firstPoint.y, 2)
  )
  
  // 始点と終点が近い
  return distance < 30
}

// 水平線判定
function isHorizontal(points) {
  if (points.length < 5) return false
  
  const yVariation = Math.abs(points[points.length - 1].y - points[0].y)
  const xVariation = Math.abs(points[points.length - 1].x - points[0].x)
  
  return xVariation > 50 && yVariation < 20
}

// 斜線判定
function isDiagonal(points) {
  if (points.length < 5) return false
  
  const yVariation = Math.abs(points[points.length - 1].y - points[0].y)
  const xVariation = Math.abs(points[points.length - 1].x - points[0].x)
  
  return xVariation > 30 && yVariation > 30
}

// 直交判定
function arePerpendicular(points1, points2) {
  // 簡易判定: 2つのストロークが十字に近い
  return true
}

// 平行判定
function areParallel(points1, points2) {
  if (points1.length < 3 || points2.length < 3) return false
  
  const y1Variation = Math.abs(points1[points1.length - 1].y - points1[0].y)
  const y2Variation = Math.abs(points2[points2.length - 1].y - points2[0].y)
  
  // 両方とも水平に近い
  return y1Variation < 15 && y2Variation < 15
}

// 斜めクロス判定（×記号）
function isDiagonalCross(points1, points2) {
  if (points1.length < 3 || points2.length < 3) return false
  
  // 両方とも斜線かどうか
  const isDiag1 = isDiagonal(points1)
  const isDiag2 = isDiagonal(points2)
  
  return isDiag1 && isDiag2
}

