// ★ 全体配信カード用：音楽・動画・画像生成
async function groupCardGenerate(type, cardId, cardIndex, courseName, cardTitle) {
  const area = document.getElementById('group-gen-result-' + (cardId || cardIndex))
  if (!area) return
  const promptEl = document.getElementById('group-gen-prompt-' + (cardId || cardIndex))
  const customPrompt = promptEl?.value?.trim() || ''
  
  if (type === 'song') {
    area.innerHTML = '<div class="text-center py-2"><i class="fas fa-spinner fa-spin text-purple-500"></i> <span class="text-xs text-purple-600 font-bold">NB2が30秒おぼえうたを作曲中...</span></div>'
    try {
      const res = await axios.post('/api/ai/generate-nb2-music', {
        card_id: cardId, card_title: cardTitle, subject: '', grade: '',
        unit_name: courseName, custom_prompt: customPrompt
      })
      const d = res.data
      if (d.success && d.song_data) {
        const sd = d.song_data
        let h = '<div class="bg-purple-50 rounded p-2 mt-1 border border-purple-200">'
        h += '<p class="font-bold text-purple-700 text-xs">🎵 ' + (sd.song_title || '30秒おぼえうた') + '</p>'
        if (sd.genre) h += '<p class="text-[9px] text-gray-500">' + sd.genre + (sd.tempo_bpm ? ' / ' + sd.tempo_bpm + 'BPM' : '') + '</p>'
        if (sd.lyrics) h += '<pre class="text-[10px] whitespace-pre-wrap bg-white p-2 rounded border mt-1 max-h-20 overflow-y-auto">' + sd.lyrics + '</pre>'
        // 🔊 音声再生ボタン
        if (d.audio_url) {
          h += '<div class="mt-1"><audio controls class="w-full" style="height:32px;" src="' + d.audio_url + '"></audio></div>'
        }
        h += '<div class="flex gap-1 mt-1 flex-wrap">'
        if (sd.lyrics) h += '<button onclick="groupPlaySong(this,\'' + encodeURIComponent((sd.lyrics||'').substring(0,500)) + '\')" class="inline-flex items-center gap-1 bg-gradient-to-r from-purple-500 to-pink-500 text-white px-2 py-1 rounded text-[10px] font-bold"><i class="fas fa-play"></i>🎵 歌を聴く</button>'
        h += '</div>'
        if (d.cover_image_url) h += '<img src="' + d.cover_image_url + '" class="max-h-16 rounded mt-1">'
        h += '<p class="text-[9px] text-gray-400 mt-1">' + (d.model||'NB2') + ' / ' + Math.round((d.generation_time_ms||0)/1000) + '秒</p>'
        h += '<button onclick="groupCardGenerate(\'song\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-[10px] text-purple-500 underline mt-1">🔄 再生成</button></div>'
        area.innerHTML = h
      } else { area.innerHTML = '<p class="text-[10px] text-red-500">失敗: ' + (d.error||'') + '</p>' }
    } catch(e) { area.innerHTML = '<p class="text-[10px] text-red-500">エラー: ' + e.message + '</p>' }
  } else if (type === 'suno') {
    area.innerHTML = '<div class="text-center py-2"><i class="fas fa-spinner fa-spin text-pink-500"></i> <span class="text-xs text-pink-600 font-bold">Sunoフル曲提案を生成中...</span></div>'
    try {
      const res = await axios.post('/api/ai/generate-suno-lyrics', {
        grade: '', subject: '', unit_name: courseName,
        topic: customPrompt || cardTitle, song_type: '学習内容の暗記・理解補助ソング'
      })
      const d = res.data
      if (d.success && d.lyrics_data) {
        const sd = d.lyrics_data
        let h = '<div class="bg-pink-50 rounded p-2 mt-1 border border-pink-200">'
        h += '<div class="flex items-center gap-1 mb-1"><span>🎤</span><span class="text-xs font-bold text-pink-700">Sunoフル曲提案</span><span class="text-[8px] bg-pink-100 text-pink-600 px-1 py-0.5 rounded font-bold">外部</span></div>'
        if (sd.song_title) h += '<p class="text-[10px] text-gray-700"><strong>曲名:</strong> ' + sd.song_title + '</p>'
        h += '<input type="text" id="gsuno-style-' + (cardId||cardIndex) + '" value="' + (sd.suno_style_prompt||'').replace(/"/g,'&quot;') + '" class="w-full border border-pink-100 rounded px-1 py-0.5 text-[10px] mt-1">'
        h += '<textarea id="gsuno-lyrics-' + (cardId||cardIndex) + '" rows="4" class="w-full border border-pink-100 rounded px-1 py-0.5 text-[9px] font-mono mt-1 resize-y">' + (sd.suno_lyrics||'') + '</textarea>'
        h += '<div class="flex gap-1 mt-1 flex-wrap">'
        h += '<button onclick="navigator.clipboard.writeText(document.getElementById(\'gsuno-lyrics-' + (cardId||cardIndex) + '\').value);this.textContent=\'✅\';setTimeout(()=>this.textContent=\'歌詞コピー\',1000)" class="bg-pink-500 text-white px-2 py-0.5 rounded text-[9px] font-bold">歌詞コピー</button>'
        h += '<button onclick="navigator.clipboard.writeText(document.getElementById(\'gsuno-style-' + (cardId||cardIndex) + '\').value);this.textContent=\'✅\';setTimeout(()=>this.textContent=\'スタイルコピー\',1000)" class="bg-pink-200 text-pink-700 px-2 py-0.5 rounded text-[9px] font-bold">スタイルコピー</button>'
        h += '<a href="https://suno.com" target="_blank" class="bg-gray-800 text-white px-2 py-0.5 rounded text-[9px] font-bold">Suno</a></div>'
        h += '<button onclick="groupCardGenerate(\'suno\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-[10px] text-pink-500 underline mt-1">🔄 再提案</button></div>'
        area.innerHTML = h
      } else { area.innerHTML = '<p class="text-[10px] text-red-500">失敗: ' + (d.error||'') + '</p>' }
    } catch(e) { area.innerHTML = '<p class="text-[10px] text-red-500">エラー: ' + e.message + '</p>' }
  } else if (type === 'video') {
    area.innerHTML = '<div class="text-center py-2"><i class="fas fa-spinner fa-spin text-red-500"></i> <span class="text-xs text-red-600 font-bold">Veo 3.1が動画を生成中（30〜90秒）...</span></div>'
    try {
      const videoPrompt = customPrompt || ('日本の小学校 ' + courseName + '「' + cardTitle + '」。子どもにわかりやすい教育動画。')
      const res = await axios.post('/api/ai/generate-video', {
        prompt: videoPrompt, card_id: cardId, card_title: cardTitle
      })
      const d = res.data
      if (d.success && d.video_url) {
        area.innerHTML = '<div class="bg-red-50 rounded p-2 mt-1 border border-red-200"><p class="font-bold text-red-700 text-xs">🎬 動画</p><video controls class="w-full rounded mt-1" style="max-height:150px;" preload="metadata"><source src="' + d.video_url + '" type="video/mp4"></video><p class="text-[9px] text-gray-400">Veo 3.1 / ' + Math.round((d.generation_time_ms||0)/1000) + '秒</p></div>'
      } else if ((d.success || d.status === 'processing') && d.operationName) {
        // ポーリング方式でリロード不要
        area.innerHTML = '<div class="bg-yellow-50 rounded p-2 mt-1 border border-yellow-200"><p class="text-xs font-bold text-yellow-700"><i class="fas fa-spinner fa-spin mr-1"></i>動画生成中...</p><p class="text-[10px] text-gray-500">自動で完了を確認します（30〜90秒）</p><div class="w-full bg-yellow-200 rounded-full h-1.5 mt-2"><div id="group-video-progress-' + (cardId || cardIndex) + '" class="bg-yellow-500 h-1.5 rounded-full transition-all" style="width:5%"></div></div></div>'
        pollGroupVideo(cardId, cardIndex, courseName, cardTitle, d.operationName)
      } else { area.innerHTML = '<p class="text-[10px] text-red-500">生成に時間がかかっています <button onclick="groupCardGenerate(\'video\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-red-500 underline">再試行</button></p>' }
    } catch(e) { area.innerHTML = '<p class="text-[10px] text-red-500">エラー: ' + e.message + '</p>' }
  } else if (type === 'image') {
    area.innerHTML = '<div class="text-center py-2"><i class="fas fa-spinner fa-spin text-pink-500"></i> <span class="text-xs text-pink-600 font-bold">AI画像生成中...</span></div>'
    try {
      const res = await axios.post('/api/ai/generate-image', {
        prompt: customPrompt || cardTitle, card_id: cardId, card_title: cardTitle, prefer_image: true
      })
      const d = res.data
      if (d.success && d.image_url) {
        area.innerHTML = '<div class="bg-pink-50 rounded p-2 mt-1 border border-pink-200"><p class="font-bold text-pink-700 text-xs">🎨 AI画像</p><img src="' + d.image_url + '" class="w-full rounded mt-1 border" style="max-height:120px;object-fit:contain;"><p class="text-[9px] text-gray-400">' + (d.model||'NB2') + ' / ' + Math.round((d.generation_time_ms||0)/1000) + '秒</p></div>'
      } else { area.innerHTML = '<p class="text-[10px] text-red-500">画像生成失敗</p>' }
    } catch(e) { area.innerHTML = '<p class="text-[10px] text-red-500">エラー: ' + e.message + '</p>' }
  }
}
window.groupCardGenerate = groupCardGenerate

// ★ 全体配信カード用：動画ポーリング（リロード不要）
async function pollGroupVideo(cardId, cardIndex, courseName, cardTitle, operationName) {
  let attempts = 0
  const maxAttempts = 20
  const interval = setInterval(async () => {
    attempts++
    const progress = Math.min(5 + attempts * 5, 95)
    const bar = document.getElementById('group-video-progress-' + (cardId || cardIndex))
    if (bar) bar.style.width = progress + '%'
    try {
      const res = await axios.get('/api/ai/video-status?operation=' + encodeURIComponent(operationName))
      const d = res.data
      if (d.done && (d.videoUrl || d.video_url)) {
        clearInterval(interval)
        const vurl = d.videoUrl || d.video_url
        const area = document.getElementById('group-gen-result-' + (cardId || cardIndex))
        if (area) {
          area.innerHTML = '<div class="bg-red-50 rounded p-2 mt-1 border border-red-200"><p class="font-bold text-red-700 text-xs">🎬 動画</p><video controls class="w-full rounded mt-1" style="max-height:150px;" preload="metadata"><source src="/api/ai/video-download?uri=' + encodeURIComponent(vurl) + '" type="video/mp4"></video><p class="text-[9px] text-gray-400">Veo 3.1</p><button onclick="groupCardGenerate(\'video\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-[10px] text-red-500 underline mt-1">🔄 再生成</button></div>'
        }
      } else if (d.done && d.error) {
        clearInterval(interval)
        const area = document.getElementById('group-gen-result-' + (cardId || cardIndex))
        if (area) area.innerHTML = '<p class="text-[10px] text-red-500">動画生成失敗 <button onclick="groupCardGenerate(\'video\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-red-500 underline">再試行</button></p>'
      }
    } catch(e) { /* continue polling */ }
    if (attempts >= maxAttempts) {
      clearInterval(interval)
      const area = document.getElementById('group-gen-result-' + (cardId || cardIndex))
      if (area) area.innerHTML = '<p class="text-[10px] text-red-500">タイムアウト <button onclick="groupCardGenerate(\'video\',' + cardId + ',' + cardIndex + ',\'' + courseName.replace(/'/g,'') + '\',\'' + cardTitle.replace(/'/g,'') + '\')" class="text-red-500 underline">再試行</button></p>'
    }
  }, 5000)
}
window.pollGroupVideo = pollGroupVideo

// ★ 全体配信カード用：歌詞を音声で再生
async function groupPlaySong(btn, encodedLyrics) {
  const lyrics = decodeURIComponent(encodedLyrics)
  const cleanText = lyrics.replace(/\[.*?\]/g, '').replace(/\n+/g, '。').substring(0, 600)
  const origHTML = btn.innerHTML
  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 読込中...'
  btn.disabled = true
  try {
    const res = await axios.post('/api/ai/tts', { text: cleanText, voice: 'Achird', speed: 1.1 })
    if (res.data && res.data.audio_url) {
      const audio = new Audio(res.data.audio_url)
      audio.play()
      btn.innerHTML = '<i class="fas fa-pause"></i> 再生中...'
      btn.onclick = () => { audio.paused ? audio.play() : audio.pause(); btn.innerHTML = audio.paused ? '<i class="fas fa-play"></i> 歌を聴く' : '<i class="fas fa-pause"></i> 再生中...' }
      audio.onended = () => { btn.innerHTML = '<i class="fas fa-play"></i> もう一度聴く'; btn.disabled = false; btn.onclick = () => groupPlaySong(btn, encodedLyrics) }
    } else {
      const u = new SpeechSynthesisUtterance(cleanText)
      u.lang = 'ja-JP'; u.rate = 1.2
      u.onend = () => { btn.innerHTML = origHTML; btn.disabled = false }
      window.speechSynthesis.speak(u)
      btn.innerHTML = '<i class="fas fa-volume-up"></i> 読み上げ中...'
    }
  } catch(e) {
    const u = new SpeechSynthesisUtterance(cleanText)
    u.lang = 'ja-JP'; u.rate = 1.2
    u.onend = () => { btn.innerHTML = origHTML; btn.disabled = false }
    window.speechSynthesis.speak(u)
    btn.innerHTML = '<i class="fas fa-volume-up"></i> 読み上げ中...'
  }
}
window.groupPlaySong = groupPlaySong

// ★ 例題の図解をAI生成（app.js側）
async function generateExampleDiagramApp(cardId, cardTitle, exampleProblem, exampleSolution) {
  const area = document.getElementById('example-diagram-card-' + cardId)
  if (!area) return
  area.innerHTML = '<div class="text-center py-3"><i class="fas fa-spinner fa-spin text-yellow-500 text-xl"></i><p class="text-xs text-yellow-600 mt-1 font-bold">AIが例題の図を描いています...</p></div>'
  try {
    const prompt = '日本の小学校の教科書に載る例題の図解を描いてください。\n' +
      '【カード】' + cardTitle + '\n' +
      '【例題】' + exampleProblem + '\n' +
      (exampleSolution ? '【解き方】' + exampleSolution + '\n' : '') +
      '条件：教科書のイラスト風。児童にわかりやすい色使い。文字は大きく日本語で。幾何の図形は正確に描く。ラベル（頂点名ABCD等）を明確に。白い背景。'
    const res = await axios.post('/api/ai/generate-image', {
      prompt: prompt,
      card_id: cardId, card_title: cardTitle,
      problem_text: exampleProblem, prefer_image: true
    })
    const d = res.data
    if (d.success && d.image_url) {
      area.innerHTML = '<div class="text-center mt-2"><img src="' + d.image_url + '" alt="例題の図" class="max-h-48 rounded border mx-auto"><div class="flex justify-center gap-2 mt-1"><span class="text-[10px] text-gray-400">' + (d.model || 'AI') + ' / ' + Math.round((d.generation_time_ms || 0) / 1000) + '秒</span><button onclick="generateExampleDiagramApp(\'' + cardId + '\',\'' + cardTitle.replace(/'/g, '') + '\',\'' + exampleProblem.replace(/'/g, '').substring(0, 80) + '\',\'' + (exampleSolution || '').replace(/'/g, '').substring(0, 80) + '\')" class="text-[10px] text-yellow-600 underline">🔄 再生成</button></div></div>'
    } else {
      area.innerHTML = '<p class="text-xs text-red-500 mt-1">図の生成に失敗 <button onclick="generateExampleDiagramApp(\'' + cardId + '\',\'' + cardTitle.replace(/'/g, '') + '\',\'' + exampleProblem.replace(/'/g, '').substring(0, 80) + '\',\'' + (exampleSolution || '').replace(/'/g, '').substring(0, 80) + '\')" class="text-yellow-600 underline">再試行</button></p>'
    }
  } catch (e) {
    area.innerHTML = '<p class="text-xs text-red-500 mt-1">通信エラー: ' + e.message + '</p>'
  }
}
window.generateExampleDiagramApp = generateExampleDiagramApp

// ============================================================
// 作図問題用：Canvas描画実技シミュレーター
// コンパス（円弧描画）+ 定規（直線描画）で実際に手を動かして作図
// ============================================================

function initConstructionAnswerWidget(card) {
  console.log('🏗️ initConstructionAnswerWidget 呼び出し:', card?.card_title, card?.problem_text?.substring(0, 50))
  const problem = (card.problem_text || card.problem_description || card.card_title || '').toLowerCase()
  const isConstruction = /垂直二等分線|角の二等分線|垂線|平行線|作図|コンパス.*定規|定規.*コンパス/.test(problem)
  console.log('🏗️ 作図判定:', isConstruction, 'problem:', problem.substring(0, 50))
  if (!isConstruction) return false

  const answerArea = document.getElementById('textAnswerArea')
  console.log('🏗️ textAnswerArea:', answerArea ? '✅発見' : '❌なし', answerArea?.parentElement?.tagName)
  if (!answerArea) return false

  // 作図タイプ判定
  let constructionType = 'general'
  if (/垂直二等分線|中点/.test(problem)) constructionType = 'perp_bisector'
  else if (/角の二等分線|角.*二等分/.test(problem)) constructionType = 'angle_bisector'
  else if (/垂線|垂直/.test(problem)) constructionType = 'perpendicular'
  else if (/平行線/.test(problem)) constructionType = 'parallel'

  const lineLength = parseInt((problem.match(/(\d+)\s*cm/) || [])[1]) || 6
  const uid = 'cw_' + Date.now()

  answerArea.innerHTML = `
    <div class="construction-canvas-widget" id="${uid}">
      <div class="bg-indigo-50 border-2 border-indigo-300 rounded-xl p-3 mb-2">
        <p class="text-sm font-bold text-indigo-800 mb-1">
          <i class="fas fa-drafting-compass mr-1"></i>作図してみよう！
        </p>
        <p class="text-xs text-indigo-600">道具をえらんで、画面の上で作図しよう。コンパスは①中心をタップ→②通る点をタップで円弧、定規は①始点タップ→②終点タップで直線がひけるよ。</p>
      </div>

      <!-- ツール選択バー -->
      <div class="flex gap-2 mb-2 flex-wrap">
        <button onclick="setConstructionTool('${uid}','compass')" id="${uid}_btn_compass"
                class="flex-1 min-w-0 bg-red-500 text-white px-3 py-2 rounded-lg font-bold text-sm border-2 border-red-600 shadow-md transition hover:bg-red-600">
          <i class="fas fa-compass mr-1"></i>コンパス
        </button>
        <button onclick="setConstructionTool('${uid}','ruler')" id="${uid}_btn_ruler"
                class="flex-1 min-w-0 bg-yellow-500 text-gray-800 px-3 py-2 rounded-lg font-bold text-sm border-2 border-yellow-600 shadow-md transition hover:bg-yellow-600 opacity-60">
          <i class="fas fa-ruler mr-1"></i>定規
        </button>
        <button onclick="constructionUndo('${uid}')" 
                class="bg-gray-400 text-white px-3 py-2 rounded-lg font-bold text-sm hover:bg-gray-500 transition">
          <i class="fas fa-undo"></i>
        </button>
        <button onclick="constructionClear('${uid}')"
                class="bg-gray-300 text-gray-700 px-3 py-2 rounded-lg font-bold text-sm hover:bg-gray-400 transition">
          <i class="fas fa-trash"></i>
        </button>
      </div>

      <!-- ツール状態表示 -->
      <div id="${uid}_status" class="text-xs text-center text-gray-500 mb-1 h-5">
        <i class="fas fa-compass text-red-500"></i> コンパス：①中心タップ → ②通る点タップで円弧
      </div>

      <!-- Canvas -->
      <div class="relative bg-white border-2 border-gray-300 rounded-xl shadow-inner" style="touch-action:none; overflow:visible; position:relative;">
        <canvas id="${uid}_canvas" width="600" height="450" 
                onpointerdown="(function(ev,u){ev.preventDefault();ev.stopPropagation();var d=document.getElementById(u+'_debug');if(d){d.textContent='pointer:'+ev.clientX+','+ev.clientY+' t='+Date.now()%10000;}if(window.constructionPointerDown){try{window.constructionPointerDown(ev,u)}catch(e){if(d)d.textContent='ERR:'+e.message}}})(event,'${uid}')"
                onpointermove="(function(ev,u){ev.preventDefault();ev.stopPropagation();if(window.constructionPointerMove){try{window.constructionPointerMove(ev,u)}catch(e){console.error('move err',e)}}})(event,'${uid}')"
                onpointerup="(function(ev,u){ev.preventDefault();ev.stopPropagation();if(window.constructionPointerUp){try{window.constructionPointerUp(ev,u)}catch(e){console.error('up err',e)}}})(event,'${uid}')"
                ontouchstart="(function(ev,u){ev.preventDefault();var t=ev.touches[0];var d=document.getElementById(u+'_debug');if(d){d.textContent='touch:'+Math.round(t.clientX)+','+Math.round(t.clientY);}var fakeEv={clientX:t.clientX,clientY:t.clientY,pointerId:undefined,preventDefault:function(){},stopPropagation:function(){}};if(window.constructionPointerDown){try{window.constructionPointerDown(fakeEv,u)}catch(e){if(d)d.textContent='TERR:'+e.message}}})(event,'${uid}')"
                ontouchmove="(function(ev,u){ev.preventDefault();var t=ev.touches[0];var fakeEv={clientX:t.clientX,clientY:t.clientY,preventDefault:function(){},stopPropagation:function(){}};if(window.constructionPointerMove){try{window.constructionPointerMove(fakeEv,u)}catch(e){}}})(event,'${uid}')"
                ontouchend="(function(ev,u){ev.preventDefault();var fakeEv={clientX:0,clientY:0,preventDefault:function(){},stopPropagation:function(){}};if(window.constructionPointerUp){try{window.constructionPointerUp(fakeEv,u)}catch(e){}}})(event,'${uid}')"
                onclick="(function(ev,u){var d=document.getElementById(u+'_debug');if(d){d.textContent='click:'+ev.clientX+','+ev.clientY+' t='+Date.now()%10000;}if(window.constructionPointerDown){try{window.constructionPointerDown(ev,u)}catch(e){if(d)d.textContent='CERR:'+e.message}}})(event,'${uid}')"
                style="width:100%; height:auto; display:block; cursor:crosshair; touch-action:none; -ms-touch-action:none; -webkit-touch-callout:none; pointer-events:auto; position:relative; z-index:50;"></canvas>
      </div>

      <!-- デバッグ情報（非表示） -->
      <div id="${uid}_debug" class="mt-1 text-xs text-orange-600 text-center font-mono hidden"></div>

      <!-- 描いた図形の情報 -->
      <div id="${uid}_info" class="mt-2 text-xs text-gray-500 text-center">円弧: 0 / 直線: 0</div>
    </div>
  `

  // hidden answerInput を確保
  let answerInput = document.getElementById('answerInput')
  if (!answerInput) {
    answerInput = document.createElement('textarea')
    answerInput.id = 'answerInput'
    answerInput.style.display = 'none'
    answerArea.appendChild(answerInput)
  }

  // 作図状態を初期化
  const state = {
    uid,
    type: constructionType,
    tool: 'compass',
    shapes: [],        // { type:'arc', cx, cy, r, startAngle, endAngle } or { type:'line', x1,y1, x2,y2 }
    phase: 'idle',     // 'idle', 'compass_center_set', 'drawing_arc', 'ruler_first_set'
    tempCenter: null,
    tempStart: null,
    tempRadius: 0,
    presetPoints: [],  // 問題で与えられた固定点
    lineLength,
  }

  // 問題に応じた初期描画（線分ABなど）
  const canvas = document.getElementById(uid + '_canvas')
  if (!canvas) { console.error('Canvas not found:', uid + '_canvas'); return false }
  const ctx = canvas.getContext('2d')
  
  // ★ イベント処理はインラインHTML属性(onpointerdown等)で実装済み
  // addEventListener は使わない（二重発火防止）
  
  // Canvas要素のスタイルを強制（他のCSSで上書きされないように）
  canvas.style.pointerEvents = 'auto'
  canvas.style.touchAction = 'none'
  canvas.style.userSelect = 'none'
  canvas.style.webkitUserSelect = 'none'
  canvas.style.msTouchAction = 'none'
  canvas.style.webkitTouchCallout = 'none'
  canvas.style.position = 'relative'
  canvas.style.zIndex = '50'
  
  // 親要素チェーンの touch-action を修正（スクロール干渉防止）
  let parent = canvas.parentElement
  while (parent && parent !== document.body) {
    const cs = getComputedStyle(parent)
    if (cs.overflowY === 'auto' || cs.overflowY === 'scroll') {
      console.log('⚠️ 作図Canvas: スクロール可能な親を検出:', parent.tagName, parent.className?.substring(0, 50))
    }
    parent = parent.parentElement
  }
  
  // canvas内のrect確認
  const rect = canvas.getBoundingClientRect()
  console.log('✅ 作図Canvas初期化完了:', uid, 'size:', canvas.width, 'x', canvas.height, 'rect:', rect.width.toFixed(0), 'x', rect.height.toFixed(0), 'at', rect.left.toFixed(0), ',', rect.top.toFixed(0))
  
  if (rect.width === 0 || rect.height === 0) {
    console.error('❌ Canvas表示サイズが0です！レイアウトが完了していない可能性があります')
    // 遅延で再試行
    setTimeout(() => {
      const r2 = canvas.getBoundingClientRect()
      console.log('🔄 Canvas再チェック:', r2.width.toFixed(0), 'x', r2.height.toFixed(0))
    }, 500)
  }
  
  drawGrid(ctx, canvas.width, canvas.height)
  
  if (constructionType === 'perp_bisector') {
    const ax = 120, ay = 300, bx = 480, by = 300
    state.presetPoints = [{x:ax, y:ay, label:'A'}, {x:bx, y:by, label:'B'}]
    state.presetLine = {x1:ax, y1:ay, x2:bx, y2:by}
    drawPreset(ctx, state)
  } else if (constructionType === 'angle_bisector') {
    const ox = 100, oy = 350
    const ax = 500, ay = 350
    const bx = 380, by = 80
    state.presetPoints = [{x:ox, y:oy, label:'O'}, {x:ax, y:ay, label:'A'}, {x:bx, y:by, label:'B'}]
    state.presetLines = [{x1:ox, y1:oy, x2:ax, y2:ay}, {x1:ox, y1:oy, x2:bx, y2:by}]
    drawPreset(ctx, state)
  } else if (constructionType === 'perpendicular') {
    const ax = 60, ay = 280, bx = 540, by = 280
    const px = 300, py = 280
    state.presetPoints = [{x:ax, y:ay, label:'A'}, {x:bx, y:by, label:'B'}, {x:px, y:py, label:'P'}]
    state.presetLine = {x1:ax, y1:ay, x2:bx, y2:by}
    drawPreset(ctx, state)
  } else {
    // 汎用：空のキャンバス
    state.presetPoints = []
  }

  window._constructionStates = window._constructionStates || {}
  window._constructionStates[uid] = state
  window._constructionCorrectSteps = null // 手順並べ替えは無効化

  return true
}

// --- 描画ヘルパー ---
function drawGrid(ctx, w, h) {
  ctx.save()
  ctx.strokeStyle = '#e5e7eb'
  ctx.lineWidth = 0.5
  for (let x = 0; x <= w; x += 30) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke() }
  for (let y = 0; y <= h; y += 30) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke() }
  ctx.restore()
}

function drawPreset(ctx, state) {
  ctx.save()
  // 固定線分
  ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 3
  if (state.presetLine) {
    ctx.beginPath(); ctx.moveTo(state.presetLine.x1, state.presetLine.y1); ctx.lineTo(state.presetLine.x2, state.presetLine.y2); ctx.stroke()
  }
  if (state.presetLines) {
    state.presetLines.forEach(l => { ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke() })
  }
  // 固定点
  state.presetPoints.forEach(p => {
    ctx.fillStyle = '#1e293b'
    ctx.beginPath(); ctx.arc(p.x, p.y, 5, 0, Math.PI * 2); ctx.fill()
    ctx.font = 'bold 16px sans-serif'
    ctx.fillText(p.label, p.x - 5, p.y + 22)
  })
  // 長さ表示
  if (state.presetLine) {
    const mx = (state.presetLine.x1 + state.presetLine.x2) / 2
    const my = state.presetLine.y1 + 20
    ctx.fillStyle = '#6b7280'; ctx.font = '12px sans-serif'
    ctx.fillText(state.lineLength + 'cm', mx - 15, my + 5)
  }
  ctx.restore()
}

function redrawConstruction(uid) {
  const state = window._constructionStates[uid]
  if (!state) return
  const canvas = document.getElementById(uid + '_canvas')
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  
  ctx.clearRect(0, 0, canvas.width, canvas.height)
  drawGrid(ctx, canvas.width, canvas.height)
  drawPreset(ctx, state)

  // 描いた図形を再描画
  state.shapes.forEach((s, i) => {
    ctx.save()
    if (s.type === 'arc') {
      ctx.strokeStyle = ['#ef4444','#3b82f6','#8b5cf6','#f59e0b','#10b981'][i % 5]
      ctx.lineWidth = 2.5
      ctx.setLineDash([6, 4])
      ctx.beginPath()
      ctx.arc(s.cx, s.cy, s.r, s.startAngle, s.endAngle)
      ctx.stroke()
      // 中心マーク
      ctx.setLineDash([])
      ctx.fillStyle = ctx.strokeStyle
      ctx.beginPath(); ctx.arc(s.cx, s.cy, 3, 0, Math.PI * 2); ctx.fill()
    } else if (s.type === 'line') {
      ctx.strokeStyle = '#22c55e'
      ctx.lineWidth = 2.5
      ctx.beginPath(); ctx.moveTo(s.x1, s.y1); ctx.lineTo(s.x2, s.y2); ctx.stroke()
      // 端点マーク
      ctx.fillStyle = '#22c55e'
      ctx.beginPath(); ctx.arc(s.x1, s.y1, 3, 0, Math.PI * 2); ctx.fill()
      ctx.beginPath(); ctx.arc(s.x2, s.y2, 3, 0, Math.PI * 2); ctx.fill()
    }
    ctx.restore()
  })

  // 情報更新
  const arcCount = state.shapes.filter(s => s.type === 'arc').length
  const lineCount = state.shapes.filter(s => s.type === 'line').length
  const info = document.getElementById(uid + '_info')
  if (info) info.textContent = `円弧: ${arcCount} / 直線: ${lineCount}`

  // answerInput にデータを書き込み（採点用）
  updateConstructionAnswer(uid)
}

function updateConstructionAnswer(uid) {
  const state = window._constructionStates[uid]
  if (!state) return
  const answerInput = document.getElementById('answerInput')
  if (answerInput) {
    answerInput.value = JSON.stringify({
      constructionType: state.type,
      shapes: state.shapes,
      presetPoints: state.presetPoints.map(p => ({x:p.x, y:p.y})),
    })
  }
}

// --- ツール切り替え ---
function setConstructionTool(uid, tool) {
  const state = window._constructionStates[uid]
  if (!state) return
  state.tool = tool
  state.phase = 'idle'
  state.tempCenter = null
  state.tempStart = null

  // ボタンUI更新
  const compassBtn = document.getElementById(uid + '_btn_compass')
  const rulerBtn = document.getElementById(uid + '_btn_ruler')
  if (compassBtn && rulerBtn) {
    if (tool === 'compass') {
      compassBtn.classList.remove('opacity-60'); compassBtn.classList.add('ring-2','ring-red-400')
      rulerBtn.classList.add('opacity-60'); rulerBtn.classList.remove('ring-2','ring-yellow-400')
    } else {
      rulerBtn.classList.remove('opacity-60'); rulerBtn.classList.add('ring-2','ring-yellow-400')
      compassBtn.classList.add('opacity-60'); compassBtn.classList.remove('ring-2','ring-red-400')
    }
  }
  
  const statusEl = document.getElementById(uid + '_status')
  if (statusEl) {
    statusEl.innerHTML = tool === 'compass'
      ? '<i class="fas fa-compass text-red-500"></i> コンパス：①中心タップ → ②通る点タップで円弧'
      : '<i class="fas fa-ruler text-yellow-600"></i> 定規：始点をタップ → 終点をタップで直線'
  }

  // プレビュー消去
  redrawConstruction(uid)
}

// --- ポインタイベント ---
function getCanvasPos(e, uid) {
  const canvas = document.getElementById(uid + '_canvas')
  if (!canvas) {
    console.warn('getCanvasPos: canvas not found for', uid)
    return {x:0, y:0}
  }
  // 防御: getBoundingClientRect が存在しない場合（非DOM要素等）
  if (typeof canvas.getBoundingClientRect !== 'function') {
    console.error('getCanvasPos: getBoundingClientRect not available on:', typeof canvas, canvas.tagName, canvas.nodeName)
    // e.target から直接 canvas を取得する試み
    const actualCanvas = e.target && e.target.tagName === 'CANVAS' ? e.target : null
    if (actualCanvas && typeof actualCanvas.getBoundingClientRect === 'function') {
      const rect = actualCanvas.getBoundingClientRect()
      const scaleX = actualCanvas.width / rect.width
      const scaleY = actualCanvas.height / rect.height
      return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY }
    }
    // offsetX/offsetY フォールバック
    if (e.offsetX !== undefined) {
      const cw = canvas.width || 600
      const ch = canvas.height || 450
      const ow = canvas.offsetWidth || cw
      const oh = canvas.offsetHeight || ch
      return { x: e.offsetX * (cw / ow), y: e.offsetY * (ch / oh) }
    }
    return {x:0, y:0}
  }
  const rect = canvas.getBoundingClientRect()
  const scaleX = canvas.width / rect.width
  const scaleY = canvas.height / rect.height
  return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY }
}

// 近くのプリセット点にスナップ（30px以内）
function snapToPoint(pos, state) {
  let closest = null, minDist = 30
  const allPoints = [...state.presetPoints]
  // 円弧の交点も検出してスナップ対象に
  const intersections = findArcIntersections(state.shapes)
  intersections.forEach(p => allPoints.push({x:p.x, y:p.y, label:''}))
  
  allPoints.forEach(p => {
    const d = Math.sqrt((pos.x - p.x)**2 + (pos.y - p.y)**2)
    if (d < minDist) { minDist = d; closest = {x:p.x, y:p.y} }
  })
  return closest || pos
}

// 2つの円弧の交点を算出
function findArcIntersections(shapes) {
  const arcs = shapes.filter(s => s.type === 'arc')
  const points = []
  for (let i = 0; i < arcs.length; i++) {
    for (let j = i + 1; j < arcs.length; j++) {
      const pts = circleCircleIntersect(arcs[i].cx, arcs[i].cy, arcs[i].r, arcs[j].cx, arcs[j].cy, arcs[j].r)
      pts.forEach(p => points.push(p))
    }
  }
  return points
}

function circleCircleIntersect(cx1,cy1,r1, cx2,cy2,r2) {
  const dx = cx2 - cx1, dy = cy2 - cy1
  const d = Math.sqrt(dx*dx + dy*dy)
  if (d > r1 + r2 || d < Math.abs(r1 - r2) || d === 0) return []
  const a = (r1*r1 - r2*r2 + d*d) / (2*d)
  const h = Math.sqrt(Math.max(0, r1*r1 - a*a))
  const mx = cx1 + a * dx / d, my = cy1 + a * dy / d
  return [
    { x: mx + h * dy / d, y: my - h * dx / d },
    { x: mx - h * dy / d, y: my + h * dx / d }
  ]
}

function constructionPointerDown(e, uid) {
  console.log('🎯 constructionPointerDown uid:', uid, 'type:', e?.type)
  try { if (e.preventDefault) e.preventDefault() } catch(ex) {}
  try { if (e.stopPropagation) e.stopPropagation() } catch(ex) {}
  
  // デバッグ表示更新
  const debugEl = document.getElementById(uid + '_debug')
  
  const state = window._constructionStates[uid]
  if (!state) { 
    console.warn('No construction state for', uid)
    if (debugEl) debugEl.textContent = '❌ state不在 uid=' + uid
    return 
  }
  
  // 二重発火防止（80ms以内）
  const now = Date.now()
  if (state._lastPointerTime && now - state._lastPointerTime < 80) {
    return
  }
  state._lastPointerTime = now
  
  // 座標取得（複数方式で堅牢に）
  const rawPos = getCanvasPosRobust(e, uid, state)
  const pos = snapToPoint(rawPos, state)
  console.log('🎯 作図タップ:', state.tool, 'pos:', Math.round(pos.x), Math.round(pos.y), 'phase:', state.phase)
  if (debugEl) debugEl.textContent = '✅ ' + state.tool + ' (' + Math.round(pos.x) + ',' + Math.round(pos.y) + ') phase:' + state.phase

  try {
    const canvas = document.getElementById(uid + '_canvas')
    const ctx = canvas ? canvas.getContext('2d') : null

    if (state.tool === 'compass') {
      if (state.phase !== 'compass_center_set') {
        // ★ コンパス 第1クリック：中心を設定
        state.tempCenter = pos
        state.phase = 'compass_center_set'
        state.tempRadius = 0
        
        const statusEl = document.getElementById(uid + '_status')
        if (statusEl) statusEl.innerHTML = '<i class="fas fa-compass text-red-500"></i> 次に、円弧を通る点をタップ！'
        
        // 中心マーク描画
        if (ctx) {
          redrawConstruction(uid)
          ctx.save()
          ctx.fillStyle = '#ef4444'
          ctx.beginPath(); ctx.arc(pos.x, pos.y, 8, 0, Math.PI * 2); ctx.fill()
          ctx.fillStyle = 'rgba(239,68,68,0.15)'
          ctx.beginPath(); ctx.arc(pos.x, pos.y, 20, 0, Math.PI * 2); ctx.fill()
          ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2; ctx.setLineDash([4,4])
          ctx.beginPath(); ctx.arc(pos.x, pos.y, 20, 0, Math.PI * 2); ctx.stroke()
          ctx.restore()
        }
        if (debugEl) debugEl.textContent = '🔴 中心設定済み (' + Math.round(pos.x) + ',' + Math.round(pos.y) + ') → 円弧通過点をタップ'

      } else {
        // ★ コンパス 第2クリック：半径確定 → 円弧描画
        const cx = state.tempCenter.x, cy = state.tempCenter.y
        const r = Math.sqrt((pos.x - cx)**2 + (pos.y - cy)**2)
        
        if (r < 10) {
          // 近すぎ→キャンセル
          if (debugEl) debugEl.textContent = '⚠️ 近すぎ（' + Math.round(r) + 'px）→やり直し'
          state.phase = 'idle'
          state.tempCenter = null
          const statusEl = document.getElementById(uid + '_status')
          if (statusEl) statusEl.innerHTML = '<i class="fas fa-compass text-red-500"></i> コンパス：中心をタップ → 円弧通過点をタップ'
          redrawConstruction(uid)
          return
        }
        
        state.shapes.push({
          type: 'arc', cx: cx, cy: cy, r: r,
          startAngle: 0, endAngle: Math.PI * 2
        })
        state.phase = 'idle'
        state.tempCenter = null
        state.tempRadius = 0
        
        const statusEl = document.getElementById(uid + '_status')
        if (statusEl) statusEl.innerHTML = '<i class="fas fa-compass text-red-500"></i> コンパス：中心をタップ → 円弧通過点をタップ'
        
        redrawConstruction(uid)
        playConstructionSound('arc')
        if (debugEl) debugEl.textContent = '✅ 円弧追加！半径' + Math.round(r) + 'px'
      }

    } else if (state.tool === 'ruler') {
      if (state.phase !== 'ruler_first_set') {
        // ★ 定規 第1クリック：始点を設定
        state.tempStart = pos
        state.phase = 'ruler_first_set'
        
        const statusEl = document.getElementById(uid + '_status')
        if (statusEl) statusEl.innerHTML = '<i class="fas fa-ruler text-yellow-600"></i> 終点をタップ！'
        
        // 始点マーク描画
        if (ctx) {
          redrawConstruction(uid)
          ctx.save()
          ctx.fillStyle = '#22c55e'
          ctx.beginPath(); ctx.arc(pos.x, pos.y, 8, 0, Math.PI * 2); ctx.fill()
          ctx.fillStyle = 'rgba(34,197,94,0.15)'
          ctx.beginPath(); ctx.arc(pos.x, pos.y, 20, 0, Math.PI * 2); ctx.fill()
          ctx.restore()
        }
        if (debugEl) debugEl.textContent = '🟢 始点設定 (' + Math.round(pos.x) + ',' + Math.round(pos.y) + ') → 終点をタップ'

      } else {
        // ★ 定規 第2クリック：終点 → 直線描画
        const dist = Math.sqrt((pos.x - state.tempStart.x)**2 + (pos.y - state.tempStart.y)**2)
        if (dist < 10) {
          if (debugEl) debugEl.textContent = '⚠️ 近すぎ（' + Math.round(dist) + 'px）→やり直し'
          return
        }
        state.shapes.push({ type: 'line', x1: state.tempStart.x, y1: state.tempStart.y, x2: pos.x, y2: pos.y })
        state.phase = 'idle'
        state.tempStart = null
        
        const statusEl = document.getElementById(uid + '_status')
        if (statusEl) statusEl.innerHTML = '<i class="fas fa-ruler text-yellow-600"></i> 定規：始点をタップ → 終点をタップで直線'
        
        redrawConstruction(uid)
        playConstructionSound('line')
        if (debugEl) debugEl.textContent = '✅ 直線追加！'
      }
    }
  } catch(err) {
    console.error('❌ constructionPointerDown error:', err.message, err.stack)
    if (debugEl) debugEl.textContent = '❌ ERR: ' + err.message
  }
}

// 堅牢な座標取得（複数フォールバック）
function getCanvasPosRobust(e, uid, state) {
  // 方法1: getBoundingClientRect
  try {
    const canvas = document.getElementById(uid + '_canvas')
    if (canvas && typeof canvas.getBoundingClientRect === 'function' && e.clientX !== undefined) {
      const rect = canvas.getBoundingClientRect()
      if (rect.width > 0 && rect.height > 0) {
        const scaleX = canvas.width / rect.width
        const scaleY = canvas.height / rect.height
        return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY }
      }
    }
  } catch(ex) { console.warn('getCanvasPos方法1失敗:', ex.message) }
  
  // 方法2: e.target から取得
  try {
    const target = e.target
    if (target && target.tagName === 'CANVAS' && typeof target.getBoundingClientRect === 'function') {
      const rect = target.getBoundingClientRect()
      if (rect.width > 0 && rect.height > 0) {
        const scaleX = target.width / rect.width
        const scaleY = target.height / rect.height
        return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY }
      }
    }
  } catch(ex) { console.warn('getCanvasPos方法2失敗:', ex.message) }
  
  // 方法3: offsetX/offsetY
  try {
    if (e.offsetX !== undefined && e.offsetY !== undefined) {
      const canvas = document.getElementById(uid + '_canvas')
      const cw = (canvas && canvas.width) || 600
      const ch = (canvas && canvas.height) || 450
      const ow = (canvas && canvas.offsetWidth) || cw
      const oh = (canvas && canvas.offsetHeight) || ch
      return { x: e.offsetX * (cw / ow), y: e.offsetY * (ch / oh) }
    }
  } catch(ex) { console.warn('getCanvasPos方法3失敗:', ex.message) }
  
  // 方法4: pageX + scroll offset
  try {
    const canvas = document.getElementById(uid + '_canvas')
    if (canvas && e.pageX !== undefined) {
      const rect = canvas.getBoundingClientRect()
      const scrollX = window.pageXOffset || document.documentElement.scrollLeft
      const scrollY = window.pageYOffset || document.documentElement.scrollTop
      const scaleX = canvas.width / (rect.width || canvas.width)
      const scaleY = canvas.height / (rect.height || canvas.height)
      return { x: (e.pageX - rect.left - scrollX) * scaleX, y: (e.pageY - rect.top - scrollY) * scaleY }
    }
  } catch(ex) {}
  
  return { x: 300, y: 225 } // 最終フォールバック: キャンバス中央
}

function constructionPointerMove(e, uid) {
  // ドラッグ非対応モード（クリック2回方式）では不要だが、
  // ポインタイベントが動作する環境向けにプレビュー表示
  const state = window._constructionStates[uid]
  if (!state) return
  try { if (e.preventDefault) e.preventDefault() } catch(ex) {}
  
  if (state.tool === 'compass' && state.phase === 'compass_center_set' && state.tempCenter) {
    // コンパス：半径プレビュー
    const pos = getCanvasPosRobust(e, uid, state)
    const cx = state.tempCenter.x, cy = state.tempCenter.y
    const r = Math.sqrt((pos.x - cx)**2 + (pos.y - cy)**2)
    if (r < 10) return
    
    state.tempRadius = r
    const canvas = document.getElementById(uid + '_canvas')
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    redrawConstruction(uid)
    
    ctx.save()
    ctx.strokeStyle = 'rgba(239,68,68,0.3)'; ctx.lineWidth = 1; ctx.setLineDash([4,4])
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(pos.x, pos.y); ctx.stroke()
    ctx.strokeStyle = 'rgba(239,68,68,0.5)'; ctx.lineWidth = 2.5; ctx.setLineDash([6,4])
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke()
    ctx.setLineDash([])
    ctx.fillStyle = '#ef4444'; ctx.font = '11px sans-serif'
    ctx.fillText(Math.round(r) + 'px', (cx + pos.x)/2 + 5, (cy + pos.y)/2 - 5)
    ctx.fillStyle = '#ef4444'
    ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2); ctx.fill()
    ctx.restore()
    
  } else if (state.tool === 'ruler' && state.phase === 'ruler_first_set' && state.tempStart) {
    // 定規：直線プレビュー
    const pos = getCanvasPosRobust(e, uid, state)
    const canvas = document.getElementById(uid + '_canvas')
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    redrawConstruction(uid)
    
    ctx.save()
    ctx.strokeStyle = 'rgba(34,197,94,0.4)'; ctx.lineWidth = 2; ctx.setLineDash([6,4])
    ctx.beginPath(); ctx.moveTo(state.tempStart.x, state.tempStart.y); ctx.lineTo(pos.x, pos.y); ctx.stroke()
    ctx.fillStyle = '#22c55e'
    ctx.beginPath(); ctx.arc(state.tempStart.x, state.tempStart.y, 5, 0, Math.PI * 2); ctx.fill()
    ctx.beginPath(); ctx.arc(pos.x, pos.y, 5, 0, Math.PI * 2); ctx.fill()
    ctx.restore()
  }
}

function constructionPointerUp(e, uid) {
  // クリック2回方式では pointerUp での確定は不要
  // ドラッグ操作が動作する環境向け互換性維持
  const state = window._constructionStates[uid]
  if (!state) return
  // ドラッグでの円弧確定（ポインタイベント対応環境のみ）
  if (state.tool === 'compass' && state.phase === 'compass_center_set' && state.tempRadius >= 15) {
    state.shapes.push({
      type: 'arc',
      cx: state.tempCenter.x, cy: state.tempCenter.y,
      r: state.tempRadius,
      startAngle: 0, endAngle: Math.PI * 2
    })
    state.phase = 'idle'
    state.tempCenter = null
    state.tempRadius = 0
    const statusEl = document.getElementById(uid + '_status')
    if (statusEl) statusEl.innerHTML = '<i class="fas fa-compass text-red-500"></i> コンパス：中心をタップ → 円弧通過点をタップ'
    redrawConstruction(uid)
    playConstructionSound('arc')
    const debugEl = document.getElementById(uid + '_debug')
    if (debugEl) debugEl.textContent = '✅ 円弧追加！(ドラッグ)'
  }
}

function constructionUndo(uid) {
  const state = window._constructionStates[uid]
  if (!state) return
  state.shapes.pop()
  state.phase = 'idle'
  redrawConstruction(uid)
}

function constructionClear(uid) {
  const state = window._constructionStates[uid]
  if (!state) return
  state.shapes = []
  state.phase = 'idle'
  redrawConstruction(uid)
}

function playConstructionSound(type) {
  try {
    const ac = new (window.AudioContext || window.webkitAudioContext)()
    const osc = ac.createOscillator()
    const gain = ac.createGain()
    osc.type = 'sine'
    osc.frequency.value = type === 'arc' ? 523 : 659
    gain.gain.setValueAtTime(0.15, ac.currentTime)
    gain.gain.exponentialRampToValueAtTime(0.01, ac.currentTime + 0.2)
    osc.connect(gain); gain.connect(ac.destination)
    osc.start(); osc.stop(ac.currentTime + 0.2)
  } catch(e) {}
}

// --- 作図の採点（幾何学的判定） ---
function gradeConstructionDrawing(uid) {
  const state = window._constructionStates[uid]
  if (!state) return { score: 0, feedback: '作図データがありません' }

  const arcs = state.shapes.filter(s => s.type === 'arc')
  const lines = state.shapes.filter(s => s.type === 'line')
  const results = []
  let score = 0

  if (state.type === 'perp_bisector') {
    // 垂直二等分線の判定
    const A = state.presetPoints[0], B = state.presetPoints[1]
    const midX = (A.x + B.x) / 2, midY = (A.y + B.y) / 2
    
    // 1. 円弧を2つ以上描いたか
    if (arcs.length >= 2) { 
      results.push({ok: true, text: '✅ 円弧を2つ描けた'}) 
      score += 20
    } else {
      results.push({ok: false, text: '❌ 円弧が2つ必要（AとBを中心に1つずつ）'})
    }

    // 2. 円弧の中心がA, Bに近いか
    const arcAtA = arcs.find(a => Math.sqrt((a.cx - A.x)**2 + (a.cy - A.y)**2) < 30)
    const arcAtB = arcs.find(a => Math.sqrt((a.cx - B.x)**2 + (a.cy - B.y)**2) < 30)
    if (arcAtA && arcAtB) {
      results.push({ok: true, text: '✅ AとBを中心に円弧を描けた'})
      score += 20
    } else {
      results.push({ok: false, text: '❌ 円弧の中心をAとBにしよう'})
    }

    // 3. 2つの円弧の半径がほぼ同じか
    if (arcAtA && arcAtB && Math.abs(arcAtA.r - arcAtB.r) < 20) {
      results.push({ok: true, text: '✅ 同じ半径で円弧を描けた'})
      score += 15
    } else if (arcAtA && arcAtB) {
      results.push({ok: false, text: '⚠️ 2つの円弧の半径を同じにしよう'})
    }

    // 4. 直線を描いたか
    if (lines.length >= 1) {
      results.push({ok: true, text: '✅ 直線を引けた'})
      score += 15
    } else {
      results.push({ok: false, text: '❌ 交点を結ぶ直線を引こう'})
    }

    // 5. 直線が中点を通るか
    if (lines.length >= 1) {
      const L = lines[lines.length - 1]
      const distToMid = pointToLineDistance(midX, midY, L.x1, L.y1, L.x2, L.y2)
      if (distToMid < 25) {
        results.push({ok: true, text: '✅ 直線が中点を通っている'})
        score += 15
      } else {
        results.push({ok: false, text: '⚠️ 直線が線分ABの中点を通るようにしよう'})
      }
    }

    // 6. 直線がABに垂直か
    if (lines.length >= 1) {
      const L = lines[lines.length - 1]
      const lineAngle = Math.atan2(L.y2 - L.y1, L.x2 - L.x1) * 180 / Math.PI
      const abAngle = Math.atan2(B.y - A.y, B.x - A.x) * 180 / Math.PI
      const angleDiff = Math.abs(((lineAngle - abAngle + 180) % 180) - 90)
      if (angleDiff < 15) {
        results.push({ok: true, text: '✅ 垂直に交わっている！'})
        score += 15
      } else {
        results.push({ok: false, text: '⚠️ 線分ABと垂直（90°）になるようにしよう'})
      }
    }

  } else if (state.type === 'angle_bisector') {
    const O = state.presetPoints[0], A = state.presetPoints[1], B = state.presetPoints[2]
    
    if (arcs.length >= 1) { results.push({ok: true, text: '✅ 円弧を描けた'}); score += 25 }
    else results.push({ok: false, text: '❌ Oを中心に円弧を描こう'})

    if (arcs.length >= 3) { results.push({ok: true, text: '✅ 3つ以上の円弧を描けた'}); score += 25 }
    else if (arcs.length >= 2) { results.push({ok: false, text: '❌ もう1つ円弧が必要（辺上の2点から交点を求めよう）'}); score += 15 }
    else { results.push({ok: false, text: '❌ 3つの円弧が必要（O中心→辺上の2点中心→交点）'}) }
    
    if (lines.length >= 1) { results.push({ok: true, text: '✅ 二等分線を引けた'}); score += 25 }
    else results.push({ok: false, text: '❌ 頂点Oから交点を通る直線を引こう'})

    // 二等分線がOを通るか
    if (lines.length >= 1) {
      const L = lines[lines.length - 1]
      const distToO = pointToLineDistance(O.x, O.y, L.x1, L.y1, L.x2, L.y2)
      if (distToO < 25) { results.push({ok: true, text: '✅ 直線が頂点Oを通っている'}); score += 25 }
      else results.push({ok: false, text: '⚠️ 直線が頂点Oを通るようにしよう'})
    }

  } else {
    // 汎用判定
    if (arcs.length >= 1) { score += 30; results.push({ok: true, text: '✅ 円弧を描けた'}) }
    if (lines.length >= 1) { score += 30; results.push({ok: true, text: '✅ 直線を引けた'}) }
    if (arcs.length >= 2) { score += 20; results.push({ok: true, text: '✅ 複数の円弧を使えた'}) }
    if (arcs.length + lines.length >= 3) { score += 20; results.push({ok: true, text: '✅ 十分な作図ステップ'}) }
    if (score === 0) results.push({ok: false, text: '❌ コンパスと定規を使って作図してみよう'})
  }

  return { score: Math.min(100, score), results, type: state.type }
}

function pointToLineDistance(px, py, x1, y1, x2, y2) {
  const A = px - x1, B = py - y1, C = x2 - x1, D = y2 - y1
  const dot = A * C + B * D
  const lenSq = C * C + D * D
  let t = lenSq !== 0 ? dot / lenSq : -1
  t = Math.max(0, Math.min(1, t))
  const xx = x1 + t * C, yy = y1 + t * D
  return Math.sqrt((px - xx)**2 + (py - yy)**2)
}

