// 先生を呼ぶ
function callTeacher() {
  window.currentHelpType = 'teacher'
  window.helpCount++
  
  // 進捗保存は行わない（先生呼び出しは単なる通知）
  
  // WebSocket通知を送信
  if (state.selectedCard && state.selectedCurriculum) {
    const card = window.currentCardData // グローバルに保存されたカードデータ
    sendHelpRequest(
      state.student.id,
      state.student.name,
      state.selectedCurriculum.id,
      state.selectedCard,
      card?.card_title || '学習カード',
      'teacher'
    )
  }
  
  alert('先生に助けを求めました。先生が来るまで他の問題に取り組んでもOKです。')
}

// 友達に聞く
async function askFriend() {
  window.currentHelpType = 'friend'
  window.helpCount++
  
  try {
    // 助けられる友達リストを取得
    const response = await axios.get(
      `/api/help/available-helpers/${state.student.classCode}/${state.selectedCurriculum.id}/${state.selectedCard}`
    )
    const { helpers } = response.data
    
    if (helpers.length === 0) {
      alert('この問題をすでにクリアしている友達がまだいません。\n\nヒントカードやAI先生を使ってみましょう！')
      return
    }
    
    // 助けられる友達リストをモーダルで表示
    const modal = document.createElement('div')
    modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4'
    modal.innerHTML = `
      <div class="bg-white rounded-lg shadow-2xl max-w-3xl w-full max-h-[80vh] overflow-auto p-8">
        <h2 class="text-3xl font-bold text-green-600 mb-6">
          <i class="fas fa-user-friends mr-3"></i>助けられる友達
        </h2>
        
        <div class="bg-green-50 border-2 border-green-300 rounded-lg p-4 mb-6">
          <p class="text-gray-700">
            この問題をすでにクリアしている友達がいます！<br>
            助けを求めてみましょう。
          </p>
        </div>
        
        <div class="space-y-4 mb-6">
          ${helpers.map(helper => `
            <div class="bg-white border-2 border-green-300 rounded-lg p-6 hover:bg-green-50 transition">
              <div class="flex items-center justify-between">
                <div class="flex items-center">
                  <div class="w-12 h-12 rounded-full bg-green-400 flex items-center justify-center text-white font-bold text-lg mr-4">
                    ${helper.student_number}
                  </div>
                  <div>
                    <h3 class="text-xl font-bold text-gray-800">${helper.name}</h3>
                    <p class="text-sm text-gray-600">
                      完了カード数: ${helper.total_completed}枚
                    </p>
                  </div>
                </div>
                <button onclick="requestPeerHelp('${helper.id}', '${helper.name}'); this.closest('.fixed').remove()" 
                        class="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-6 rounded-lg">
                  <i class="fas fa-comments mr-2"></i>助けを求める
                </button>
              </div>
            </div>
          `).join('')}
        </div>
        
        <button onclick="this.closest('.fixed').remove()" 
                class="w-full bg-gray-400 hover:bg-gray-500 text-white font-bold py-3 px-6 rounded-lg">
          閉じる
        </button>
      </div>
    `
    
    document.body.appendChild(modal)
  } catch (error) {
    console.error('友達検索エラー:', error)
    alert('この問題をすでにクリアしている友達がまだいません。\n\nヒントカードやAI先生を使ってみましょう！')
  }
}

// 分かった度設定
function setUnderstanding(level) {
  window.currentUnderstandingLevel = level
  
  // すべてのボタンのスタイルをリセット
  document.querySelectorAll('.understanding-btn').forEach(btn => {
    btn.classList.remove('bg-indigo-100', 'border-2', 'border-indigo-600')
  })
  
  // 選択されたボタンをハイライト
  const selectedBtn = document.querySelector(`[data-level="${level}"]`)
  selectedBtn.classList.add('bg-indigo-100', 'border-2', 'border-indigo-600')
}

// ============================================
// 一問一答システム
// ============================================
window.qaStepState = {
  questions: [],       // [{question, answer, index}]
  currentStep: 0,
  totalSteps: 0,
  results: [],         // [{correct, studentAnswer, correctAnswer}]
  originalProblem: '', // 元の問題文
  originalAnswer: '',  // 元の正解
  active: false
}

// 問題文を小問に分割する
function parseSubQuestions(problemText, answerText) {
  const lines = problemText.split('\n').map(l => l.trim()).filter(Boolean)
  const answerLines = answerText.split('\n').map(l => l.trim()).filter(Boolean)
  
  // 小問パターン（(1) (2), ①②, ⑴⑵, 問1 問2, (ア)(イ) etc.）
  const subQPatterns = [
    /^[\(（]\s*(\d+)\s*[\)）]/,        // (1) (2) (3)
    /^(\d+)\s*[\.\)）]/,               // 1. 2. 3) 
    /^([①②③④⑤⑥⑦⑧⑨⑩])/,           // ①②③
    /^[\(（]\s*([ア-オ])\s*[\)）]/,     // (ア)(イ)
    /^[\(（]\s*([a-e])\s*[\)）]/i,      // (a)(b)
    /^問\s*(\d+)/                       // 問1 問2
  ]
  
  const questions = []
  let contextLines = [] // 共通の問題文（小問の前に来るテキスト）
  let currentQ = null
  
  for (const line of lines) {
    let isSubQ = false
    for (const pat of subQPatterns) {
      if (pat.test(line)) {
        isSubQ = true
        break
      }
    }
    
    if (isSubQ) {
      if (currentQ) questions.push(currentQ)
      currentQ = { text: line, lines: [line] }
    } else if (currentQ) {
      currentQ.text += '\n' + line
      currentQ.lines.push(line)
    } else {
      contextLines.push(line)
    }
  }
  if (currentQ) questions.push(currentQ)
  
  // 小問が見つからなかった場合 → 「また、」「そして」「さらに」で分割を試みる
  if (questions.length <= 1) {
    const fullText = problemText.replace(/\n/g, ' ')
    // 「〜ですか。また、〜」「〜なさい。そして、〜」「〜しょう。さらに、〜」パターン
    const splitPatterns = [
      /([^。]+(?:ですか|ください|なさい|ましょう|しょう)[。？?])\s*(?:また[、,]|そして[、,]|さらに[、,]|次に[、,]|それから[、,])/g
    ]
    
    let splitParts = []
    for (const pat of splitPatterns) {
      const fullCopy = fullText
      let lastIndex = 0
      let match
      pat.lastIndex = 0
      while ((match = pat.exec(fullCopy)) !== null) {
        splitParts.push(match[1].trim())
        lastIndex = match.index + match[1].length
      }
      if (splitParts.length > 0) {
        // 残りの部分を最後の小問として追加
        const remaining = fullText.substring(lastIndex).replace(/^\s*(?:また[、,]|そして[、,]|さらに[、,]|次に[、,]|それから[、,])\s*/, '').trim()
        if (remaining) splitParts.push(remaining)
        break
      }
    }
    
    // 分割できなかった場合、「。」で終わる質問文を区切る（2つ以上の質問がある場合）
    if (splitParts.length <= 1) {
      // 「〜は誰ですか。」「〜はどのような様子ですか。」のようなパターンを探す
      const questionSentences = fullText.match(/[^。]*(?:ですか|ください|なさい|ましょう|しょう|でしょう)[。？?]/g) || []
      if (questionSentences.length >= 2) {
        // 共通部分（文頭の導入文）を検出
        let contextPart = ''
        const firstQStart = fullText.indexOf(questionSentences[0])
        if (firstQStart > 0) {
          contextPart = fullText.substring(0, firstQStart).trim()
        }
        splitParts = questionSentences.map(q => (contextPart ? contextPart + ' ' : '') + q.trim())
      }
    }
    
    if (splitParts.length >= 2) {
      // 正解テキストも分割
      const splitAnswers = splitAnswerText(answerText, splitParts.length)
      return splitParts.map((q, i) => ({
        question: q,
        answer: splitAnswers[i] || answerText,
        context: '',
        subQuestion: q,
        index: i
      }))
    }
    
    // 分割できなかった場合 → 1問として扱う
    return [{
      question: problemText,
      answer: answerText,
      index: 0
    }]
  }
  
  // 正解テキストも同様に分割
  const parsedAnswers = []
  let currentA = null
  for (const line of answerLines) {
    let isSubA = false
    for (const pat of subQPatterns) {
      if (pat.test(line)) {
        isSubA = true
        break
      }
    }
    if (isSubA) {
      if (currentA) parsedAnswers.push(currentA)
      currentA = line
    } else if (currentA) {
      currentA += '\n' + line
    } else {
      // コンテキスト行（無視）
    }
  }
  if (currentA) parsedAnswers.push(currentA)
  
  // 分割結果がない場合、行ごとに分割を試みる
  if (parsedAnswers.length === 0 && answerLines.length > 0) {
    // 改行やカンマで区切られた回答
    const splitAns = answerText.split(/[,、\n]/).map(s => s.trim()).filter(Boolean)
    splitAns.forEach(a => parsedAnswers.push(a))
  }
  
  const context = contextLines.join('\n')
  
  return questions.map((q, i) => ({
    question: (context ? context + '\n\n' : '') + q.text,
    answer: parsedAnswers[i] || answerText, // フォールバック：全体の正解
    context: context,
    subQuestion: q.text,
    index: i
  }))
}

// 正解テキストを小問数に合わせて分割する
function splitAnswerText(answerText, numParts) {
  if (!answerText) return Array(numParts).fill('')
  
  // 「。」区切りで文を分割
  const sentences = answerText.split(/(?<=[。？?])\s*/).filter(Boolean)
  if (sentences.length >= numParts) {
    const result = []
    const perPart = Math.ceil(sentences.length / numParts)
    for (let i = 0; i < numParts; i++) {
      result.push(sentences.slice(i * perPart, (i + 1) * perPart).join(''))
    }
    return result
  }
  
  // 「、」区切り
  const parts = answerText.split(/[、,\n]/).map(s => s.trim()).filter(Boolean)
  if (parts.length >= numParts) {
    const result = []
    const perPart = Math.ceil(parts.length / numParts)
    for (let i = 0; i < numParts; i++) {
      result.push(parts.slice(i * perPart, (i + 1) * perPart).join('、'))
    }
    return result
  }
  
  // 分割できない場合は全体を各問に割り当て
  return Array(numParts).fill(answerText)
}

// 一問一答モードを初期化
function initQAStepMode(problemText, answerText, cardId) {
  const qs = parseSubQuestions(problemText, answerText)
  
  window.qaStepState = {
    questions: qs,
    currentStep: 0,
    totalSteps: qs.length,
    results: [],
    originalProblem: problemText,
    originalAnswer: answerText,
    active: qs.length > 1,
    cardId: cardId
  }
  
  if (qs.length > 1) {
    renderQAStep()
  }
}

// 現在のステップを表示
function renderQAStep() {
  const st = window.qaStepState
  if (!st.active) return
  
  const step = st.currentStep
  const q = st.questions[step]
  if (!q) return
  
  // 問題文エリアを更新
  const problemDiv = document.querySelector('.bg-pink-50.border-l-4.border-pink-400')
  if (problemDiv) {
    // 進捗バー
    const progress = Math.round(((step) / st.totalSteps) * 100)
    const completedCount = st.results.length
    const correctCount = st.results.filter(r => r.correct).length
    
    problemDiv.innerHTML = `
      <div class="flex items-center justify-between mb-3">
        <p class="text-sm font-bold text-pink-600"><i class="fas fa-question-circle mr-1"></i>もんだい：</p>
        <div class="flex items-center gap-2">
          <span class="text-xs font-bold text-pink-500 bg-pink-100 px-2 py-0.5 rounded-full">${step + 1} / ${st.totalSteps}</span>
          ${correctCount > 0 ? `<span class="text-xs text-green-600">✓${correctCount}</span>` : ''}
        </div>
      </div>
      <!-- 進捗バー -->
      <div class="w-full bg-pink-200 rounded-full h-2 mb-3">
        <div class="bg-gradient-to-r from-pink-400 to-rose-500 h-2 rounded-full transition-all duration-500" style="width:${progress}%"></div>
      </div>
      ${q.context ? `<pre class="card-content text-gray-700 whitespace-pre-wrap font-sans leading-relaxed text-base mb-3">${formatText(q.context)}</pre>` : ''}
      <pre class="card-content text-gray-800 whitespace-pre-wrap font-sans leading-relaxed text-lg font-bold">${formatText(q.subQuestion || q.question)}</pre>
    `
  }
  
  // 採点ボタンを更新
  const gradeBtn = document.getElementById('gradeBtn')
  if (gradeBtn) {
    const escapedAnswer = (q.answer || '').replace(/'/g, "\\'").replace(/\n/g, '\\n')
    gradeBtn.className = 'w-full bg-gradient-to-r from-green-500 to-emerald-600 text-white py-4 px-6 rounded-xl font-bold text-lg hover:from-green-600 hover:to-emerald-700 transition shadow-lg'
    gradeBtn.innerHTML = '<i class="fas fa-check-double mr-2"></i>答え合わせをする'
    gradeBtn.onclick = () => gradeAnswer(q.answer)
  }
  
  // 回答欄をクリア＆フォーカス
  const answerInput = document.getElementById('answerInput')
  if (answerInput) {
    answerInput.value = ''
    answerInput.focus()
  }
  
  // 前の結果を非表示
  const resultDiv = document.getElementById('gradeResult')
  if (resultDiv) resultDiv.classList.add('hidden')
}

// 次の問題に進む
function goToNextQAStep() {
  const st = window.qaStepState
  if (!st.active) return
  
  st.currentStep++
  
  if (st.currentStep >= st.totalSteps) {
    // 全問完了 → 結果表示
    showQAResults()
  } else {
    renderQAStep()
  }
}

// 全問完了の結果表示
function showQAResults() {
  const st = window.qaStepState
  const correct = st.results.filter(r => r.correct).length
  const total = st.totalSteps
  const percent = Math.round((correct / total) * 100)
  
  const resultDiv = document.getElementById('gradeResult')
  if (!resultDiv) return
  
  const emoji = percent >= 80 ? '🎉' : percent >= 50 ? '👍' : '💪'
  const msg = percent >= 80 ? 'すばらしい！' : percent >= 50 ? 'よくがんばりました！' : 'もう少しがんばろう！'
  
  resultDiv.innerHTML = `
    <div class="bg-gradient-to-br from-indigo-50 to-purple-50 border-2 border-indigo-300 rounded-xl p-6 text-center">
      <div class="text-6xl mb-3">${emoji}</div>
      <p class="text-2xl font-bold text-indigo-700 mb-2">${msg}</p>
      <p class="text-lg text-gray-700 mb-4">${total}問中 <span class="text-green-600 font-bold text-2xl">${correct}</span> 問正解！</p>
      
      <!-- 各問の結果 -->
      <div class="text-left space-y-2 mb-4">
        ${st.results.map((r, i) => `
          <div class="flex items-center gap-2 p-2 rounded-lg ${r.correct ? 'bg-green-50' : 'bg-red-50'}">
            <span class="text-lg">${r.correct ? '✅' : '❌'}</span>
            <span class="text-sm text-gray-700 flex-1">(${i + 1}) ${r.correct ? '正解' : 'あなたの答え: ' + (r.studentAnswer || '').substring(0, 30)}</span>
          </div>
        `).join('')}
      </div>
      
      <div class="flex gap-2 justify-center">
        ${correct < total ? `
        <button onclick="retryWrongQASteps()" 
                class="bg-yellow-500 hover:bg-yellow-600 text-white px-5 py-2.5 rounded-lg font-bold transition shadow">
          <i class="fas fa-redo mr-2"></i>間違えた問題をやり直す
        </button>` : ''}
        <button onclick="saveProgress()" 
                class="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg font-bold transition shadow">
          <i class="fas fa-save mr-2"></i>保存して次へ
        </button>
      </div>
    </div>
  `
  resultDiv.classList.remove('hidden')
  
  // 理解度を自動設定
  window.currentUnderstandingLevel = percent
  setUnderstanding(percent >= 80 ? 5 : percent >= 60 ? 4 : percent >= 40 ? 3 : percent >= 20 ? 2 : 1)
}

// 間違えた問題だけやり直す
function retryWrongQASteps() {
  const st = window.qaStepState
  const wrongIndices = st.results.map((r, i) => r.correct ? -1 : i).filter(i => i >= 0)
  
  if (wrongIndices.length === 0) return
  
  // 間違えた問題だけの新しいステップリストを作成
  const retryQuestions = wrongIndices.map(i => st.questions[i])
  st.questions = retryQuestions
  st.totalSteps = retryQuestions.length
  st.currentStep = 0
  st.results = []
  st.active = true
  
  renderQAStep()
}

window.initQAStepMode = initQAStepMode
window.renderQAStep = renderQAStep
window.goToNextQAStep = goToNextQAStep
window.showQAResults = showQAResults
window.retryWrongQASteps = retryWrongQASteps

// 答え合わせ（採点）機能
async function gradeAnswer(correctAnswer) {
  const answerInput = document.getElementById('answerInput')
  const studentAnswer = answerInput ? answerInput.value.trim() : ''
  
  // ★ 作図Canvas実技モードの判定
  const constructionState = window._constructionStates && Object.values(window._constructionStates)[0]
  if (constructionState && studentAnswer.startsWith('{')) {
    try {
      const data = JSON.parse(studentAnswer)
      if (data.constructionType && data.shapes) {
        const uid = constructionState.uid
        const gradeResult = gradeConstructionDrawing(uid)
        const resultDiv = document.getElementById('gradeResult')
        if (!resultDiv) return
        
        // ★ 作図は全項目クリア（100点）のみ合格
        const isPerfect = gradeResult.results.every(r => r.ok)
        const failedItems = gradeResult.results.filter(r => !r.ok)
        
        if (isPerfect) {
          // 正解音
          try {
            const ac = new (window.AudioContext || window.webkitAudioContext)()
            ;[523, 659, 784, 1047].forEach((freq, i) => {
              const osc = ac.createOscillator(); const gain = ac.createGain()
              osc.type = 'triangle'; osc.frequency.value = freq
              gain.gain.setValueAtTime(0.2, ac.currentTime + i*0.15)
              gain.gain.exponentialRampToValueAtTime(0.01, ac.currentTime + i*0.15 + 0.3)
              osc.connect(gain); gain.connect(ac.destination)
              osc.start(ac.currentTime + i*0.15); osc.stop(ac.currentTime + i*0.15 + 0.35)
            })
          } catch(e) {}
        }
        
        resultDiv.innerHTML = isPerfect ? `
          <div class="bg-green-50 border-2 border-green-400 rounded-xl p-5" style="animation: correctPop 0.6s ease-out">
            <div class="text-center mb-3">
              <div class="text-5xl mb-2">🎉</div>
              <p class="text-2xl font-bold text-green-700">完璧な作図！</p>
              <p class="text-sm text-green-600 mt-1">すべての手順が正しくできています！</p>
            </div>
            <div class="space-y-2 mt-3">
              ${gradeResult.results.map(r => `
                <div class="flex items-center gap-2 p-2 rounded-lg bg-green-50">
                  <span class="text-base">${r.text}</span>
                </div>
              `).join('')}
            </div>
          </div>
          <style>@keyframes correctPop { 0% { transform: scale(0.5); opacity: 0; } 50% { transform: scale(1.08); } 100% { transform: scale(1); opacity: 1; } }</style>
        ` : `
          <div class="bg-amber-50 border-2 border-amber-400 rounded-xl p-5" style="animation: correctPop 0.6s ease-out">
            <div class="text-center mb-3">
              <div class="text-4xl mb-2">💪</div>
              <p class="text-xl font-bold text-amber-700">あと少し！</p>
              <p class="text-sm text-amber-600 mt-1">下のチェックリストを確認して、もう一度やってみよう</p>
            </div>
            <div class="space-y-2 mt-3">
              <p class="text-xs font-bold text-gray-700 mb-1">チェックリスト：</p>
              ${gradeResult.results.map(r => `
                <div class="flex items-center gap-2 p-2 rounded-lg ${r.ok ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'}">
                  <span class="text-base">${r.text}</span>
                </div>
              `).join('')}
            </div>
            <div class="mt-4 bg-blue-50 rounded-lg p-3">
              <p class="text-sm font-bold text-blue-800 mb-1"><i class="fas fa-lightbulb mr-1"></i>できていないところ</p>
              <ul class="text-xs text-blue-700 space-y-1">
                ${failedItems.map(r => `<li>・${r.text.replace(/^[❌⚠️]\s*/, '')}</li>`).join('')}
              </ul>
            </div>
            <button onclick="document.getElementById('gradeResult').classList.add('hidden')"
                    class="mt-3 w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-3 rounded-xl font-bold transition hover:from-blue-600 hover:to-indigo-700">
              <i class="fas fa-redo mr-2"></i>もう一度チャレンジ！
            </button>
          </div>
          <style>@keyframes correctPop { 0% { transform: scale(0.5); opacity: 0; } 50% { transform: scale(1.08); } 100% { transform: scale(1); opacity: 1; } }</style>
        `
        resultDiv.classList.remove('hidden')
        
        if (isPerfect) {
          const gradeBtn = document.getElementById('gradeBtn')
          if (gradeBtn) {
            gradeBtn.className = 'w-full bg-green-500 text-white py-4 px-6 rounded-xl font-bold text-lg cursor-default'
            gradeBtn.innerHTML = '<i class="fas fa-check-circle mr-2"></i>作図クリア！'
            gradeBtn.onclick = null
          }
        }
        return
      }
    } catch(e) { /* JSON解析失敗→通常の採点に進む */ }
  }
  
  if (!studentAnswer) {
    // 作図Canvasがある場合
    if (constructionState) {
      alert('コンパスや定規を使って作図してから「答え合わせ」を押してください。')
      return
    }
    alert('答えを入力してから「答え合わせ」を押してください。')
    if (answerInput) answerInput.focus()
    return
  }
  
  const resultDiv = document.getElementById('gradeResult')
  if (!resultDiv) return
  
  // 正解判定（柔軟な比較 - 数値・キーワードベース）
  const normalize = (s) => s.replace(/[\s　\n\r\t]/g, '').replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0)).replace(/[：:]/g, ':').replace(/[、，,]/g, ',').toLowerCase()
  const normalizedStudent = normalize(studentAnswer)
  const normalizedCorrect = normalize(correctAnswer)
  
  // 判定方法0: 自由記述・例示型回答の判定
  // 「例：〜」「〜など」「〜等」の場合、例示のいずれかに合致すれば正解
  const isOpenEndedAnswer = /例[：:]|など$|等$|〜$|いずれか|のような|が考えられ/.test(normalizedCorrect)
  let openEndedMatch = false
  if (isOpenEndedAnswer) {
    // 「例：A、B、C、など」からA,B,Cを抽出
    const cleanedCorrect = normalizedCorrect.replace(/^例[：:]\s*/, '').replace(/[、,]\s*など$/, '').replace(/など$/, '').replace(/等$/, '')
    const examples = cleanedCorrect.split(/[、,]/).map(s => s.trim()).filter(s => s.length >= 2)
    // 生徒の回答がいずれかの例示に含まれている or 例示が回答に含まれている
    openEndedMatch = examples.some(ex => {
      const normEx = normalize(ex)
      return normalizedStudent.includes(normEx) || normEx.includes(normalizedStudent)
    })
    console.log('📝 自由記述判定:', { examples, openEndedMatch, normalizedStudent })
  }
  
  // 判定方法0b: 性格・特徴・理由など複数回答可の問題
  // 正解が「A、B、C」のように読点区切りで複数の短い特徴を列挙している場合、
  // そのうち1つでも回答に含まれていれば正解とする
  let multiTraitMatch = false
  const correctTraits = normalizedCorrect.split(/[、,。・\/]/).map(s => s.trim()).filter(s => s.length >= 2 && s.length <= 20)
  if (correctTraits.length >= 2 && !normalizedCorrect.match(/\d{2,}/)) {
    // 数値が主体でない、かつ2つ以上の短い語句に分割できる場合
    multiTraitMatch = correctTraits.some(trait => {
      // 生徒の回答が特徴語句を含む or 特徴語句が生徒の回答を含む
      return normalizedStudent.includes(trait) || trait.includes(normalizedStudent)
    })
    // さらに: 生徒の回答を分割して各語句が正解の特徴と部分一致するかも判定
    if (!multiTraitMatch) {
      const studentParts = normalizedStudent.split(/[、,。・\/]/).map(s => s.trim()).filter(s => s.length >= 2)
      multiTraitMatch = studentParts.some(sp => 
        correctTraits.some(trait => sp.includes(trait) || trait.includes(sp))
      )
    }
    if (multiTraitMatch) {
      console.log('📝 性格・特徴判定:', { correctTraits, multiTraitMatch, normalizedStudent })
    }
  }
  
  // 判定方法1: 完全一致 or 包含関係
  const exactOrContains = normalizedStudent === normalizedCorrect || 
                    normalizedCorrect.includes(normalizedStudent) || 
                    normalizedStudent.includes(normalizedCorrect)
  
  // 判定方法2: 数値キーワードベース判定
  // 正解から「値」の部分（コロン後や句読点後の数値）を抽出
  const extractAnswerValues = (s) => {
    const values = []
    // 「：値」パターン（例: "気温：18度"→"18度"）
    const kvMatches = s.match(/[:：]\s*(\d+[\.\d]*\s*[度℃%％円個枚本匹人時分秒cmkgmLdlmlkm²³点番目倍割]*)/g) || []
    kvMatches.forEach(m => {
      const v = m.replace(/^[:：]\s*/, '')
      if (v) values.push(v)
    })
    // 抽出できなかった場合は全数値を取得
    if (values.length === 0) {
      const allNums = s.match(/\d+[\.\d]*\s*[度℃%％円個枚本匹人時分秒cmkgmLdlmlkm²³点番目倍割]*/g) || []
      allNums.forEach(m => values.push(m.replace(/\s/g, '')))
    }
    return [...new Set(values)]
  }
  const extractAllNumbers = (s) => {
    return (s.match(/\d+[\.\d]*\s*[度℃%％円個枚本匹人時分秒cmkgmLdlmlkm²³点番目倍割]*/g) || []).map(m => m.replace(/\s/g, ''))
  }
  const correctValues = extractAnswerValues(normalizedCorrect)
  const studentNumbers = extractAllNumbers(normalizedStudent)
  
  // 正解の値がすべて生徒の回答に含まれているか
  const allNumbersMatch = correctValues.length > 0 && correctValues.every(num => {
    return studentNumbers.some(sNum => sNum === num || sNum.includes(num) || num.includes(sNum))
  })
  
  // 判定方法3: 正解のキーポイントを抽出して部分一致
  // 「：」「:」で区切られた値の部分を抽出
  const extractKeyValues = (s) => {
    const parts = s.split(/[,:、。．\.\n]/).filter(p => p.length > 0)
    const values = []
    parts.forEach(p => {
      const kv = p.split(/[:：]/)
      if (kv.length >= 2) values.push(kv[kv.length - 1].trim())
      // 数値+単位のパターンも抽出
      const numMatch = p.match(/\d+[\.\d]*\s*[度℃%％円個枚本匹人時分秒cmkgmLdlmlkm²³点番目倍割]+/)
      if (numMatch) values.push(numMatch[0])
    })
    return [...new Set(values)]
  }
  const correctKeyValues = extractKeyValues(normalizedCorrect)
  const keyValuesMatch = correctKeyValues.length > 0 && correctKeyValues.every(v => normalizedStudent.includes(v))
  
  const isCorrect = openEndedMatch || multiTraitMatch || exactOrContains || allNumbersMatch || keyValuesMatch || (() => {
    // 追加判定: 人名・選択肢判定（「Aさん」「Bさん」など比較問題）
    const personMatch = normalizedCorrect.match(/([abcABC][さくんちゃん]*|[ア-ン]+さん)/) 
    if (personMatch && normalizedStudent.includes(personMatch[0])) return true
    // 分数判定（X分のY = Y/X）
    const fracs = normalizedCorrect.match(/\d+分の\d+|\d+\/\d+/g) || []
    if (fracs.length > 0 && fracs.every(f => {
      const normalized = f.replace(/(\d+)分の(\d+)/, '$2/$1')
      return normalizedStudent.includes(normalized) || normalizedStudent.includes(f)
    })) return true
    // 小数判定
    const decs = normalizedCorrect.match(/\d+\.\d+/g) || []
    if (decs.length > 0 && decs.every(d => normalizedStudent.includes(d))) return true
    // 主要キーワード一致（正解に含まれるキー名詞が半分以上回答に含まれる）
    const coreKeywords = normalizedCorrect.replace(/[0-9.,:、。]/g, '').split(/\s+/).filter(w => w.length >= 2)
    if (coreKeywords.length > 0) {
      const matchCount = coreKeywords.filter(kw => normalizedStudent.includes(kw)).length
      if (matchCount >= Math.ceil(coreKeywords.length * 0.4)) return true
    }
    // 日本語意味キーワード判定（助詞・接続詞で分割して核となる語句を抽出）
    const jaKeywords = normalizedCorrect
      .replace(/[。、,.\s]/g, '')
      .split(/[がのをにへとでやかもはばれるたいなくてしまうする]/)
      .filter(w => w.length >= 2)
    // 正解と生徒の回答から共通する核となる語句を探す
    const studentJaKeywords = normalizedStudent
      .replace(/[。、,.\s]/g, '')
      .split(/[がのをにへとでやかもはばれるたいなくてしまうする]/)
      .filter(w => w.length >= 2)
    if (jaKeywords.length > 0 && studentJaKeywords.length > 0) {
      const jaMatchCount = jaKeywords.filter(kw => normalizedStudent.includes(kw)).length
      if (jaMatchCount >= Math.ceil(jaKeywords.length * 0.5)) return true
    }
    // 短い部分文字列マッチ（正解から2-6文字の重要語を抽出して比較）
    const substrKeywords = []
    const cleanCorrect = normalizedCorrect.replace(/[。、,.]/g, '')
    for (let len = 3; len <= Math.min(6, cleanCorrect.length); len++) {
      for (let i = 0; i <= cleanCorrect.length - len; i++) {
        const sub = cleanCorrect.substring(i, i + len)
        if (!/^[はがのをにへとでもや]+$/.test(sub)) substrKeywords.push(sub)
      }
    }
    // 重要な部分文字列が生徒の回答に多く含まれていれば正解
    if (substrKeywords.length > 0) {
      const uniqueSubs = [...new Set(substrKeywords)]
      const subMatchCount = uniqueSubs.filter(s => normalizedStudent.includes(s)).length
      if (subMatchCount >= Math.ceil(uniqueSubs.length * 0.3)) return true
    }
    return false
  })()
  
  console.log('📝 採点:', { studentAnswer: normalizedStudent, correctAnswer: normalizedCorrect, exactOrContains, allNumbersMatch, keyValuesMatch, correctValues, studentNumbers, correctKeyValues, isCorrect })
  
  if (isCorrect) {
    // 正解音を再生
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)()
      // 正解の明るい音（ド→ミ→ソ → 高いド）
      const notes = [523.25, 659.25, 783.99, 1046.50]
      notes.forEach((freq, i) => {
        const osc = audioCtx.createOscillator()
        const gain = audioCtx.createGain()
        osc.type = 'sine'
        osc.frequency.value = freq
        gain.gain.setValueAtTime(0.3, audioCtx.currentTime + i * 0.15)
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + i * 0.15 + 0.3)
        osc.connect(gain)
        gain.connect(audioCtx.destination)
        osc.start(audioCtx.currentTime + i * 0.15)
        osc.stop(audioCtx.currentTime + i * 0.15 + 0.35)
      })
    } catch (e) { /* 音声再生失敗時は無視 */ }
    
    // ★★★ 入力欄に直接、大きく太い赤丸○を描画する ★★★
    const answerArea = document.getElementById('answerInput') || document.querySelector('[id^="handwriting-"]')
    if (answerArea) {
      // 入力欄の親要素をposition:relativeにしてSVGオーバーレイを配置
      const answerParent = answerArea.parentElement
      if (answerParent) answerParent.style.position = 'relative'
      
      // 入力欄のサイズを取得
      const rect = answerArea.getBoundingClientRect()
      const parentRect = (answerParent || answerArea).getBoundingClientRect()
      const offsetTop = rect.top - parentRect.top
      const offsetLeft = rect.left - parentRect.left
      const w = rect.width
      const h = rect.height
      
      // 既存の赤丸オーバーレイがあれば削除
      const existingMaru = document.getElementById('correct-maru-svg-overlay')
      if (existingMaru) existingMaru.remove()
      
      // SVGオーバーレイを入力欄に重ねて表示
      const svgSize = Math.max(w, h) * 0.9 // 入力欄より少し小さく
      const svgOverlay = document.createElement('div')
      svgOverlay.id = 'correct-maru-svg-overlay'
      svgOverlay.style.cssText = `
        position: absolute;
        top: ${offsetTop + h/2 - svgSize/2}px;
        left: ${offsetLeft + w/2 - svgSize/2}px;
        width: ${svgSize}px;
        height: ${svgSize}px;
        pointer-events: none;
        z-index: 9999;
      `
      // 円周 = 2πr。r = 45% of viewBox (90)。C = 2*π*90 ≈ 565
      svgOverlay.innerHTML = `
        <svg viewBox="0 0 200 200" width="${svgSize}" height="${svgSize}" 
             style="filter: drop-shadow(0 2px 10px rgba(220,38,38,0.4)) drop-shadow(0 0 20px rgba(220,38,38,0.2));">
          <circle cx="100" cy="100" r="88" fill="none" stroke="#DC2626" stroke-width="12" stroke-linecap="round"
            stroke-dasharray="553" stroke-dashoffset="553"
            style="animation: maruDrawStroke 0.6s cubic-bezier(0.4,0,0.2,1) 0.15s forwards;" />
          <circle cx="100" cy="100" r="88" fill="none" stroke="rgba(255,100,100,0.2)" stroke-width="22" stroke-linecap="round"
            opacity="0" style="animation: maruGlowPulse 1.5s ease-in-out 0.6s forwards;" />
        </svg>
      `
      ;(answerParent || answerArea.parentElement || document.body).appendChild(svgOverlay)
      
      // オーバーレイ全体のポップアニメーション
      svgOverlay.style.animation = 'maruPopIn 0.7s cubic-bezier(0.34,1.56,0.64,1) 0.1s both'
      
      // 入力欄自体にもゴールドの輝きボーダー
      answerArea.style.border = '3px solid #DC2626'
      answerArea.style.borderRadius = '16px'
      answerArea.style.boxShadow = '0 0 12px 4px rgba(220,38,38,0.2), 0 0 30px 8px rgba(220,38,38,0.08)'
      answerArea.style.transition = 'box-shadow 0.5s ease-out, border-color 0.5s ease-out'
      
      // 5秒後にゆっくりフェードアウト
      setTimeout(() => {
        if (svgOverlay) {
          svgOverlay.style.transition = 'opacity 1.5s ease-out'
          svgOverlay.style.opacity = '0'
          setTimeout(() => svgOverlay.remove(), 1600)
        }
        answerArea.style.boxShadow = '0 0 8px 2px rgba(220,38,38,0.1)'
      }, 5000)
    }
    
    // グローバルスタイル注入（1回のみ）
    if (!document.getElementById('maru-animation-styles')) {
      const styleEl = document.createElement('style')
      styleEl.id = 'maru-animation-styles'
      styleEl.textContent = `
        @keyframes maruDrawStroke { 0% { stroke-dashoffset: 553; } 100% { stroke-dashoffset: 0; } }
        @keyframes maruPopIn { 0% { transform: scale(0.2); opacity: 0; } 60% { transform: scale(1.18); opacity: 1; } 80% { transform: scale(0.95); } 100% { transform: scale(1); opacity: 1; } }
        @keyframes maruGlowPulse { 0% { opacity: 0; } 30% { opacity: 0.6; } 60% { opacity: 0.2; } 100% { opacity: 0; } }
        @keyframes correctPopResult { 0% { transform: scale(0.5); opacity: 0; } 50% { transform: scale(1.08); } 100% { transform: scale(1); opacity: 1; } }
        @keyframes starBurstResult { 0% { transform: scale(0) rotate(-30deg); } 50% { transform: scale(1.4) rotate(10deg); } 100% { transform: scale(1) rotate(0deg); } }
        @keyframes fadeInUpResult { 0% { transform: translateY(15px); opacity: 0; } 100% { transform: translateY(0); opacity: 1; } }
      `
      document.head.appendChild(styleEl)
    }
    
    resultDiv.innerHTML = `
      <div class="bg-green-50 border-2 border-green-400 rounded-xl p-5 text-center relative overflow-visible" style="animation: correctPopResult 0.6s ease-out">
        <div class="text-5xl mb-3" style="animation: starBurstResult 0.8s ease-out">🎉</div>
        <p class="text-2xl font-bold text-green-700 mb-2" style="animation: fadeInUpResult 0.5s ease-out 0.2s both">正解！すごい！</p>
        <p class="text-sm text-green-600" style="animation: fadeInUpResult 0.5s ease-out 0.4s both">よくできました。${window.qaStepState?.active && window.qaStepState.currentStep < window.qaStepState.totalSteps - 1 ? '次の問題に進みましょう！' : '次のカードに進みましょう！'}</p>
        ${window.qaStepState?.active && window.qaStepState.currentStep < window.qaStepState.totalSteps - 1 ? `
        <button onclick="window.qaStepState.results.push({correct:true, studentAnswer:'', correctAnswer:''}); goToNextQAStep()" 
                class="mt-3 bg-gradient-to-r from-blue-500 to-indigo-600 hover:from-blue-600 hover:to-indigo-700 text-white px-6 py-3 rounded-xl font-bold text-lg transition shadow-lg" style="animation: fadeInUpResult 0.5s ease-out 0.6s both">
          <i class="fas fa-arrow-right mr-2"></i>次の問題へ（${window.qaStepState.currentStep + 2}/${window.qaStepState.totalSteps}）
        </button>` : ''}
      </div>
    `
    // 一問一答モードの結果を記録
    if (window.qaStepState?.active) {
      // 最後の問題の場合は結果を記録して全問結果を表示
      if (window.qaStepState.currentStep >= window.qaStepState.totalSteps - 1) {
        window.qaStepState.results.push({ correct: true, studentAnswer, correctAnswer })
        setTimeout(() => showQAResults(), 1500)
      }
    }
    // 採点ボタンを更新
    const gradeBtn = document.getElementById('gradeBtn')
    if (gradeBtn) {
      gradeBtn.className = 'w-full bg-green-500 text-white py-4 px-6 rounded-xl font-bold text-lg cursor-default'
      gradeBtn.innerHTML = '<i class="fas fa-check-circle mr-2"></i>正解！'
      gradeBtn.onclick = null
    }
  } else {
    // 不正解の音
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)()
      const osc = audioCtx.createOscillator()
      const gain = audioCtx.createGain()
      osc.type = 'sine'
      osc.frequency.value = 330
      gain.gain.setValueAtTime(0.2, audioCtx.currentTime)
      gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.4)
      osc.connect(gain); gain.connect(audioCtx.destination)
      osc.start(); osc.stop(audioCtx.currentTime + 0.4)
    } catch (e) {}
    
    // AI分析中のUI表示
    resultDiv.innerHTML = `
      <div class="bg-yellow-50 border-2 border-yellow-400 rounded-xl p-5 text-center">
        <div class="text-5xl mb-3">🤔</div>
        <p class="text-xl font-bold text-yellow-700 mb-2">もう少し！</p>
        <div class="flex items-center justify-center gap-2 text-sm text-gray-600 mb-3">
          <div class="animate-spin rounded-full h-4 w-4 border-2 border-purple-400 border-t-transparent"></div>
          <span>あなたの考えを読み取っています...</span>
        </div>
      </div>
    `
    resultDiv.classList.remove('hidden')
    
    // AIで回答を分析
    try {
      const cardData = typeof state.selectedCard === 'object' ? state.selectedCard : (window.currentCardData || {})
      const question = cardData?.problem_content || cardData?.problem_text || document.querySelector('.text-pink-700, .problem-text')?.textContent || ''
      const subject = cardData?.subject || state.selectedCurriculum?.subject || ''
      const grade = cardData?.grade || state.selectedCurriculum?.grade || ''
      const cardTitle = cardData?.card_title || ''
      
      const aiRes = await axios.post('/api/ai/analyze-answer', {
        question: question.substring(0, 500),
        correctAnswer: correctAnswer,
        studentAnswer: studentAnswer,
        subject: subject,
        grade: grade,
        cardTitle: cardTitle
      }, { timeout: 15000 })
      
      const analysis = aiRes.data
      
      resultDiv.innerHTML = `
        <div class="bg-yellow-50 border-2 border-yellow-400 rounded-xl p-5">
          <div class="text-center mb-4">
            <div class="text-5xl mb-2">🤔</div>
            <p class="text-xl font-bold text-yellow-700">もう少し！</p>
          </div>
          
          ${analysis.where_wrong ? `
          <div class="bg-white rounded-lg p-3 mb-3 border border-orange-200">
            <p class="text-sm font-bold text-orange-600 mb-1"><i class="fas fa-search mr-1"></i>ここが違うよ</p>
            <p class="text-sm text-gray-700">${analysis.where_wrong}</p>
          </div>` : ''}
          
          ${analysis.why_wrong ? `
          <div class="bg-white rounded-lg p-3 mb-3 border border-blue-200">
            <p class="text-sm font-bold text-blue-600 mb-1"><i class="fas fa-lightbulb mr-1"></i>こう考えたのかな？</p>
            <p class="text-sm text-gray-700">${analysis.why_wrong}</p>
          </div>` : ''}
          
          ${analysis.hint ? `
          <div class="bg-purple-50 rounded-lg p-3 mb-3 border border-purple-200">
            <p class="text-sm font-bold text-purple-600 mb-1"><i class="fas fa-magic mr-1"></i>ヒント</p>
            <p class="text-sm text-gray-700">${analysis.hint}</p>
          </div>` : ''}
          
          ${analysis.encouragement ? `
          <p class="text-center text-sm text-green-600 font-bold mb-3"><i class="fas fa-star mr-1"></i>${analysis.encouragement}</p>
          ` : ''}
          
          <div class="flex gap-2 justify-center flex-wrap">
            <button onclick="document.getElementById('gradeResult').classList.add('hidden'); document.getElementById('answerInput').value=''; document.getElementById('answerInput')?.focus()"
                    class="bg-yellow-500 hover:bg-yellow-600 text-white px-5 py-2.5 rounded-lg font-bold transition shadow">
              <i class="fas fa-redo mr-2"></i>もう一度やってみる
            </button>
            ${window.qaStepState?.active && window.qaStepState.currentStep < window.qaStepState.totalSteps - 1 ? `
            <button onclick="window.qaStepState.results.push({correct:false, studentAnswer:'${studentAnswer.replace(/'/g, "\\'")}', correctAnswer:''}); goToNextQAStep()"
                    class="bg-gray-400 hover:bg-gray-500 text-white px-5 py-2.5 rounded-lg font-bold transition shadow">
              <i class="fas fa-arrow-right mr-2"></i>次の問題へ
            </button>` : ''}
          </div>
        </div>
      `
    } catch (aiError) {
      console.error('AI分析エラー:', aiError)
      // AI分析失敗時のフォールバック
      resultDiv.innerHTML = `
        <div class="bg-yellow-50 border-2 border-yellow-400 rounded-xl p-5 text-center">
          <div class="text-5xl mb-3">🤔</div>
          <p class="text-xl font-bold text-yellow-700 mb-2">もう少し！</p>
          <p class="text-sm text-gray-600 mb-3">ヒントを見てもう一度考えてみよう。</p>
          <div class="flex gap-2 justify-center flex-wrap">
            <button onclick="document.getElementById('gradeResult').classList.add('hidden'); document.getElementById('answerInput').value=''; document.getElementById('answerInput')?.focus()"
                    class="bg-yellow-500 hover:bg-yellow-600 text-white px-6 py-2 rounded-lg font-bold transition">
              <i class="fas fa-redo mr-2"></i>もう一度やってみる
            </button>
            ${window.qaStepState?.active && window.qaStepState.currentStep < window.qaStepState.totalSteps - 1 ? `
            <button onclick="window.qaStepState.results.push({correct:false, studentAnswer:'', correctAnswer:''}); goToNextQAStep()"
                    class="bg-gray-400 hover:bg-gray-500 text-white px-5 py-2 rounded-lg font-bold transition">
              <i class="fas fa-arrow-right mr-2"></i>次の問題へ
            </button>` : ''}
          </div>
        </div>
      `
    }
  }
  
  resultDiv.classList.remove('hidden')
  resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  
  // 学習ログ記録
  logLearningActivity({
    action: 'grade_answer',
    cardId: state.selectedCard,
    isCorrect: isCorrect,
    studentAnswer: studentAnswer.substring(0, 200)
  }).catch(() => {})
}

