// 学習進捗保存
async function saveProgress(teacherCall = false) {
  const answerInputElement = document.getElementById('answerInput')
  const answerInput = answerInputElement ? answerInputElement.value : ''
  
  if (!answerInput && !teacherCall) {
    alert('答えを書いてから保存してください。')
    return
  }
  
  try {
    // カードIDを安全に取得（オブジェクトの場合はIDを抽出）
    const cardId = typeof state.selectedCard === 'object' 
      ? (state.selectedCard?.card_id || state.selectedCard?.id || 0)
      : (state.selectedCard || 0)
    const cardTitle = typeof state.selectedCard === 'object'
      ? (state.selectedCard?.card_title || '')
      : ''
    
    // 解答時間を計算（秒単位）
    let answerTime = 0
    if (learningSession.currentCardStartTime) {
      answerTime = Math.floor((Date.now() - learningSession.currentCardStartTime) / 1000)
    }
    
    // 正解かどうかを理解度から推測（暫定実装）
    const isCorrect = (window.currentUnderstandingLevel || 0) >= 60
    
    // 学習ログを記録
    await logLearningActivity({
      cardId: cardId,
      unitId: state.selectedCurriculum?.id,
      courseType: state.selectedCourse,
      isCorrect: isCorrect,
      answerTime: answerTime,
      hintCount: window.helpCount || 0,
      retryCount: 0,
      difficulty: getDifficultyLevel(state.selectedCourse),
      problemType: getProblemType(cardTitle)
    })
    
    // courseIdを安全に取得
    const courseId = typeof state.selectedCourse === 'object'
      ? (state.selectedCourse?.id || state.selectedCourse?.course_id || 0)
      : (state.selectedCourse || 0)
    
    // 進捗を保存
    await axios.post('/api/progress', {
      student_id: state.student?.id || 1,
      curriculum_id: state.selectedCurriculum?.id || 0,
      course_id: courseId,
      learning_card_id: cardId,
      status: 'completed',
      understanding_level: window.currentUnderstandingLevel || 0,
      help_requested_from: window.currentHelpType || null,
      help_count: window.helpCount || 0
    })
    
    // WebSocket通知を送信
    sendProgressUpdate(
      state.student?.id || 1,
      state.selectedCurriculum?.id || 0,
      courseId,
      cardId,
      'completed',
      window.currentUnderstandingLevel || 0
    )
    
    // バックグラウンドでプロファイルを更新（5問ごと）
    if (learningSession.stats.totalProblems % 5 === 0) {
      updateLearningProfile()
    }
    
    if (!teacherCall) {
      alert('保存しました！次のカードに進みましょう。')
      // 次のカードに進む
      const cardsList = window._courseCardsList || []
      const currentIdx = cardsList.indexOf(state.selectedCard)
      if (currentIdx >= 0 && currentIdx < cardsList.length - 1) {
        loadCardPage(cardsList[currentIdx + 1])
      } else {
        goBackToGuide()
      }
    }
  } catch (error) {
    console.error('進捗保存エラー:', error)
    console.error('Error details:', {
      message: error.message,
      response: error.response?.data,
      status: error.response?.status
    })
    // teacherCallの場合はアラートを表示しない（先生呼び出しは進捗保存不要）
    if (!teacherCall) {
      alert('保存に失敗しました: ' + (error.response?.data?.error || error.message))
    }
  }
}

// 保存して次のカードへ進む（ページネーション対応）
async function saveProgressAndNext(nextCardId) {
  try {
    await saveProgress(true)
  } catch (e) {
    console.warn('保存エラー（続行）:', e)
  }
  if (nextCardId && nextCardId > 0) {
    loadCardPage(nextCardId)
  } else {
    alert('全てのカードを完了しました！おつかれさまでした！')
    goBackToGuide()
  }
}
window.saveProgressAndNext = saveProgressAndNext

