// 候補から単元を選択
function selectSuggestedUnit(unitName, index) {
  document.getElementById('genUnitName').value = unitName
  
  // 選択した候補を強調表示
  const buttons = document.getElementById('unitSuggestionList').querySelectorAll('button')
  buttons.forEach((btn, i) => {
    if (i === index - 1) {
      btn.classList.add('bg-purple-200', 'border-purple-400')
      btn.classList.remove('bg-white', 'hover:bg-purple-100')
    } else {
      btn.classList.remove('bg-purple-200', 'border-purple-400')
      btn.classList.add('bg-white', 'hover:bg-purple-100')
    }
  })
}

async function startUnitGeneration() {
  try {
    console.log('🚀🚀🚀 startUnitGeneration が呼び出されました!!!')
    
    const grade = document.getElementById('genGrade')?.value
    const subject = document.getElementById('genSubject')?.value
    const textbook = document.getElementById('genTextbook')?.value
    const unitName = document.getElementById('genUnitName')?.value

    console.log('📝 入力値:', { grade, subject, textbook, unitName })

    // 必須項目チェック
    if (!grade || !subject || !textbook || !unitName) {
      console.error('❌ 必須項目が不足しています')
      alert('学年、教科、教科書会社、単元名は必須です')
      return
    }
    
    console.log('✅ 必須項目チェック完了')
  
    // AI品質モードを取得（ラジオボタンから）
    const selectedQualityMode = document.querySelector('input[name="qualityMode"]:checked')
    const qualityMode = selectedQualityMode ? selectedQualityMode.value : 'standard'
    
    console.log('🎨 品質モード:', qualityMode)
    
    // 生成パラメータを保存（再生成用）
    lastGenerationParams = {
      grade,
      subject,
      textbook,
      unitName,
      studentNeeds: document.getElementById('genStudentNeeds')?.value || '',
      teacherGoals: document.getElementById('genTeacherGoals')?.value || '',
      learningStyle: document.getElementById('genLearningStyle')?.value || '',
      specialSupport: document.getElementById('genSpecialSupport')?.value || '',
      qualityMode: qualityMode
    }
    
    console.log('💾 保存されたパラメータ:', lastGenerationParams)
    
    // 実際の生成処理を実行
    console.log('🎯 executeUnitGeneration を呼び出します')
    await executeUnitGeneration(lastGenerationParams)
    console.log('✅ executeUnitGeneration 完了')
  } catch (error) {
    console.error('💥💥💥 startUnitGeneration でエラーが発生:', error)
    console.error('エラーメッセージ:', error.message)
    console.error('エラースタック:', error.stack)
    loadingManager.hide()
    alert('エラーが発生しました: ' + error.message)
  }
}

// 単元生成の実際の処理（段階的生成）
async function executeUnitGeneration(params) {
  console.log('📦 executeUnitGeneration が開始されました')
  console.log('📋 パラメータ:', params)
  
  const { grade, subject, textbook, unitName, studentNeeds, teacherGoals, learningStyle, specialSupport, qualityMode } = params
  
  // カスタマイズ情報
  const customization = {
    studentNeeds: studentNeeds || '',
    teacherGoals: teacherGoals || '',
    learningStyle: learningStyle || '',
    specialSupport: specialSupport || ''
  }

  // モーダルを閉じる
  closeUnitGeneratorModal()

  // 生成プロセス画面を表示
  showGenerationProgress(grade, subject, unitName, qualityMode)

  try {
    // 【段階的生成】まず単元の基本情報を生成
    console.log('📝 ステップ1/4: 単元基本情報を生成中...')
    updateGenerationProgress('単元の基本情報を生成しています...', 10)
    
    const unitInfoResponse = await axios.post('/api/ai/generate-unit', {
      grade,
      subject,
      textbook,
      unitName,
      customization,
      qualityMode
    }, { timeout: 180000 })  // 180秒タイムアウト

    if (unitInfoResponse.data.error) {
      throw new Error(unitInfoResponse.data.error)
    }

    const unitData = unitInfoResponse.data.data
    const unitGoal = unitData.curriculum.unit_goal
    
    console.log('✅ 単元基本情報の生成完了')
    console.log('📚 単元目標:', unitGoal)
    
    // 【段階的生成】3つのコースを個別に生成
    const courseDefinitions = [
      {
        level: 'slow',
        info: {
          name: 'じっくりコース',
          label: 'じっくり考えながら進むコース',
          description: 'ひとつひとつていねいに学びたい人におすすめ',
          color_code: 'green'
        }
      },
      {
        level: 'steady',
        info: {
          name: 'しっかりコース',
          label: 'バランスよく学ぶコース',
          description: '着実に力をつけたい人におすすめ',
          color_code: 'blue'
        }
      },
      {
        level: 'fast',
        info: {
          name: 'ぐんぐんコース',
          label: '発展的な内容にチャレンジするコース',
          description: 'より高い目標を目指したい人におすすめ',
          color_code: 'purple'
        }
      }
    ]
    
    const generatedCourses = []
    
    // 【高速化】3つのコースを並列生成（Promise.allSettled）
    console.log('🚀 3コースを並列生成開始...')
    // ★ 15%で中間表示（10→15のスムーズ遷移）、コース完了時に個別更新
    updateGenerationProgress('3つのコースを同時に生成しています...（約60〜90秒）', 15)
    
    const coursePromises = courseDefinitions.map((courseDef, i) => {
      // 少しずらして送信（レート制限対策: 0秒、1秒、2秒）
      return new Promise(async (resolve, reject) => {
        if (i > 0) await new Promise(r => setTimeout(r, i * 1500))
        
        let lastError = null
        for (let retry = 0; retry < 3; retry++) {
          try {
            if (retry > 0) {
              console.log(`🔄 ${courseDef.info.name} リトライ ${retry}...`)
              await new Promise(r => setTimeout(r, 5000))
            }
            
            const resp = await axios.post('/api/ai/generate-course', {
              grade,
              subject,
              textbook,
              unitName,
              unitGoal,
              courseLevel: courseDef.level,
              courseInfo: courseDef.info,
              customization
            }, { timeout: 180000 })
            
            if (resp.data.error) {
              lastError = new Error(resp.data.error)
              continue
            }
            resolve(resp.data.course)
            return
          } catch (e) {
            lastError = e
          }
        }
        reject(lastError)
      })
    })
    
    const results = await Promise.allSettled(coursePromises)
    
    for (let i = 0; i < results.length; i++) {
      const result = results[i]
      if (result.status === 'fulfilled') {
        generatedCourses.push(result.value)
        console.log(`✅ ${courseDefinitions[i].info.name}の生成完了（${result.value.cards.length}枚）`)
        // ★ 各コース完了ごとに均等に進行: 20→40→60
        updateGenerationProgress(`${courseDefinitions[i].info.name} 完了！`, 20 + ((i + 1) * 13))
      } else {
        console.error(`❌ ${courseDefinitions[i].info.name}の生成失敗:`, result.reason)
        throw new Error(`${courseDefinitions[i].info.name}の生成に失敗: ${result.reason?.message || 'Unknown'}`)
      }
    }
    
    // 生成されたコースをunitDataに統合（配列として直接設定）
    unitData.courses = generatedCourses
    
    console.log('✅ 全コースの生成完了:', {
      コース1: generatedCourses[0].name + ' ' + generatedCourses[0].cards.length + '枚',
      コース2: generatedCourses[1].name + ' ' + generatedCourses[1].cards.length + '枚',
      コース3: generatedCourses[2].name + ' ' + generatedCourses[2].cards.length + '枚'
    })
    
    // ★ 保存中は70%→90%へスムーズに
    updateGenerationProgress('生成完了！保存しています...', 70)

    // 保存処理完了後に90%→100%へスムーズに
    setTimeout(() => {
      updateGenerationProgress('保存中...', 90)
    }, 500)
    
    // 100%にして完了アニメーション（保存が完了してから）
    setTimeout(() => {
      updateGenerationProgress('✨ 生成完了！プレビューを表示します...', 100)
      const progressBar = document.getElementById('progressBar')
      if (progressBar) {
        progressBar.style.background = 'linear-gradient(90deg, #10b981, #34d399)'
      }
    }, 1200)

    // プレビュー画面を表示（スムーズなアニメーション完了後に表示）
    const modelUsed = unitInfoResponse.data.model_used
    setTimeout(() => showUnitPreview(unitData, modelUsed), 2500)

  } catch (error) {
    console.error('❌❌❌ 単元生成エラー:', error)
    console.error('エラータイプ:', typeof error)
    console.error('エラー詳細:', error.response?.data)
    console.error('エラースタック:', error.stack)
    
    // ローディングオーバーレイを確実に解除
    loadingManager.hide()
    
    // エラー詳細を取得
    const errorDetails = error.response?.data?.details || error.message || '不明なエラー'
    const errorMessage = error.response?.data?.error || '単元の生成に失敗しました'
    const validationErrors = error.response?.data?.validation_errors || []
    
    // エラー表示
    const app = document.getElementById('app')
    app.innerHTML = `
      <div class="container mx-auto px-4 py-8">
        <div class="bg-white rounded-lg shadow-lg p-8">
          <div class="text-center mb-6">
            <i class="fas fa-exclamation-triangle text-6xl text-red-500 mb-4"></i>
            <h2 class="text-2xl font-bold text-gray-800 mb-4">単元生成エラー</h2>
            <p class="text-gray-600 mb-4">
              ${errorMessage}
            </p>
          </div>
          
          <div class="bg-red-50 border-2 border-red-200 rounded-lg p-4 mb-6">
            <h3 class="font-bold text-red-800 mb-2">
              <i class="fas fa-info-circle mr-2"></i>エラー詳細
            </h3>
            <p class="text-sm text-red-700 whitespace-pre-wrap">${errorDetails}</p>
            ${validationErrors.length > 0 ? `
              <div class="mt-4">
                <h4 class="font-bold text-red-800 mb-2">データ検証エラー:</h4>
                <ul class="list-disc list-inside text-sm text-red-700">
                  ${validationErrors.map(err => `<li>${err}</li>`).join('')}
                </ul>
              </div>
            ` : ''}
          </div>
          
          <div class="bg-blue-50 border-2 border-blue-200 rounded-lg p-4 mb-6">
            <h3 class="font-bold text-blue-800 mb-2">
              <i class="fas fa-lightbulb mr-2"></i>対処方法
            </h3>
            <ul class="text-sm text-blue-700 list-disc list-inside space-y-1">
              <li>もう一度お試しください（一時的なエラーの可能性があります）</li>
              <li>単元名を変えてみてください</li>
              <li>カスタマイズ内容を簡潔にしてください</li>
              <li>標準モードで試してみてください</li>
            </ul>
          </div>
          
          <div class="flex gap-4">
            <button onclick="renderTopPage()" 
                    class="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-6 rounded-lg">
              <i class="fas fa-home mr-2"></i>
              トップページに戻る
            </button>
            <button onclick="retryUnitGeneration()" 
                    class="flex-1 bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-6 rounded-lg">
              <i class="fas fa-redo mr-2"></i>
              もう一度生成する
            </button>
          </div>
        </div>
      </div>
    `
  }
}

// 同じパラメータで単元を再生成
async function retryUnitGeneration() {
  if (!lastGenerationParams) {
    alert('前回の生成パラメータが見つかりません。最初から生成してください。')
    renderTopPage()
    return
  }
  
  console.log('🔄 再生成を開始...', lastGenerationParams)
  await executeUnitGeneration(lastGenerationParams)
}

// モーダルのドラッグ機能を初期化
function initModalDrag(headerId, contentId) {
  const header = document.getElementById(headerId)
  const content = document.getElementById(contentId)
  
  if (!header || !content) {
    console.warn('ドラッグ要素が見つかりません:', headerId, contentId)
    return
  }
  
  let isDragging = false
  let currentX = 0
  let currentY = 0
  let initialX = 0
  let initialY = 0
  let xOffset = 0
  let yOffset = 0
  let animationFrameId = null
  
  // GPU加速を有効化
  content.style.willChange = 'transform'
  
  header.addEventListener('mousedown', dragStart, { passive: false })
  document.addEventListener('mousemove', drag, { passive: false })
  document.addEventListener('mouseup', dragEnd, { passive: true })
  
  // タッチイベント対応
  header.addEventListener('touchstart', dragStart, { passive: false })
  document.addEventListener('touchmove', drag, { passive: false })
  document.addEventListener('touchend', dragEnd, { passive: true })
  
  function dragStart(e) {
    // ボタンクリックの場合はドラッグしない
    if (e.target.tagName === 'BUTTON' || e.target.closest('button')) {
      return
    }
    
    if (e.type === 'touchstart') {
      initialX = e.touches[0].clientX - xOffset
      initialY = e.touches[0].clientY - yOffset
    } else {
      initialX = e.clientX - xOffset
      initialY = e.clientY - yOffset
    }
    
    isDragging = true
    header.style.cursor = 'grabbing'
    content.style.transition = 'none' // ドラッグ中はtransitionを無効化
    document.body.style.userSelect = 'none' // テキスト選択を無効化
  }
  
  function drag(e) {
    if (!isDragging) return
    
    e.preventDefault()
    
    if (e.type === 'touchmove') {
      currentX = e.touches[0].clientX - initialX
      currentY = e.touches[0].clientY - initialY
    } else {
      currentX = e.clientX - initialX
      currentY = e.clientY - initialY
    }
    
    xOffset = currentX
    yOffset = currentY
    
    // requestAnimationFrameで滑らかに更新（デバウンス不要）
    if (!animationFrameId) {
      animationFrameId = requestAnimationFrame(() => {
        setTranslate(currentX, currentY, content)
        animationFrameId = null
      })
    }
  }
  
  function dragEnd(e) {
    if (animationFrameId) {
      cancelAnimationFrame(animationFrameId)
      animationFrameId = null
    }
    isDragging = false
    header.style.cursor = 'move'
    content.style.transition = '' // transitionを復元
    document.body.style.userSelect = '' // テキスト選択を復元
  }
  
  function setTranslate(xPos, yPos, el) {
    // translate3dを使用してGPU加速を有効化
    el.style.transform = `translate3d(${xPos}px, ${yPos}px, 0)`
  }
}

// フルスクリーンローディングオーバーレイを表示
function showLoadingOverlay(message = '処理中...') {
  const overlay = document.createElement('div')
  overlay.id = 'loadingOverlay'
  overlay.className = 'fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[9999]'
  overlay.innerHTML = `
    <div class="bg-white rounded-2xl p-8 shadow-2xl text-center max-w-md">
      <div class="mb-4">
        <i class="fas fa-spinner fa-spin text-6xl text-purple-600"></i>
      </div>
      <p class="text-xl font-bold text-gray-800 mb-2">${message}</p>
      <p class="text-sm text-gray-600">しばらくお待ちください...</p>
      <div class="mt-4 flex justify-center">
        <div class="animate-bounce mx-1 h-3 w-3 bg-purple-600 rounded-full"></div>
        <div class="animate-bounce mx-1 h-3 w-3 bg-pink-600 rounded-full" style="animation-delay: 0.1s"></div>
        <div class="animate-bounce mx-1 h-3 w-3 bg-blue-600 rounded-full" style="animation-delay: 0.2s"></div>
      </div>
    </div>
  `
  document.body.appendChild(overlay)
  document.body.style.overflow = 'hidden'
}

// フルスクリーンローディングオーバーレイを非表示
function hideLoadingOverlay() {
  const overlay = document.getElementById('loadingOverlay')
  if (overlay) {
    overlay.remove()
    document.body.style.overflow = ''
  }
}

// フィードバックを送信
async function submitFeedback() {
  const type = document.getElementById('feedbackType')?.value
  const email = document.getElementById('feedbackEmail')?.value || ''
  const message = document.getElementById('feedbackMessage')?.value
  
  if (!message || message.trim() === '') {
    alert('内容を入力してください')
    return
  }
  
  try {
    showLoadingOverlay('フィードバックを送信中...')
    
    // フィードバックデータを作成
    const feedbackData = {
      type,
      email,
      message: message.trim(),
      user_id: state.auth.user?.id || state.student.id,
      user_name: state.student.name,
      user_role: state.auth.user?.role || 'student',
      timestamp: new Date().toISOString()
    }
    
    // APIに送信（後でバックエンドに追加）
    const response = await axios.post('/api/feedback', feedbackData)
    
    hideLoadingOverlay()
    
    if (response.data.success) {
      alert('✅ フィードバックを送信しました！\n\nご意見ありがとうございます。システム改善の参考にさせていただきます。')
      
      // フォームをクリア
      document.getElementById('feedbackType').value = 'feedback'
      document.getElementById('feedbackEmail').value = ''
      document.getElementById('feedbackMessage').value = ''
    } else {
      throw new Error(response.data.error || '送信に失敗しました')
    }
  } catch (error) {
    console.error('フィードバック送信エラー:', error)
    hideLoadingOverlay()
    alert('❌ フィードバックの送信に失敗しました。\n\nもう一度お試しください。')
  }
}

// フォントサイズパネルの表示・非表示
function toggleFontSizePanel() {
  const panel = document.getElementById('fontSizePanel')
  if (panel) {
    panel.classList.toggle('hidden')
  } else {
    // パネルを新規作成
    const grade = state.selectedCurriculum?.grade || '小学3年'
    const defaultFontSize = getGradeFontSize(grade)
    const savedFontSize = localStorage.getItem('customFontSize')
    const currentFontSize = savedFontSize ? JSON.parse(savedFontSize) : defaultFontSize
    
    const panelHTML = `
      <div id="fontSizePanel" class="fixed right-4 top-20 bg-white rounded-lg shadow-2xl p-6 z-50 border-2 border-indigo-500" style="width: 320px;">
        <div class="flex items-center justify-between mb-4">
          <h3 class="font-bold text-lg text-gray-800">
            <i class="fas fa-text-height mr-2"></i>文字サイズ設定
          </h3>
          <button onclick="toggleFontSizePanel()" class="text-gray-500 hover:text-gray-700">
            <i class="fas fa-times text-xl"></i>
          </button>
        </div>
        
        <div class="space-y-4">
          <!-- 本文サイズ -->
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">
              本文: <span id="baseSizeLabel">${currentFontSize.base}px</span>
            </label>
            <input type="range" id="baseSizeSlider" min="12" max="28" value="${currentFontSize.base}" 
                   class="w-full" oninput="updateFontSize('base', this.value)">
          </div>
          
          <!-- タイトルサイズ -->
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">
              タイトル: <span id="titleSizeLabel">${currentFontSize.title}px</span>
            </label>
            <input type="range" id="titleSizeSlider" min="16" max="32" value="${currentFontSize.title}" 
                   class="w-full" oninput="updateFontSize('title', this.value)">
          </div>
          
          <!-- 見出しサイズ -->
          <div>
            <label class="block text-sm font-bold text-gray-700 mb-2">
              見出し: <span id="headingSizeLabel">${currentFontSize.heading}px</span>
            </label>
            <input type="range" id="headingSizeSlider" min="14" max="30" value="${currentFontSize.heading}" 
                   class="w-full" oninput="updateFontSize('heading', this.value)">
          </div>
          
          <!-- ボタン -->
          <div class="flex gap-2 mt-6">
            <button onclick="resetFontSize()" 
                    class="flex-1 bg-gray-300 hover:bg-gray-400 text-gray-800 font-bold py-2 px-4 rounded">
              <i class="fas fa-undo mr-1"></i>リセット
            </button>
            <button onclick="saveFontSize()" 
                    class="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded">
              <i class="fas fa-save mr-1"></i>保存
            </button>
          </div>
        </div>
      </div>
    `
    document.body.insertAdjacentHTML('beforeend', panelHTML)
  }
}

// フォントサイズをリアルタイム更新
function updateFontSize(type, value) {
  const label = document.getElementById(`${type}SizeLabel`)
  if (label) {
    label.textContent = `${value}px`
  }
  
  // CSSを即座に更新
  const styles = document.head.querySelector('style[data-font-size]') || document.createElement('style')
  styles.setAttribute('data-font-size', 'true')
  
  const baseSize = document.getElementById('baseSizeSlider')?.value || 16
  const titleSize = document.getElementById('titleSizeSlider')?.value || 20
  const headingSize = document.getElementById('headingSizeSlider')?.value || 18
  
  styles.textContent = `
    .card-content { font-size: ${baseSize}px !important; }
    .card-title { font-size: ${titleSize}px !important; }
    .card-heading { font-size: ${headingSize}px !important; }
  `
  
  if (!styles.parentNode) {
    document.head.appendChild(styles)
  }
}

// フォントサイズをリセット
function resetFontSize() {
  const grade = state.selectedCurriculum?.grade || '小学3年'
  const defaultFontSize = getGradeFontSize(grade)
  
  document.getElementById('baseSizeSlider').value = defaultFontSize.base
  document.getElementById('titleSizeSlider').value = defaultFontSize.title
  document.getElementById('headingSizeSlider').value = defaultFontSize.heading
  
  updateFontSize('base', defaultFontSize.base)
  updateFontSize('title', defaultFontSize.title)
  updateFontSize('heading', defaultFontSize.heading)
  
  localStorage.removeItem('customFontSize')
  alert('✅ フォントサイズをリセットしました')
}

// フォントサイズを保存
function saveFontSize() {
  const fontSize = {
    base: parseInt(document.getElementById('baseSizeSlider').value),
    title: parseInt(document.getElementById('titleSizeSlider').value),
    heading: parseInt(document.getElementById('headingSizeSlider').value)
  }
  
  localStorage.setItem('customFontSize', JSON.stringify(fontSize))
  alert('✅ フォントサイズを保存しました！\n\n次回から this設定が適用されます。')
  toggleFontSizePanel()
}

