// changeDeliveryMode は削除 — 配信モードは単元作成時に決定、後から変更しない

// ===== 教師承認管理関数群 =====

// 個別コースを承認する
async function approveCourse(curriculumId, courseId) {
  try {
    // 現在の承認リストを取得
    const metaResponse = await axios.get(`/api/curriculum/${curriculumId}/metadata`)
    let approved = metaResponse.data.approved_courses || []
    if (!approved.includes(courseId)) {
      approved.push(courseId)
    }
    await axios.put(`/api/curriculum/${curriculumId}/metadata`, { approved_courses: approved })
    console.log('✅ コース承認:', courseId)
    loadGuidePage(curriculumId)
  } catch (error) {
    console.error('承認エラー:', error)
    alert('承認に失敗しました')
  }
}
window.approveCourse = approveCourse

// 個別コースの承認を取消する
async function unapproveCourse(curriculumId, courseId) {
  try {
    const metaResponse = await axios.get(`/api/curriculum/${curriculumId}/metadata`)
    let approved = (metaResponse.data.approved_courses || []).filter(id => id !== courseId)
    await axios.put(`/api/curriculum/${curriculumId}/metadata`, { approved_courses: approved })
    console.log('✅ 承認取消:', courseId)
    loadGuidePage(curriculumId)
  } catch (error) {
    console.error('承認取消エラー:', error)
    alert('承認取消に失敗しました')
  }
}
window.unapproveCourse = unapproveCourse

// 全コースを一括承認する
async function approveAllCourses(curriculumId) {
  try {
    // カリキュラムの全個別コースを取得
    const response = await axios.get(`/api/curriculum/${curriculumId}`)
    const allPersonalized = (response.data.courses || []).filter(c => c.course_level === 'personalized')
    const allIds = allPersonalized.map(c => c.id || c.course_id)
    
    await axios.put(`/api/curriculum/${curriculumId}/metadata`, { approved_courses: allIds })
    console.log('✅ 全コース一括承認:', allIds.length, '件')
    loadGuidePage(curriculumId)
  } catch (error) {
    console.error('一括承認エラー:', error)
    alert('一括承認に失敗しました')
  }
}
window.approveAllCourses = approveAllCourses

// 配信管理モーダル（全体配信用：児童ごとにON/OFF）
async function showDeliveryManager(curriculumId, mode) {
  try {
    // 児童リストを取得
    let students = []
    try {
      const res = await axios.get('/api/students/list')
      students = res.data.students || res.data || []
    } catch (e) {
      // フォールバック：デフォルトの児童リスト
      students = Array.from({length: 30}, (_, i) => ({ id: `student_${i+1}`, name: `児童${i+1}` }))
    }
    
    // 現在の除外リストを取得
    const metaResponse = await axios.get(`/api/curriculum/${curriculumId}/metadata`)
    const excludedStudents = metaResponse.data.excluded_students || []
    
    const modal = document.createElement('div')
    modal.id = 'delivery-manager-modal'
    modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50'
    modal.innerHTML = `
      <div class="bg-white rounded-2xl shadow-2xl max-w-2xl w-full mx-4 max-h-[80vh] overflow-hidden">
        <div class="p-6 border-b bg-gradient-to-r from-orange-500 to-amber-500 text-white rounded-t-2xl">
          <h2 class="text-xl font-bold"><i class="fas fa-user-check mr-2"></i>配信管理</h2>
          <p class="text-sm opacity-90 mt-1">配信する児童を選択してください。チェックを外すと配信しません。</p>
        </div>
        
        <div class="p-4 border-b bg-gray-50">
          <div class="flex gap-2 flex-wrap items-center">
            <button onclick="deliveryManagerSelectAll(true)" class="text-xs bg-green-500 hover:bg-green-600 text-white px-3 py-1.5 rounded-lg font-bold">
              <i class="fas fa-check-double mr-1"></i>全員配信
            </button>
            <button onclick="deliveryManagerSelectAll(false)" class="text-xs bg-red-500 hover:bg-red-600 text-white px-3 py-1.5 rounded-lg font-bold">
              <i class="fas fa-times mr-1"></i>全員除外
            </button>
            <span id="delivery-count" class="ml-auto text-sm font-bold text-gray-600">
              ${students.length - excludedStudents.length}名に配信 / ${excludedStudents.length}名を除外
            </span>
          </div>
        </div>
        
        <div class="p-4 overflow-y-auto" style="max-height:50vh;">
          <div class="grid grid-cols-3 gap-2">
            ${students.map(s => {
              const sid = s.id || s.student_id || s.name
              const isExcluded = excludedStudents.includes(sid)
              return `
              <label class="flex items-center gap-2 p-2 rounded-lg border cursor-pointer hover:bg-blue-50 transition ${isExcluded ? 'bg-gray-100 border-gray-300' : 'bg-white border-blue-200'}">
                <input type="checkbox" class="delivery-student-cb w-4 h-4" value="${sid}" ${!isExcluded ? 'checked' : ''} onchange="updateDeliveryCount()">
                <i class="fas fa-user-graduate text-gray-500"></i>
                <span class="text-sm font-bold ${isExcluded ? 'text-gray-400 line-through' : 'text-gray-700'}">${s.name || sid}</span>
              </label>`
            }).join('')}
          </div>
        </div>
        
        <div class="p-4 border-t flex gap-3">
          <button onclick="document.getElementById('delivery-manager-modal').remove()" class="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-700 py-3 rounded-lg font-bold">
            キャンセル
          </button>
          <button onclick="saveDeliverySettings(${curriculumId})" class="flex-1 bg-gradient-to-r from-orange-500 to-amber-500 hover:from-orange-600 hover:to-amber-600 text-white py-3 rounded-lg font-bold">
            <i class="fas fa-save mr-1"></i>配信設定を保存
          </button>
        </div>
      </div>
    `
    document.body.appendChild(modal)
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove() })
  } catch (error) {
    console.error('配信管理エラー:', error)
    alert('配信管理の表示に失敗しました')
  }
}
window.showDeliveryManager = showDeliveryManager

function deliveryManagerSelectAll(checked) {
  document.querySelectorAll('.delivery-student-cb').forEach(cb => {
    cb.checked = checked
    const label = cb.closest('label')
    const nameSpan = label.querySelector('span')
    if (checked) {
      label.className = label.className.replace('bg-gray-100 border-gray-300', 'bg-white border-blue-200')
      nameSpan.classList.remove('text-gray-400', 'line-through')
      nameSpan.classList.add('text-gray-700')
    } else {
      label.className = label.className.replace('bg-white border-blue-200', 'bg-gray-100 border-gray-300')
      nameSpan.classList.remove('text-gray-700')
      nameSpan.classList.add('text-gray-400', 'line-through')
    }
  })
  updateDeliveryCount()
}
window.deliveryManagerSelectAll = deliveryManagerSelectAll

function updateDeliveryCount() {
  const all = document.querySelectorAll('.delivery-student-cb')
  const checked = document.querySelectorAll('.delivery-student-cb:checked')
  const el = document.getElementById('delivery-count')
  if (el) {
    el.textContent = `${checked.length}名に配信 / ${all.length - checked.length}名を除外`
  }
  // ラベルのスタイルも更新
  all.forEach(cb => {
    const label = cb.closest('label')
    const nameSpan = label.querySelector('span')
    if (cb.checked) {
      label.className = label.className.replace('bg-gray-100 border-gray-300', 'bg-white border-blue-200')
      nameSpan.classList.remove('text-gray-400', 'line-through')
      nameSpan.classList.add('text-gray-700')
    } else {
      label.className = label.className.replace('bg-white border-blue-200', 'bg-gray-100 border-gray-300')
      nameSpan.classList.remove('text-gray-700')
      nameSpan.classList.add('text-gray-400', 'line-through')
    }
  })
}
window.updateDeliveryCount = updateDeliveryCount

async function saveDeliverySettings(curriculumId) {
  try {
    const all = document.querySelectorAll('.delivery-student-cb')
    const excluded = []
    all.forEach(cb => { if (!cb.checked) excluded.push(cb.value) })
    
    await axios.put(`/api/curriculum/${curriculumId}/metadata`, { excluded_students: excluded })
    console.log('✅ 配信設定保存:', excluded.length, '名を除外')
    document.getElementById('delivery-manager-modal').remove()
    loadGuidePage(curriculumId)
  } catch (error) {
    console.error('配信設定保存エラー:', error)
    alert('配信設定の保存に失敗しました')
  }
}
window.saveDeliverySettings = saveDeliverySettings

// ===== 個別最適化セクションへスクロール =====
function scrollToPersonalizedSection() {
  const section = document.getElementById('personalized-course-section')
  if (section) {
    section.scrollIntoView({ behavior: 'smooth', block: 'center' })
    // ハイライトアニメーション
    section.classList.add('ring-4', 'ring-pink-400', 'ring-offset-2')
    setTimeout(() => section.classList.remove('ring-4', 'ring-pink-400', 'ring-offset-2'), 2000)
  }
}
window.scrollToPersonalizedSection = scrollToPersonalizedSection

// ===== 個別最適化コース管理セクションを描画 =====
function renderPersonalizedSection(curriculumId, personalizedCourses, approvedCourseIds) {
  console.log('🎨 renderPersonalizedSection呼び出し:', { curriculumId, count: personalizedCourses?.length || 0, courses: personalizedCourses?.map(c => c.course_name), approvedCourseIds })
  const placeholder = document.getElementById('personalized-section-placeholder')
  if (!placeholder) { console.warn('⚠️ personalized-section-placeholder が見つかりません'); return }
  
  const pendingCourses = personalizedCourses.filter(pc => !approvedCourseIds.includes(pc.course_id))
  const approvedCourses = personalizedCourses.filter(pc => approvedCourseIds.includes(pc.course_id))
  
  let badges = ''
  if (personalizedCourses.length > 0) badges += '<span class="text-xs bg-pink-200 text-pink-800 px-2 py-0.5 rounded-full font-bold">' + personalizedCourses.length + '件 生成済み</span>'
  if (pendingCourses.length > 0) badges += '<span class="text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded-full font-bold animate-pulse">' + pendingCourses.length + '件 未確認</span>'
  if (approvedCourses.length > 0) badges += '<span class="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-bold">' + approvedCourses.length + '件 承認済</span>'
  
  // 進捗バー
  const step1Class = personalizedCourses.length > 0 ? 'bg-pink-500 text-white' : 'bg-gray-200 text-gray-500'
  const step2Class = pendingCourses.length > 0 ? 'bg-orange-500 text-white' : approvedCourses.length > 0 ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'
  const step2Label = pendingCourses.length > 0 ? pendingCourses.length + '件待ち' : approvedCourses.length > 0 ? '完了' : '—'
  const step3Class = approvedCourses.length > 0 ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'
  
  let courseListHtml = ''
  if (personalizedCourses.length > 0) {
    courseListHtml = personalizedCourses.map(function(pc) {
      const isApproved = approvedCourseIds.includes(pc.course_id)
      const cardCount = pc.cards ? pc.cards.length : 0
      const safeName = (pc.course_name || '').replace(/'/g, "\\'")
      
      let actionBtns = ''
      const guideUrl = window.location.origin + '/guide/' + curriculumId + '?course=' + pc.course_id
      if (!isApproved) {
        actionBtns = '<button onclick="approveCourse(' + curriculumId + ', ' + pc.course_id + ')" ' +
          'class="bg-green-500 hover:bg-green-600 text-white px-2.5 py-1.5 rounded-lg text-xs font-bold transition" title="承認して配信可能にする">' +
          '<i class="fas fa-check mr-1"></i>承認</button>'
      } else {
        actionBtns = '<a href="' + guideUrl + '" target="_blank" ' +
          'class="bg-green-500 hover:bg-green-600 text-white px-2.5 py-1.5 rounded-lg text-xs font-bold transition inline-flex items-center" title="配信ページを開く">' +
          '<i class="fas fa-external-link-alt mr-1"></i>配信</a>' +
          '<button onclick="copyPersonalizedGuideUrl(' + curriculumId + ', ' + pc.course_id + ', \'' + safeName + '\')" ' +
          'class="bg-blue-400 hover:bg-blue-500 text-white px-2 py-1.5 rounded-lg text-xs transition" title="URLをコピー">' +
          '<i class="fas fa-copy"></i></button>' +
          '<button onclick="unapproveCourse(' + curriculumId + ', ' + pc.course_id + ')" ' +
          'class="bg-gray-300 hover:bg-gray-400 text-gray-700 px-2 py-1.5 rounded-lg text-xs transition" title="承認取消">' +
          '<i class="fas fa-undo"></i></button>'
      }
      
      return '<div class="bg-white rounded-lg p-3 border ' + (isApproved ? 'border-green-300 shadow-sm' : 'border-orange-300') + ' flex items-center gap-2">' +
        '<i class="fas ' + (isApproved ? 'fa-check-circle text-green-500 text-lg' : 'fa-clock text-orange-500 text-lg') + '"></i>' +
        '<div class="flex-1 min-w-0">' +
          '<div class="font-bold text-gray-800 text-sm truncate">' + pc.course_name + '</div>' +
          '<div class="text-xs text-gray-500">学習カード ' + cardCount + '枚 ' + (isApproved ? '・<span class="text-green-600 font-bold">承認済み</span>' : '・<span class="text-orange-600 font-bold">未確認</span>') + '</div>' +
        '</div>' +
        '<div class="flex items-center gap-1.5 flex-shrink-0">' +
          '<button onclick="showPersonalizedCourseGuide(' + pc.course_id + ', \'' + safeName + '\', ' + curriculumId + ')" ' +
            'class="bg-blue-100 hover:bg-blue-200 text-blue-700 px-2.5 py-1.5 rounded-lg text-xs font-bold transition" title="内容を確認">' +
            '<i class="fas fa-eye mr-1"></i>確認</button>' +
          actionBtns +
        '</div></div>'
    }).join('')
  }
  
  let actionButtons = ''
  if (pendingCourses.length > 0) {
    actionButtons += '<button onclick="approveAllCourses(' + curriculumId + ')" ' +
      'class="flex-1 text-xs bg-green-500 hover:bg-green-600 text-white py-2 px-3 rounded-lg font-bold transition">' +
      '<i class="fas fa-check-double mr-1"></i>全て承認する (' + pendingCourses.length + '件)</button>'
  }
  if (approvedCourses.length > 0) {
    actionButtons += '<button onclick="showPersonalizedDeliveryPanel(' + curriculumId + ')" ' +
      'class="flex-1 text-xs bg-gradient-to-r from-green-500 to-teal-500 hover:from-green-600 hover:to-teal-600 text-white py-2 px-3 rounded-lg font-bold transition">' +
      '<i class="fas fa-paper-plane mr-1"></i>承認済みを一括配信 (' + approvedCourses.length + '件)</button>'
  }
  
  let contentHtml = ''
  if (personalizedCourses.length > 0) {
    contentHtml = '<p class="text-xs text-gray-600 mb-3">児童ごとにAIが生成した個別学習カードです。内容を確認し、承認してから配信してください。</p>' +
      '<div class="grid grid-cols-3 gap-1 mb-3">' +
        '<div class="text-center py-1.5 rounded-l-lg ' + step1Class + ' text-xs font-bold"><i class="fas fa-magic mr-1"></i>①生成 ' + personalizedCourses.length + '件</div>' +
        '<div class="text-center py-1.5 ' + step2Class + ' text-xs font-bold"><i class="fas fa-clipboard-check mr-1"></i>②確認 ' + step2Label + '</div>' +
        '<div class="text-center py-1.5 rounded-r-lg ' + step3Class + ' text-xs font-bold"><i class="fas fa-paper-plane mr-1"></i>③配信 ' + approvedCourses.length + '件</div>' +
      '</div>' +
      '<div class="space-y-2 max-h-48 overflow-y-auto mb-3">' + courseListHtml + '</div>' +
      '<div class="flex gap-2">' + actionButtons + '</div>'
  } else {
    contentHtml = '<p class="text-xs text-gray-600 mb-3">3コースの全体学習データを基に、児童一人ひとりに最適化された学習カードをAIが生成します。</p>' +
      '<div class="bg-white rounded-lg p-4 border border-dashed border-pink-300 text-center">' +
        '<i class="fas fa-magic text-pink-300 text-2xl mb-2"></i>' +
        '<p class="text-sm text-gray-500 mb-2">まだ個別最適化コースが作成されていません</p>' +
        '<p class="text-xs text-gray-400">「新規生成」ボタンから児童を選択して生成してください</p>' +
        '<p class="text-xs text-blue-400 mt-2 font-mono bg-blue-50 rounded px-2 py-1 inline-block">カリキュラムID: ' + curriculumId + '</p>' +
      '</div>'
  }
  
  placeholder.innerHTML = '<div id="personalized-course-section" class="mt-4 border-2 border-pink-300 bg-gradient-to-r from-pink-50 to-purple-50 rounded-xl p-5">' +
    '<div class="flex items-center justify-between mb-3">' +
      '<div class="flex items-center gap-2">' +
        '<div class="w-8 h-8 rounded-full bg-gradient-to-r from-pink-500 to-purple-600 text-white flex items-center justify-center font-bold text-sm"><i class="fas fa-magic"></i></div>' +
        '<h4 class="font-bold text-pink-800">個別最適化コース</h4>' +
        badges +
      '</div>' +
      '<button onclick="showPersonalizedCourseSelector(' + curriculumId + ')" class="text-xs bg-gradient-to-r from-pink-500 to-purple-600 hover:from-pink-600 hover:to-purple-700 text-white py-2 px-4 rounded-lg font-bold transition shadow">' +
        '<i class="fas fa-plus mr-1"></i>新規生成</button>' +
    '</div>' +
    contentHtml +
  '</div>'
}
window.renderPersonalizedSection = renderPersonalizedSection

// ===== 配信タブ関連関数群 =====

// タブ切替
function switchDeliveryTab(tab) {
  const printBtn = document.getElementById('tab-print-btn')
  const onlineBtn = document.getElementById('tab-online-btn')
  const printContent = document.getElementById('tab-print-content')
  const onlineContent = document.getElementById('tab-online-content')
  if (!printBtn || !onlineBtn || !printContent || !onlineContent) return
  
  if (tab === 'print') {
    printBtn.className = 'flex-1 py-3 px-4 text-sm font-bold text-center border-b-2 border-indigo-600 text-indigo-700 bg-indigo-50 transition'
    onlineBtn.className = 'flex-1 py-3 px-4 text-sm font-bold text-center border-b-2 border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50 transition'
    printContent.style.display = ''
    onlineContent.style.display = 'none'
  } else {
    onlineBtn.className = 'flex-1 py-3 px-4 text-sm font-bold text-center border-b-2 border-green-600 text-green-700 bg-green-50 transition'
    printBtn.className = 'flex-1 py-3 px-4 text-sm font-bold text-center border-b-2 border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50 transition'
    onlineContent.style.display = ''
    printContent.style.display = 'none'
    // URLを実際の値に更新
    const urlInput = document.getElementById('guide-url-input')
    if (urlInput) {
      const url = window.location.origin + '/guide/' + urlInput.value.split('/guide/')[1]
      urlInput.value = url
    }
  }
}
window.switchDeliveryTab = switchDeliveryTab

// URLコピー
function copyGuideUrl(curriculumId) {
  const url = window.location.origin + '/guide/' + curriculumId
  navigator.clipboard.writeText(url).then(() => {
    const btn = event.target.closest('button')
    const orig = btn.innerHTML
    btn.innerHTML = '<i class="fas fa-check mr-1"></i>コピー済み'
    btn.classList.replace('bg-blue-600', 'bg-green-600')
    setTimeout(() => { btn.innerHTML = orig; btn.classList.replace('bg-green-600', 'bg-blue-600') }, 2000)
  }).catch(() => {
    prompt('URLをコピーしてください:', url)
  })
}
window.copyGuideUrl = copyGuideUrl

// QRコード印刷
function printQRCode(curriculumId) {
  const url = window.location.origin + '/guide/' + curriculumId
  const qrUrl = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' + encodeURIComponent(url)
  const w = window.open('', '_blank')
  w.document.write(`
    <html><head><title>QRコード</title>
    <style>body{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100vh;font-family:sans-serif;}
    @media print{button{display:none;}}</style></head>
    <body>
      <h2 style="margin-bottom:8px;">📖 学習のてびき</h2>
      <img src="${qrUrl}" style="width:300px;height:300px;margin:16px;" />
      <p style="font-size:12px;color:#666;word-break:break-all;max-width:400px;text-align:center;">${url}</p>
      <button onclick="window.print()" style="margin-top:16px;padding:8px 24px;font-size:14px;cursor:pointer;">印刷する</button>
    </body></html>
  `)
  w.document.close()
}
window.printQRCode = printQRCode

// 児童名つきリンク生成モーダル
async function showStudentLinkGenerator(curriculumId) {
  let students = []
  try {
    const res = await axios.get('/api/students/list')
    students = res.data.students || res.data || []
  } catch (e) {
    students = Array.from({length: 30}, (_, i) => ({ id: `student_${i+1}`, name: `児童${i+1}` }))
  }
  
  const baseUrl = window.location.origin + '/guide/' + curriculumId
  
  const modal = document.createElement('div')
  modal.id = 'student-link-modal'
  modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50'
  modal.innerHTML = `
    <div class="bg-white rounded-2xl shadow-2xl max-w-2xl w-full mx-4 max-h-[85vh] overflow-hidden">
      <div class="p-5 border-b bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-t-2xl">
        <h2 class="text-lg font-bold"><i class="fas fa-link mr-2"></i>児童ごとのリンク一覧</h2>
        <p class="text-sm opacity-90 mt-1">各児童の名前入りURLです。コピーして保護者に送信してください。</p>
      </div>
      
      <div class="p-3 border-b bg-gray-50 flex gap-2">
        <button onclick="copyAllStudentLinks()" class="text-xs bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded-lg font-bold">
          <i class="fas fa-copy mr-1"></i>全員のリンクをコピー
        </button>
      </div>
      
      <div class="overflow-y-auto" style="max-height:55vh;">
        <table class="w-full text-sm">
          <thead class="bg-gray-100 sticky top-0">
            <tr>
              <th class="py-2 px-3 text-left text-xs font-bold text-gray-600">児童名</th>
              <th class="py-2 px-3 text-left text-xs font-bold text-gray-600">URL</th>
              <th class="py-2 px-3 text-center text-xs font-bold text-gray-600 w-20">操作</th>
            </tr>
          </thead>
          <tbody>
            ${students.map(s => {
              const name = s.name || s.student_name || s.id || ''
              const sid = s.student_id || s.id || ''
              const url = baseUrl + '?name=' + encodeURIComponent(name) + (sid ? '&student_id=' + encodeURIComponent(sid) : '')
              return `
              <tr class="border-b hover:bg-blue-50">
                <td class="py-2 px-3 font-bold text-gray-700"><i class="fas fa-user-graduate text-gray-400 mr-1"></i>${name}</td>
                <td class="py-2 px-3"><input type="text" readonly value="${url}" class="w-full text-xs font-mono text-gray-600 bg-transparent outline-none truncate student-link-url" /></td>
                <td class="py-2 px-3 text-center">
                  <button onclick="copySingleLink(this, '${url.replace(/'/g, "\\'")}')" class="text-xs bg-blue-500 hover:bg-blue-600 text-white px-2 py-1 rounded font-bold">
                    <i class="fas fa-copy"></i>
                  </button>
                </td>
              </tr>`
            }).join('')}
          </tbody>
        </table>
      </div>
      
      <div class="p-4 border-t">
        <button onclick="document.getElementById('student-link-modal').remove()" class="w-full bg-gray-200 hover:bg-gray-300 text-gray-700 py-2.5 rounded-lg font-bold">
          閉じる
        </button>
      </div>
    </div>
  `
  document.body.appendChild(modal)
  modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove() })
}
window.showStudentLinkGenerator = showStudentLinkGenerator

function copySingleLink(btn, url) {
  navigator.clipboard.writeText(url).then(() => {
    const orig = btn.innerHTML
    btn.innerHTML = '<i class="fas fa-check"></i>'
    btn.classList.replace('bg-blue-500', 'bg-green-500')
    setTimeout(() => { btn.innerHTML = orig; btn.classList.replace('bg-green-500', 'bg-blue-500') }, 1500)
  }).catch(() => { prompt('コピーしてください:', url) })
}
window.copySingleLink = copySingleLink

function copyAllStudentLinks() {
  const inputs = document.querySelectorAll('.student-link-url')
  const lines = []
  inputs.forEach(input => {
    const row = input.closest('tr')
    const name = row.querySelector('td').textContent.trim()
    lines.push(name + '\n' + input.value)
  })
  navigator.clipboard.writeText(lines.join('\n\n')).then(() => {
    alert('全員のリンクをクリップボードにコピーしました')
  }).catch(() => { alert('コピーに失敗しました') })
}
window.copyAllStudentLinks = copyAllStudentLinks

