// タブ切り替え関数
function switchCardTab(tabName) {
  // すべてのタブボタンを非アクティブに
  document.querySelectorAll('#cardDetailModal button[id^="tab-"]').forEach(btn => {
    btn.className = 'flex-1 px-6 py-4 font-bold text-center transition border-b-4 border-transparent hover:bg-gray-50 text-gray-600'
  })
  
  // アクティブタブのボタンをハイライト
  const activeTab = document.getElementById(`tab-${tabName}`)
  if (activeTab) {
    const colors = {
      problem: 'border-blue-600 bg-white text-blue-600',
      hints: 'border-yellow-600 bg-white text-yellow-600',
      answer: 'border-green-600 bg-white text-green-600',
      explanation: 'border-purple-600 bg-white text-purple-600',
      history: 'border-orange-600 bg-white text-orange-600'
    }
    activeTab.className = `flex-1 px-6 py-4 font-bold text-center transition border-b-4 ${colors[tabName]}`
  }
  
  // すべてのタブコンテンツを非表示
  document.querySelectorAll('#cardDetailModal .tab-content').forEach(content => {
    content.classList.add('hidden')
  })
  
  // 選択されたタブのコンテンツを表示
  const activeContent = document.getElementById(`content-${tabName}`)
  if (activeContent) {
    activeContent.classList.remove('hidden')
    
    // 編集履歴タブの場合は履歴を読み込む
    if (tabName === 'history') {
      loadCardEditHistory()
    }
  }
}

// 編集履歴を読み込む関数
async function loadCardEditHistory() {
  const historyContent = document.getElementById('history-content')
  const historyLoading = document.getElementById('history-loading')
  
  if (!state.selectedCard || !state.selectedCard.id) {
    historyContent.innerHTML = `
      <div class="text-center py-12 text-gray-500">
        <i class="fas fa-exclamation-circle text-6xl mb-4 text-gray-300"></i>
        <p class="text-lg">カード情報が見つかりません</p>
      </div>
    `
    historyLoading.classList.add('hidden')
    historyContent.classList.remove('hidden')
    return
  }
  
  const cardId = state.selectedCard.id
  
  try {
    const response = await axios.get(`/api/cards/${cardId}/edit-history`)
    
    if (!response.data.success) {
      throw new Error('履歴の取得に失敗しました')
    }
    
    const history = response.data.history || []
    
    historyLoading.classList.add('hidden')
    
    if (history.length === 0) {
      historyContent.innerHTML = `
        <div class="text-center py-12 text-gray-500">
          <i class="fas fa-history text-6xl mb-4 text-gray-300"></i>
          <p class="text-lg">編集履歴がありません</p>
          <p class="text-sm mt-2 text-gray-400">このカードはまだ編集されていません</p>
        </div>
      `
    } else {
      historyContent.innerHTML = `
        <div class="space-y-4">
          ${history.map((record, index) => {
            const beforeData = record.before_data ? JSON.parse(record.before_data) : null
            const afterData = record.after_data ? JSON.parse(record.after_data) : null
            
            return `
              <div class="border rounded-lg p-4 hover:bg-gray-50 transition border-gray-200 bg-white">
                <div class="flex items-start justify-between mb-3">
                  <div class="flex-1">
                    <div class="flex items-center gap-2 mb-2">
                      <span class="px-3 py-1 rounded-full text-xs font-bold ${
                        record.edit_type === 'create' ? 'bg-green-100 text-green-700' :
                        record.edit_type === 'update' ? 'bg-blue-100 text-blue-700' :
                        record.edit_type === 'delete' ? 'bg-red-100 text-red-700' :
                        'bg-gray-100 text-gray-700'
                      }">
                        ${record.edit_type === 'create' ? '新規作成' :
                          record.edit_type === 'update' ? '更新' :
                          record.edit_type === 'delete' ? '削除' :
                          record.edit_type || '変更'}
                      </span>
                      ${index === 0 ? '<span class="px-2 py-1 bg-orange-100 text-orange-700 rounded text-xs font-bold">最新</span>' : ''}
                    </div>
                    <div class="text-sm text-gray-600">
                      <i class="fas fa-clock mr-2"></i>
                      ${new Date(record.edited_at).toLocaleString('ja-JP')}
                    </div>
                    ${record.edited_by_name ? `
                      <div class="text-sm text-gray-600 mt-1">
                        <i class="fas fa-user mr-2"></i>
                        編集者: ${record.edited_by_name}
                      </div>
                    ` : ''}
                    ${record.change_summary ? `
                      <div class="text-sm text-gray-700 mt-2 font-medium">
                        <i class="fas fa-info-circle mr-2"></i>
                        ${record.change_summary}
                      </div>
                    ` : ''}
                  </div>
                </div>
                
                ${beforeData && afterData ? `
                  <div class="mt-3 p-3 bg-gray-50 rounded text-xs">
                    <div class="font-bold text-gray-700 mb-2">変更内容:</div>
                    <div class="grid grid-cols-2 gap-4">
                      <div>
                        <div class="text-gray-500 mb-1 font-bold">変更前:</div>
                        <div class="text-gray-800 bg-white p-2 rounded border border-red-200">
                          ${beforeData.card_title || beforeData.problem_description || '不明'}
                        </div>
                      </div>
                      <div>
                        <div class="text-gray-500 mb-1 font-bold">変更後:</div>
                        <div class="text-gray-800 bg-white p-2 rounded border border-green-200 font-bold">
                          ${afterData.card_title || afterData.problem_description || '不明'}
                        </div>
                      </div>
                    </div>
                  </div>
                ` : ''}
              </div>
            `
          }).join('')}
        </div>
      `
    }
    
    historyContent.classList.remove('hidden')
  } catch (error) {
    console.error('編集履歴読み込みエラー:', error)
    historyLoading.classList.add('hidden')
    historyContent.innerHTML = `
      <div class="text-center py-12 text-red-500">
        <i class="fas fa-exclamation-triangle text-6xl mb-4"></i>
        <p class="text-lg">編集履歴の読み込みに失敗しました</p>
        <p class="text-sm mt-2 text-gray-600">${error.message}</p>
      </div>
    `
    historyContent.classList.remove('hidden')
  }
}

// 類似問題生成関数（仮実装）
async function generateSimilarProblem(cardId) {
  const button = event.target
  const originalHTML = button.innerHTML
  button.disabled = true
  button.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>生成中...'
  
  try {
    const response = await axios.post(`/api/cards/${cardId}/generate-similar`, {}, { timeout: 90000 })
    if (response.data.success) {
      // 新しい問題を表示（タブを問題に切り替え）
      alert('✨ 新しい問題を生成しました！\n\n' + response.data.problem.problem_text)
      // TODO: モーダルを更新して新しい問題を表示
    } else {
      throw new Error(response.data.error || '生成に失敗しました')
    }
  } catch (error) {
    console.error('類似問題生成エラー:', error)
    alert('❌ 問題の生成に失敗しました。もう一度お試しください。')
  } finally {
    button.disabled = false
    button.innerHTML = originalHTML
  }
}

// 学習カード画面用の類似問題生成関数
async function generateAndShowSimilarProblem(cardId) {
  // cardIdが渡されていない場合はstate.selectedCardを使用
  if (!cardId) {
    cardId = state.selectedCard || window.currentCardData?.id
  }
  
  if (!cardId) {
    alert('❌ カードIDが見つかりません。ページを再読み込みしてください。')
    return
  }
  
  console.log('🔄 類似問題生成開始 - カードID:', cardId)
  
  // フルスクリーンローディング表示
  showLoadingOverlay('AIが新しい問題を生成中...')
  
  // 練習開始時刻を記録
  window.practiceStartTime = Date.now()
  window.practiceCardId = cardId
  window.practiceHintUsed = false
  
  try {
    const response = await axios.post(`/api/cards/${cardId}/generate-similar`, {}, { timeout: 90000 })
    console.log('類似問題生成レスポンス:', response.data)
    
    if (response.data.success && response.data.problem) {
      const problem = response.data.problem
      
      // ローディングを非表示
      hideLoadingOverlay()
      
      // モーダルで問題を表示
      const modalHTML = `
        <div id="similarProblemModal" 
             class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4"
             onclick="if(event.target.id === 'similarProblemModal') closeSimilarProblemModal()">
          <div id="similarProblemContent" class="bg-white rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto"
               style="position: relative;"
               onclick="event.stopPropagation()">
            <!-- ヘッダー（ドラッグハンドル） -->
            <div id="similarProblemHeader" class="bg-gradient-to-r from-purple-600 to-pink-600 text-white p-6 rounded-t-2xl cursor-move">
              <div class="flex items-center justify-between">
                <h2 class="text-2xl font-bold">
                  <i class="fas fa-magic mr-2"></i>もう1問練習
                  <span class="text-sm ml-2 opacity-75">（ドラッグで移動できます）</span>
                </h2>
                <button onclick="closeSimilarProblemModal()" 
                        class="text-white hover:bg-white hover:bg-opacity-20 rounded-full p-2 transition">
                  <i class="fas fa-times text-xl"></i>
                </button>
              </div>
            </div>

            <!-- コンテンツ -->
            <div class="p-6">
              <!-- 問題 -->
              <div class="bg-blue-50 rounded-lg p-6 mb-6">
                <h3 class="text-lg font-bold text-blue-800 mb-3">
                  <i class="fas fa-pencil-alt mr-2"></i>問題
                </h3>
                <pre class="text-gray-800 whitespace-pre-wrap font-sans text-lg">${problem.problem_text}</pre>
              </div>

              <!-- 答えを表示ボタン -->
              <div class="mb-4">
                <button onclick="toggleSimilarAnswer()" 
                        id="toggleSimilarAnswerBtn"
                        class="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-6 rounded-lg transition">
                  <i class="fas fa-eye mr-2"></i>答えを表示
                </button>
              </div>

              <!-- 答え（初期非表示） -->
              <div id="similarAnswer" class="hidden">
                <div class="bg-green-50 rounded-lg p-6 mb-4">
                  <h3 class="text-lg font-bold text-green-800 mb-3">
                    <i class="fas fa-check-circle mr-2"></i>答え
                  </h3>
                  <pre class="text-gray-800 whitespace-pre-wrap font-sans text-lg">${problem.answer}</pre>
                </div>

                ${problem.explanation ? `
                  <div class="bg-purple-50 rounded-lg p-6">
                    <h3 class="text-lg font-bold text-purple-800 mb-3">
                      <i class="fas fa-lightbulb mr-2"></i>解説
                    </h3>
                    <pre class="text-gray-800 whitespace-pre-wrap font-sans">${problem.explanation}</pre>
                  </div>
                ` : ''}
              </div>
            </div>

            <!-- フッター -->
            <div class="bg-gray-50 p-4 border-t flex gap-3">
              <button onclick="generateAndShowSimilarProblem(${cardId})" 
                      class="flex-1 bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-bold py-3 px-6 rounded-lg transition shadow-lg">
                <i class="fas fa-redo mr-2"></i>
                もう1問
              </button>
              <button onclick="closeSimilarProblemModal()" 
                      class="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg transition">
                <i class="fas fa-check mr-2"></i>
                閉じる
              </button>
            </div>
          </div>
        </div>
      `
      
      // 既存のモーダルがあれば削除
      const existingModal = document.getElementById('similarProblemModal')
      if (existingModal) {
        existingModal.remove()
      }
      
      // 新しいモーダルを表示
      document.body.insertAdjacentHTML('beforeend', modalHTML)
      document.body.style.overflow = 'hidden'
      
      // ドラッグ機能を初期化
      initModalDrag('similarProblemHeader', 'similarProblemContent')
      
      // 復習の開始時刻を記録
      window.reviewStartTime = Date.now()
      
      // 🌟 復習ログを記録（既にクリアしたカードの「もう一度練習」を評価）
      try {
        const reviewLogResponse = await axios.post('/api/card/review-log', {
          student_id: state.auth.user?.username || 'anonymous',
          card_id: cardId,
          curriculum_id: state.selectedCurriculum?.id || 0,
          review_type: 'similar_problem',
          is_already_cleared: true,  // クリア済みカードの復習
          is_correct: null,  // まだ解いていない
          answer_time_seconds: 0,
          hint_count: 0
        })
        
        if (reviewLogResponse.data.success) {
          console.log('✅ 復習ログ記録:', reviewLogResponse.data)
          
          // 励ましメッセージを表示（短時間）
          setTimeout(() => {
            const encouragement = document.createElement('div')
            encouragement.className = 'fixed top-4 right-4 bg-green-500 text-white px-6 py-3 rounded-lg shadow-lg z-[60]'
            encouragement.innerHTML = '<i class="fas fa-star mr-2"></i>復習の努力が記録されました！'
            document.body.appendChild(encouragement)
            
            setTimeout(() => {
              encouragement.style.transition = 'opacity 0.5s'
              encouragement.style.opacity = '0'
              setTimeout(() => encouragement.remove(), 500)
            }, 2000)
          }, 300)
        }
      } catch (reviewError) {
        console.warn('復習ログ記録エラー（非致命的）:', reviewError)
      }
      
    } else {
      throw new Error(response.data.error || '生成に失敗しました')
    }
  } catch (error) {
    console.error('類似問題生成エラー:', error)
    hideLoadingOverlay()
    alert('❌ 問題の生成に失敗しました。\n\nもう一度お試しください。')
  }
}

// 類似問題の答えを表示/非表示
function toggleSimilarAnswer() {
  const answer = document.getElementById('similarAnswer')
  const btn = document.getElementById('toggleSimilarAnswerBtn')
  
  if (answer.classList.contains('hidden')) {
    answer.classList.remove('hidden')
    btn.innerHTML = '<i class="fas fa-eye-slash mr-2"></i>答えを隠す'
    btn.className = 'bg-gray-500 hover:bg-gray-600 text-white font-bold py-3 px-6 rounded-lg transition'
    // ヒントを使用したことを記録
    window.practiceHintUsed = true
  } else {
    answer.classList.add('hidden')
    btn.innerHTML = '<i class="fas fa-eye mr-2"></i>答えを表示'
    btn.className = 'bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-6 rounded-lg transition'
  }
}

// 類似問題モーダルを閉じる
async function closeSimilarProblemModal() {
  const modal = document.getElementById('similarProblemModal')
  if (modal) {
    // 練習時間を計算
    if (window.practiceStartTime && window.practiceCardId) {
      const practiceTime = Math.floor((Date.now() - window.practiceStartTime) / 1000) // 秒単位
      
      console.log('📊 復習記録:', {
        cardId: window.practiceCardId,
        practiceTime: practiceTime + '秒',
        hintUsed: window.practiceHintUsed
      })
      
      // 復習記録をAPIに送信（学生がログインしている場合のみ）
      if (state.student && state.student.id && state.selectedCurriculum) {
        try {
          await axios.post('/api/learning/log', {
            student_id: state.student.id,
            curriculum_id: state.selectedCurriculum.id,
            card_id: window.practiceCardId,
            course_type: 'review',
            is_correct: 1, // 復習なので正解扱い
            answer_time_seconds: practiceTime,
            hint_count: window.practiceHintUsed ? 1 : 0,
            retry_count: 1,
            difficulty_level: 'review',
            problem_type: 'similar_practice'
          })
          console.log('✅ 復習記録を保存しました')
        } catch (error) {
          console.error('❌ 復習記録の保存に失敗:', error)
        }
      }
      
      // リセット
      window.practiceStartTime = null
      window.practiceCardId = null
      window.practiceHintUsed = false
    }
    
    modal.remove()
    document.body.style.overflow = ''
  }
}

