function closeCardDetail(event) {
  // 背景クリックまたは閉じるボタンの場合のみ閉じる
  if (!event || event.target.id === 'cardDetailModal' || event.type === 'click') {
    const modal = document.getElementById('cardDetailModal')
    if (modal) {
      modal.remove()
      document.body.style.overflow = ''
    }
  }
}

