function closeCardEditModal() {
  const modal = document.getElementById('cardEditModal')
  if (modal) {
    modal.remove()
    document.body.style.overflow = ''
  }
}

// カード編集を保存
async function saveCardEdit(cardId, courseIndex, cardIndex) {
  try {
    // 元のカードデータを取得
    const originalCard = window.currentUnitData?.courses[courseIndex]?.cards[cardIndex] || {}
    
    // フォームデータを取得
    const updatedCard = {
      card_title: document.getElementById('edit_card_title').value,
      card_type: originalCard.card_type || 'main', // 既存のcard_typeを保持
      textbook_page: originalCard.textbook_page || '', // 既存のtextbook_pageを保持
      problem_description: document.getElementById('edit_problem_description').value,
      new_terms: document.getElementById('edit_new_terms').value,
      example_problem: document.getElementById('edit_example_problem').value,
      example_solution: document.getElementById('edit_example_solution').value,
      real_world_connection: document.getElementById('edit_real_world_connection').value,
      answer: document.getElementById('edit_answer').value,
      answer_explanation: document.getElementById('edit_answer_explanation').value,
      problem_image_url: document.getElementById('edit_problem_image_url')?.value || null,
      solution_video_url: document.getElementById('edit_solution_video_url')?.value || null
    }
    
    // APIリクエスト
    const response = await axios.put(`/api/cards/${cardId}`, updatedCard)
    
    if (response.data.success) {
      // ローカルデータを更新
      if (window.currentUnitData?.courses[courseIndex]?.cards[cardIndex]) {
        Object.assign(window.currentUnitData.courses[courseIndex].cards[cardIndex], updatedCard)
      }
      
      // モーダルを閉じる
      closeCardEditModal()
      
      // 成功メッセージ
      alert('✅ カードを保存しました！')
      
      // 画面を再描画
      showTeacherOverview(window.currentUnitData)
    } else {
      throw new Error(response.data.error || '保存に失敗しました')
    }
  } catch (error) {
    console.error('カード保存エラー:', error)
    alert('❌ 保存に失敗しました: ' + (error.response?.data?.error || error.message))
  }
}

// グローバル関数として公開
window.showTeacherOverview = showTeacherOverview

// 基本情報編集モードの切り替え
function toggleBasicInfoEdit() {
  const displayDiv = document.getElementById('basic-info-display')
  const editDiv = document.getElementById('basic-info-edit')
  const editBtn = document.getElementById('basic-info-edit-btn')
  
  if (editDiv.classList.contains('hidden')) {
    // 編集モードに切り替え
    displayDiv.classList.add('hidden')
    editDiv.classList.remove('hidden')
    editBtn.innerHTML = '<i class="fas fa-times mr-1"></i>閉じる'
  } else {
    // 表示モードに切り替え
    displayDiv.classList.remove('hidden')
    editDiv.classList.add('hidden')
    editBtn.innerHTML = '<i class="fas fa-edit mr-1"></i>編集'
  }
}

window.toggleBasicInfoEdit = toggleBasicInfoEdit

// 基本情報を保存
async function saveBasicInfo(curriculumId) {
  try {
    const grade = document.getElementById('edit-grade').value
    const subject = document.getElementById('edit-subject').value
    const textbook = document.getElementById('edit-textbook').value
    const unitName = document.getElementById('edit-unit-name').value
    const unitGoal = document.getElementById('edit-unit-goal').value
    const nonCognitiveGoal = document.getElementById('edit-non-cognitive-goal').value
    
    console.log('💾 基本情報を保存:', { grade, subject, textbook, unitName })
    
    // APIで更新
    const response = await axios.put(`/api/curriculum/${curriculumId}`, {
      basicInfo: {
        grade,
        subject,
        textbook_company: textbook,
        unit_name: unitName,
        unit_goal: unitGoal,
        non_cognitive_goal: nonCognitiveGoal
      },
      courses: [] // 空配列を渡す（カードは更新しない）
    })
    
    console.log('✅ 保存成功:', response.data)
    
    if (response.data.success) {
      // window.currentUnitDataを更新
      if (window.currentUnitData && window.currentUnitData.curriculum) {
        window.currentUnitData.curriculum.grade = grade
        window.currentUnitData.curriculum.subject = subject
        window.currentUnitData.curriculum.textbook_company = textbook
        window.currentUnitData.curriculum.unit_name = unitName
        window.currentUnitData.curriculum.unit_goal = unitGoal
        window.currentUnitData.curriculum.non_cognitive_goal = nonCognitiveGoal
      }
      
      alert('✅ 保存しました！')
      
      // ページを再読み込み
      showTeacherOverview(window.currentUnitData)
    } else {
      throw new Error(response.data.error || '保存に失敗しました')
    }
  } catch (error) {
    console.error('❌ 保存エラー:', error)
    alert(`❌ 保存に失敗しました\\n\\n${error.response?.data?.details || error.message}`)
  }
}

window.saveBasicInfo = saveBasicInfo

// カード詳細の展開/折りたたみ
function toggleCardDetails(courseIndex, cardIndex) {
  const detailsDiv = document.getElementById(`card-details-${courseIndex}-${cardIndex}`)
  const icon = document.getElementById(`card-icon-${courseIndex}-${cardIndex}`)
  
  if (detailsDiv.classList.contains('hidden')) {
    detailsDiv.classList.remove('hidden')
    icon.classList.remove('fa-chevron-down')
    icon.classList.add('fa-chevron-up')
  } else {
    detailsDiv.classList.add('hidden')
    icon.classList.remove('fa-chevron-up')
    icon.classList.add('fa-chevron-down')
  }
}

window.toggleCardDetails = toggleCardDetails

// インライン編集モードの切り替え
function toggleEditMode(courseIndex, cardIndex, fieldName) {
  const displayDiv = document.getElementById(`display-${fieldName}-${courseIndex}-${cardIndex}`)
  const editDiv = document.getElementById(`edit-${fieldName}-${courseIndex}-${cardIndex}`)
  const editBtn = document.getElementById(`edit-btn-${fieldName}-${courseIndex}-${cardIndex}`)
  
  if (displayDiv && editDiv && editBtn) {
    const isEditing = !editDiv.classList.contains('hidden')
    
    if (isEditing) {
      // 編集モード → 表示モード
      displayDiv.classList.remove('hidden')
      editDiv.classList.add('hidden')
      editBtn.innerHTML = '<i class="fas fa-edit mr-1"></i>編集'
    } else {
      // 表示モード → 編集モード
      displayDiv.classList.add('hidden')
      editDiv.classList.remove('hidden')
      editBtn.innerHTML = '<i class="fas fa-times mr-1"></i>閉じる'
    }
  }
}

window.toggleEditMode = toggleEditMode

// 編集モードのキャンセル
function cancelEditMode(courseIndex, cardIndex, fieldName) {
  const displayDiv = document.getElementById(`display-${fieldName}-${courseIndex}-${cardIndex}`)
  const editDiv = document.getElementById(`edit-${fieldName}-${courseIndex}-${cardIndex}`)
  const editBtn = document.getElementById(`edit-btn-${fieldName}-${courseIndex}-${cardIndex}`)
  
  if (displayDiv && editDiv && editBtn) {
    displayDiv.classList.remove('hidden')
    editDiv.classList.add('hidden')
    editBtn.innerHTML = '<i class="fas fa-edit mr-1"></i>編集'
  }
}

window.cancelEditMode = cancelEditMode

// フィールド編集の保存
async function saveFieldEdit(courseIndex, cardIndex, fieldName, cardId) {
  try {
    const input = document.getElementById(`input-${fieldName}-${courseIndex}-${cardIndex}`)
    const newValue = input.value
    
    // 変更前の値を取得
    const card = window.currentUnitData?.courses[courseIndex]?.cards[cardIndex]
    const oldValue = card ? card[fieldName] : ''
    
    console.log(`💾 フィールド保存: ${fieldName} = ${newValue.substring(0, 50)}...`)
    
    // APIで更新
    const response = await axios.put(`/api/card/${cardId}`, {
      [fieldName]: newValue
    })
    
    console.log('✅ 保存成功:', response.data)
    
    if (response.data.success) {
      // 変更履歴をトラッキング
      trackCardEdit(cardId, fieldName, oldValue, newValue)
      
      // 表示を更新
      const displayDiv = document.getElementById(`display-${fieldName}-${courseIndex}-${cardIndex}`)
      if (displayDiv) {
        displayDiv.innerHTML = newValue.replace(/\n/g, '<br>') || '(なし)'
      }
      
      // window.currentUnitDataも更新
      if (window.currentUnitData && window.currentUnitData.courses[courseIndex]) {
        const card = window.currentUnitData.courses[courseIndex].cards[cardIndex]
        if (card) {
          card[fieldName] = newValue
        }
      }
      
      // 編集モードを閉じる
      cancelEditMode(courseIndex, cardIndex, fieldName)
      
      alert('✅ 保存しました！')
    } else {
      throw new Error(response.data.error || '保存に失敗しました')
    }
  } catch (error) {
    console.error('❌ 保存エラー:', error)
    alert(`❌ 保存に失敗しました\n\n${error.response?.data?.details || error.message}`)
  }
}

window.saveFieldEdit = saveFieldEdit

// ヒントの追加
function addHint(courseIndex, cardIndex) {
  const editorDiv = document.getElementById(`hints-editor-${courseIndex}-${cardIndex}`)
  if (!editorDiv) return
  
  const currentHints = editorDiv.querySelectorAll('textarea')
  const newIndex = currentHints.length
  
  const newHintHtml = `
    <div class="bg-purple-50 p-3 rounded-lg" id="hint-container-${courseIndex}-${cardIndex}-${newIndex}">
      <div class="flex items-center justify-between mb-2">
        <p class="font-bold text-purple-700 text-sm">ヒント ${newIndex + 1}</p>
        <button onclick="removeHint(${courseIndex}, ${cardIndex}, ${newIndex})"
                class="bg-red-500 hover:bg-red-600 text-white px-2 py-1 rounded text-xs font-bold transition">
          <i class="fas fa-trash mr-1"></i>削除
        </button>
      </div>
      <textarea 
        id="input-hint-${courseIndex}-${cardIndex}-${newIndex}"
        class="w-full p-2 border-2 border-purple-300 rounded-lg focus:border-purple-500 focus:outline-none text-sm"
        rows="3"
        style="line-height: 1.6;"
        placeholder="新しいヒントを入力..."
      ></textarea>
    </div>
  `
  
  editorDiv.insertAdjacentHTML('beforeend', newHintHtml)
  console.log(`✅ ヒント ${newIndex + 1} を追加`)
}

window.addHint = addHint

// ヒントの削除
function removeHint(courseIndex, cardIndex, hintIndex) {
  const container = document.getElementById(`hint-container-${courseIndex}-${cardIndex}-${hintIndex}`)
  if (container && confirm('このヒントを削除しますか？')) {
    container.remove()
    console.log(`🗑️ ヒント ${hintIndex + 1} を削除`)
  }
}

window.removeHint = removeHint

// ヒント編集の保存
async function saveHintsEditV1(courseIndex, cardIndex, cardId) {
  try {
    const editorDiv = document.getElementById(`hints-editor-${courseIndex}-${cardIndex}`)
    if (!editorDiv) return
    
    // 全てのヒントを収集
    const hintTextareas = editorDiv.querySelectorAll('textarea')
    const hints = []
    
    hintTextareas.forEach((textarea, index) => {
      const text = textarea.value.trim()
      if (text) {
        hints.push({
          hint_number: index + 1,
          hint_text: text
        })
      }
    })
    
    console.log(`💾 ヒント保存: ${hints.length}段階`)
    
    // APIで更新
    const response = await axios.put(`/api/card/${cardId}`, {
      hints: hints
    })
    
    console.log('✅ 保存成功:', response.data)
    
    if (response.data.success) {
      // window.currentUnitDataも更新
      if (window.currentUnitData && window.currentUnitData.courses[courseIndex]) {
        const card = window.currentUnitData.courses[courseIndex].cards[cardIndex]
        if (card) {
          card.hints = hints
        }
      }
      
      // 表示を更新
      const displayDiv = document.getElementById(`display-hints-${courseIndex}-${cardIndex}`)
      if (displayDiv) {
        displayDiv.innerHTML = hints.map((hint, index) => `
          <div class="bg-purple-50 p-3 rounded-lg">
            <p class="font-bold text-purple-700 text-sm mb-1">ヒント ${index + 1}</p>
            <p class="text-gray-700 text-sm whitespace-pre-wrap" style="line-height: 1.6;">${hint.hint_text}</p>
          </div>
        `).join('')
      }
      
      // 編集モードを閉じる
      cancelEditMode(courseIndex, cardIndex, 'hints')
      
      alert('✅ ヒントを保存しました！')
    } else {
      throw new Error(response.data.error || '保存に失敗しました')
    }
  } catch (error) {
    console.error('❌ ヒント保存エラー:', error)
    alert(`❌ 保存に失敗しました\n\n${error.response?.data?.details || error.message}`)
  }
}

window.saveHintsEdit = saveHintsEdit
window.editCardContent = editCardContent
window.closeCardEditModal = closeCardEditModal
window.saveCardEdit = saveCardEdit

