async function saveTeacherOptionalProblemEdit(problemId, problemIndex) {
  try {
    console.log('📝 選択問題の保存を開始:', { problemId, problemIndex })
    
    const updatedProblem = {
      problem_title: document.getElementById('edit_problem_title').value,
      problem_description: document.getElementById('edit_problem_description').value,
      learning_meaning: document.getElementById('edit_learning_meaning').value,
      difficulty_level: document.getElementById('edit_difficulty_level').value
    }
    
    console.log('📝 更新データ:', updatedProblem)
    
    // フロントエンドでのバリデーション
    const errors = []
    if (!updatedProblem.problem_title || updatedProblem.problem_title.trim() === '') {
      errors.push('問題タイトルが入力されていません')
    }
    if (!updatedProblem.problem_description || updatedProblem.problem_description.trim() === '') {
      errors.push('問題内容が入力されていません')
    }
    if (!updatedProblem.difficulty_level) {
      errors.push('難易度が選択されていません')
    }
    
    if (errors.length > 0) {
      alert('❌ 入力エラー\n\n' + errors.join('\n'))
      return
    }
    
    const response = await axios.put(`/api/optional-problem/${problemId}`, updatedProblem)
    
    console.log('✅ サーバーレスポンス:', response.data)
    
    if (response.data.success) {
      if (window.currentUnitData?.optional_problems[problemIndex]) {
        Object.assign(window.currentUnitData.optional_problems[problemIndex], updatedProblem)
      }
      
      closeOptionalProblemEditModal()
      alert('✅ 選択問題を保存しました！')
      showTeacherOverview(window.currentUnitData)
    } else {
      throw new Error(response.data.error || '保存に失敗しました')
    }
  } catch (error) {
    console.error('❌ 選択問題保存エラー:', error)
    console.error('❌ エラーレスポンス:', error.response?.data)
    const errorMsg = error.response?.data?.details || error.response?.data?.error || error.message
    alert(`❌ 保存に失敗しました\n\nエラー: ${errorMsg}`)
  }
}

window.editTeacherOptionalProblem = editTeacherOptionalProblem
window.closeOptionalProblemEditModal = closeOptionalProblemEditModal
window.saveTeacherOptionalProblemEdit = saveTeacherOptionalProblemEdit

