/**
 * Chart.jsグラフ描画
 */
function renderLearningCharts(report) {
  const studentId = report.student.id
  
  // 1. 学習時間推移グラフ（折れ線グラフ）
  const timeCtx = document.getElementById(`learningTimeChart-${studentId}`)
  if (timeCtx && report.charts.learning_time_trend) {
    new Chart(timeCtx, {
      type: 'line',
      data: {
        labels: report.charts.learning_time_trend.map(d => new Date(d.date).toLocaleDateString('ja-JP', { month: 'short', day: 'numeric' })),
        datasets: [
          {
            label: '学習時間（分）',
            data: report.charts.learning_time_trend.map(d => d.minutes),
            borderColor: 'rgb(59, 130, 246)',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            tension: 0.3,
            fill: true
          },
          {
            label: '累積学習時間（分）',
            data: report.charts.learning_time_trend.map(d => d.cumulative_minutes),
            borderColor: 'rgb(139, 92, 246)',
            backgroundColor: 'rgba(139, 92, 246, 0.1)',
            tension: 0.3,
            fill: true,
            borderDash: [5, 5]
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'top'
          },
          tooltip: {
            mode: 'index',
            intersect: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: '時間（分）'
            }
          }
        }
      }
    })
  }
  
  // 2. 習熟度レーダーチャート
  const radarCtx = document.getElementById(`masteryRadarChart-${studentId}`)
  if (radarCtx && report.charts.mastery_radar) {
    new Chart(radarCtx, {
      type: 'radar',
      data: {
        labels: report.charts.mastery_radar.labels,
        datasets: [{
          label: '習熟度スコア',
          data: report.charts.mastery_radar.scores,
          borderColor: 'rgb(34, 197, 94)',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          pointBackgroundColor: 'rgb(34, 197, 94)',
          pointBorderColor: '#fff',
          pointHoverBackgroundColor: '#fff',
          pointHoverBorderColor: 'rgb(34, 197, 94)'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'top'
          }
        },
        scales: {
          r: {
            beginAtZero: true,
            max: 100,
            ticks: {
              stepSize: 20
            }
          }
        }
      }
    })
  }
  
  // 3. 教科別パフォーマンス棒グラフ（クラス平均比較）
  const barCtx = document.getElementById(`subjectPerformanceChart-${studentId}`)
  if (barCtx && report.charts.subject_performance_bar) {
    const subjects = report.charts.subject_performance_bar.map(d => d.subject)
    const studentScores = report.charts.subject_performance_bar.map(d => d.score)
    const classAverages = report.charts.subject_performance_bar.map(d => d.class_average || 0)
    
    new Chart(barCtx, {
      type: 'bar',
      data: {
        labels: subjects,
        datasets: [
          {
            label: '本人スコア',
            data: studentScores,
            backgroundColor: 'rgba(59, 130, 246, 0.8)',
            borderColor: 'rgb(59, 130, 246)',
            borderWidth: 1
          },
          {
            label: 'クラス平均',
            data: classAverages,
            backgroundColor: 'rgba(156, 163, 175, 0.5)',
            borderColor: 'rgb(156, 163, 175)',
            borderWidth: 1
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'top'
          },
          tooltip: {
            mode: 'index',
            intersect: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            max: 100,
            title: {
              display: true,
              text: 'スコア'
            }
          }
        }
      }
    })
  }
}

/**
 * 学習スタイルラベル取得
 */
function getLearningStyleLabel(style) {
  const labels = {
    'visual': '視覚型 (Visual)',
    'auditory': '聴覚型 (Auditory)',
    'reading': '読書型 (Reading)',
    'kinesthetic': '体感型 (Kinesthetic)',
    'unknown': '分析中'
  }
  return labels[style] || '不明'
}

/**
 * VARKスコアのプログレスバー生成
 */
function generateVARKBars(varkBreakdown) {
  const varkLabels = {
    visual: { label: '視覚 (Visual)', icon: 'fa-eye', color: 'blue' },
    auditory: { label: '聴覚 (Auditory)', icon: 'fa-ear-listen', color: 'green' },
    reading: { label: '読書 (Reading)', icon: 'fa-book-open', color: 'purple' },
    kinesthetic: { label: '体感 (Kinesthetic)', icon: 'fa-hand-paper', color: 'orange' }
  }
  
  return Object.entries(varkBreakdown).map(([key, value]) => {
    const vark = varkLabels[key]
    if (!vark) return ''
    
    const percentage = Math.round(value * 100)
    
    return `
      <div>
        <div class="flex items-center justify-between mb-1">
          <span class="text-sm font-semibold text-gray-700">
            <i class="fas ${vark.icon} mr-2"></i>${vark.label}
          </span>
          <span class="text-sm font-bold text-${vark.color}-600">${percentage}%</span>
        </div>
        <div class="w-full bg-gray-200 rounded-full h-3">
          <div class="h-3 rounded-full bg-gradient-to-r from-${vark.color}-400 to-${vark.color}-600 transition-all" 
               style="width: ${percentage}%"></div>
        </div>
      </div>
    `
  }).join('')
}

/**
 * 詳細レポートをPDF出力
 */
async function exportDetailedReportToPDF(reportType) {
  showLoading('PDFを生成中...')
  
  try {
    const modal = document.getElementById('detailed-report-modal')
    if (!modal) {
      throw new Error('レポートが見つかりません')
    }

    const periodText = reportType === 'weekly' ? '週次レポート' : 
                       reportType === 'monthly' ? '月次レポート' : '学期レポート'
    const today = new Date().toISOString().split('T')[0]

    const opt = {
      margin: [10, 10, 10, 10],
      filename: `${periodText}_${today}.pdf`,
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { 
        scale: 2, 
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff'
      },
      jsPDF: { 
        unit: 'mm', 
        format: 'a4', 
        orientation: 'portrait',
        compress: true
      },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    }

    await html2pdf().set(opt).from(modal).save()
    
    hideLoading()
    console.log('✅ 詳細レポートPDF生成完了')
  } catch (error) {
    hideLoading()
    console.error('PDF生成エラー:', error)
    alert('PDF生成に失敗しました')
  }
}

