// 削除済み: 重複していた古いaddOptionalProblem関数（13610行目の新バージョンを使用）

// ============================================
// 認証機能
// ============================================

// APIリクエストヘルパー（認証トークン付き）
async function authFetch(url, options = {}) {
  const headers = {
    'Content-Type': 'application/json',
    ...options.headers
  }
  
  if (state.auth.sessionToken) {
    headers['Authorization'] = `Bearer ${state.auth.sessionToken}`
  }
  
  const response = await fetch(url, {
    ...options,
    headers
  })
  
  // 401エラー（認証切れ）の場合、リフレッシュを試みる
  if (response.status === 401 && state.auth.refreshToken) {
    const refreshed = await refreshSession()
    if (refreshed) {
      // リトライ
      headers['Authorization'] = `Bearer ${state.auth.sessionToken}`
      return fetch(url, { ...options, headers })
    } else {
      // リフレッシュ失敗: ログアウト
      logout()
      return response
    }
  }
  
  return response
}

// セッション検証
async function verifySession() {
  try {
    // 10秒タイムアウトを設定（Wranglerビジー時にハングしないように）
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 10000)
    const response = await authFetch('/api/auth/me', { signal: controller.signal })
    clearTimeout(timeoutId)
    if (!response.ok) {
      logout()
      return false
    }
    return true
  } catch (error) {
    console.error('セッション検証エラー:', error)
    // タイムアウトの場合はログアウトせず、保存済みセッションで続行
    if (error.name === 'AbortError') {
      console.warn('⚠️ セッション検証タイムアウト - オフラインモードで続行')
      return true // タイムアウト時はセッション有効として扱う
    }
    logout()
    return false
  }
}

// セッション更新
async function refreshSession() {
  try {
    const response = await fetch('/api/auth/refresh', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refresh_token: state.auth.refreshToken })
    })
    
    if (!response.ok) {
      return false
    }
    
    const data = await response.json()
    state.auth.sessionToken = data.session_token
    localStorage.setItem('session_token', data.session_token)
    
    return true
  } catch (error) {
    console.error('セッション更新エラー:', error)
    return false
  }
}

