// ログイン処理
async function handleLogin(event) {
  event.preventDefault()
  
  const username = document.getElementById('username').value
  const password = document.getElementById('password').value
  const errorDiv = document.getElementById('loginError')
  const errorMessage = document.getElementById('loginErrorMessage')
  
  loadingManager.show('ログイン中...')
  errorDiv.classList.add('hidden')
  
  try {
    const response = await axios.post('/api/auth/login', {
      username,
      password
    })
    
    const data = response.data
    
    if (!data.success) {
      loadingManager.hide()
      errorMessage.textContent = data.error || 'ログインに失敗しました'
      errorDiv.classList.remove('hidden')
      return
    }
    
    // 認証情報を保存
    state.auth.isAuthenticated = true
    state.auth.sessionToken = data.session_token
    state.auth.refreshToken = data.refresh_token
    state.auth.user = data.user
    
    localStorage.setItem('session_token', data.session_token)
    localStorage.setItem('refresh_token', data.refresh_token)
    localStorage.setItem('user', JSON.stringify(data.user))
    localStorage.setItem('user_id', String(data.user.id || data.user.user_id))
    localStorage.setItem('user_role', data.user.role)
    localStorage.setItem('user_name', data.user.name || data.user.full_name || '')
    
    // ユーザー情報をstateに反映
    if (data.user.role === 'student') {
      state.currentStudent = { id: data.user.user_id, name: data.user.full_name }
    }
    
    loadingManager.hide()
    
    // ロール別リダイレクト
    if (data.user.role === 'student') {
      // 児童 → 学習のてびき
      window.location.href = `/static/student-home.html?student_id=${data.user.id || data.user.user_id}`
      return
    }
    
    // 教師・管理者 → トップページ
    renderTopPage()
  } catch (error) {
    loadingManager.hide()
    console.error('ログインエラー:', error)
    errorMessage.textContent = error.response?.data?.error || 'ログインに失敗しました。もう一度お試しください。'
    errorDiv.classList.remove('hidden')
  }
}

