// 学習カード画像URL編集機能
async function editCardImageUrl(cardId, imageType) {
  const typeLabel = imageType === 'problem' ? '問題画像' : imageType === 'answer' ? '解答画像' : '動画'
  const isVideo = (imageType === 'video')
  
  // 選択ダイアログ
  const options = isVideo
    ? `【${typeLabel}の設定】\n\n操作を選んでください:\n\n1 = URLを直接入力（YouTube等）\n2 = 動画ファイルをアップロード（MP4/WebM/MOV, 50MBまで）\n3 = 削除\n\n番号を入力してください:`
    : `【${typeLabel}の設定】\n\n操作を選んでください:\n\n1 = 画像URLを直接入力\n2 = 画像ファイルをアップロード（JPEG/PNG/GIF/WebP, 5MBまで）\n3 = AIで図・イラストを自動生成\n4 = 削除\n\n番号を入力してください:`
  
  const choice = prompt(options, isVideo ? '2' : '2')
  
  if (choice === null) return // キャンセル
  const c = choice.trim()
  
  // 削除
  if ((!isVideo && c === '4') || (isVideo && c === '3')) {
    try {
      const fieldName = isVideo ? 'solution_video_url' : (imageType === 'answer' ? 'answer_image_url' : 'problem_image_url')
      await axios.put('/api/card/' + cardId, { [fieldName]: '' })
      alert('✅ ' + typeLabel + 'を削除しました')
      window.location.reload()
    } catch (error) {
      alert(typeLabel + 'の削除に失敗しました')
    }
    return
  }
  
  // ファイルアップロード
  if (c === '2') {
    uploadMediaAndSaveToCard(cardId, isVideo ? 'video' : imageType)
    return
  }
  
  // AI生成（画像のみ）
  if (!isVideo && c === '3') {
    const genPrompt = prompt(
      '🎨 AI画像生成\n\nどんな図やイラストを生成しますか？\n（例：「折れ線グラフの例」「分数の円グラフ」「温度計の図」等）'
    )
    if (!genPrompt || genPrompt.trim().length < 2) return
    
    try {
      alert('Gemini で教育用の図を生成中です...（15〜45秒かかります）')
      const rawCd = window.currentCardData || {}
      const cd = rawCd.card || rawCd
      const res = await axios.post('/api/ai/generate-image', {
        prompt: genPrompt.trim(),
        card_id: cardId,
        problem_text: cd.problem_content || cd.problem_text || cd.content || '',
        card_title: cd.card_title || cd.title || '',
        unit_name: cd.unit_name || '',
        subject: cd.subject || '',
        grade: cd.grade_level || cd.grade || '',
        style: 'educational diagram'
      }, { timeout: 90000 })
      
      if (res.data.success && res.data.image_url) {
        const fieldName = imageType === 'answer' ? 'answer_image_url' : 'problem_image_url'
        await axios.put('/api/card/' + cardId, { [fieldName]: res.data.image_url })
        alert('✅ AI画像を生成してカードに設定しました！（' + (res.data.generation_time_ms || 0) + 'ms）')
        window.location.reload()
      } else {
        alert('画像生成に失敗しました: ' + (res.data.error || ''))
      }
    } catch (err) {
      alert('AI画像生成エラー: ' + (err.response?.data?.error || err.message))
    }
    return
  }
  
  // URL直接入力（デフォルト: 1）
  const currentUrl = prompt(
    typeLabel + 'のURLを入力してください（削除する場合は空欄にしてください）:'
  )
  
  if (currentUrl === null) return
  
  try {
    const fieldName = isVideo ? 'solution_video_url' : (imageType === 'answer' ? 'answer_image_url' : 'problem_image_url')
    const response = await axios.put('/api/card/' + cardId, {
      [fieldName]: currentUrl
    })
    
    if (response.data.success) {
      alert('✅ ' + typeLabel + 'URLを更新しました')
      window.location.reload()
    }
  } catch (error) {
    console.error(typeLabel + 'URL更新エラー:', error)
    alert(typeLabel + 'URLの更新に失敗しました')
  }
}

window.editCardImageUrl = editCardImageUrl

// ============================================
// 画像URL貼り付けクイック挿入（教師向け）
// ============================================
async function quickPasteImageUrl(cardId) {
  const url = prompt('URLを貼り付けてください：\n\n対応URL:\n・画像URL（png, jpg, gif, webp...）\n・YouTube動画URL\n・Gemini共有リンク\n・NHK for School リンク\n・Google Drive / Googleスライド\n・その他の外部リンク（参考資料として保存）\n\n例：\nhttps://gemini.google.com/share/d03081003278\nhttps://example.com/image.png')
  if (!url || !url.trim()) return
  
  const trimmedUrl = url.trim()
  
  // 簡易バリデーション
  if (!trimmedUrl.startsWith('http://') && !trimmedUrl.startsWith('https://')) {
    alert('URLは http:// または https:// で始まる必要があります')
    return
  }
  
  try {
    // プレースホルダーを読み込み中表示に変更
    const placeholder = document.getElementById('image-placeholder-' + cardId)
    if (placeholder) {
      placeholder.innerHTML = `
        <div class="p-6 text-center">
          <div class="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent mb-3"></div>
          <p class="text-blue-700 font-bold">URLを保存中...</p>
        </div>
      `
    }
    
    // URLの種類を判定
    const isImage = /\.(png|jpg|jpeg|gif|webp|svg|bmp|tiff?)(\?|$)/i.test(trimmedUrl)
    const isYT = /youtube\.com|youtu\.be/i.test(trimmedUrl)
    const isGemini = /gemini\.google\.com\/share/i.test(trimmedUrl)
    const isNHK = /nhk\.or\.jp/i.test(trimmedUrl)
    const isGDrive = /drive\.google\.com|docs\.google\.com|slides\.google\.com/i.test(trimmedUrl)
    
    // 画像URLの場合はproblem_image_urlに保存
    if (isImage) {
      await axios.put('/api/card/' + cardId, { problem_image_url: trimmedUrl })
    } else {
      // 非画像URL（Gemini、YouTube、NHK等）→ solution_video_url に保存
      await axios.put('/api/card/' + cardId, { solution_video_url: trimmedUrl })
    }
    
    // プレースホルダーを適切な表示に置き換え
    if (placeholder) {
      if (isImage) {
        placeholder.innerHTML = `
          <div class="text-center">
            <img src="${trimmedUrl}" alt="問題の図" 
                 class="max-w-full h-auto rounded-lg shadow-md mx-auto border-2 border-gray-200" style="max-height: 400px;"
                 onerror="handleImageLoadError(this, ${cardId})">
            <div class="mt-2 flex items-center justify-center gap-2">
              <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold"><i class="fas fa-check-circle mr-1"></i>保存しました</span>
              <button onclick="quickPasteImageUrl(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline">変更</button>
              <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
            </div>
          </div>`
      } else if (isYT) {
        const ytMatch = trimmedUrl.match(/(?:v=|youtu\.be\/)([^&?]+)/)
        const ytId = ytMatch ? ytMatch[1] : ''
        if (ytId) {
          placeholder.innerHTML = `
            <div class="text-center">
              <div class="relative rounded-lg overflow-hidden shadow-md border-2 border-gray-200 mx-auto" style="max-width:560px;">
                <iframe src="https://www.youtube.com/embed/${ytId}" class="w-full" style="height:315px;" frameborder="0" allowfullscreen></iframe>
              </div>
              <div class="mt-2 flex items-center justify-center gap-2">
                <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold"><i class="fas fa-check-circle mr-1"></i>YouTube動画を保存</span>
                <button onclick="quickPasteImageUrl(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline">変更</button>
                <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
              </div>
            </div>`
        }
      } else {
        // Gemini、NHK、Google Drive等 → iframeまたはリンクボタンで表示
        const label = isGemini ? 'Gemini共有リンク' : isNHK ? 'NHK for School' : isGDrive ? 'Google資料' : '参考リンク'
        const icon = isGemini ? 'fa-sparkles' : isNHK ? 'fa-tv' : isGDrive ? 'fa-file-alt' : 'fa-link'
        const color = isGemini ? 'purple' : isNHK ? 'blue' : isGDrive ? 'green' : 'gray'
        placeholder.innerHTML = `
          <div class="bg-gradient-to-br from-${color}-50 to-${color}-100 border-2 border-${color}-300 rounded-xl p-5 text-center shadow-sm">
            <div class="mb-3">
              <i class="fas ${icon} text-${color}-500 text-4xl"></i>
            </div>
            <p class="text-sm font-bold text-${color}-800 mb-2">${label}</p>
            <a href="${trimmedUrl}" target="_blank" rel="noopener" 
               class="inline-flex items-center gap-2 bg-${color}-600 hover:bg-${color}-700 text-white px-6 py-3 rounded-xl font-bold transition shadow-lg text-sm">
              <i class="fas fa-external-link-alt"></i>
              リンクを開いて確認する
            </a>
            <div class="mt-3 flex items-center justify-center gap-2">
              <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold"><i class="fas fa-check-circle mr-1"></i>保存しました</span>
              <button onclick="quickPasteImageUrl(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline">変更</button>
              <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
            </div>
            <p class="text-xs text-gray-500 mt-2">生徒はこのリンクから問題を確認できます</p>
          </div>`
      }
    }
  } catch (error) {
    console.error('URL保存エラー:', error)
    alert('URLの保存に失敗しました。もう一度試してください。')
    // プレースホルダーを元に戻す
    if (typeof showCard === 'function') {
      showCard(state.currentCardIndex || 0)
    }
  }
}
window.quickPasteImageUrl = quickPasteImageUrl

// カードメディア削除（図・動画・URL）
async function deleteCardMedia(cardId) {
  if (!confirm('この図/メディアを削除しますか？')) return
  try {
    await axios.put('/api/card/' + cardId, { 
      problem_image_url: '', 
      solution_video_url: '' 
    })
    // カードを再読み込み
    loadCardPage(cardId)
  } catch (error) {
    console.error('メディア削除エラー:', error)
    alert('削除に失敗しました')
  }
}
window.deleteCardMedia = deleteCardMedia

// ============================================
// ファイル直接アップロード（JPG/PNG/PDF ドラッグ&ドロップ・ファイル選択・クリップボード対応）
// ============================================

// 追加メディアとしてアップロード（media API経由）
async function addMediaFileToCard(cardId, file, mediaType) {
  const gallery = document.getElementById('media-gallery-' + cardId)
  if (gallery) {
    gallery.innerHTML = `
      <div class="p-4 text-center">
        <div class="animate-spin rounded-full h-10 w-10 border-4 border-purple-200 border-t-purple-600 mx-auto mb-2"></div>
        <p class="text-sm text-purple-700 font-bold">アップロード中... ${file.name}</p>
      </div>`
  }
  try {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('media_type', mediaType)
    formData.append('label', file.name)
    const res = await axios.post('/api/card/' + cardId + '/media/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
      timeout: 180000,
      maxContentLength: 100 * 1024 * 1024,
      maxBodyLength: 100 * 1024 * 1024
    })
    if (res.data.success) {
      loadMediaGallery(cardId)
      return true
    } else {
      throw new Error(res.data.error)
    }
  } catch (err) {
    console.error('メディアアップロードエラー:', err)
    alert('アップロードに失敗しました: ' + (err.response?.data?.error || err.message))
    loadMediaGallery(cardId)
    return false
  }
}
window.addMediaFileToCard = addMediaFileToCard

// ファイルをアップロードしてカードに保存
async function uploadFileToCard(cardId, file) {
  const imageTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp', 'application/pdf']
  const videoTypes = ['video/mp4', 'video/webm', 'video/ogg', 'video/quicktime']
  const audioTypes = ['audio/mpeg', 'audio/wav', 'audio/ogg', 'audio/mp4', 'audio/aac', 'audio/webm']
  const allAllowed = [...imageTypes, ...videoTypes, ...audioTypes]
  
  if (!allAllowed.includes(file.type)) {
    alert('対応形式: JPG, PNG, PDF, MP4, WebM, MP3, WAV\n選択されたファイル: ' + file.type)
    return false
  }
  
  // メディアタイプ判定
  let mediaType = 'image'
  if (videoTypes.includes(file.type)) mediaType = 'video'
  else if (audioTypes.includes(file.type)) mediaType = 'audio'
  
  // 既に画像があるカードへの画像D&Dの場合、追加メディアとして扱う
  const existingContainer = document.getElementById('card-image-container-' + cardId)
  const existingMedia = existingContainer?.querySelector('img, video, audio, iframe')
  if (existingMedia && mediaType === 'image') {
    // 差し替えか追加かを確認
    const addNew = confirm('既にメディアがあります。\n\n「OK」→ 追加メディアとして追加\n「キャンセル」→ 今のメディアを差し替え')
    if (addNew) {
      // 追加メディアとしてアップロード
      return addMediaFileToCard(cardId, file, mediaType)
    }
  }
  
  // 動画・音声: 常にmedia API経由でアップロード（media_items管理の一貫性を保つ）
  if (mediaType !== 'image') {
    const placeholder = document.getElementById('image-placeholder-' + cardId)
    const guidePlaceholder = document.getElementById('guide-img-' + cardId)
    const hasNoMedia = !existingContainer && (placeholder || guidePlaceholder)
    
    if (hasNoMedia) {
      // メディアがないカード: アップロード中UIを表示
      const targetEl = placeholder || guidePlaceholder
      if (targetEl) {
        targetEl.innerHTML = `
          <div class="p-8 text-center">
            <div class="inline-block relative mb-4">
              <div class="animate-spin rounded-full h-16 w-16 border-4 border-purple-200 border-t-purple-600"></div>
              <i class="fas fa-cloud-upload-alt absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-purple-600 text-xl"></i>
            </div>
            <p class="text-purple-700 font-bold text-lg">${mediaType === 'video' ? '動画' : '音声'}アップロード中...</p>
            <p class="text-sm text-gray-500 mt-1">${file.name} (${(file.size / (1024*1024)).toFixed(1)} MB)</p>
          </div>`
      }
    }
    
    // media upload API経由でアップロード（media_itemsに正しく登録される）
    const result = await addMediaFileToCard(cardId, file, mediaType)
    
    if (result && hasNoMedia) {
      // メディアがなかったカード: メイン表示領域を更新
      try {
        const mediaRes = await axios.get('/api/card/' + cardId + '/media')
        if (mediaRes.data.success) {
          const items = mediaRes.data.media_items || []
          const firstItem = items.find(it => it.type === mediaType)
          if (firstItem) {
            const targetEl = document.getElementById('image-placeholder-' + cardId) || document.getElementById('guide-img-' + cardId)
            if (targetEl) {
              targetEl.outerHTML = renderMediaEmbed(firstItem.url, cardId, firstItem.label || file.name)
            }
            // problem_image_urlも更新
            await axios.put('/api/card/' + cardId, { problem_image_url: firstItem.url }).catch(() => {})
          }
        }
      } catch (e) { console.error('メイン表示更新エラー:', e) }
    }
    return result
  }
  // サイズチェック: 画像5MB、動画50MB、音声20MB
  const sizeLimits = { image: 10, video: 50, audio: 20 }
  const sizeLimit = (sizeLimits[mediaType] || 5) * 1024 * 1024
  if (file.size > sizeLimit) {
    alert('ファイルサイズが大きすぎます（上限' + (sizeLimits[mediaType] || 5) + 'MB、現在' + (file.size/1024/1024).toFixed(1) + 'MB）')
    return false
  }
  
  const placeholder = document.getElementById('image-placeholder-' + cardId)
  const guidePlaceholder = document.getElementById('guide-img-' + cardId)
  const targetEl = placeholder || guidePlaceholder
  
  // アップロード中UI
  if (targetEl) {
    targetEl.innerHTML = `
      <div class="p-8 text-center">
        <div class="inline-block relative mb-4">
          <div class="animate-spin rounded-full h-16 w-16 border-4 border-purple-200 border-t-purple-600"></div>
          <i class="fas fa-cloud-upload-alt absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-purple-600 text-xl"></i>
        </div>
        <p class="text-purple-700 font-bold text-lg">アップロード中...</p>
        <p class="text-sm text-gray-500 mt-1">${file.name} (${(file.size / 1024).toFixed(0)} KB)</p>
        <div class="w-48 mx-auto bg-gray-200 rounded-full h-2 mt-3">
          <div class="bg-purple-600 h-2 rounded-full animate-pulse" style="width:70%"></div>
        </div>
      </div>
    `
  }
  
  try {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('card_id', String(cardId))
    
    const res = await axios.post('/api/upload/image', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
      timeout: 60000
    })
    
    if (res.data.success) {
      const imageUrl = res.data.image_url
      const isPdf = res.data.is_pdf
      
      if (targetEl) {
        if (isPdf) {
          // PDF: iframeで表示
          targetEl.outerHTML = `
            <div class="mt-4 text-center" id="card-image-container-${cardId}">
              <div class="border-2 border-gray-200 rounded-lg overflow-hidden shadow-md" style="max-height:500px;">
                <iframe src="${imageUrl}" class="w-full" style="height:450px; border:none;"></iframe>
              </div>
              <div class="mt-2 flex items-center justify-center gap-2 flex-wrap">
                <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold">
                  <i class="fas fa-check-circle mr-1"></i>PDF保存済み
                </span>
                <a href="${imageUrl}" target="_blank" class="text-xs text-blue-500 hover:text-blue-700 underline">
                  <i class="fas fa-external-link-alt mr-1"></i>新しいタブで開く
                </a>
                <button onclick="replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>
              </div>
            </div>
          `
        } else {
          // 画像: imgタグで表示
          targetEl.outerHTML = `
            <div class="mt-4 text-center" id="card-image-container-${cardId}">
              <img src="${imageUrl}" alt="問題の図" 
                   class="max-w-full h-auto rounded-lg shadow-md mx-auto border-2 border-gray-200" style="max-height: 400px;"
                   onerror="handleImageLoadError(this, ${cardId})">
              <div class="mt-2 flex items-center justify-center gap-2 flex-wrap">
                <span class="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold">
                  <i class="fas fa-check-circle mr-1"></i>保存済み
                </span>
                <button onclick="openImageEditor(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline"><i class="fas fa-edit mr-1"></i>編集</button>
                <button onclick="replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>
              </div>
            </div>
          `
        }
      }
      // ギャラリーも更新（追加画像ボタンを表示するため）
      loadMediaGallery(cardId)
      return true
    } else {
      throw new Error(res.data.error || 'アップロード失敗')
    }
  } catch (error) {
    console.error('ファイルアップロードエラー:', error)
    if (targetEl) {
      targetEl.innerHTML = `
        <div class="p-4 text-center">
          <i class="fas fa-exclamation-triangle text-red-500 text-3xl mb-2 block"></i>
          <p class="text-red-700 font-bold mb-2">アップロードに失敗しました</p>
          <p class="text-xs text-gray-500 mb-3">${error.response?.data?.error || error.message || 'ネットワークエラー'}</p>
          <div class="flex gap-2 justify-center">
            <button onclick="openFilePickerForCard(${cardId})" class="bg-blue-500 text-white px-4 py-2 rounded-lg text-sm font-bold">
              <i class="fas fa-redo mr-1"></i>もう一度試す
            </button>
            <button onclick="quickPasteImageUrl(${cardId})" class="bg-green-500 text-white px-4 py-2 rounded-lg text-sm font-bold">
              <i class="fas fa-paste mr-1"></i>URL貼付
            </button>
          </div>
        </div>
      `
    }
    return false
  }
}
window.uploadFileToCard = uploadFileToCard

