// =============================================================================
// Phase 14: ファイルアップロード機能
// =============================================================================

// ファイルアップロード状態
const fileUploadState = {
  selectedImageFile: null,
  selectedVideoFile: null
}

// 画像ファイル選択ハンドラ
function handleImageFileSelect(event) {
  const file = event.target.files[0]
  if (file) {
    previewImageFile(file)
  }
}

// 画像ドラッグオーバーハンドラ
function handleDragOver(event) {
  event.preventDefault()
  event.stopPropagation()
  event.dataTransfer.dropEffect = 'copy'
}

// 画像ドロップハンドラ
function handleImageDrop(event) {
  event.preventDefault()
  event.stopPropagation()
  
  const file = event.dataTransfer.files[0]
  if (file && file.type.startsWith('image/')) {
    previewImageFile(file)
  } else {
    alert('画像ファイルのみアップロード可能です')
  }
}

// 画像ファイルプレビュー
function previewImageFile(file) {
  // ファイルサイズチェック（10MB）
  const maxSize = 10 * 1024 * 1024
  if (file.size > maxSize) {
    alert('ファイルサイズが大きすぎます。10MB以下の画像を選択してください。')
    return
  }
  
  fileUploadState.selectedImageFile = file
  
  // プレビュー表示
  const reader = new FileReader()
  reader.onload = (e) => {
    const previewDiv = document.getElementById('image-upload-preview')
    const previewImg = document.getElementById('image-preview-img')
    const previewName = document.getElementById('image-preview-name')
    const uploadBtn = document.getElementById('upload-image-btn')
    
    previewImg.src = e.target.result
    previewName.innerHTML = `
      <div class="flex items-center justify-between flex-wrap gap-2">
        <span class="font-medium">${file.name} (${formatFileSize(file.size)})</span>
        <div class="flex gap-2 flex-wrap">
          <button onclick="showImageEditor(fileUploadState.selectedImageFile)" 
                  class="px-3 py-1 bg-purple-600 text-white text-sm rounded hover:bg-purple-700 transition">
            <i class="fas fa-edit"></i> 簡易編集
          </button>
          <button onclick="openPhotopeaEditor(fileUploadState.selectedImageFile)" 
                  class="px-3 py-1 bg-indigo-600 text-white text-sm rounded hover:bg-indigo-700 transition">
            <i class="fas fa-paint-brush"></i> 高度な編集
          </button>
          <button onclick="handleFaceBlur()" 
                  class="px-3 py-1 bg-pink-600 text-white text-sm rounded hover:bg-pink-700 transition">
            <i class="fas fa-user-secret"></i> 顔にモザイク
          </button>
        </div>
      </div>
    `
    previewDiv.classList.remove('hidden')
    uploadBtn.classList.remove('hidden')
  }
  reader.readAsDataURL(file)
}

// 画像プレビュークリア
function clearImagePreview() {
  fileUploadState.selectedImageFile = null
  
  const previewDiv = document.getElementById('image-upload-preview')
  const uploadBtn = document.getElementById('upload-image-btn')
  const fileInput = document.getElementById('image-file-input')
  
  previewDiv.classList.add('hidden')
  uploadBtn.classList.add('hidden')
  fileInput.value = ''
}

// URLが動画かどうか判定するヘルパー
function isVideoUrl(url) {
  if (!url) return false
  // R2パス or 拡張子ベースで判定
  if (/\/api\/media\/(files\/)?videos\//.test(url)) return true
  if (/\.(mp4|webm|ogg|mov|avi|mkv|m4v)(\?|$)/i.test(url)) return true
  // data URLの判定
  if (/^data:video\//i.test(url)) return true
  return false
}
window.isVideoUrl = isVideoUrl

// URLがYouTubeかどうか判定するヘルパー
function isYouTubeUrl(url) {
  if (!url) return null
  const m = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([A-Za-z0-9_-]+)/)
  return m ? m[1] : null
}
window.isYouTubeUrl = isYouTubeUrl

// URLが音声かどうか判定するヘルパー
function isAudioUrl(url) {
  if (!url) return false
  if (/\/api\/media\/(files\/)?audio\//.test(url)) return true
  if (/\.(mp3|wav|ogg|m4a|aac|flac|wma)(\?|$)/i.test(url)) return true
  if (/^data:audio\//i.test(url)) return true
  return false
}
window.isAudioUrl = isAudioUrl

// メディアURLに応じた表示HTMLを生成（カード用）
function renderMediaEmbed(url, cardId, description, options = {}) {
  const { showEdit = true, showReplace = true, maxHeight = '400px' } = options
  const ytId = isYouTubeUrl(url)
  
  if (ytId) {
    return `
      <div class="mt-4 text-center" id="card-image-container-${cardId}">
        <div class="relative rounded-lg overflow-hidden shadow-md border-2 border-gray-200 mx-auto" style="max-width:560px;">
          <iframe src="https://www.youtube.com/embed/${ytId}" class="w-full" style="height:315px;" frameborder="0" allowfullscreen></iframe>
        </div>
        <div class="mt-1 flex items-center justify-center gap-2 flex-wrap">
          <p class="text-xs text-gray-500"><i class="fas fa-video mr-1"></i>${description || 'YouTube動画'}</p>
          ${showReplace ? `<button onclick="replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>` : ''}
          <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
        </div>
      </div>`
  }
  
  if (isVideoUrl(url)) {
    return `
      <div class="mt-4 text-center" id="card-image-container-${cardId}">
        <video controls class="max-w-full h-auto rounded-lg shadow-md mx-auto border-2 border-gray-200" style="max-height: ${maxHeight};" preload="metadata">
          <source src="${url}" type="video/mp4">
          <source src="${url}">
          動画を再生できません
        </video>
        <div class="mt-1 flex items-center justify-center gap-2 flex-wrap">
          <p class="text-xs text-gray-500"><i class="fas fa-video mr-1"></i>${description || '動画'}</p>
          ${showReplace ? `<button onclick="replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>` : ''}
          <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
        </div>
      </div>`
  }
  
  if (isAudioUrl(url)) {
    // 拡張子からMIMEタイプを推定
    const audioExt = (url.match(/\.(\w+)(?:\?|$)/i) || [])[1] || ''
    const audioMimeMap = { mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg', m4a: 'audio/mp4', aac: 'audio/aac', flac: 'audio/flac', wma: 'audio/x-ms-wma', opus: 'audio/opus', webm: 'audio/webm' }
    const audioMime = audioMimeMap[audioExt.toLowerCase()] || 'audio/mpeg'
    return `
      <div class="mt-4 text-center bg-gradient-to-br from-green-50 to-emerald-50 border-2 border-green-200 rounded-xl p-5 shadow-sm" id="card-image-container-${cardId}">
        <div class="mb-3">
          <i class="fas fa-music text-green-500 text-4xl"></i>
        </div>
        <p class="text-sm font-bold text-green-800 mb-2"><i class="fas fa-headphones mr-1"></i>音声を聞いてみよう</p>
        <audio controls class="mx-auto w-full" style="max-width:400px;" preload="auto" controlslist="nodownload">
          <source src="${url}" type="${audioMime}">
          <source src="${url}" type="audio/mpeg">
          <source src="${url}" type="audio/mp4">
          <source src="${url}">
          音声を再生できません
        </audio>
        <p class="text-xs text-gray-500 mt-2"><i class="fas fa-info-circle mr-1"></i>再生ボタンを押して音声を聞きましょう</p>
        <div class="mt-2 flex items-center justify-center gap-2 flex-wrap">
          <p class="text-xs text-gray-500"><i class="fas fa-music mr-1"></i>${description || '音声'}</p>
          ${showReplace ? `<button onclick="replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>` : ''}
          <button onclick="deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
        </div>
      </div>`
  }
  
  // デフォルト: 画像
  return `
    <div class="mt-4 text-center" id="card-image-container-${cardId}">
      <div class="relative group inline-block cursor-pointer" onclick="replaceCardImage(${cardId})">
        <img src="${url}" alt="${description || '問題の図'}" 
             class="max-w-full h-auto rounded-lg shadow-md mx-auto border-2 border-gray-200 transition group-hover:brightness-90" style="max-height: ${maxHeight};"
             onerror="handleImageLoadError(this, ${cardId})">
        <div class="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-30 transition-all rounded-lg flex items-center justify-center opacity-0 group-hover:opacity-100">
          <div class="flex gap-2">
            <span class="bg-white bg-opacity-90 text-gray-700 px-3 py-2 rounded-lg text-sm font-bold shadow-lg"><i class="fas fa-edit mr-1"></i>編集</span>
            <span class="bg-white bg-opacity-90 text-gray-700 px-3 py-2 rounded-lg text-sm font-bold shadow-lg"><i class="fas fa-sync-alt mr-1"></i>差し替え</span>
          </div>
        </div>
      </div>
      <div class="mt-1 flex items-center justify-center gap-2 flex-wrap">
        <p class="text-xs text-gray-500"><i class="fas fa-image mr-1"></i>${description || '問題の図'}</p>
        ${showEdit ? `<button onclick="event.stopPropagation(); openImageEditor(${cardId})" class="text-xs text-blue-500 hover:text-blue-700 underline"><i class="fas fa-crop-alt mr-1"></i>編集</button>` : ''}
        ${showReplace ? `<button onclick="event.stopPropagation(); replaceCardImage(${cardId})" class="text-xs text-gray-500 hover:text-gray-700 underline">差し替え</button>` : ''}
        <button onclick="event.stopPropagation(); deleteCardMedia(${cardId})" class="text-xs text-red-500 hover:text-red-700 underline"><i class="fas fa-trash mr-1"></i>削除</button>
      </div>
    </div>`
}
window.renderMediaEmbed = renderMediaEmbed

// ファイルサイズフォーマット
function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + ' B'
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
}

// 画像ファイルアップロード
// 進捗バー表示
function showUploadProgress(fileName, fileSize) {
  const modalHTML = `
    <div id="upload-progress-modal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div class="bg-white rounded-lg p-6 w-96">
        <h3 class="text-lg font-bold mb-4">📤 アップロード中</h3>
        <p class="text-sm text-gray-600 mb-2">${fileName}</p>
        <p class="text-xs text-gray-500 mb-4">${formatFileSize(fileSize)}</p>
        
        <div class="w-full bg-gray-200 rounded-full h-4 mb-2">
          <div id="upload-progress-bar" class="bg-blue-600 h-4 rounded-full transition-all duration-300" style="width: 0%"></div>
        </div>
        
        <div class="flex justify-between text-sm">
          <span id="upload-progress-percent">0%</span>
          <span id="upload-progress-speed"></span>
        </div>
      </div>
    </div>
  `
  document.body.insertAdjacentHTML('beforeend', modalHTML)
}

// 進捗バー更新
function updateUploadProgress(percent, speed = '') {
  const bar = document.getElementById('upload-progress-bar')
  const percentText = document.getElementById('upload-progress-percent')
  const speedText = document.getElementById('upload-progress-speed')
  
  if (bar) bar.style.width = percent + '%'
  if (percentText) percentText.textContent = percent + '%'
  if (speedText) speedText.textContent = speed
}

// 進捗バー非表示
function hideUploadProgress() {
  const modal = document.getElementById('upload-progress-modal')
  if (modal) modal.remove()
}

async function uploadImageFile() {
  if (!fileUploadState.selectedImageFile) {
    alert('画像ファイルが選択されていません')
    return
  }
  
  const file = fileUploadState.selectedImageFile
  
  try {
    // 進捗バー表示
    showUploadProgress(file.name, file.size)
    
    // FormData作成
    const formData = new FormData()
    formData.append('file', file)
    
    // アップロード開始時刻
    const startTime = Date.now()
    let lastLoaded = 0
    let lastTime = startTime
    
    // アップロード実行（進捗監視付き）
    const response = await axios.post('/api/upload/image', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      onUploadProgress: (progressEvent) => {
        if (progressEvent.total) {
          const percent = Math.round((progressEvent.loaded * 100) / progressEvent.total)
          
          // 速度計算
          const now = Date.now()
          const timeDiff = (now - lastTime) / 1000 // 秒
          const loadedDiff = progressEvent.loaded - lastLoaded
          
          if (timeDiff > 0.5) { // 0.5秒ごとに速度更新
            const speed = loadedDiff / timeDiff // バイト/秒
            const speedMB = (speed / (1024 * 1024)).toFixed(2)
            updateUploadProgress(percent, `${speedMB} MB/s`)
            lastLoaded = progressEvent.loaded
            lastTime = now
          } else {
            updateUploadProgress(percent)
          }
        }
      }
    })
    
    hideUploadProgress()
    
    if (response.data.success) {
      // アップロード成功 - 画像URLをフォームに設定
      document.getElementById('new-image-url').value = response.data.image_url
      document.getElementById('new-image-alt').value = file.name.split('.')[0]
      
      alert('✅ 画像をアップロードしました！\n\n「画像を追加」ボタンをクリックして学習カードに追加してください。')
      
      // プレビュークリア
      clearImagePreview()
    } else {
      alert('❌ アップロードに失敗しました: ' + response.data.error)
    }
    
  } catch (error) {
    hideUploadProgress()
    console.error('❌ 画像アップロードエラー:', error)
    alert('画像のアップロードに失敗しました')
  }
}

// 動画ファイル選択ハンドラ
function handleVideoFileSelect(event) {
  const file = event.target.files[0]
  if (file) {
    previewVideoFile(file)
  }
}

// 動画ドロップハンドラ
function handleVideoDrop(event) {
  event.preventDefault()
  event.stopPropagation()
  
  const file = event.dataTransfer.files[0]
  if (file && file.type.startsWith('video/')) {
    previewVideoFile(file)
  } else {
    alert('動画ファイルのみアップロード可能です')
  }
}

// 動画ファイルプレビュー
function previewVideoFile(file) {
  // ファイルサイズチェック（50MB）
  const maxSize = 50 * 1024 * 1024
  if (file.size > maxSize) {
    alert('ファイルサイズが大きすぎます。50MB以下の動画を選択してください。')
    return
  }
  
  fileUploadState.selectedVideoFile = file
  
  const previewDiv = document.getElementById('video-upload-preview')
  const previewName = document.getElementById('video-preview-name')
  const uploadBtn = document.getElementById('upload-video-btn')
  
  if (previewDiv && previewName && uploadBtn) {
    previewName.innerHTML = `
      <div class="flex items-center justify-between">
        <span>${file.name} (${formatFileSize(file.size)})</span>
        <button onclick="showVideoEditor(fileUploadState.selectedVideoFile)" 
                class="ml-4 px-3 py-1 bg-indigo-600 text-white text-sm rounded hover:bg-indigo-700">
          <i class="fas fa-cut"></i> 動画編集
        </button>
      </div>
    `
    previewDiv.classList.remove('hidden')
    uploadBtn.classList.remove('hidden')
  }
}

// 動画プレビュークリア
function clearVideoPreview() {
  fileUploadState.selectedVideoFile = null
  
  const previewDiv = document.getElementById('video-upload-preview')
  const uploadBtn = document.getElementById('upload-video-btn')
  const fileInput = document.getElementById('video-file-input')
  
  if (previewDiv && uploadBtn && fileInput) {
    previewDiv.classList.add('hidden')
    uploadBtn.classList.add('hidden')
    fileInput.value = ''
  }
}

