// Chart.jsでグラフを描画
function renderLearningProgressChart(stats) {
  const canvas = document.getElementById('learningProgressChart')
  if (!canvas) return
  
  const ctx = canvas.getContext('2d')
  
  // データ準備
  const labels = []
  const accuracyData = []
  const attemptData = []
  
  stats.forEach(stat => {
    const typeLabel = {
      'frequent_problems': 'よく出る問題',
      'application_problems': '応用問題',
      'review_checklist': '総復習'
    }[stat.content_type] || stat.content_type
    
    labels.push(typeLabel)
    accuracyData.push(stat.accuracy_rate || 0)
    attemptData.push(stat.total_attempts || 0)
  })
  
  // Chart.js未読み込みの場合は簡易表示
  if (typeof Chart === 'undefined') {
    canvas.parentElement.innerHTML = `
      <div class="flex items-center justify-center h-full">
        <p class="text-gray-500">グラフを表示するにはChart.jsが必要です</p>
      </div>
    `
    return
  }
  
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [{
        label: '正答率 (%)',
        data: accuracyData,
        backgroundColor: 'rgba(59, 130, 246, 0.5)',
        borderColor: 'rgb(59, 130, 246)',
        borderWidth: 2,
        yAxisID: 'y'
      }, {
        label: '挑戦回数',
        data: attemptData,
        backgroundColor: 'rgba(168, 85, 247, 0.5)',
        borderColor: 'rgb(168, 85, 247)',
        borderWidth: 2,
        yAxisID: 'y1'
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: 'index',
        intersect: false
      },
      scales: {
        y: {
          type: 'linear',
          display: true,
          position: 'left',
          title: {
            display: true,
            text: '正答率 (%)'
          },
          max: 100
        },
        y1: {
          type: 'linear',
          display: true,
          position: 'right',
          title: {
            display: true,
            text: '挑戦回数'
          },
          grid: {
            drawOnChartArea: false
          }
        }
      }
    }
  })
}

function closeLearningDashboard(event) {
  if (event && event.target.id !== 'learningDashboardModal') return
  const modal = document.getElementById('learningDashboardModal')
  if (modal) modal.remove()
}

// 折れ線グラフ：学習推移
function renderLearningTrendLineChart(history) {
  const canvas = document.getElementById('learningTrendLineChart')
  if (!canvas) return
  
  if (typeof Chart === 'undefined') {
    canvas.parentElement.innerHTML = '<div class="flex items-center justify-center h-full"><p class="text-gray-500">グラフを表示するにはChart.jsが必要です</p></div>'
    return
  }
  
  if (!history || history.length === 0) {
    canvas.parentElement.innerHTML = '<div class="flex items-center justify-center h-full text-gray-400"><i class="fas fa-chart-line text-4xl mb-2"></i><p>学習データが蓄積されると推移グラフが表示されます</p></div>'
    return
  }
  
  // 日付ごとに集計
  const dailyData = {}
  history.slice().reverse().forEach(record => {
    const date = new Date(record.created_at)
    const key = date.toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' })
    if (!dailyData[key]) {
      dailyData[key] = { correct: 0, total: 0, totalTime: 0, count: 0 }
    }
    dailyData[key].total++
    dailyData[key].count++
    if (record.is_correct === 1) dailyData[key].correct++
    if (record.answer_time_seconds) dailyData[key].totalTime += record.answer_time_seconds
  })
  
  const labels = Object.keys(dailyData)
  const accuracyData = labels.map(k => dailyData[k].total > 0 ? Math.round((dailyData[k].correct / dailyData[k].total) * 100) : 0)
  const timeData = labels.map(k => dailyData[k].count > 0 ? Math.round(dailyData[k].totalTime / dailyData[k].count) : 0)
  const countData = labels.map(k => dailyData[k].total)
  
  const ctx = canvas.getContext('2d')
  new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: [{
        label: '正答率 (%)',
        data: accuracyData,
        borderColor: 'rgb(59, 130, 246)',
        backgroundColor: 'rgba(59, 130, 246, 0.1)',
        borderWidth: 3,
        fill: true,
        tension: 0.3,
        pointRadius: 5,
        pointHoverRadius: 7,
        yAxisID: 'y'
      }, {
        label: '平均回答時間 (秒)',
        data: timeData,
        borderColor: 'rgb(234, 88, 12)',
        backgroundColor: 'rgba(234, 88, 12, 0.1)',
        borderWidth: 2,
        borderDash: [5, 5],
        fill: false,
        tension: 0.3,
        pointRadius: 4,
        pointHoverRadius: 6,
        yAxisID: 'y1'
      }, {
        label: '回答数',
        data: countData,
        borderColor: 'rgb(168, 85, 247)',
        backgroundColor: 'rgba(168, 85, 247, 0.3)',
        borderWidth: 2,
        type: 'bar',
        yAxisID: 'y2'
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { position: 'top', labels: { font: { size: 11 } } },
        tooltip: {
          callbacks: {
            afterBody: function(items) {
              const idx = items[0].dataIndex
              return '回答数: ' + countData[idx] + '問'
            }
          }
        }
      },
      scales: {
        y: {
          type: 'linear', display: true, position: 'left',
          title: { display: true, text: '正答率 (%)' },
          min: 0, max: 100,
          grid: { color: 'rgba(0,0,0,0.05)' }
        },
        y1: {
          type: 'linear', display: true, position: 'right',
          title: { display: true, text: '回答時間 (秒)' },
          grid: { drawOnChartArea: false }
        },
        y2: {
          type: 'linear', display: false,
          min: 0
        }
      }
    }
  })
}

