// 個別最適化コースの学習を開始（state設定→selectCourse）
async function startPersonalizedCourseLearning(courseId, curriculumId) {
  try {
    // モーダルを閉じる
    const modal = document.getElementById('personalizedGuideModal')
    if (modal) modal.remove()
    
    // state.selectedCurriculum を設定（selectCourseで必要）
    if (!state.selectedCurriculum || state.selectedCurriculum.id !== curriculumId) {
      try {
        const currRes = await axios.get('/api/curriculum/' + curriculumId)
        state.selectedCurriculum = currRes.data.curriculum
      } catch (e) {
        console.warn('カリキュラム情報取得失敗:', e)
        state.selectedCurriculum = { id: curriculumId, unit_name: '個別学習', grade: '', subject: '', textbook_company: '' }
      }
    }
    
    // カード一覧を取得してグローバルに保存（ページネーション用）
    try {
      const cardsRes = await axios.get('/api/courses/' + courseId + '/cards')
      const cards = cardsRes.data || []
      window._courseCardsList = cards.map(c => c.card_id || c.id).filter(Boolean)
      window._courseCardsData = cards
      console.log('📚 個別コースカード保存:', window._courseCardsList.length, '枚')
    } catch (e) {
      console.warn('カード一覧取得失敗:', e)
      window._courseCardsList = []
    }
    
    state.selectedCourse = courseId
    
    // 個別最適コースフラグを設定（戻るボタン用）
    window._isPersonalizedCourse = true
    window._personalizedCourseId = courseId
    window._personalizedCurriculumId = curriculumId
    console.log('🎯 個別最適コースフラグ設定:', { courseId, curriculumId })
    
    // 最初のカードを直接表示（1ページずつ表示）
    if (window._courseCardsList && window._courseCardsList.length > 0) {
      loadCardPage(window._courseCardsList[0])
    } else {
      selectCourse(courseId)
    }
  } catch (err) {
    console.error('個別最適化コース学習開始エラー:', err)
    alert('学習の開始に失敗しました。ページを再読み込みしてください。')
  }
}
window.startPersonalizedCourseLearning = startPersonalizedCourseLearning

// カード編集パネルの表示/非表示
function toggleCardEdit(cardId, index) {
  // Try multiple possible panel IDs
  let panel = document.getElementById('card-edit-panel-' + cardId)
  if (!panel && index !== undefined) panel = document.getElementById('card-edit-panel-' + index)
  if (panel) {
    panel.classList.toggle('hidden')
    if (!panel.classList.contains('hidden')) {
      panel.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }
  } else {
    console.warn('Edit panel not found:', { cardId, index })
    alert('編集パネルが見つかりません。ページを再読み込みしてください。')
  }
}
window.toggleCardEdit = toggleCardEdit

// カード手動保存
async function saveCardEditV2(cardId, index) {
  if (!cardId) { alert('カードIDが不明です'); return }
  const id = cardId || index
  try {
    const updates = {
      card_title: document.getElementById('edit-title-' + id)?.value,
      problem_text: document.getElementById('edit-problem-' + id)?.value,
      correct_answer: document.getElementById('edit-answer-' + id)?.value,
      difficulty_level: document.getElementById('edit-difficulty-' + id)?.value,
      explanation: document.getElementById('edit-explanation-' + id)?.value,
      solution_video_url: document.getElementById('edit-video-' + id)?.value,
      problem_image_url: document.getElementById('edit-image-' + id)?.value || null,
    }
    const res = await axios.put('/api/teacher/edit-card/' + cardId, updates)
    if (res.data.success) {
      alert('✅ カードを保存しました！ページを更新して確認してください。')
      toggleCardEdit(cardId, index)
    } else {
      alert('保存エラー: ' + (res.data.error || ''))
    }
  } catch (err) {
    alert('保存エラー: ' + (err.message || err))
  }
}
window.saveCardEditV2 = saveCardEditV2

// AI修正指示
async function aiRegenerateCard(cardId, index) {
  if (!cardId) { alert('カードIDが不明です'); return }
  const id = cardId || index
  const instruction = document.getElementById('edit-instruction-' + id)?.value
  if (!instruction || instruction.trim().length < 3) {
    alert('AI修正指示を入力してください（例：もっと難しくして）')
    return
  }
  if (!confirm('AIに修正指示を送信します。よろしいですか？\n\n指示: ' + instruction)) return
  
  try {
    const btn = event.target.closest('button')
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i>AI処理中...' }
    
    const res = await axios.post('/api/teacher/regenerate-card/' + cardId, { instruction })
    if (res.data.success) {
      alert('✅ AIがカードを修正しました！ページを更新して確認してください。')
      toggleCardEdit(cardId, index)
    } else {
      alert('AI修正エラー: ' + (res.data.error || ''))
    }
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-magic mr-1"></i>AI修正' }
  } catch (err) {
    alert('AI修正エラー: ' + (err.message || err))
  }
}
window.aiRegenerateCard = aiRegenerateCard

// AI画像生成（カード編集用）
async function generateCardImage(cardId, index) {
  const id = cardId || index
  const titleEl = document.getElementById('edit-title-' + id)
  const problemEl = document.getElementById('edit-problem-' + id)
  const imageInput = document.getElementById('edit-image-' + id)
  
  const cardTitle = titleEl ? titleEl.value : ''
  const problemText = problemEl ? problemEl.value : ''
  
  // プロンプト入力ダイアログ
  const defaultPrompt = cardTitle + (problemText ? '（' + problemText.substring(0, 60) + '）' : '')
  const userPrompt = prompt(
    '🎨 AI画像生成\n\nどんな図やイラストを生成しますか？\n（例：「折れ線グラフの例」「分数の円グラフ」「地図」等）\n\nカードの内容から自動入力しています。変更してOKです。',
    defaultPrompt
  )
  
  if (!userPrompt || userPrompt.trim().length < 2) return
  
  // ボタンを無効化
  const btn = event.target.closest('button')
  const originalBtnHtml = btn ? btn.innerHTML : ''
  if (btn) {
    btn.disabled = true
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'
  }
  
  // プレビュー領域を表示
  const previewDiv = document.getElementById('image-preview-' + id)
  if (previewDiv) {
    previewDiv.classList.remove('hidden')
    previewDiv.innerHTML = '<div class="flex items-center gap-2 text-xs text-purple-600"><i class="fas fa-spinner fa-spin"></i>AI画像を生成中...</div>'
  }
  
  try {
    const res = await axios.post('/api/ai/generate-image', {
      prompt: userPrompt.trim(),
      card_id: cardId,
      style: 'educational illustration, child-friendly'
    })
    
    if (res.data.success && res.data.image_url) {
      // 画像URLをセット
      if (imageInput) imageInput.value = res.data.image_url
      
      // プレビュー表示
      if (previewDiv) {
        previewDiv.innerHTML = '<div class="text-xs text-green-600 mb-1"><i class="fas fa-check-circle mr-1"></i>生成完了！（' + (res.data.generation_time_ms || 0) + 'ms）</div><img src="' + res.data.image_url + '" class="max-h-40 rounded border" onerror="this.style.display=\'none\'">'
      }
    } else {
      throw new Error(res.data.error || '画像生成に失敗しました')
    }
  } catch (err) {
    console.error('AI画像生成エラー:', err)
    if (previewDiv) {
      previewDiv.innerHTML = '<div class="text-xs text-red-600"><i class="fas fa-exclamation-circle mr-1"></i>' + (err.response?.data?.error || err.message || '画像生成に失敗しました') + '</div>'
    }
  } finally {
    if (btn) {
      btn.disabled = false
      btn.innerHTML = originalBtnHtml
    }
  }
}
window.generateCardImage = generateCardImage

// ============================================
// ファイルアップロード共通関数（画像・動画）
// ============================================

// 隠しinput要素をクリーンアップ
function _cleanupFileInput(inputId) {
  const old = document.getElementById(inputId)
  if (old) old.remove()
}

// カード編集パネル用: ファイルを選択→R2アップロード→URL欄に反映
async function uploadMediaForCard(cardId, index, mediaType) {
  const id = cardId || index
  const isVideo = (mediaType === 'video')
  const accept = isVideo ? 'video/mp4,video/webm,video/ogg,video/quicktime' : 'image/jpeg,image/png,image/gif,image/webp'
  const maxLabel = isVideo ? '50MB' : '5MB'
  const inputElId = isVideo ? ('edit-video-' + id) : ('edit-image-' + id)
  const previewElId = isVideo ? ('video-preview-' + id) : ('image-preview-' + id)
  
  // 隠しfile inputを作成
  const fileInputId = '_upload_tmp_' + mediaType + '_' + id
  _cleanupFileInput(fileInputId)
  const fileInput = document.createElement('input')
  fileInput.type = 'file'
  fileInput.id = fileInputId
  fileInput.accept = accept
  fileInput.style.display = 'none'
  document.body.appendChild(fileInput)
  
  fileInput.addEventListener('change', async () => {
    const file = fileInput.files[0]
    if (!file) { _cleanupFileInput(fileInputId); return }
    
    // プレビュー領域
    const previewDiv = document.getElementById(previewElId)
    const urlInput = document.getElementById(inputElId)
    
    if (previewDiv) {
      previewDiv.classList.remove('hidden')
      previewDiv.innerHTML = '<div class="flex items-center gap-2 text-xs text-blue-600"><i class="fas fa-spinner fa-spin"></i>アップロード中... (' + (file.size / 1024 / 1024).toFixed(1) + 'MB)</div>'
    }
    
    try {
      const formData = new FormData()
      formData.append('file', file)
      
      const endpoint = isVideo ? '/api/upload/video' : '/api/upload/image'
      const res = await axios.post(endpoint, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        timeout: isVideo ? 120000 : 30000
      })
      
      if (res.data.success) {
        const mediaUrl = isVideo ? res.data.video_url : res.data.image_url
        
        // URL欄に反映
        if (urlInput) urlInput.value = mediaUrl
        
        // プレビュー
        if (previewDiv) {
          if (isVideo) {
            previewDiv.innerHTML = '<div class="text-xs text-green-600 mb-1"><i class="fas fa-check-circle mr-1"></i>アップロード完了！</div><video src="' + mediaUrl + '" controls class="max-h-32 rounded border" style="max-width:100%"></video>'
          } else {
            previewDiv.innerHTML = '<div class="text-xs text-green-600 mb-1"><i class="fas fa-check-circle mr-1"></i>アップロード完了！</div><img src="' + mediaUrl + '" class="max-h-32 rounded border" onerror="this.style.display=\'none\'">'
          }
        }
      } else {
        throw new Error(res.data.error || 'アップロードに失敗しました')
      }
    } catch (err) {
      console.error('メディアアップロードエラー:', err)
      if (previewDiv) {
        previewDiv.innerHTML = '<div class="text-xs text-red-600"><i class="fas fa-exclamation-circle mr-1"></i>' + (err.response?.data?.error || err.message || 'アップロードに失敗しました') + '</div>'
      }
    }
    _cleanupFileInput(fileInputId)
  })
  
  fileInput.click()
}
window.uploadMediaForCard = uploadMediaForCard

// 全体配信カード用: ファイルアップロード→カードに直接保存
async function uploadMediaAndSaveToCard(cardId, imageType) {
  const isVideo = (imageType === 'video')
  const accept = isVideo ? 'video/mp4,video/webm,video/ogg,video/quicktime' : 'image/jpeg,image/png,image/gif,image/webp'
  
  const fileInputId = '_upload_save_' + imageType + '_' + cardId
  _cleanupFileInput(fileInputId)
  const fileInput = document.createElement('input')
  fileInput.type = 'file'
  fileInput.id = fileInputId
  fileInput.accept = accept
  fileInput.style.display = 'none'
  document.body.appendChild(fileInput)
  
  fileInput.addEventListener('change', async () => {
    const file = fileInput.files[0]
    if (!file) { _cleanupFileInput(fileInputId); return }
    
    try {
      alert('ファイルをアップロード中です...（' + (file.size / 1024 / 1024).toFixed(1) + 'MB）')
      
      const formData = new FormData()
      formData.append('file', file)
      
      const endpoint = isVideo ? '/api/upload/video' : '/api/upload/image'
      const res = await axios.post(endpoint, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        timeout: isVideo ? 120000 : 30000
      })
      
      if (res.data.success) {
        const mediaUrl = isVideo ? res.data.video_url : res.data.image_url
        const fieldName = isVideo ? 'solution_video_url' : (imageType === 'answer' ? 'answer_image_url' : 'problem_image_url')
        
        // カードに保存
        await axios.put('/api/card/' + cardId, { [fieldName]: mediaUrl })
        alert('✅ ' + (isVideo ? '動画' : '画像') + 'をアップロードしてカードに設定しました！')
        window.location.reload()
      } else {
        throw new Error(res.data.error || 'アップロードに失敗しました')
      }
    } catch (err) {
      alert('アップロードエラー: ' + (err.response?.data?.error || err.message))
    }
    _cleanupFileInput(fileInputId)
  })
  
  fileInput.click()
}
window.uploadMediaAndSaveToCard = uploadMediaAndSaveToCard

// 編集モーダル内のinput欄にアップロード結果を反映する関数
async function uploadMediaInModal(inputElId, mediaType) {
  const isVideo = (mediaType === 'video')
  const accept = isVideo ? 'video/mp4,video/webm,video/ogg,video/quicktime' : 'image/jpeg,image/png,image/gif,image/webp'
  
  const fileInputId = '_upload_modal_' + inputElId
  _cleanupFileInput(fileInputId)
  const fileInput = document.createElement('input')
  fileInput.type = 'file'
  fileInput.id = fileInputId
  fileInput.accept = accept
  fileInput.style.display = 'none'
  document.body.appendChild(fileInput)
  
  fileInput.addEventListener('change', async () => {
    const file = fileInput.files[0]
    if (!file) { _cleanupFileInput(fileInputId); return }
    
    const urlInput = document.getElementById(inputElId)
    
    try {
      if (urlInput) urlInput.value = 'アップロード中...'
      
      const formData = new FormData()
      formData.append('file', file)
      
      const endpoint = isVideo ? '/api/upload/video' : '/api/upload/image'
      const res = await axios.post(endpoint, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        timeout: isVideo ? 120000 : 30000
      })
      
      if (res.data.success) {
        const mediaUrl = isVideo ? res.data.video_url : res.data.image_url
        if (urlInput) urlInput.value = mediaUrl
        alert('✅ アップロード完了！保存ボタンを押してカードに反映してください。')
      } else {
        throw new Error(res.data.error || 'アップロードに失敗しました')
      }
    } catch (err) {
      if (urlInput) urlInput.value = ''
      alert('アップロードエラー: ' + (err.response?.data?.error || err.message))
    }
    _cleanupFileInput(fileInputId)
  })
  
  fileInput.click()
}
window.uploadMediaInModal = uploadMediaInModal

// テスト対策の弱点から個別最適化コースを生成
async function generatePersonalizedFromTestPrep(studentId, curriculumIdsJson, weakTopics) {
  console.log('🎯 テスト対策弱点→個別最適化コース生成:', { studentId, curriculumIdsJson, weakTopics })
  
  try {
    let curriculumIds = []
    try { curriculumIds = JSON.parse(curriculumIdsJson) } catch {}
    
    // カリキュラムIDが取得できない場合、児童のアクティブなカリキュラムを検索
    let curriculumId = curriculumIds[0]
    if (!curriculumId) {
      try {
        const res = await axios.get('/api/curriculum/list')
        const curricula = res.data || []
        if (curricula.length > 0) curriculumId = curricula[0].id
      } catch {}
    }
    
    if (!curriculumId) {
      alert('カリキュラムが見つかりません。先に単元を作成してください。')
      return
    }
    
    // 弱点情報をクエリパラメータとして個別最適化コース生成を呼び出す
    generatePersonalizedCourse(studentId, curriculumId)
  } catch (error) {
    console.error('❌ テスト対策→個別最適化連携エラー:', error)
    alert('エラーが発生しました: ' + error.message)
  }
}

